export default [{"id":66,"question":"هنا السائلة تقول: ولدي يريد الزواج من فتاة أنا أرضعت أختها هل يصح ذلك؟","title":"حكم الزواج بأخت من أرضعتها الأم","answer":"الجواب: نعم إذا تزوج التي ما أرضعت، أما أختها التي أرضعتِها تكون أختًا له إذا  كان رضاعًا تامًّا خمس مرات أو أكثر في الحولين، إذا كان الرضاع خمس مرات أو أكثر في الحولين؛ تصير أختًا له، أما أختها التي ما رضعت فلا بأس له أن يتزوج التي ما أرضعتِها.","link":"https://binbaz.org.sa/fatwas/2982/حكم-الزواج-باخت-من-ارضعتها-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0041.mp3","categories":["الرضاع"]},{"id":121,"question":"في درسٍ سابقٍ تحدثتُم عن الرضاع المُلزم، وأنه يكون خمس رضعات مُشبعات، فهل يمكن أن تكون هذه الرضعات الخمس في جلسةٍ واحدةٍ مدّتها خمس أو عشر دقائق؛ وذلك بأن يُمسك الرضيعُ الثَّدي ثم يتركه مُختارًا، ثم يعود ويُمسكه مرةً أخرى، ويتركه، وهكذا حتى يُكمل الخمس رضعات؟","title":"ما صفة ومقدار الرضعات الملزمات؟","answer":"الجواب: لا، خمس رضعات ولو غير مُشبعات، ما قلتُ: مشبعات، جزاك الله خيرًا، رضعات ولو غير مشبعات، ولا يقول أحدٌ من العلماء أنَّ \"مُشبعات\" شرط، لا، ما هو بلازمٍ، فالرضعات تنفع وتُحَرِّم ولو ما أشبعت، فليس الشبعُ شرطًا، فإذا أرضعته خمس مراتٍ في مجلسٍ أو مجالس ولو ما شبع يكون ولدًا لها.\nفمَن رضع وجعل يمصُّ الثَّدي، ويبلع اللبن، وهي تجزم وتعرف أنه ابتلع اللبن، ثم أطلق الثدي، ثم بعد ذلك عاد ورضع ومصَّ الثدي، وبلع اللبن، ثم أطلقه، وهكذا حتى أكمل الخمس في مجلسٍ أو في مجلسين أو أكثر؛ يكون ولدًا لها، خمس أو أكثر، ولو ما شبع، في الحولين، فلا بدّ أن يكون قبل الفطام.","link":"https://binbaz.org.sa/fatwas/3619/ما-صفة-ومقدار-الرضعات-الملزمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0106.mp3","categories":["الرضاع"]},{"id":152,"question":"هل يجوز منع الحمل بسبب الرضاعة؛ لأنها لو حملت انقطع اللبنُ؟","title":"ما حكم منع الحمل من أجل الرضاعة؟","answer":"الجواب: هذا شيء بين الزوج وزوجته، فإذا كانت تُرضعه واصطلح هو وإياها على أنه لا يُجامعها خوفًا من الحمل، أو تتعاطى الحبوب المانعة حتى لا تحمل؛ لأجل بقاء اللبن للرضيع والعناية بتربيته؛ فلا حرج إن شاء الله، فتعاطي حبوب المنع من الحمل لمصلحة الطفل، أو لمصلحة الأم؛ لأنه يضرُّها الحمل، أو لأسبابٍ أخرى وجيهة لا محذور فيها؛ لا بأس.\nأما كونه يمتنع من الجماع فقد يضرُّه هذا، وقد يضرُّها هذا، وقد يُفضي إلى شرٍّ عظيمٍ عليهما جميعًا من جهة عدم الجماع، فربما أطلق بصره، وربما وقع في الفاحشة، وهي كذلك، لكن الأوْلى أن يُجامعها ويتصل بها، وتتعاطى الشيء الذي يمنع الحمل إذا كان يخشى من الحمل على الطفل الذي عندهما.\nوبالإمكان أن يُعطى الطفل من الحليب الذي يتعاطاه الناسُ، ويُفطم عن ثدي أمه، إذا اصطلحا على ذلك فلا بأس، إذا اتفق الزوجُ والزوجة على فطامه على لبنها وتربيته بشيءٍ آخر من الألبان المُجففة وغير ذلك فلا بأس؛ لأنَّ الله قال: فَإِنْ أَرَادَا فِصَالًا عَنْ تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا [البقرة:233].","link":"https://binbaz.org.sa/fatwas/3689/ما-حكم-منع-الحمل-من-اجل-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0145.mp3","categories":["الرضاع"]},{"id":204,"question":"زوجة الرجل إذا كانت لها أمٌّ مُرضعة فما حكم أخوات المُرضعة لزوج الراضعة من جهة الزواج كالجارة للراضعة؟","title":"ما حكم أقارب الزوجة من الرضاعة؟","answer":"الجواب: خالات لها، لا يجمع بين المرأة وعمَّتها، ولا بين المرأة وخالتها، لا من النسب، ولا من الرضاع، فليس له أن يجمع إليها أختها من الرضاع، ولا عمّتها من الرضاع، ولا خالتها من الرضاع، كالنسب.","link":"https://binbaz.org.sa/fatwas/3942/ما-حكم-اقارب-الزوجة-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0211.mp3","categories":["الرضاع"]},{"id":352,"question":"أريد أن أتزوج ابنة ابن عمي، لكني علمتُ أن هذه البنت قد رضعت من أختي التي تكبرني بعد أن كبر ولد أختي، ولا نعلم كم أرضعتها، علمًا بأن والد البنت التي أريد الزواج منها غير راضٍ عن هذه الرضاعة؛ لأن أختي أتت وأرضعتها بدون إذنٍ مُسبقٍ، فهل أتزوج هذه البنت أم لا؟","title":"ما حكم زواج رجل بمن أرضعتها أخته؟","answer":"الجواب: إذا كانت أختك قد أرضعتها رضاعًا كاملًا -خمس مرات أو أكثر- فهذه البنت تكون أنت خالها، وليست لك، أما إذا كانت الرضاعة غير مضبوطةٍ، غير معلومةٍ، لا يُدرى: هي رضعة أو رضعتان أو ثلاث؛ فلا تحرم بذلك؛ لأن الرضاعة المحرمة لا بدّ أن تكون خمس رضعات أو أكثر في الحولين؛ لما ثبت عنه ﷺ أنه قال: لا تُحرم الرضعةُ ولا الرضعتان، وقال لسهلة بنت سهيل: أرضعي سالمًا خمس رضعات تحرمي عليه، وقالت عائشة رضي الله عنها: \"كان فيما أُنزل من القرآن: \"عشر رضعات معلومات يحرمن\" ثم نُسخن بخمسٍ معلومات، فتُوفي النبيُّ ﷺ والأمر على ذلك\"، وفي لفظٍ: \"بخمس معلومات\" فتوفي النبيُّ ﷺ وهي فيما يُقرأ من القرآن\".\nفدلَّ ذلك على أنَّ الرضاع الذي يحصل به التَّحريم لا بدّ أن يكون خمس رضعات معلومات حال كون الطفل في الحولين، فإذا كانت أختُك أرضعتها خمس رضعات في الحولين فإنَّك تكون خالها، فلا تحلّ لك، أما إن كانت أختُك لا تدري: هل أرضعتها واحدةً أو ثنتين أو ثلاثًا؟ فلا تحرم عليك بذلك، لكن تركها من باب ترك الريبة، ومن باب دع ما يريبك فهو أفضل.","link":"https://binbaz.org.sa/fatwas/4441/ما-حكم-زواج-رجل-بمن-ارضعتها-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0405.mp3","categories":["الرضاع"]},{"id":852,"question":"شخص يسأل يا سماحة الشيخ فيقول: يسأل رجلٌ على أنه رضع من ابنة عمَّته رضعةً واحدةً، فهل يجوز الزواج بها أم لا بدّ من خمس رضعات؟","title":"حكم من رضع من ابنة عمَّته رضعةً واحدةً","answer":"الجواب: الرضاع حدده الشارعُ، لا بدّ من خمس رضعات، رضعة واحدة لا يحصل بها التحريم، ولا تُعتبر؛ لقوله ﷺ: لا تحرم الرضعةُ ولا الرضعتان رواه مسلمٌ في \"الصحيح\"، ولما ثبت في \"صحيح مسلم\" أيضًا عن عائشة رضي الله عنها قالت: \"كان فيما أُنزل من القرآن: عشر رضعات معلومات يحرمن، ثم نُسخت بخمسٍ معلومات، فتوفي النبيُّ ﷺ وهي فيما يُقرأ من القرآن\"، وفي رواية الترمذي: \"والأمر على ذلك\"، فالرضعة لا يحصل بها التَّحريم.","link":"https://binbaz.org.sa/fatwas/20886/حكم-من-رضع-من-ابنة-عمته-رضعة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0681مسألة في الرضاع.mp3","categories":["الرضاع"]},{"id":963,"question":"رجلٌ تزوج بامرأةٍ وأنجب منها أولادًا، ولكن علم بعد ذلك أنها أخته من الرضاع، فما حكم زواجه بها؟ وماذا في الأولاد الذين أنجبتهم منه؟ أفيدونا جزاكم الله خيرًا.","title":"حكم من تزوجا وأنجبا ثم علما برضاعهما","answer":"الجواب: الأولاد أولاده، والاعتبار بالنكاح الشرعي الظاهر، وليس عليه في هذا إثمٌ ولا حرجٌ إذا كانوا ما قصَّروا ولا فرَّطوا؛ لكونهم علموا بعد ذلك أنها أخته من الرضاعة، لا يضرُّهم، الأولاد أولاده، وليس عليهم إثمٌ ما داما لم يعلما إلا بعد ذلك، الحمد لله، والله جلَّ وعلا لا يُؤاخذ بالجهالة، إنما يُؤاخذ بما تعمَّده الإنسان: رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، إذا كان ما تعمَّد الباطلَ فلا شيء عليه.\nس: يقول: يُطلِّقها؟\nج: يبطل النكاح... بطل النكاح، إذا علم أنها أخته بطل النكاح، لكن إذا طلَّقها طلقةً عن الشُّبهة طلَّقها طلقةً... إذا طلَّقها طلقةً يكون أحوط؛ خروجًا من الخلاف، يُطلِّقها طلقةً حتى يُعتمد عليها في تزويجها لغيره.","link":"https://binbaz.org.sa/fatwas/21005/حكم-من-تزوجا-وانجبا-ثم-علما-برضاعهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0802رجل تزوج بأمرأة وأجب منها أولاداً وعلم بعد ذلك أنها أخته من الرضاعة فما الحكم؟ ابن باز.mp3","categories":["الرضاع","المحرمات من النساء","مبطلات النكاح"]},{"id":970,"question":"إذا كان ذكر وأنثى أخوان في الرضاعة فهل يجوز لكلٍّ منهما أن يُقبِّل الآخر؟","title":"هل يجوز تقبيل الرجل أخته من الرضاعة؟","answer":"الجواب: الرضاعة كالنسب، قال تعالى: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23]، وقال النبيُّ ﷺ: يحرم من الرضاع ما يحرم من النسب، فكما يُقبّل أمَّه التي ولدته يُقبّل أمه من الرضاعة، وأخته من الرضاعة، وهكذا، هكذا أباح الله له. لكن يكون في غير الفم، يُقبّلها على جبهتها، على أنفها، على خدها، يكون هذا أوْلى، وقد كان الصديقُ  يُقبّل عائشة مع خدِّها.\nفالحاصل أنه إذا قبَّل رأس أمه من الرضاعة، أو أخته الكبيرة من الرضاعة، أو خالته من الرضاعة، أو نحو ذلك، أو بنته من الرضاعة؛ لا بأس، لكن الأفضل في الكبيرة أن يُقبّلها على رأسها، على أنفها، على جبتها، والصغيرة على خدِّها، كل ذلك حسنٌ، إلا الصغير فلا بأس أن يُقبّله مع الفم، الصغير والصغيرة؛ لأنَّ هؤلاء ليسوا محلَّ الشهوة، وليسوا محل الخطر، كان النبيُّ يُقبّل الحسن، ويُقبّل الحسين في صغرهما، رضي الله عنهما وأرضاهما.","link":"https://binbaz.org.sa/fatwas/21012/هل-يجوز-تقبيل-الرجل-اخته-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0809إذا كان ذكر وأنثى أخوان من الرضاعة فهل يجوز لكل منهما أن يقبل الآخر؟ ابن باز فتاوى المحاضرات.mp3","categories":["الرضاع"]},{"id":1142,"question":"هل يجوز لي أن أتزوج من شقيق أبي رضاعةً؟","title":"حكم الزواج من شقيق الأب بالرضاعةً","answer":"الجواب:\nهذا عمُّك، تتزوجين عمك؟! شقيق أبيك رضاعةً مثل شقيقه نسبًا، والعم مُحرَّمٌ، لا يجوز التزوج عليه، أما ابن العم فلا بأس، عمّك وعمّ جدك، حتى عمّ الجد وعمّ الأب عمٌّ لك، عمُّكِ وعمُّ أبيك وعمُّ جدك من النَّسب والرضاع كلهم محارم، أما ابن العم فلا بأس.","link":"https://binbaz.org.sa/fatwas/21190/حكم-الزواج-من-شقيق-الاب-بالرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز الزواج من شقيق الأب رضاعة.mp3","categories":["شروح الحديث","الرضاع"]},{"id":1542,"question":"هل يجوز إنشاء بنك للبن الآدميات؟","title":"ما حكم إنشاء بنك للبن الآدميات؟","answer":"الجواب:\nلا يجوز، هذا فسادٌ كبيرٌ، هذا يترتب عليه إلحاق أنسابٍ بعد الموت، ما يجوز، هذا يجب إتلافه.\nس: من الممكن أن يُجعل هذا اللبن في عبوات، ويُجعل على كل عبوةٍ معلومات عن هذه المرأة؟\nج: لا، ما يصلح، يجب القضاء عليه.","link":"https://binbaz.org.sa/fatwas/21642/ما-حكم-انشاء-بنك-للبن-الادميات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إنشاء بنك للبن الآدميات.mp3","categories":["الرضاع"]},{"id":2101,"question":"رجل رضع في السنة الأولى مرة، وفي السنة الثانية رضع مرات؟","title":"حكم الرضاع المتفرق في الحَوْلَين","answer":"الجواب:\nما دام في الحولين وتمت خمسًا يكون ولدًا له، ولو متفرقات، ولو كان هذا في شهر، وهذا في شهر، وهذا في شهر، فإذا بلغت خمسًا فأكثر صار ولدًا له.\nس: في الحولين؟\nج: نعم، يكون الطفلُ في الحولين.\nس: تحسب متفرقة؟\nج: نعم، ولو متفرقات.","link":"https://binbaz.org.sa/fatwas/22219/حكم-الرضاع-المتفرق-في-الحولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة الرضاع المتفرق في الحولين.mp3","categories":["الرضاع"]},{"id":2430,"question":"ما حكم من أرضعت طفلة: هل تحرم عليها فروع أخوالها أو أولاد خالها أو فروع صاحب اللبن؟","title":"هل يَحْرُم بالرضاع فروع صاحب اللبن؟","answer":"الجواب:\nإذا أرضعتها خمس رضعات في الحولين صارت بنتًا لها وبنتًا لزوجها وأختًا لأولادهما، وصار إخوتها أخوالها وإخوة الزوج أعمام، مثل النسب يحرم من الرضاع ما يحرم من النسب لكن بشرط أن تكون الرضعات خمس أو أكثر في الحولين قبل الفطام، مثل النسب سواء.","link":"https://binbaz.org.sa/fatwas/22558/هل-يحرم-بالرضاع-فروع-صاحب-اللبن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يحرم بالرضاع فروع أخوالها أو أولاد خالها أو فروع صاحب اللبن.mp3","categories":["الرضاع"]},{"id":2733,"question":"يقول: له زوجة، له منها ابن بالرضاعة، هل زوجة ابن الرضاعة يكون لها مَحْرَماً؟","title":"هل زوجة ابن الرضاعة من المحارم؟","answer":"الجواب: مَحْرَم؛ يَحْرُمُ مِنَ الرَّضَاعِ ما يَحْرُمُ مِنَ النَّسَبِ.","link":"https://binbaz.org.sa/fatwas/22881/هل-زوجة-ابن-الرضاعة-من-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل زوجة ابن الرضاعة تكون له محرم.mp3","categories":["الرضاع"]},{"id":3731,"question":"الأخ من الرضاعة إذا ما عُلم عنه إلا بعد كِبَرِ البنات ثم استحيين؟","title":"حكم امتناع المرأة عن أخيها من الرضاعة","answer":"الجواب: ولو، إذا ثبت لا بأس.\nس: لكن لو امتنعن حياء يأثمن؟\nالشيخ: الظاهر مثل ما قال النبي ﷺ: ائذني له فإنه عمك، عدم مخالفة الشرع؛ فإذا كان عندها امتناع تجلس معها أخرى.","link":"https://binbaz.org.sa/fatwas/23923/حكم-امتناع-المراة-عن-اخيها-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الامتناع عن الأخ من الرضاعة.mp3","categories":["الرضاع"]},{"id":5070,"question":"ما معنى: خمس رضعات مُشبعات؟","title":"ما معنى: خمس رضعات مُشبعات؟","answer":"الجواب: خمس رضعات، ما في مشبعات، ما أحد يقول: مشبعات، خمس رضعات، لكن ولو غير مشبعات، إذا رضع وابتلع اللبنَ ووصل إلى جوفه اللبنُ ولو ما شبع يُعدّ رضعةً، فإذا عاد وارتضع ثانيةً ولو ما شبع يُعدّ رضعةً ثانيةً، وهكذا، ليس من شرطها أن تكون مُشبعةً.\n س: ولو في مجلسٍ واحدٍ؟\nالشيخ: ولو في مجلسٍ واحدٍ، أو في مجالس.","link":"https://binbaz.org.sa/fatwas/29380/ما-معنى-خمس-رضعات-مشبعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى خمس رضعات مشبعات؟.mp3","categories":["الرضاع","شروح الحديث"]},{"id":5160,"question":"سائل يقول: في درسٍ سابقٍ تحدثتُم عن الرضاع المُلزم، وأنه يكون خمس رضعات مُشبعات، فهل يمكن أن تكون هذه الرضعات الخمس في جلسةٍ واحدةٍ مدّتها خمس أو عشر دقائق؛ وذلك بأن يُمسك الرضيعُ الثَّدي ثم يتركه مُختارًا، ثم يعود ويُمسكه مرةً أخرى، ويتركه، وهكذا حتى يُكمل الخمس رضعات؟","title":"ما ضابط الرضاع المُلزم والمُحرِّم؟","answer":"الجواب: لا، خمس رضعات ولو غير مُشبعات، ما قلتُ: مشبعات، جزاك الله خيرًا، رضعات ولو غير مشبعات، ولا يقول أحدٌ من العلماء أنَّ (مُشبعات) شرط، لا، ما هو بلازمٍ، فالرضعات تنفع وتُحَرِّم ولو ما أشبعت، فليس الشبعُ شرطًا، فإذا أرضعته خمس مراتٍ في مجلسٍ أو مجالس ولو ما شبع؛ يكون ولدًا لها. فمَن رضع وجعل يمصُّ الثَّدي، ويبلع اللبن، وهي تجزم وتعرف أنه ابتلع اللبن، ثم أطلق الثدي، ثم بعد ذلك عاد ورضع ومصَّ الثدي، وبلع اللبن، ثم أطلقه، وهكذا حتى أكمل الخمس في مجلسٍ أو في مجلسين أو أكثر؛ يكون ولدًا لها، خمس أو أكثر، ولو ما شبع، في الحولين، فلا بدّ أن يكون قبل الفطام.","link":"https://binbaz.org.sa/fatwas/30082/ما-ضابط-الرضاع-الملزم-والمحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 106.mp3","categories":["الرضاع"]},{"id":5305,"question":"هل قصة رضاع سالم مولى أبي حذيفة خاصة به أو بمن كانت حالته مثل حالة سالم، وهل يجوز إرضاع الكبير ولو دعت الحاجة، نرجو التفصيل في هذه المسألة؟","title":"هل يجوز إرضاع الكبير إذا دعت الحاجة؟","answer":"الجواب: الصواب أنه لا يجوز إرضاع الكبير، هذا خاص بسالم أو منسوخ؛ لقوله ﷺ: لا رضاع إلا في الحولين لا رضاع إلا ما كان قبل الفطام، إن الرضاعة من المجاعة، هذا هو الصواب الذي عليه جمهور أهل العلم، وقصة سالم إما منسوخة كما قال جماعة من أهل العلم، أو خاصة كما قال آخرون، أزواج النبي ﷺ: تقول أم سلمة: كنا نعد هذا خاصًّا بسالم، ما عدا عائشة رضي الله عنها.[1]","link":"https://binbaz.org.sa/fatwas/30955/هل-يجوز-ارضاع-الكبير-اذا-دعت-الحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 025.mp3","categories":["الرضاع"]},{"id":5332,"question":"امرأة أرضعت طفلة لمدة سبعة أيام لكن الرضعات لم تكن من الثدي مباشرة إنما وضعت في كأس ثم شربتها الطفلة فهل تلزم هذه الرضعات؟","title":"هل إرضاع المولود من كأس يترتب عليه التحريم؟","answer":"الجواب: ما في بأس، لا حرج، الرضاع يكون من الثدي، ويكون من الرضّاعات؛ لأن الرضيع قد لا يقبل الثدي ويكون بالرضّاعات؛ فإذا رضع خمس رضعات أو أكثر صار ولدًا للمرضعة، لكن لا بدّ أن يكون في الحولين قبل أن يفطم.[1]","link":"https://binbaz.org.sa/fatwas/31002/هل-ارضاع-المولود-من-كاس-يترتب-عليه-التحريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 053.mp3","categories":["الرضاع"]},{"id":5700,"question":"سؤال آخر: لي أخت أكبر مني رضعت مع عمي، فهل بنات عمي يحللن له ولي، ولإخوتي؟","title":"الزواج من أخت أخته من الرضاعة","answer":"الجواب: ما دامت المرأة التي رضعَتْ أختك فرضاعها ما يضركم، أنت لك أن تنكح بنات عمك، فكون أختك رضعت من زوجة عمك، ما يمنع إذا كنت أنت ما رضعت من زوجة عمك، وبنات عمك ما رضعوا من أمك، ولا من زوجة أبيك، ولا من أخواتك لا يضر.  لكن هذا ينبغي يسأل بنفسه؛ لأن بعض الناس يكتب سؤالا، ولا يعرفه، وين السائل؟ يسأل عن نفسه.","link":"https://binbaz.org.sa/fatwas/986/الزواج-من-اخت-اخته-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_15.mp3","categories":["شروط وأركان الزواج","الرضاع"]},{"id":5849,"question":"لي أخ أكبر مني، وهو أكبر إخواني، وقد رضع مع عمي تقريبًا أكثر من خمس رضعات، فهل بناته تحل لأخي الكبير، وإخواني، أم لا؟","title":"ما الذي يحرمه الرضاع؟","answer":"الجواب: على كل حال إذا رضع أخوه، يعني أخوك رضع من زوجة جدك، أم عمك، زوجة جدك، يعني، هذا عمك أخو أبيك، إذا رضعت المرأة من زوجة جدك؛ صار أخًا لكم، صار أخًا لأبيه، وأخًا لأعمامه. السؤال: يعني بناته ما يحلِنَّ لي؟ الجواب: أنت عمهم، لكن ما يحلِنَّ لأولادك؛ لأنه صار عمًا لهم رضع، وعمًا لبناتك، وأبنائك جميعًا، إذا رضع إنسان من زوجة جدك؛ صار هو أخًا لك، ولإخوتك، وصار عمًا لأولادكم بالرضاع، يحرم من الرضاع ما يحرم من النسب.","link":"https://binbaz.org.sa/fatwas/1194/ما-الذي-يحرمه-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_190.mp3","categories":["الرضاع"]},{"id":5943,"question":"شاب يريد أن يتزوج من فتاة، وللفتاة أخ يكبرها بسنة، وأم الفتاة أرضعت هذا الشاب رضعة واحدة في يوم واحد مع ابنها الذي يكبر الفتاة، هل يصح الزواج بينهما؟","title":"عدد الرضعات التي يحرم بها النكاح","answer":"الجواب: الرضعة الواحدة لا تحرم، النبي -عليه الصلاة والسلام- قال: لا تحرم الرضعة، ولا الرضعتان لا بدّ من خمس رضعات في الحولين، إذا كان الرضعات أقل من ذلك، ومضبوط؛ فلا يحصل به التحريم.","link":"https://binbaz.org.sa/fatwas/1309/عدد-الرضعات-التي-يحرم-بها-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_278.mp3","categories":["الرضاع"]},{"id":6099,"question":"نرجو شرح الرضاع الذي يحرم، حيث إن بعض الناس يتزوج أخت أخيه الصغير من الرضاع، هل يجوز هذا؟","title":"التحريم بالرضاع","answer":"الجواب: الرضاع قد أوضحه نبينا -عليه الصلاة والسلام- وبين ... القرآن قال الله -جل وعلا-: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23].  فالتحريم بالرضاعة موجود في القرآن الكريم في الأمهات، والأخوات، ثم جاءت السنة بتحريم الباقين مثل النسب، قال النبي ﷺ: يحرم من الرضاع ما يحرم من النسب ولما قيل له: ألا تتزوج ابنة حمزة؟ قال: إنها ابنة أخي من الرضاعة، يحرم من الرضاع ما يحرم من النسب. ولما استأذن عم عائشة من الرضاعة عليها قال لها النبي ﷺ: ائذني له فإنه عمك فدل ذلك على أن الرضاع كالنسب.  فإذا ثبت الرضاع بالبينة الشرعية... امرأة ثقة بأنها أرضعت المرأة خمس رضعات، والطفل في الحولين؛ ثبت حكم الرضاع خمس رضعات، فأكثر، الطفل في الحولين، فإنه يثبت الرضاع، وتكون المرضعة أمَّا له، ويكون أولادها إخوة له، وأبوها يكون جدًا لها، وأمها تكون جدة له، وهذا ما يترتب على النسب يترتب على الرضاع. لكن بعض الناس قد يغلط في هذه المسائل، فإذا كان أخوه الصغير قد ارتضع من امرأة، والكبير ما رضع منها؛ فله أن ينكح أخت أخيه الصغير؛ لأنه لم يرتضع من أمها، إنما ارتضع ... من أمه.  فالحاصل: أنه إذا كان أخوه الصغير رضع من امرأة؛ صارت بناتها إخوة للصغير، ولا يحرم على أخيه الكبير الذي لم يرضع، فإذا رضع زيد -أخ صغير- من زينب، وله إخوة كبار، ولزينب بنات؛ فإنهن يكن حلًا لإخوان الرضيع، ولا يحلن للرضيع، فالرضيع أخ لهن، ولكن إخوانه ليسوا حرام عليهن، ولسن أخوات لإخوانه الكبار؛ لأنهم ما رضعوا من أمهن، وهن لم يرضعن من أمهات الكبار، ولا من زوجات آبائهم، ولا من أخواتهم، فلا يحرمن عليه، وإن حرمن على أخيه الصغير الذي رضع من أمهن.","link":"https://binbaz.org.sa/fatwas/1513/التحريم-بالرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_443.mp3","categories":["الرضاع"]},{"id":6112,"question":"سماحة شيخي، معي أخ رضع من ابنة عمي، هل يجوز لي أن أتزوج التي بعدها، أم لا؟","title":"حكم التزوج ببنت من رضع منها الأخ","answer":"الجواب: إذا كان أخوك رضع مع ابنة عمك، يعني من أمها؛ فهو أخوها، هو إذا كان رضع من أمها رضاعًا شرعيًا خمس رضعات، أو أكثر في الحولين؛ صار أخًا لها هو، أما أنت ما عليك منها إذا ما كنت رضعت من أمها، ولا من زوجة أبيها، ولا من أخواتها، ما تحرم عليك، تحرم عليه هو بس، هي نفسها، والتي قبلها، والتي بعدها.  التحريم يختص بأخيك إذا رضع من أمها خمس رضعات، أو أكثر صار أخًا لها، وحرمت عليه هي، وجميع بنات المرضعة، وجميع بنات الزوج الذي له اللبن، هن أخوات له، إذا كان رضاعه يشتمل على خمس رضعات، أو أكثر حال كونه في الحولين طفلًا صغيرًا، أما أنت فلا حرج عليك.","link":"https://binbaz.org.sa/fatwas/1535/حكم-التزوج-ببنت-من-رضع-منها-الاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_465.mp3","categories":["الرضاع"]},{"id":6188,"question":"طيب الرضاع  من المرأة الكبيرة، ودرت على طفل صغير، ورضعته، يعتبر رضاعًا شرعيًا؟","title":"مشروعية إرضاع العجوز للطفل قبل تمام الحولين","answer":"الجواب: نعم يعتبر رضاعًا شرعيًا، إذا درت العجوز على طفل، درت عليه قبل أن يفطم، قبل أن يتم الحولين، إذا درت عليه، وأرضعته رضاعًا تامًا، خمس رضعات، أو أكثر؛ صارت أمًا له، وصار أخًا لأولادها ذكورهم، وإناثهم.","link":"https://binbaz.org.sa/fatwas/1675/مشروعية-ارضاع-العجوز-للطفل-قبل-تمام-الحولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_549.mp3","categories":["الرضاع"]},{"id":6284,"question":"إذا كان أخ من أبي، وله أخت من الرضاعة، فهل يجوز لي مصافحتها؟","title":"حكم مصافحة أخت الأخ من الأب من الرضاعة","answer":"الجواب: إذا كانت الأخت من الرضاعة أرضعتها زوجة أبيك، فهي أخت لك، وله جميعًا، تصير أختًا لك من أبيه من الرضاع، إذا كان الرضاع من زوجة أبيك، أما إذا كان أخوك من أبيك أرضعته امرأة أخرى؛ فهي أم له من الرضاع، وليست أمًا لك.","link":"https://binbaz.org.sa/fatwas/1804/حكم-مصافحة-اخت-الاخ-من-الاب-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_645.mp3","categories":["الرضاع"]},{"id":6390,"question":"بنت رضعت من أختها لأبيها، فهل تحل لإخوان زوجها، أي إخوان الزوجة المرضعة؟","title":"حكم زواج المرأة بأخي زوج من رضعت منها","answer":"الجواب: إذا رضعت المرأة من امرأة رضاعًا كاملاً، خمس رضعات، أو أكثر؛ فإن صاحب اللبن، وهو الزوج يكون أبًا لها، وتكون المرضعة أمًا لها، ويكون إخوان الزوج أعمامًا لها، وأخواته عمات لها، وإخوان المرأة أخوالًا لها، وأخواتها خالات لها، لا يحل لهم نكاحها إذا كان الرضاع شرعيًّا، خمس مرات، أو أكثر في الحولين.","link":"https://binbaz.org.sa/fatwas/1962/حكم-زواج-المراة-باخي-زوج-من-رضعت-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_749.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":6422,"question":"هل يجوز عند الضرورة إرضاع الرجل الكبير، كما في قصة سالم مولى أبي حذيفة، أرضعيه تحرمي عليه؟ وكيف الجمع بين هذا، وقوله انظرن من إخوانكم، فإنما الرضاعة من المجاعة؟","title":"حكم إرضاع الرجل الكبير للضرورة","answer":"الجواب: الصواب: أنه لا يقع إرضاع الكبير، لا يحصل به تحريم، وهذا مما قاله أهل العلم، أن جمهور أهل العلم أنه خاصة بسالم، وسهلة بنت سهيل، وكما أفتى بهذا أزواج النبي ﷺ ما عدا عائشة. فالصواب: أن إرضاع الكبير لا يؤثر، ولا حكم له، وإنما يؤثر الرضاع في الحولين؛ لحديث: انظرن من إخوانكن؛ فإنما الرضاعة من المجاعة رواه الشيخان البخاري، ومسلم في الصحيحين، ولحديث: لا رضاع إلا في الحولين ولحديث آخر: لا رضاع إلا ما فتق الأمعاء، وكان قبل الفطام.  فالصواب: أن الرضاع إنما يحرم إذا كان في الحولين. السؤال: وقصة سالم؟ الجواب: محمولة على الخصوصية، هذا هو الأرجح.","link":"https://binbaz.org.sa/fatwas/2127/حكم-ارضاع-الرجل-الكبير-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_775.mp3","categories":["الرضاع"]},{"id":6470,"question":"رضعت ابنتي من زوجة أخي، ورضعت ابنة أخي من زوجته، هل يجوز لأبناء أخي الآخرين أن يتزوجوا من بناتي الأخريات، وكذلك العكس؟","title":"إذا رضعت ابنة أخي من زوجتي، فهل تحرم أخواتها على أولادي؟","answer":"الجواب: إذا رضعت ابنة أخيك من زوجتك رضاعًا شرعيًا ثلاث رضعات، أو أكثر، فهذا الرضاع يحرمها على أولادك، وتكون أختًا لهم، إذا رضعت في الحولين خمس رضعات، أو أكثر من زوجتك، فإن جميع أولادك لا يحل لهم نكاحها، ولكن لا بأس أن يتزوجوا أخواتها اللاتي ما رضعن أخواتها الأخريات.  وكذلك إذا رضعت ابنتك من زوجة أخيك؛ صارت بنتًا لأخيك، إذا كان الرضاع خمس رضعات، أو أكثر في الحولين؛ صارت بنتًا لأخيك، وحرم على أبنائه نكاحها، ولكن لا بأس لأولاد أخيك أن ينكحوا البنات الأخريات، غير التي رضعت من زوجة أخيك.  فينبغي أن يفهم هذا الراضعة من زوجة أخيك لا تحل لأبنائك، والراضعة من بنات أخ، زوجتك لا تحل لأبنائك أيضًا.  المقصود: بنت أخيك التي رضعت مع أبنائك صارت بنتًا لك، تحرم على أبنائك، وبنتك التي رضعت من زوجة أخيك، وصارت بنتًا لأخيك، لا تحل لأبنائه، ومن سواهن، لا بأس به، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/2219/اذا-رضعت-ابنة-اخي-من-زوجتي-فهل-تحرم-اخواتها-على-اولادي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_839.mp3","categories":["الرضاع"]},{"id":6474,"question":"رضعت ابنتي من زوجة أخي، ورضعت ابنة أخي من زوجته، هل يجوز لأبناء أخي الآخرين أن يتزوجوا من بناتي الأخريات، وكذلك العكس؟","title":"إذا رضعت ابنة أخي من زوجتي، فهل تحرم أخواتها على أولادي؟","answer":"الجواب: إذا رضعت ابنة أخيك من زوجتك رضاعًا شرعيًا ثلاث رضعات، أو أكثر، فهذا الرضاع يحرمها على أولادك، وتكون أختًا لهم، إذا رضعت في الحولين خمس رضعات، أو أكثر من زوجتك، فإن جميع أولادك لا يحل لهم نكاحها، ولكن لا بأس أن يتزوجوا أخواتها اللاتي ما رضعن أخواتها الأخريات.  وكذلك إذا رضعت ابنتك من زوجة أخيك؛ صارت بنتًا لأخيك، إذا كان الرضاع خمس رضعات، أو أكثر في الحولين؛ صارت بنتًا لأخيك، وحرم على أبنائه نكاحها، ولكن لا بأس لأولاد أخيك أن ينكحوا البنات الأخريات، غير التي رضعت من زوجة أخيك.  فينبغي أن يفهم هذا الراضعة من زوجة أخيك لا تحل لأبنائك، والراضعة من بنات أخ، زوجتك لا تحل لأبنائك أيضًا.  المقصود: بنت أخيك التي رضعت مع أبنائك صارت بنتًا لك، تحرم على أبنائك، وبنتك التي رضعت من زوجة أخيك، وصارت بنتًا لأخيك، لا تحل لأبنائه، ومن سواهن، لا بأس به، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/2219/اذا-رضعت-ابنة-اخي-من-زوجتي-فهل-تحرم-اخواتها-على-اولادي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_839.mp3","categories":["الرضاع"]},{"id":6752,"question":"أنا وأخي تزوجنا أختين، وقد رزقتُ ببنت، ورزق أخي بولد، إلا أن ابنتي رضعت من جدتها لأمها، ولا تعرف عدد الرضعات، فهل تصح زوجة لابن عمها، وابن خالتها؟","title":"الرضاع الذي لا يعلم عدده والرضاع المحرم","answer":"الجواب: إذا أرضع من جدته أم أمه؛ صار خالًا لأولاد خالاته، إذا رضع من جدته، أم أبيه؛ صار عمًا لأولاد عماته، فلا يجوز النكاح، لكن إذا كان الرضاع غير مضبوط، لا يدرى كم عدد الرضاع؛ لا يثبت به التحريم، لا بد يكون الرضاع مضبوطًا خمس مرات، أو أكثر خمس رضعات، أو أكثر، هذا هو الرضاع المحرم، فإذا كان الرضاع لا يعلم عدده، أو أقل من خمس رضعات؛ فلا يحصل به التحريم.  السؤال:.. الجواب: من باب دع ما يريبك، لكن لا يحرم، إنما هو من باب الشبهات، تركه أفضل. السؤال: يفرق بينهما؟ الجواب: إذا في شبهة يكون تركه أفضل، إذا اشتبهوا في كم عدد الرضاع؛ تركه أفضل، لكن لا يحرم إلا بالضبط.","link":"https://binbaz.org.sa/fatwas/2662/الرضاع-الذي-لا-يعلم-عدده-والرضاع-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1158.mp3","categories":["الرضاع"]},{"id":6763,"question":"أنا وأخي تزوجنا أختين، وقد رزقتُ ببنت، ورزق أخي بولد، إلا أن ابنتي رضعت من جدتها لأمها، ولا تعرف عدد الرضعات، فهل تصح زوجة لابن عمها، وابن خالتها؟","title":"الرضاع الذي لا يعلم عدده والرضاع المحرم","answer":"الجواب: إذا أرضع من جدته أم أمه؛ صار خالًا لأولاد خالاته، إذا رضع من جدته، أم أبيه؛ صار عمًا لأولاد عماته، فلا يجوز النكاح، لكن إذا كان الرضاع غير مضبوط، لا يدرى كم عدد الرضاع؛ لا يثبت به التحريم، لا بد يكون الرضاع مضبوطًا خمس مرات، أو أكثر خمس رضعات، أو أكثر، هذا هو الرضاع المحرم، فإذا كان الرضاع لا يعلم عدده، أو أقل من خمس رضعات؛ فلا يحصل به التحريم.  السؤال:.. الجواب: من باب دع ما يريبك، لكن لا يحرم، إنما هو من باب الشبهات، تركه أفضل. السؤال: يفرق بينهما؟ الجواب: إذا في شبهة يكون تركه أفضل، إذا اشتبهوا في كم عدد الرضاع؛ تركه أفضل، لكن لا يحرم إلا بالضبط.","link":"https://binbaz.org.sa/fatwas/2662/الرضاع-الذي-لا-يعلم-عدده-والرضاع-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1158.mp3","categories":["الرضاع"]},{"id":6890,"question":"هل من رضع من أمي وهي ميت عنها رجل غير أبيه، هل أتزوج من بنات ذلك الرضيع، أم لا؟","title":"حكم زواج الرجل من بنات رجل اشترك معه في الرضاعة","answer":"الجواب: لا، إذا رضع إنسان من أمك، وهي مع زوج آخر غير أبيك، يرضع من أمك من أي زوج كان، أو ليس عندها زوج إذا درت عليه، وأرضعته خمس رضعات في الحولين، وإن كانت ما عندها زوج قد طلقها، أو مات عنها، فهذا الرضيع يكون أخاك، وتكون بنته بنت أخيك، لا تتزوجها، وأنت عمها، فلا تتزوجها إذا كان الرجل الذي رضع من أمك من زوج غير أبيك، أو في حال كبرها قد درت عليه، وهي ما عندها زوج، وأرضعته خمس مرات، فأكثر حال كونه في الحولين؛ فإنه يكون أخاك، وتكون بناته بنات أخيك، ليس لك أن تنكح منهن أحدًا.","link":"https://binbaz.org.sa/fatwas/2771/حكم-زواج-الرجل-من-بنات-رجل-اشترك-معه-في-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1263.mp3","categories":["الرضاع"]},{"id":6891,"question":"فتاة وفتى رضعا من عمتهم، هل يجوز للفتى أن يتزوج بهذه الفتاة؟","title":"حكم زواج الرجل بفتاة اشترك معها في الرضاعة من امرأة","answer":"الجواب: إذا اجتمع فتى وفتاة في الرضاع من أي امرأة كانت؛ صارا أخوين، سواء كانت عمتهم، أو صارت ابنة عمهم، أو بعيدة منهم، إذا اجتمعا في الرضاع من أي امرأة؛ فإنهما يكونان أخوين إذا تم الرضاع الشرعي، إذا كان الرضاع خمس رضعات، فأكثر في الحولين، فإنهما يكونان أخوين، وإن كانت المرضعة أجنبية منهما بالكلية، يكونا أخوين، ليس له أن ينكحها؛ لأنها صارت أخته بالرضاع، إذا كان الرضاع خمس رضعات، فأكثر، وكان رضاعهما في الحولين، لا بعدهما، هذا هو الذي جاءت به الشريعة عن النبي -عليه الصلاة والسلام-.","link":"https://binbaz.org.sa/fatwas/2767/حكم-زواج-الرجل-بفتاة-اشترك-معها-في-الرضاعة-من-امراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1259.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":6972,"question":"عدد الرضعات المحرمة؟","title":"عدد الرضعات المحرمة وكيفيتها","answer":"الجواب:\n\nخمس مرات فأكثر، يمص الثدي، ويرضع اللبن، ثم يطلق الثدي هذه واحدة، فإذا عاد إليه، وشرب، امتص اللبن، ثم بلعه، ثم أطلقه؛ يكون ثانية، وهكذا حتى يكمل خمس، ولو ما شبع.","link":"https://binbaz.org.sa/fatwas/2914/عدد-الرضعات-المحرمة-وكيفيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1362.mp3","categories":["الرضاع"]},{"id":7132,"question":"أريد أن أتزوج من فتاة، ولكن هناك مشكلة، وهي أنني رضعت مع ابن إحدى الأسر، وهذه البنت رضعت مع بنت هذه الأسرة، أي أنها رضعت مع أخت الأخ الذي رضعت أنا معه؟","title":"حكم الزواج ممن رضعت مع أخت الأخ الذي رضعت معه؟","answer":"الجواب:\n\nما دامت رضعت من المرأة التي رضعت منها فهي تكون أختًا لك إذا كان الرضاع تامًا، خمس رضعات، أو أكثر، إذا كنت رضعت من امرأة زينب، فاطمة، وهي رضعت منها أيضًا مع ولد آخر، مع بنت أخرى؛ تكون أختًا لك، ولو أنها قبلك، أو بعدك، إذا كان الرضاع كاملًا تامًا خمس رضعات، أو أكثر في الحولين.","link":"https://binbaz.org.sa/fatwas/3165/حكم-الزواج-ممن-رضعت-مع-اخت-الاخ-الذي-رضعت-معه ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1523.mp3","categories":["الرضاع"]},{"id":7190,"question":"إذا أنا رضعت من امرأة، فهل أبناء زوجها من غيرها إخوة لي؟","title":"الأبناء إخوة لمن رضع من زوجة أبيهم","answer":"الجواب:\n\nنعم إذا رضعت من زوجة زيد فاطمة، أرضعك من لبنه وهي معه رضاعًا تامًا خمس مرات فأكثر، وأنت في الحولين -ما بعد فطمت- تكون ولدًا لها، وولدًا لزوجها، وتكون أخًا لأولادها من الزوج السابق، أو الزوج اللاحق هي.\n\nوتكون أيضًا أخًا لأولاد هذا الزوج من الزوجات السابقات واللاحقات أخًا من الأب بالرضاع، وأخًا لأولاده من هذه المرأة، شقيقًا للرضاع، وأخًا لأولادها إن كان لها أولاد من زوج سابق من الأم بالرضاع كالنسب, يحرم من الرضاع ما يحرم من النسب.","link":"https://binbaz.org.sa/fatwas/3234/الابناء-اخوة-لمن-رضع-من-زوجة-ابيهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1576.mp3","categories":["الرضاع"]},{"id":7202,"question":"عمي تزوج امرأتين، امرأة أنجبت ولدًا، والأخرى أنجبت بنتًا، أنا رضعت من أم البنت، هل يجوز لي أن أتزوج بنت الولد الذي أنجبت المرأة التي لم أرضع منها؟","title":"حكم الزواج بابنة ابن العم الذي رضعت من زوجة أبيه","answer":"الجواب:\n\nإذا رضعت من أم البنت؛ صرت ولدًا للشخص، إذا كان رضاعًا تامًا، خمس مرات فأكثر؛ صرت ولدًا له، وأخًا لعياله كلهم، وعمًا لأولادهم، ليس لك ذلك، إذا رضعت من شخص من إحدى زوجتيه، أو زوجاته؛ صرت ولدًا له، إذا كان الرضاع خمس مرات، أو أكثر حال كونك في الحولين؛ تكون ولدًا له، وعمًا لجميع أولاده، لجميع الزوجات، وعمًا لبناته كذلك.\n\nالسؤال: .. لم يرضع منها فلا يصير ابنا لها؟\n\nالجواب: لكن هو رضع، إذا ما رضع ما يحتاج.\n\nالسؤال: يقول: هل يجوز لي أن أتزوج بنت الولد الذي أنجبته المرأة التي لم أرضع منها؟\n\nالجواب: يتزوج بنت أخيه! تكون بنت أخيه، لا، تكون بنت أخيك؛ لأنك أخًا لجميع أولاده، فيكون بنات الأولاد بنات لأخيك، وأنت عمهن، فلا تأخذها.","link":"https://binbaz.org.sa/fatwas/3264/حكم-الزواج-بابنة-ابن-العم-الذي-رضعت-من-زوجة-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1592.mp3","categories":["الرضاع"]},{"id":7208,"question":"حضنتني جدتي، وأنا ابن أربعة شهور، تغذيني على حليب صناعي، وإذا بكيت؛ تعطيني ثديها لإسكاتي وتهدأتي، مع العلم أنها كبيرة، عمرها ستون عامًا، ولا يوجد فيها حليب، وزوجها جدي متوفي قبل عشرين سنة،  هل يجوز لي أن أتزوج ابنة عمي شقيق والدي؟","title":"حكم الرضاع ممن انقطع لبنها، والزواج من ابنة العم","answer":"الجواب:\n\nنعم، إذا كانت الجدة ما درت عليك، إنما تسقيك من الحليب الصناعي، ولكن تعطيك ثديها للتلهية والتسلية فقط، ولا درت -ما درت- عليك لبنًا حليبًا؛ ما يضر، ما في شيء، لا بأس.\n\nأما لو درت عليك -ولو أنها كبيرة- لو درت حتى أرضعتك رضاعًا كاملاً، خمس مرات أو أكثر؛ تكون أمًا لك -إذا كانت أم أبيك- تكون أما لك، وتكون أخًا لأبيك، وأخًا لأعمامك وعمًا لأولادهم، أما ما دام ما درت، ولكنها تشغلك بثديها، تلهيك وهي ما درت؛ ما يضر.","link":"https://binbaz.org.sa/fatwas/3265/حكم-الرضاع-ممن-انقطع-لبنها-والزواج-من-ابنة-العم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1593.mp3","categories":["الرضاع"]},{"id":7232,"question":"رضعت من امرأة، ولكن لا أحد يؤكد عدد الرضعات، هل أبناء هذه المرأة إخوة لي، علمًا أن المرأة المرضعة قد توفيت، ولم أعرفها؟","title":"الحكم عند عدم معرفة عدد الرضعات ووفاة المرضعة","answer":"الجواب:\n\nلا بد من ثبات الرضاع ثبوتًا شرعيًا، وأن يكون خمس رضعات، أو أكثر في الحولين، حال كونك في الحولين صغير، وأن الرضعات خمس، أو أكثر.\n\nفإذا لم يثبت هذا؛ فليسوا إخوة لك، وليسوا محارمًا لك، إن كانوا بنات لا، لأن الواجب الاحتياط في هذه الأمور، والبعد عن أسباب الفتنة، فإذا لم يثبت الرضاع الشرعي؛ فليسوا  إخوة لك.","link":"https://binbaz.org.sa/fatwas/3301/الحكم-عند-عدم-معرفة-عدد-الرضعات-ووفاة-المرضعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1626.mp3","categories":["الرضاع"]},{"id":7258,"question":"هل الأخوات من الرضاعة رحم يجب علي وصلهن، أم لا؟","title":"الأخوات من الرضاعة لسن أرحاماً","answer":"الجواب:\n\nليسوا برحم، الأخوات من الرضاعة ليسوا من الأرحام، الأرحام هم القرابات، هكذا أبو الزوجة، وأخو الزوجة، وعم الزوجة، وأقاربها يقال لهم: أصهار، وليسوا رحمًا.\n\nالرحم هم القرابات، لكن أولئك ينبغي الإحسان إليهم، وصلتهم من باب المجاملة، ومن باب مقابلة المعروف بالمعروف، لا لأنهم أقارب، لكن أصهاره، وأقاربه من الرضاعة، إذا أحسنت إليهم، ووصلتهم؛ فهذا من مكارم الأخلاق.","link":"https://binbaz.org.sa/fatwas/3314/الاخوات-من-الرضاعة-لسن-ارحاما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1638.mp3","categories":["الرضاع","الآداب والأخلاق المحمودة"]},{"id":7260,"question":"يوجد لي بنت عم أريد الزواج بها وهي راضعة مع الأكثر من إخوتي من أمي، وليس من أبي، علمًا بأن الحليب لرجل قبل أبي كانت أمي مطلقة منه، وأمي لا تعرف كم رضعة أرضعتها ثلاثًا، أم ثنتين، أم أكثر، فما أدري رأي سماحتكم في ذلك؟","title":"مقدار الرضاع الذي يحصل به التحريم","answer":"الجواب:\n\nالحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\n\nفالرضاع الذي يحصل به التحريم لا بد أن يكون خمس رضعات، أو أكثر في الحولين، لما ثبت عن عائشة -رضي الله تعالى عنها- في صحيح مسلم قالت: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ وهي فيما يقرأ من القرآن\" وفي رواية الترمذي: \"والأمر على ذلك\". \n\nوفي حديثها أيضًا -رضي الله عنها- أن النبي ﷺ قال لسهلة بنت سهيل: أرضعي سالمًا خمس رضعات تحرمي عليه، فلا بد من خمس رضعات، فإذا كانت المرضعة لا تدري هل أرضعته واحدة، أو ثنتين، أو ثلاثًا، أو أكثر، فإن هذا الرضاع لا يعتبر، ولا يكون به الرضيع ولدًا لها، ولا أخًا لأولادها ولا ولدًا لزوجها صاحب اللبن حتى يكون الرضاع خمسًا فأكثر، وحتى يكون الطفل الراضع في الحولين لقوله -عليه الصلاة والسلام-: لا رضاع إلا في الحولين.","link":"https://binbaz.org.sa/fatwas/3339/مقدار-الرضاع-الذي-يحصل-به-التحريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1660.mp3","categories":["الرضاع"]},{"id":7270,"question":"يوجد لي بنت عم أريد الزواج بها وهي راضعة مع الأكثر من إخوتي من أمي، وليس من أبي، علمًا بأن الحليب لرجل قبل أبي كانت أمي مطلقة منه، وأمي لا تعرف كم رضعة أرضعتها ثلاثًا، أم ثنتين، أم أكثر، فما أدري رأي سماحتكم في ذلك؟","title":"مقدار الرضاع الذي يحصل به التحريم","answer":"الجواب:\n\nالحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\n\nفالرضاع الذي يحصل به التحريم لا بد أن يكون خمس رضعات، أو أكثر في الحولين، لما ثبت عن عائشة -رضي الله تعالى عنها- في صحيح مسلم قالت: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ وهي فيما يقرأ من القرآن\" وفي رواية الترمذي: \"والأمر على ذلك\". \n\nوفي حديثها أيضًا -رضي الله عنها- أن النبي ﷺ قال لسهلة بنت سهيل: أرضعي سالمًا خمس رضعات تحرمي عليه، فلا بد من خمس رضعات، فإذا كانت المرضعة لا تدري هل أرضعته واحدة، أو ثنتين، أو ثلاثًا، أو أكثر، فإن هذا الرضاع لا يعتبر، ولا يكون به الرضيع ولدًا لها، ولا أخًا لأولادها ولا ولدًا لزوجها صاحب اللبن حتى يكون الرضاع خمسًا فأكثر، وحتى يكون الطفل الراضع في الحولين لقوله -عليه الصلاة والسلام-: لا رضاع إلا في الحولين.","link":"https://binbaz.org.sa/fatwas/3339/مقدار-الرضاع-الذي-يحصل-به-التحريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1660.mp3","categories":["الرضاع"]},{"id":7310,"question":"خالتي أم زوجتي أرضعت ولد ابنتها التي مع زوج آخر، وهي لا تعلم كم عدد الرضعات، وهذا الولد يدخل على بناتي، ولا يتحجبن عنه، ويقول: إنهن أخوات لي من الرضاعة، هل يثبت حكم الرضاعة والمرضعة لا تعلم كم عدد الرضعات؟ علمًا بأن أم الولد تقول: بأن أمها أرضعت ابنها ثلاثة أيام في وقت مرضها، وهل يؤخذ بقول أم الولد، أو بقول المرضعة؟","title":"شروط ثبوت الرضاعة","answer":"الجواب: لا بد أولًا من ضبط الرضاع، وأن يكون خمس أو أكثر، فإذا شكت المرضعة؛ فلا عبرة بقولها، إذا شكت ما تدري هل هي ثلاث أو ثنتين أو أربع أو خمس ما يكون كلامها معتبرًا، ولا يثبت الرضاع مع الشك، فلا بد مثل ما جاء في حديث عائشة لا بد من خمس معلومات في الحولين، لا رضاع إلا في الحولين. ثم لا يقبل قولها ولا قول غيرها إلا إذا كانت عدل، إذا كانت المرأة عدلة، معروفة بالثقة، ما هي بكذوب ولا فاسقة، أما إذا كانت كذوب أو معروفة بالفسق؛ فلا يقبل قولها، سواء كانت مرضعة، أو غير مرضعة.","link":"https://binbaz.org.sa/fatwas/3383/شروط-ثبوت-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1700.mp3","categories":["الرضاع"]},{"id":7311,"question":"أنا شاب، ولي جد من أبي، وعنده ثلاث نسوة إحداهن أم أبي، والثانية أرضعتني أربعة مرات أو خمسة، والثالثة منهم أتت لها بنت على جدي، وتصبح عمتي أخت أبي، وعمتي هذه تزوجت وأنجبت بنتًا، فهل يصح لي الزواج بهذه البنت، أي بنت عمتي؟","title":"رضع من زوجة جده الثانية، فهل يتزوج من بنت زوجته الثالثة؟","answer":"الجواب:  إذا كنت على ما قلت فإنها تكون بنت أختك من الرضاع، إذا كان ثبت الرضاع من زوجة جدك أرضعتك؛ تكون أخًا لأبيك، وأخا لعمتك، وخالًا لبناته -إذا كان الرضاع مثبوتًا- أرضعتك زوجة جدك خمس رضعات، أو أكثر في الأيام التي قلت، فأنت تكون أخًا لأبيك، وأخا لعمتك، وخالًا لأولادها الذكور والإناث، لا يصلح.","link":"https://binbaz.org.sa/fatwas/3379/رضع-من-زوجة-جده-الثانية-فهل-يتزوج-من-بنت-زوجته-الثالثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1697.mp3","categories":["الرضاع"]},{"id":7316,"question":"خالتي أم زوجتي أرضعت ولد ابنتها التي مع زوج آخر، وهي لا تعلم كم عدد الرضعات، وهذا الولد يدخل على بناتي، ولا يتحجبن عنه، ويقول: إنهن أخوات لي من الرضاعة، هل يثبت حكم الرضاعة والمرضعة لا تعلم كم عدد الرضعات؟ علمًا بأن أم الولد تقول: بأن أمها أرضعت ابنها ثلاثة أيام في وقت مرضها، وهل يؤخذ بقول أم الولد، أو بقول المرضعة؟","title":"شروط ثبوت الرضاعة","answer":"الجواب: لا بد أولًا من ضبط الرضاع، وأن يكون خمس أو أكثر، فإذا شكت المرضعة؛ فلا عبرة بقولها، إذا شكت ما تدري هل هي ثلاث أو ثنتين أو أربع أو خمس ما يكون كلامها معتبرًا، ولا يثبت الرضاع مع الشك، فلا بد مثل ما جاء في حديث عائشة لا بد من خمس معلومات في الحولين، لا رضاع إلا في الحولين. ثم لا يقبل قولها ولا قول غيرها إلا إذا كانت عدل، إذا كانت المرأة عدلة، معروفة بالثقة، ما هي بكذوب ولا فاسقة، أما إذا كانت كذوب أو معروفة بالفسق؛ فلا يقبل قولها، سواء كانت مرضعة، أو غير مرضعة.","link":"https://binbaz.org.sa/fatwas/3383/شروط-ثبوت-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1700.mp3","categories":["الرضاع"]},{"id":7381,"question":"إذا رضع معي من أمي ولد، ووالد الولد أخذ امرأة أخرى، وأنجب منها بنتًا، فهل يجوز لي أن أتزوجها؟","title":"الأحكام المترتبة على الرضاعة","answer":"الجواب:  إذا رضع من أمك ولد، وصار رضاعًا تامًا خمس رضعات، صار أخًا لك هذا الولد، أما أبوه إذا تزوج امرأة، وأنجب منها بنتًا، فهذه البنت ما هي أخت لك، هذه بنت زوجة غير أمك، هذا ولد صار أخًا لك؛ لأنه رضع من أمك، ورضع من لبن زوج أمك، وهو أبوك، أما أبو الولد الأجنبي، فما له تعلق بهذا، إنما هذا الولد الذي رضع من أمك يكون الذي رضع من أمك معك، من أمك يكون أخًا لك، وتكون بناته أنت عمهن.  أما والد الطفل ما لك ولأولاده أجناب، فلك أن تأخذ بنت هذا الرجل التي هي أخت الراضع معك، هي أخته ليست أختا لك، ولكنها بنت أبي هذا الراضع، وأما هو صار أخًا لك؛ لأنه رضع من أمك، لا لأنه ولد فلان، بل لأنه رضع من أمك، ويكون جميع أولاد الزوج الذي هو صاحب اللبن إن كان أباك فهم إخوة لك، وإن كان زوجًا لأمك فأولاده الذين حصلوا من زوجة أخرى يكونوا إخوة لك من الأب، أما والد الطفل الذي رضع منك فأجنبي هو وأولاده. السؤال: لذلك يجوز أن يتزوجها؟ الجواب: نعم أجنبي.","link":"https://binbaz.org.sa/fatwas/3474/الاحكام-المترتبة-على-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1778.mp3","categories":["الرضاع"]},{"id":7382,"question":"رضعت بنت عمي معي من والدتي قبل اكتمال الحولين، وكان الرضاع في جلسة واحدة، رضعت حتى أوشكت أن تخلص الثدي، وكان الرضاع عن طريق الخطأ في الليل، وعندما عرفت والدتي التي ترضعها؛ سحبت الثدي، ولم تتذكر شيئًا عن تردد البنت على الثدي، هي ترددت، أم استمرت، حتى سحبت الثدي منها، وهذا حصل مرة واحدة فقط، فهل يجوز أن أتزوج بنت عمي، أفيدوني جزاكم الله خيرًا؟","title":"الرضاع الذي يحصل به التحريم","answer":"الجواب: لا بد من الرضاع الذي يحصل به التحريم أن تكون الرضعات خمسة، ولو في مجلس واحد، وصفة ذلك: أن يمسك الطفل الثدي، ويمتص اللبن، وتعرف المرضعة أنه امتص اللبن، وأنه ذهب إلى جوفه، فإن استمر؛ فهذه واحدة، فإذا قطع الثدي وانفصل الثدي، ثم عاد؛ صارت ثانية، وهكذا حتى يكمل الخمس حال كونه في الحولين؛ لما ثبت عنه -عليه الصلاة والسلام- أنه قال: لا تحرم الرضعة ولا الرضعتان، ولا الإملاجة ولا الإملاجتان، ولا المصة ولا المصتان رواه مسلم في الصحيح. وثبت عن عائشة -رضي الله عنها- قالت : \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي الرسول ﷺ والأمر على ذلك\" خرجه مسلم في صحيحه، والإمام الترمذي في جامعه وهذا لفظ، وفي لفظ آخر: \"فتوفي رسول الله ﷺ وهي فيما يقرأ من القرآن\".  وفي حديث عائشة أيضًا أن النبي ﷺ قال لسهلة: أرضعي سالمًا خمس رضعات تحرمي عليه فلا بد من خمس في مجلس، أو مجالس، أو ما هو أكثر من ذلك، لكن أقل شيء خمس في مجلس، أو في أيام، أو في شهور متى استكمل خمسًا؛ صار ولدًا للمرضعة، وصار أخًا لأولادها، وصار ولدًا لزوجها، وصار أخًا لأولاد زوجها، وصار إخوة المرأة أخوالًا له، وأخواتها خالات له، وصار إخوان الرجل أعمامًا له، وأخواته عمات له، وهكذا لقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب والله قال في القرآن -جل وعلا-: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23].  أما هذه الصورة التي وقعت أنه امتص الثدي، ثم أطلقت منه، ولم تعرف شيئًا عن ذلك إلا هذه المصة، هذا لا يحرم، هذه لا تحرم، هذه تعتبر رضعة واحدة كونه امتص الثدي واستمر حتى عرفت أنه ليس ولدها، فجذبت الثدي منه، ولم تضبط عليه خمس رضعات، فهذا لا يكون ولدًا لها، ولا يعتبر رضاعا معتمدًا حتى يكمل خمس رضعات، يمتص اللبن، ويذهب إلى جوفه اللبن، ثم ينفصل، ثم يعود ويمتص اللبن، ويذهب إلى جوفه، ثم ينفصل ثم يعود، وهكذا في يوم، أو أيام، أو جلسات، أو في أشهر نعم.","link":"https://binbaz.org.sa/fatwas/3469/الرضاع-الذي-يحصل-به-التحريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1773.mp3","categories":["الرضاع"]},{"id":7397,"question":"ماتت أمي وأنا صغير، فأرضعتني امرأة مع ابنة لها فترة طويلة، ثم سافرت وتغربت عنهم أكثر من ثمان عشرة سنة، وبعد عودتي علمت أنها تزوجت، وسكنت في قرية أخرى، لا أعرف مكانها، وأنا أود أن أزورها، ولكن لا أعرفها، ولا تعرفني لطول المدة التي تغربت فيها، وأنا أخشى من عقوبة قطع الرحم، ووالداها كبيران في السن، وشيخان مسنان، أرجو إفادتي كيف أستطيع زيارة أختي، وهل علي إثم من هذه القطيعة، أم لا؟","title":"ما ينبغي نحو الأقارب من جهة الرضاعة","answer":"الجواب: ليست الرضاعة رحمًا، ولكن يُحسن للمرضعة، وتكرم، وليست رحمًا لو ما زرتها، ولا جئتها ما عليك بأس، الرحم القرابة: أمك من النسب، وخالتك، وعمتك، وأخواتك، وبنات عمك، أما المرضعة، وأولاد المرضعة، وقرابات المرضعة فليسوا رحمًا، وإنما لهم ما تيسر من الكرامة بإرضائها والإحسان إليها، فإذا عرفت محلها وزرتها من باب التقدير والاعتراف بإحسانها إليك؛ فهذا حسن وإلا ما يضرك، ولا تسمى قاطعًا، وليست قطيعة رحم.","link":"https://binbaz.org.sa/fatwas/3478/ما-ينبغي-نحو-الاقارب-من-جهة-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1782.mp3","categories":["الرضاع"]},{"id":7466,"question":"هنا سؤال من السائل (ع. ت. س) يقول: عقد رجل على امرأة فطلقها قبل أن يدخل بها، فهل تجوز لابنه من بعد طلاقه لها؟","title":"حكم زواج الابن بزوجة أبيه المطلقة قبل الدخول بها","answer":"الجواب: لا، إذا طلق الرجل امرأة حرمت على جميع ذريته؛ من أولاده وأولاد بنيه وأولاد بناته؛ لأنها زوجة أبيهم وإن لم يدخل بها؛ لأن الله ما علق .... بالدخول، قال سبحانه: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ إِلَّا مَا قَدْ سَلَفَ [النساء:22] فحرم نكاح زوجات الآباء مطلقاً، والأب يدخل فيه أبوه القريب وجده وأبو أمه وآباء أمه كلهم؛ كل آبائه من جهة الأم ومن جهة الأب، زوجاتهم محرمة عليه وهو محرم لهم في الآية الكريمة وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22] هذا يعم المدخول بها وغير المدخول بها، وهذا محل إجماع عند أهل العلم ليس فيه خلاف.\nوهكذا العكس؛ الابن، حلائل الأبناء يحرمن على الآباء مطلقاً، ولو لم يدخل بها الابن، إذا تزوج رجل امرأة ثم مات عنها قبل الدخول بها أو طلقها قبل الدخول بها حرمت على آبائه وأجداده كلهم؛ لأن الله قال: وَحَلائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلابِكُمْ [النساء:23] ولم يقل: اللاتي دخلتم بهن. نعم.","link":"https://binbaz.org.sa/fatwas/4187/حكم-زواج-الابن-بزوجة-ابيه-المطلقة-قبل-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_002/00203.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7490,"question":"سماحة الشيخ! أول سؤال في هذا اللقاء وردنا من اليمن، من أحد الإخوة الذي رمز باسمه بـ (ش. ف. ك) يقول: إذا تزوج رجل امرأة ثم ثبت أن جدتها أم أمها أرضعته سنة كاملة بلبن خفيف وهي عجوز، قد مات زوجها لمدة طويلة، فهل يبطل هذا النكاح؟ أفتونا مأجورين.","title":"حكم من تزوج بامرأة ثم ثبت أن جدتها أرضعته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفقد ثبت في الكتاب العزيز والسنة المطهرة: أن الرضاع يحرم به ما يحرم من النسب، وقد بين الله في كتابه الكريم تحريم الأمهات من الرضاع والأخوات من الرضاع، وقد ثبت في السنة عن رسول الله عليه الصلاة والسلام أنه قال: يحرم من الرضاع ما يحرم من النسب فعم ذلك جميع المحرمات من النسب، فالأم من الرضاع، والبنت من الرضاع، والأخت من الرضاع، وبنت الأخ من الرضاع، وبنت الأخت من الرضاع، والعمة من الرضاع، والخالة من الرضاع، كلهن محرمات، كما أنهن محرمات من النسب، بنص رسول الله عليه الصلاة والسلام، فهذه المسألة التي ارتضع فيها إنسان من جدة زوجته؛ أم أمها يكون بذلك خالاً لها أخا أمها، إذا كان أرضعته العجوز سنة كاملة، بل يكفي أنها أرضعته خمس رضعات، إذا أرضعته خمس رضعات ولو في مجلس واحد فإنه يكون بذلك خالاً لزوجته؛ أخاً لأمها، فتحرم عليه؛ لأن بنت الأخت حرام من النسب، فهكذا تكون حرام من الرضاع بنص الرسول عليه الصلاة والسلام وبإجماع أهل العلم، ولو أنها عجوز كبيرة، ولو أنها ليست ذات بعل قد مات بعلها من مدة طويلة، فإن ظهور اللبن فيها يحرم من أرضعته به، فتكون هذه الزوجة بنت أخت الزوج، ويكون خالها، فتحرم عليه بذلك، وتكون العجوز أماً لهذا الزوج وجدة لأولاده من هذه الزوجة ومن غيرها؛ لأنه صار ولداً لها، بهذا الرضاع، ولو أنه خفيف ما دام لبناً يغذيه يتغذى به، فإنه يحرم به ما يحرم من النسب، ولو أنها ليست ذات بعل في الوقت الحاضر، حتى ولو كانت شابة على الصحيح؛ لم توطأ ولم تحمل، إذا درت باللبن وأرضعت صار أماً للرضيع، وصار إخوتها أخوالاً له، وخواتها خالات له، واشتراط أن تكون المرأة قد حملت ليس بجيد، أو وطئت ليس بجيد، أما هذه التي قد حملت وولد لها وقد مات بعلها من قديم، هذه تامة فيها الشروط عند أهل العلم، فقد حملت وقد ولدت، فهي على كل حال لبنها مؤثر، ولو أنها قد مات زوجها من مدة طويلة، فهذا اللبن الذي أرضعت به هذا الرجل يكون به خالاً لزوجته، فتحرم عليه زوجته. نعم.","link":"https://binbaz.org.sa/fatwas/4451/حكم-من-تزوج-بامراة-ثم-ثبت-ان-جدتها-ارضعته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_006/00601.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7560,"question":"السؤال الخامس يقول: إذا امتلكت مبلغاً من المال عن طريق حلال، فأيهما أفضل: أن أشتري بها كتب علم وأتصدق بجزء من المال، أم أتصدق بالمال جميعاً؟","title":"أفضلية اقتناء كتب العلم على الصدقة","answer":"الجواب: إذا كان عنده مال وهو يحتاج إلى كتب العلم فكتب العلم أولى، يشتري كتب العلم حتى يستفيد منها، أو عنده من يحتاج إليها في بلد، يحطها في مكتبة يستفيد منها طلبة العلم، فكونه يشتري كتباً تنفع الناس مثل الصحيحين، مثل السنن الأربع، مثل المغني، مثل غيرها من الكتب النافعة.. تفسير ابن كثير ، تفسير البغوي ، تفسير ابن جرير .. إلى غير ذلك من الكتب المفيدة، كونه يشتري بها كتب مفيدة في مكتبته يحتاجها هو أو يحتاجها أولاده أو إخوانه طلبة العلم، أو يجعلها في مكتبة المسجد، أو في المكتبات العامة يرد إليها الناس ويستفيدون منها الناس، هذا أولى من الصدقة، وأما إذا كان ما هناك حاجة إلى المكتبة؛ لأن هناك كتب تغني عن شرائه هو، فإذا تصدق بها على الفقراء من أقاربه أو غيرهم فهذا حسن، هذه قربى إلى الله جل وعلا، لكن الكتب إذا كانت لها حاجة أنفع وأفضل؛ لأن نفعها أعظم. نعم.","link":"https://binbaz.org.sa/fatwas/4564/افضلية-اقتناء-كتب-العلم-على-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01405.mp3","categories":["الرضاع","العالم والمتعلم"]},{"id":7562,"question":"الرسالة هذه من أحد السائلين وهو خلف سرور من جدة أيضاً، ويسأل عن زواج الشغار، يقول: جئت لأحد الإخوان وطلبت منه أن يزوجني بنته وقال لي: زوجني بنتك ولا عندي مانع، وبقيت في حيرة من الأمر، أرجو من فضيلتكم توضيح الطريق الصحيح، وهل في هذا الشيء حلال أم حرام؟ وفقكم الله لعمل الخير، وجزاكم الله خيري الدنيا والآخرة، شاكرين لكم وللعاملين على هذا البرنامج؟","title":"حكم نكاح الشغار","answer":"الجواب: نكاح الشغار، ويسميه بعض الناس نكاح البدل لا يجوز، وهو أن يقول: زوجني بنتك، أو زوج ولدي أو أخي أو ابن أخي وأزوجك بنتي، أو أزوج ولدك، أو ابن أخيه، هذا لا يجوز، هذا هو الشغار الذي نهى عنه النبي ﷺ وزجر عنه في عدة أحاديث، الرسول ﷺ زجر عن نكاح الشغار، وهو ما يسمى: نكاح البدل، فلا يجوز أبداً لأي مسلم أن يتزوج نكاح الشغار ولو بالمهر المعتاد، لا يجوز هذا؛ لأن الشرط نكاح في نكاح، وعقد في عقد، فهو من جنس بيعتين في بيعة، ولأنه يفضي إلى فساد كبير إلى نزاع وخصومات، وإلى إجبار النساء وظلم النساء من جهة أوليائهن لمصالحهم أو مصالح أولادهم، أو أبناء إخوتهم أو نحو ذلك، ثم يفضي إلى النزاع بعد ذلك، كلما تنازع زوج مع زوجته خرجت الأخرى.\nفالمقصود أنه منكر، ولهذا الرسول نهى عنه عليه الصلاة والسلام، ويكفي هذا، كون الرسول ﷺ نهى عنه يكفي هذا، ولكن مع هذا كله يقع أهله في مشاكل كثيرة، وهذا من شؤم الذنوب وشؤم المعصية، معصية الرسول ﷺ، فإن المعصية لها عواقب وخيمة، فالذين يقعون في الشغار ويعصون الرسول ﷺ تقع لهم مشاكل مع نسائهم في الغالب.\nفالواجب على المسلم أن يحذر ذلك، وأن لا يتزوج بالشغار أبداً، والنكاح بالشغار غير صحيح. نعم.","link":"https://binbaz.org.sa/fatwas/4566/حكم-نكاح-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01407.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":7598,"question":"الرسالة التي بين يدينا وصلت من سوريا من دمشق من المستمع أمين وحالي يقول: إنني أسألكم هذا السؤال يا شيوخنا الكرام! أبقاكم الله لنا لتسلكوا بنا الطريق الصحيح، وسؤالي هو: لي ابنة عم أصغر مني، وقبل أن أصير أنا وهذه البنت لي أخت أكبر مني رضعت على أخ البنت وهو أكبر من البنت بكثير، وتوفي الولد الذي رضعت عليه أختي من صغره وأختي لا زالت طيبة ولها أولاد وبنات، يقول: والمهم أنا والبنت ليس رضعنا من بعضنا أبداً ولكن أختي وأخيها قبل أن نصير أنا والبنت رضعت أختي على أخي، فهل يجوز الزواج من ابنة عمي، أفيدوني أفادكم الله؟","title":"حكم زواج رجل من امرأة رضعت أخته من أمها","answer":"الجواب: لا حرج عليك أيها السائل أن تتزوج من ابنة عمك؛ لأن ليس بينكما رضاع ولا قرابة، وإنما الرضاع حصل من أختك الكبيرة مع أخيها الكبير من أمها فلا يضرك ذلك، رضاع أختك لا يمنعك من الزواج ما دمت أنت لم ترضع من أم البنت، والبنت ما رضعت من أمك ولا من زوجة أبيك ولا من أخواتك، فأنت لا حرج عليك في نكاح بنت عمك المذكورة؛ لأنك ليس بينك وبينها قرابة تمنع ولا رضاعة تمنع، أما كون أختك ارتضعت من أمها فهذا لا يحرمها عليك. نعم.","link":"https://binbaz.org.sa/fatwas/4651/حكم-زواج-رجل-من-امراة-رضعت-اخته-من-امها ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_020/02006.mp3","categories":["الرضاع"]},{"id":7601,"question":"سماحة الشيخ! هذه الرسالة وردتنا من المستفتي على يقول مفرح سعيد القحطاني من الرياض: أنا شاب يوجد لدي مشكلة وهي أن أخي الكبير رضع من ثدي عمتي أخت أبي، وابنها رضع مع أخي الذي أكبر مني سناً، ثم جاء بنت على عمتي، ورغبت الزواج منها إلا أنني متردد بسبب موضوع الرضاع، وأنني أرجو إفادتي هل يجوز لي الزواج من هذه الفتاة أم لا؟ الشيخ: أعد السؤال.المقدم: يقول: إن أخي الكبير رضع من ثدي عمتي أخت أبي، وابنها رضع مع أخي الذي أكبر مني سناً، ثم جاء بنت على عمتي -يعني من عمتي- ورغبت الزواج منها إلا أنني متردد بسبب موضوع الرضاع، وأنني أرجو إفادتي هل يجوز لي الزواج من هذه الفتاة أم لا، مع العلم بأنني لم أرضع أنا وإنما هو أخي الكبير وأخوها الكبير منها، والله يحفظكم ويرعاكم؟","title":"حكم الزواج بأخت الأخ من الرضاع","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: \nفهذا الرضاع الذي ذكره السائل لا يمنعه من تزوج ابنة عمته، كون أخيها رضع من أمه، وكون أخاه رضع من أمها لا يمنعه من تزوجها، مادام هو.. مادام السائل لم يرضع من أمها وهي لم ترضع من أمه ولا من أخواته، ولا من زوجة أبيه، فليس بينهما رضاع يمنعها، الحاصل أنه لا بأس من تزوجه إياها؛ لأن رضاع أخيه من أمها لا يحرمها عليه، وهكذا رضاع أخيها من أمه لا يحرمها عليه؛ لأنها هي لم ترضع من أم الخاطب وهو لم يرضع من أمها، فلا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4654/حكم-الزواج-باخت-الاخ-من-الرضاع ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_021/02101.mp3","categories":["الرضاع"]},{"id":7618,"question":"سماحة الشيخ! هذه الرسالة وردتنا من محافظة الأنبار من الجمهورية العراقية، ومن الطالب: صبار حمادي ، يقول في رسالته بعد الثناء على العلماء المشاركين في هذا البرنامج: أرضعتني امرأة عندما كنت طفلاً بشهادة تلك المرأة ووالدتي رضعات غير معلومة، هل هن واحدة أو ثلاثة أم أقل أو أكثر، وكان الرضاع في يوم واحد فقط من العصر وحتى ميعاد النوم في الليل، فهل يحق لي الزواج من أحد بناتها، وخصوصاً البنت الأخيرة التي أنجبتها، نرجو الإفادة وفقكم الله؟","title":"الحكم حال الشك في عدد الرضعات المحرمات","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: يحرم من الرضاع ما يحرم من النسب وقال عليه الصلاة والسلام: لا تحرم الرضعة ولا الرضعتان وقال أيضاً فيما ثبت عن عائشة رضي الله عنها قالت: كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك وقال عليه الصلاة والسلام: إنما الرضاعة من المجاعة، لا رضاعة إلا في الحولين إلى غير ذلك. هذه الأحاديث وما جاء في معناها تدلنا على أنه لا بد من خمس رضعات فأكثر، فإذا كانت المرأة المرضع تشك في الرضاع الواقع منها هل هو واحدة أو أكثر من ذلك، فإنه لا يحصل به تحريم الرضاع ولا تنشر به الحرمة، ولا حرج أن ينكح بعض بناتها؛ لأنها لم تثبت أنها أم له، حتى يثبت أنها أرضعته خمس رضعات أو أكثر، وبهذا يعلم السائل أنه لا حرج عليه في نكاح ابنة المرأة التي أرضعته هذا الرضاع الذي غير معروف، وإن ترك ذلك من باب ترك الشبهة، ومن باب (دع ما يريبك) فلا حرج.. حسن، وإلا فليس عليه حرج في ذلك، إنما من باب ترك الشبهات وترك الريبة، إذا ترك ذلك فهو حسن، عملاً بقول النبي ﷺ: دع ما يريبك إلى ما لا يريبك فإنها قد تكون أرضعته عدة رضعات بلغت الخمس لكن لم تحفظ ذلك، فإذا ترك ذلك احتياطاً وبعداً عن الشبهة فهو مشكور ومأجور، وقد قال عليه الصلاة والسلام: من اتقى الشبهات فقد استبرأ لدينه وعرضه. نعم.","link":"https://binbaz.org.sa/fatwas/4671/الحكم-حال-الشك-في-عدد-الرضعات-المحرمات ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_024/02401.mp3","categories":["الرضاع"]},{"id":7641,"question":"هذه رسالة وردتنا من مرسلها محمد بن علي سلمان يقول: صاحب الفضيلة الرئيس العام لإدارات البحوث العلمية والإفتاء والدعوة والإرشاد، سماحة الشيخ عبد العزيز بن عبد الله بن باز الموقر، السلام عليكم ورحمة الله وبركاته، الموضوع أحسن الله عملك أنا محمد بن علي سلمان الأحمدي المالكي من قضاء بني مالك تابع لجيزان، جزاكم الله خير الجزاء لما لكم من فعل الخير وإيضاحه وطمس الشر ومعالمه، لي أخ من الرضاعة وله ثلاث بنات، هن: معزيه بنت حسن وفاطمة بنت حسن ، وجميلة بنت حسن بن سالم بن قاسم ، وأخي المذكور متوفى قبل والده، وصرنا عصبة، هل البنات لي محرم، وأجوز لهن محرم أم لا؟ أفتوني بهذا الأمر وفقكم الله، وسدد خطاكم بحفظه ورعايته، والرجاء أن تتكرموا بإذاعة هذه الفتوى في برنامج نور على الدرب، والله يرعاكم؟","title":"حكم بنات الأخ من الرضاع","answer":"الجواب: إذا كان أخو السائل قد ارتضع من أم السائل خمس رضعات فأكثر، أو السائل ارتضع من أمه وهو حسن هذا، إذا ارتضع من أمه خمس رضعات فأكثر فإنه يكون أخاه، وتكون بناته بنات أخ من الرضاعة محارم، فإذا تحقق هذا بأن كانت أم السائل أرضعت حسن المذكور فإنه يكون أخاه من الرضاعة، أو زوجة أبيه أرضعت حسن المذكور خمس رضعات فأكثر، أو أم حسن أرضعت السائل خمس رضعات فأكثر، فإن السائل يكون أخاً لـحسن هذا، ويكون عماً لبناته وعماً لبنات بناته وهكذا، يكون عم ويكون هو عمهن من الرضاع، ويكون محرماً لهن؛ لقول النبي عليه الصلاة والسلام: يحرم من الرضاع ما يحرم من النسب.\nأما إن كانت الرضعات أقل من خمس أو كانت الرضعات فيها شك لا يدرى هل ارتضع أم لم يرتضع، وإنما يقال: إنه أخوه من الرضاعة من غير جزم، هذا لا يكن محارم للسائل، ولا يكون عماً لهن إلا برضاع ثابت، بشهادة المرضعة الثقة أو شهادة غيرها من الثقات أن أم حسن أرضعته أو أن أمه أرضعت حسن ، فصار أخاً له أو زوجة أبيه، أو زوجة أبي حسن أرضعته، هذا هو الحكم في هذه المسألة.\nفالواجب التثبت في الأمر، حتى إذا ثبت الرضاع فإنه يكون عماً لبنات حسن المذكور، وهكذا بناتهن وبنات أولادهن هو عمهن.","link":"https://binbaz.org.sa/fatwas/4774/حكم-بنات-الاخ-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_035/03502.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7702,"question":"هذه رسالة وردتنا من الشيخ حمدان حامد مسعود العضلي يقول في رسالته عن الرضاعة: تزوج رجل من امرأتين وأنجب بنات من كلتا المرأتين، وهناك رجل بعيد عنهم تزوج كذلك بامرأة، ووضعت زوجته وتركت طفلاً، فأحضره إلى الرجل الأول ليرضعه مع بناته، وفعلاً أعطاه للزوجة الأولى ورضع معها، والسؤال هو: هل يحق لهذا الابن أن يتزوج من بنات المرأة الثانية التي لم يرضع معها الطفل، أفيدونا أفادكم الله، حيث أننا في حيرة من أمرنا، وفقكم الله وسدد خطاكم؟","title":"حكم من له زوجتان ورضع طفله من إحداهما، وأراد التزوج من بنات الثانية","answer":"الجواب: هذا الطفل إذا كان ارتضع من إحدى الزوجتين خمس رضعات فأكثر فإنه يكون ابناً للرجل.. لزوج المرأتين، يكون ابناً له، ويكون جميع أولاد الرجل إخوة له، إذا كان ارتضع من إحدى الزوجتين خمس مرات خمس رضعات فأكثر، فإنه بهذا يكون ولداً له، وتكون الزوجة التي أرضعته أماً له من الرضاع، وتكون الزوجة الثانية زوجة أبيه من الرضاع، وجميع أولاد الزوجتين إخوة له من الرضاع، فليس له أن ينكح لا بنات هذه ولا بنات هذه، وهكذا جميع أولاد الزوج هذا من جميع النساء قبل وبعد يكونوا إخوة له، وهكذا بنات الزوجتين، بنات الزوجة التي أرضعته من قبل إخوة له.. أخوات له لا ينكح منهن أحداً، أما الزوجة الثانية التي ما أرضعته إن كان عندها بنات من غير هذا الزوج، بنات سابقات من زوج آخر قبل فلا بأس، ما يكن أخوات له، أما بناتها من هذا الزوج فإنهن إخوة له؛ لأنه صار ولداً لهذا الزوج بالرضاع، فجميع أولاد الرجل هذا إخوة له ذكورهم وإناثهم، إذا كان الرضاع خمس مرات.. خمس رضعات فأكثر في الحولين، حال كون الطفل في الحولين، أما إن كان الرضاع أقل من خمس رضعات كواحدة أو ثنتين لا، لا يكون لها حرمة الرضاع، لا ينشر الحرمة ولا يعتبر؛ لقول النبي ﷺ: لا تحرم الرضعة ولا الرضعتان، ولحديث عائشة رضي الله عنها عند مسلم: كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك فلا بد من خمس رضعات فأكثر..","link":"https://binbaz.org.sa/fatwas/4901/حكم-من-له-زوجتان-ورضع-طفله-من-احداهما-واراد-التزوج-من-بنات-الثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_029/02904.mp3","categories":["الرضاع"]},{"id":7703,"question":"لكن إذا رضع مثلاً رضعة أو رضعتين لا يجوز أن يأخذ منهم ولا يكون محرم لهم؟","title":"حكم الرضعة والرضعتين في التحريم","answer":"الجواب: لا، لا بأس أن يأخذ، ما يصير إخوة له، ما يكن إخوة له بنات الزوجتين المرأتين، ولا تكون المرأة التي أرضعته أماً له، ولا الزوج أباً له، إذا كان رضع قليل.. مرة أو مرتين ما يعتبر، لا بد من خمس رضعات.. \nالمقدم: ويأخذ منهم سماحة الشيخ؟\nالشيخ: لا بأس، وإن ترك هذا للشبهة لا بأس، إن ترك هذا للشبهة لا مانع، لكن لا يحرمن عليه إلا بخمس رضعات. نعم.","link":"https://binbaz.org.sa/fatwas/4902/حكم-الرضعة-والرضعتين-في-التحريم ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_029/02905.mp3","categories":["الرضاع"]},{"id":7748,"question":"هذه رسالة المرسل محمد ماجد سليمان ، يقول في رسالته: سؤالي حول وطء الزوجة في دبرها، فقد قرأت في كتاب المغني لـابن قدامة الجزء السابع، صفحة رقم اثنين وعشرين فصل: ولا يحل وطء الزوجة في الدبر في قول أكثر أهل العلم منهم علي وعبد الله وأبو الدرداء وابن عباس وعبد الله بن عمرو وأبو هريرة ، وبه قال سعيد بن المسيب وأبو بكر بن عبد الرحمن ومجاهد وعكرمة والشافعي وأصحاب الرأي وابن المنذر ، ورويت إباحته عن ابن عمر وزيد بن أسلم ونافع ومالك ، وروي عن مالك أنه قال: ما أدركت أحداً أقتدي به في ديني يشك في أنه حلال، وأهل العراق من أصحاب مالك ينكرون ذلك، واحتج من أجله بقول الله تعالى نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ [البقرة:223]، وقوله سبحانه: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ [المؤمنون:5-6]، فما رأي الدين في قول الذين أباحوا ذلك واحتجاج الإمام مالك بالآيتين الكريمتين؟ أرجو بيان حكم الدين بذلك، وفي قول الإمام مالك وابن عمر وزيد بن أسلم ونافع ؟! والسلام عليكم ورحمة الله.","title":"حكم وطء الزوجة في الدبر","answer":"الجواب: هذه المسألة مما قامت الأدلة الصحيحة عن رسول الله عليه الصلاة والسلام بالدلالة على تحريمها، وهي مسألة: الوطء في الدبر، هذه هي اللوطية المعروفة، ويقال لها: اللوطية الصغرى، فهي محرمة، هذه المسألة محرمة ومنكر ومن الكبائر، وقد جاءت الأحاديث عن رسول الله ﷺ تحذر من ذلك، وتبين أن وطء الدبر من الزوجة أمر محرم ومنكر، وبه قال عامة أهل العلم وجمهورهم للأحاديث الواردة في ذلك منها قوله عليه الصلاة والسلام: لا ينظر الله إلى رجل أتى رجلاً أو امرأة في دبرها رواه الترمذي والنسائي بإسناد صحيح وأحمد رحمة الله عليهم، ومنها قوله عليه الصلاة والسلام: إن الله لا يستحي من الحق، لا تأتوا النساء في أدبارهن -وفي لفظ: في أعجازهن، ويروى عنه عليه الصلاة والسلام: ملعون من أتى امرأة في دبرها في أحاديث كثيرة كلها دالة على تحريم الوطء في الدبر.\nأما قوله جل وعلا: نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُم [البقرة:223]، فهي كما دلت عليه الأحاديث؛ الحرث: هو الفرج، هذا محل الحرث، هو القبل، أما الدبر فليس محل حرث، ولكنه محل قذر.. محل غائط، فليس محل الحرث، وإنما حرث الإنسان قبل زوجته.. محل الولادة.. محل البذر يطؤها فيه ... تحصل البذرة من المني ثم إذا أراد الله شيئاً انعقد ذلك المني مع منيها وجاء الولد، فالقبل هو محل الحرث وليس الدبر، الدبر محل القذر.. محل النجاسة، والقبل هو محل الحرث، وفي الحديث الآخر: مقبلات.. لما قالت اليهود: إن الرجل إذا أتى امرأته من دبرها في قبلها كان الولد أحول، أكذبهم الله وأنزل قوله سبحانه: نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُم ، قال النبي ﷺ: إذا كان في صمام واحد يعني: في القبل، هو الصمام، يعني: محل الحرث.\nفالحاصل أن الأحاديث الصحيحة وأقوال أئمة العلم من الصحابة ومن بعدهم كلها تدل على تحريم الوطء في الدبر، أما ما يروى عن ابن عمر أنه أجازه فهو غلط على ابن عمر ، والصواب أنه لا يثبت عن ابن عمر ، وإنما أراد ابن عمر أنه يجوز أن تؤتى من قفاها في قبلها، يعني: يأتيها من دبرها في قبلها، يعني يكون إلى الدبر وهي مثلاً على جنبها أو كالساجدة فيأتيها من جهة قفاها في قبلها في الفرج لا في الدبر نفسه، فغلط بعض الناس فظن أنه يجيز الوطء في الدبر، وإنما يأتيها مدبرة في قبلها لا في دبرها، هذا هو الذي أراده ابن عمر وغيره ممن نقل عنه ذلك، ولو فرضنا أن بعض التابعين أو من بعدهم أجاز ذلك صريحاً وتوهم وغلط في هذا فقوله مردود وباطل لا يلتفت إليه؛ لأنه مصادم للآية الكريمة ومصادم للأحاديث الصحيحة، وكل قول يخالف ما قاله الله ورسوله فهو واجب الاطراح وواجب الترك، ولا يجوز أن تعارض به السنة الثابتة عن رسول الله عليه الصلاة والسلام، كما لا يجوز أن يعارض به ما قاله الله عز وجل، فالله قال: نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُم فالحرث هو محله القبل فقط، وكذلك قال النبي ﷺ: إن الله لا يستحي من الحق، لا تأتوا النساء في أدبارهن وقال: لا ينظر الله إلى رجل أتى رجلاً أو امرأة في دبرها، ويروى عنه عليه الصلاة والسلام: ملعون من أتى امرأة في دبرها، وقد جاء في حديث ابن عمر ومن حديث عبد الله بن عمرو بسند جيد موقوفاً ومرفوعاً أنه سئل عن الوطء في الدبر فقال: (اللوطية الصغرى).\nفالحاصل أنه محرم بالنص وبقول أهل العلم الذي هو كالإجماع، وما يروى عن ابن عمر أو زيد بن أسلم أو مالك كله لا أصل له ولا صحة له، ولا يثبت عن مالك إباحته فيما نعلم، وإنما أوهام وأغلاط من بعض الرواة عنه والمنتسبين إليه، أما المحفوظ عنه رحمه الله فهو المنع وعدم جواز الوطء في الدبر، وهكذا المحفوظ عن ابن عمر هو المنع وليس الجواز، وإنما توهم بعض الناس في بعض الروايات عنه أنها تؤتى من دبرها في قبلها، فظنوا أنه يجيز الوطء في الدبر، وإنما أراد أن تؤتى من جهة الدبر في القبل نفسه.. في الفرج نفسه لا في الدبر الذي هو محل القذر، هذا هو الحق، وهو كالإجماع من أهل العلم، والخلاف الذي في هذا عن بعض السلف شاذ لا يلتفت إليه ولا يعول عليه بل هو منكر وباطل. نعم..","link":"https://binbaz.org.sa/fatwas/4945/حكم-وطء-الزوجة-في-الدبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_042/04203.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":7762,"question":"من جيزان بعث بهذه الرسالة (م. ن. ع) يقول: أنا إمام مسجد، ويرى الجماعة أنني أحسن أهل البلد فقهاً في الدين، وليس ذلك من جودتي وعلمي، ولكن هذا عائد لقلة الدارسين في بلدتنا، ويأتيني أسئلة متعددة في الرضاعة وأفتي فيها، ولكن أحياناً أشك في هذه الفتوى، فهل هناك قاعدة مطردة في وجوه الرضاعة من حيث الحل والتحريم والزواج؟ أرجو عرض رسالتي هذه على سماحة الشيخ عبد العزيز بن باز ؟","title":"قاعدة شاملة في الرضاع","answer":"الجواب: الواجب على طالب العلم أنه لا يفتي إلا عن بصيرة، وألا يقول على الله بغير علم؛ لأن الله حرم القول عليه بغير علم، فلا يجوز للمسلم أن يفتي إلا بعلم، لا في الرضاع ولا في غيره، وطالب العلم أولى الناس بأن يتحرى ويطالع كتب أهل العلم، ويسأل أهل العلم حتى يكون على بينة فيما يريد الفتوى فيه من رضاع أو غيره.\nفالسائل يجب عليه أن يعتني بأحكام الرضاع ويراجعها في أمهات الكتب، ويراجع كلام أهل العلم ويتبصر ويراجع الأحاديث مثل: بلوغ المرام، ومثل: منتقى الأخبار، وهكذا الكتب المفيدة التي شرحت أحكام الرضاع حتى يكون على بصيرة، فإذا عرف الأحكام الشرعية في الرضاع أفتى.\nوالخلاصة في هذا أن الرضاع المحرم الذي تحصل به الحرمة لابد فيه من أمرين: أحدهما: أن تكون الرضعات خمس مرات فأكثر، والأمر الثاني: أن يكون في الحولين، هذا الطفل في الحولين.\nفعلى المفتي أن يلاحظ هذا، فإذا كانت الرضعات خمساً أو أكثر، وكان الطفل في الحولين حين الرضاع تمت أحكام الرضاع وصارت المرضع أماً له، وأولادها إخوةً له، وأبوها جده، وأمها جدته، وهكذا كالنسب لقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب ولابد من مراعات أن تكون المرضعة ثقة التي أخبرت أو الذي أخبر عنها ثقة عدل، فالمرضعة التي ليست مضبوطة أو معروفة بالكذب أو ما أشبه ذلك مما يقدح فيها لا يعتمد على قولها أنها أرضعت فلان، وهكذا من ينقل عنها الرضاع ويشهد عليها بالرضاع لابد يكون عدل، ويقبل في هذا واحد ثقة من الرجال وثقة من النساء، ولا يقبل من ليس بثقة لا من الرجال ولا من النساء، فإذا شهدت ثقة أنها أرضعت الرجل خمس رضعات أو المرأة أرضعت خمس رضعات في الحولين؛ اعتبرت هذه الرضاعة، وصارت المرضعة أماً للرضيع، وصارت أمها وجداتها جداتٍ له، وصار أولادها إخوةً له، وصار زوجها أباً له وهكذا. نعم.\nفيجب على المفتي أن يلاحظ هذا، ثم الرضاعة لابد أن يعرف فيها الرضاع كونه يمسك الثدي ويمص اللبن ثم يطلقه، هذه رضعة، فإذا أمسك الطفل الثدي وامتص اللبن وابتلع اللبن هذه واحدة، فإذا أطلقه وعاد وامتص اللبن هذه ثانية، فإذا أطلقه وعاد هذه ثالثة وهكذا حتى يكمل خمس رضعات وإن كان في مجلسٍ واحد، وإن كان في ساعة واحدة.\nوهكذا لو كان في أيام أو في أوقات، لا بأس. نعم.\nالحاصل أنه لابد أن يهتم ويعتني ولا يتساهل، لا من جهة الرضعات ولا من جهة المرضعة، والشاهد من الرضاع، والرضاعة مثل النسب يحرم من الرضاع ما يحرم من النسب، إذا ثبت وإذا اشتبه عليه شيء لا يعجل في الفتوى، يؤجل ولا يعجل حتى يتضح له الأمر، أو يتصل بأهل العلم يسألهم أو يكتب إلى البعيد عنه يسألهم حتى يكون على بينة وعلى بصيرة ، وهذا من الاحتياط الواجب ومن الورع الواجب حتى لا يقول على الله بغير علم. نعم.\nالمقدم: طيب بالنسبة للرضاع «يحرم من الرضاع ما يحرم من النسب» لكن هل اللبن دائماً للزوج والزوجة أو للزوج فقط؟\nالشيخ: لهما جميعاً.\nالمقدم: لهما جميعاً؟!\nالشيخ: للفحل وللزوجة، ولهذا إخوان الزوج أعمام يكونوا للرضيع، وأبوه جداً للرضيع، وأولاده من زوجةٍ أخرى إخوة للرضيع أيضاً من أبيه، فهو يتعلق بالفحل والأم، فأولاد المرضعة كلهم إخوة للرضيع من هذا الزوج ومن غيره، من زوج سابق أو زوجٍ لاحق، وهكذا الزوج صاحب اللبن، أولاده من هذه المرأة المرضعة إخوة للرضيع، وأولاده من غيرها كذلك، قبلها أو بعدها إخوة للرضيع. نعم.","link":"https://binbaz.org.sa/fatwas/4969/قاعدة-شاملة-في-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_045/04504.mp3","categories":["الرضاع"]},{"id":7794,"question":"وسماحة الشيخ! نبدأ برسالة عبد الله بن حسين الحسين من حوطة بني تميم أسفل الباطن التي يقول فيها:إلى حضرة الشيخ العزيز الغالي عبد العزيز بن باز .. حفظه الله ورعاه تحية طيبة وبعد..أرفع إليكم سؤالي هذا راجياً منكم التكرم بالإجابة عليه، يقول: (س) تزوجت امرأة اسمها حصة وأتت ببنت اسمها نورة ، ثم توفي زوج حصة وتزوجت رجلاً آخر وأتت منه ببنت اسمها هند ، وتزوجت نورة وأتت أيضاً ببنت، وقامت نورة بإرضاع بنت أمها التي هي هند ، ثم توفي زوج نورة وتزوجت رجلاً آخر، فهل يصح لـهند أن تكشف لزوج أمها من الرضاعة وأختها من أمها علماً بأن هند ، رضعت من لبن الرجل نورة الأول وشكراً؟","title":"زوج الأم من النسب والرضاع محرم للبنت","answer":"الجواب: أي: صارت بنتاً لها، هند هذه التي هي أخت نورة إذا كانت نورة أرضعتها رضاعاً كاملاً وهو خمس رضعات فأكثر في الحولين، فإن هند تكون بنتاً لـنورة بنتاً لأختها الكبرى ويكون زوج نورة الجديد يكون محرماً لـهند لأنه زوج أمها بالرضاعة، فـنورة هذه تزوجت زوجاً أخيراً يكون بالنسبة إلى هند التي هي أختها يكون زوجاً لأمها من الرضاعة فيكون محرماً لها؛ لأن زوج الأم من النسب والرضاع محرم للبنت، وهند بموجب السؤال صارت بنتاً لأختها نورة الكبرى من الرضاعة، وزوج نورة يكون حينئذٍ زوج أم هند سواء كان زوجها الأول أو زوجها الآخر، المقصود: إنها صارت بنتاً لأختها نورة ، فأزواج نورة كلهم يكونون محارم زوجها الموجود أو زوجها الذي يأتي بعده، أزواج نورة أزواج لأم هند ، فتكون هند محرماً، فتكون هند محرماً لهم وهم محرم لها بسبب الرضاع، لكن بشرط أن يكون الرضاع خمس رضعات فأكثر، يعني: تكون نورة أرضعتها خمس مرات أو أكثر من خمس مرات حال كون هند في الحولين، إذا تم هذا الشرط فإن أزواج نورة يكونوا محارم لأختها هند بموجب الرضاعة. نعم.","link":"https://binbaz.org.sa/fatwas/5144/زوج-الام-من-النسب-والرضاع-محرم-للبنت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05001.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7795,"question":"المقدم: وهذا آخر سؤال فيه رسالة هذه أخرى ملاصقة للرسالة هذه هذا بعثها المرسل من بحرة عبد الرحمن محمد حزام الشيباني يقول: الحمد لله، والصلاة والسلام على أشرف المرسلين.أما بعد:أفيدوني أفادكم الله أن والدي تزوج ابنة عمه شقيقته وأخذت في حبله خمس سنوات ولم تنجب أحد فطلقها فتزوج بعدها زوجة أخرى وهي والدتي، فهل يجوز لي السلام عليها -يعني: على زوجة والده الأولى- لأنها عمتي زوجة والدي سابقاً، فهل يجوز لي السلام أم لا أفيدوني أفادكم الله وأطال في أعماركم؟","title":"حكم النظر والمصافحة لزوجة الأب بعد تطليقها","answer":"الجواب: نعم، زوجة أبيك محرم لك سواء أنجبت أم لم تنجب، زوجة أبيك -أيها السائل- محرم لك سواء أنجبت من أبيك أم لم تنجب ولو عقد عليها فقط عقداً مجرداً ولم يدخل بها فإنها محرم لك؛ لأن الله قال: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22] فزوجات الآباء والأجداد محارم لمجرد العقد، فإذا لم يدخل بها جدك أو أبوك فهي محرم لك، وإن دخل بها واجتمع بها فمن باب أولى أنها محرم لك وإن لم تنجب.\nفالخلاصة: أن زوجات الآباء والأجداد محارم سواء أنجبن من آبائك وأجدادك أم لم ينجبن، والله جل وعلا أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/5158/حكم-النظر-والمصافحة-لزوجة-الاب-بعد-تطليقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05007.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7796,"question":"أيضاً يقول المستمع عبد الله بن حسين الحسين من حوطة بني تميم: امرأة لها بنات ابن، فلما توفي زوجها -أي: الذي هو جد البنات- تزوجت رجلاً آخر، فهل يصح لبنات ابنها أن تكشف لزوجها الأخير؟","title":"حكم كشف البنات لزوج جدتهن","answer":"الجواب: إيه، لأنه زوج جدتهم، زوج الجدة وزوج الأم محرم، زوج الجدات وزوج الأم محرماً لبنات الابن وبنات البنت محرماً لهم بموجب الرضاع، وكذلك لأن هنا هم أولاد نسب ليسوا برضاع، وهي أم أبيهم من النسب ولو كانوا من الرضاعة كذلك.\nفالحاصل أنه محرم لهم، زوج الجدة محرم لأولادها وأولاد بناتها، وأولاد ابنها من جميع الوجوه سواء كانوا أولاداً من النسب أو أولاداً من الرضاعة. نعم.","link":"https://binbaz.org.sa/fatwas/5148/حكم-كشف-البنات-لزوج-جدتهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05002.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":7868,"question":"هذه الرسالة وردتنا من جيزان يقول أخوكم جابر صالح النوراي أو النوراني: أنا جابر صالح نوراي أتقدم إليكم طالب حل مشكلتي من سماحة الشيخ عبد العزيز حيث تتعلق بالرضاعة، يقول: لي بنت عم أريد أن أتجوزها ولكن والدتي أخبرتني أنها قد أرضعت أختاً لها قد ماتت، وأنا أريد أن أتجوز البنت التي لم ترضعها أمي فهل تجوز لي أم لا؟ أفيدوني جزاكم الله خيراً في الدنيا والآخرة؟","title":"حكم الزواج من أخت الأخت من الرضاع","answer":"الجواب: نعم، لا حرج عليك في زواج البنت الموجودة؛ لأن الرضاعة تتعلق بالميتة والميتة ذهبت، ورضاعها لا يسري على أختها، فالذي أرضعتها أمك توفيت وهذه لم ترضعها أمك، وأنت لم ترضع من أمها ولا من أخواتها حتى تكون خالة لك، مادام ما بينك وبينها رضاع فلا حرج في زواجها. نعم.","link":"https://binbaz.org.sa/fatwas/5325/حكم-الزواج-من-اخت-الاخت-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05612.mp3","categories":["شروط وأركان الزواج","الرضاع"]},{"id":7908,"question":"أيضاً سؤالهما الثالث والأخير، يقولان فيه: هل يجوز رضاعة الزوج لزوجته؟","title":"حكم رضاع الزوج من زوجته","answer":"الجواب: لا حرج، يعني: لو مص ثديها ما يضره، لو مص اللبن من ثديها؛ لأن رضاع الكبير لا يؤثر شيئاً عند جمهور العلم، لكن ترك ذلك أولى لا حاجة إلى هذا، يعني كونه يمص ثديها من باب المزح أو من باب المداعبة أو من باب إظهار المحبة لا يضر ذلك، لا يضر الزوجية لو شرب من ثديها لا يضر شيئاً، وهي زوجته ولا يكون ولداً لها، ولكن ترك هذا أحسن، نعم، لا سيما أن بعض أهل العلم يرى إرضاع الكبير، فلا ينبغي أن يرضع ثديها بل ترك ذلك أولى. نعم.","link":"https://binbaz.org.sa/fatwas/5397/حكم-رضاع-الزوج-من-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06206.mp3","categories":["الرضاع"]},{"id":7948,"question":"هذه الرسالة من عبد الرحمن إبراهيم أحمد يقول فيها من جمهورية مصر العربية، يقول: أريد أن أتزوج ابنة خالي ولكني أنا رضعت مع أختها الكبرى، ولكن أختها الكبرى من أم والثانية -التي يريد أن يتزوجها- من أم، هل تحل لي الذي رضعت مع أختها أم لا؟","title":"هل يجوز التزوج من ابنة خاله التي رضع مع أختها؟","answer":"الجواب: إذا كان السائل رضع من أخت المخطوبة من أبيها زوجة أبيها أو من أمها فهو أخ لها، إذا كان رضع من زوجة أبيها أو رضع من أمها فإنه يكون أخاً لها، ولو لم يكن رضع معها، ما دام رضع مع أختها التي قبلها فإنه يكون أخاً لها أو مع أختها التي بعدها كله واحد.\nالمقصود: إذا كان رضع من زوجة أبيها أو من أمها فإنه يكون أخاً لها إما من الأم وإما من الأب وإما منهما جميعاً، فلا يحل له زواجها ولو كان رضاعه مع أخت كبرى أو مع أخت صغرى. نعم.\nالمقدم: أيضاً يقول: هل تحل لأخوي الأصغر أم لا؟\nالشيخ: إذا كان أخوه لم يرضع من أمها تحل له، إذا كان لم يرضع من أمها ولا من زوجة أبيها، ما بينهما رضاع فإنها تحل له، أما الذي رضع من أمها أو رضع من زوجة أبيها فإنها تكون أختاً له. نعم. لكن لابد يلاحظ أن الرضاع لابد يكون خمس رضعات فأكثر، ولابد يكون في الحولين، لابد أن يكون الرضاع خمس رضعات مضبوطة مثبوتة، ولابد أن يكون في الحولين، أما الرضاع أقل من خمس أو فوق الحولين الطفل فوق الحولين، هذا لا يؤثر على الصحيح من أقوال أهل العلم. نعم.","link":"https://binbaz.org.sa/fatwas/5473/هل-يجوز-التزوج-من-ابنة-خاله-التي-رضع-مع-اختها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06804.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":7952,"question":"نبدأ أولاً برسالة إبراهيم مطر، يقول إبراهيم مطر في رسالته: السلام عليكم ورحمة الله وبركاته، ووفقكم وجزاكم الله خيراً بما قمتم به من تبصير الناس في دينهم، ولي أسئلة أرجو أن تجيبوا عليها ولكم جزيل الشكر.السؤال الأول يقول: قال الله تعالى: وَأَنْ تَجْمَعُوا بَيْنَ الأُخْتَيْنِ [النساء:23] فهل الأخت من الرضاعة مثل الأخت من النسب يحرم نكاحها إذا كانت مع أخت من النسب لها أو أختها من الرضاعة؟ أرشدونا أرشدكم الله.","title":"حكم الجمع بين الأختين من الرضاع","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقوله سبحانه: وَأَنْ تَجْمَعُوا بَيْنَ الأُخْتَيْنِ [النساء:23] يعم الأختين من النسب والأختين من الرضاع؛ لأن النبي عليه السلام قال: يحرم من الرضاع ما يحرم من النسب، فلا يجوز الجمع بين الأختين لا من النسب ولا من الرضاع، سواءً كانت الأختان شقيقتين أو لأب أو لأم أو مختلفتين، وسواءً كانتا من النسب أو من الرضاع، هذا هو الحق، وهو الذي عليه أهل العلم. نعم.","link":"https://binbaz.org.sa/fatwas/5470/حكم-الجمع-بين-الاختين-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06801.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":7968,"question":"هذه رسالة وردتنا من عمان (س. ب) المملكة الأردنية الهاشمية عبد الله لفى البصيص ، إذاعة نداء الإسلام من مكة المكرمة، برنامج نور على الدرب أرجو التكرم علينا بحل السؤالين التاليين ولكم منا جزيل الشكر، يقول في سؤاله الأول: يوجد لي أخ رضع من امرأة ويوجد لها فتاة، هل يجوز لي أن أتقدم بطلب يد هذه الفتاة لزواجها أم لا؟","title":"حكم الزواج من أخت الأخ من الرضاع","answer":"الجواب: إذا كان أخوك ارتضع من أمها وأنت لم ترتضع من أمها فلا بأس، إنما تحرم على أخيك، إذا كان ارتضع من أمها حرمت عليه هو، إذا كان الرضاع خمس رضعات أو أكثر في الحولين حرمت عليه، أما أنت فلست منها في شيء، فلا حرج عليك أن تتزوجها إذا كانت أجنبية رضع منها أخوك فبناتها حرم على أخيك إذا كان الرضاع كاملاً، خمس رضعات فأكثر وكان رضاعه منها في الحولين فإنه يكون ولداً لها وتكون بناتها أخوات له، أما أنت فأجنبي، فلا حرج عليك أن تتزوج إحدى بناتها. نعم.","link":"https://binbaz.org.sa/fatwas/5517/حكم-الزواج-من-اخت-الاخ-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_070/07002.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":8003,"question":"هذه رسالة بعث بها حمود بن سليمان بن سلمان الجهني من مرور المدينة المنورة، يقول في رسالته: قبل أن أبث لكم برسالتي أود تبليغ شكري وتقديري إلى القائمين بهذا البرنامج وإلى فضيلة العلماء والمشايخ الذين يجيبون على رسائل المستمعين.يقول عنده مشكلة رضاع، يقول: أفيدكم أنني من تاريخ ولادتي توفت والدتي، وكنا من سكان البادية وأخذوا يطعمونني من ألبان الإبل والغنم، ثم قامت جدتي أم والدي برعايتي وحن قلبها إلي، وأرضعتني من نفسها، وبعد ذلك مضت الأيام وكبرت وكان لأبي إخوان من أمه وأبيه، ولديهم بنات، وأردت أن أتزوج من أحد إحداهن، فهل تحل لي أم لا، أفيدوني جزاكم الله عنا خيرا وتقبلوا تحياتي؟","title":"حكم من رضع من جدته ويريد الزواج بإحدى بنات عمه","answer":"الجواب: إذا كانت جدة السائل قد أرضعته رضاعاً تاماً خمس رضعات فأكثر حال كونه في الحولين فإنه يكون أخاً لأبيه وأعمامه، وعماً لبنات أعمامه، فلا يحل له أن ينكح منهن أحداً؛ لأنه صار عماً لهن بالرضاع، فلابد من التثبت في هذا الأمر، فإذا كانت الجدة قد در لها لبن أرضعتك منه -أيها السائل- خمس مرات يعني: خمس رضعات فأكثر حال كونك في الحولين فإنها تكون أمك من الرضاعة وتكون أنت أخاً لأبيك وأعمامك من الرضاعة، وعماً لبنات أعمامك من الرضاعة، فلا يحل لك نكاح أحد منهن، والله سبحانه وتعالى أعلم.","link":"https://binbaz.org.sa/fatwas/5569/حكم-من-رضع-من-جدته-ويريد-الزواج-باحدى-بنات-عمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_075/07502.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":8150,"question":"هذه رسالة وردتنا من المرسل ع.خ.ع، من العراق من نينوى، يقول في رسالته: نحن إخوان مع أخت لنا، عمر واحد خمسة وعشرين وعمر الثاني ثلاثة وعشرون، وعمر الأخت عشرين سنة، يقول: وعندي بنت عمي عمرها عشرين سنة أيضاً، حيث أرضعت أمي أختي وبنت عمي، يقول هل بنت عمي حرام علي، إذا أردت أن أتزوجها أم لا؟ أفيدونا جزاكم الله عنا خير الجزاء.","title":"تحريم الأخوات من الرضاعة","answer":"الجواب: إذا كانت أمك أرضعتها خمس رضعات أو أكثر فهي تكون أختكم جميعاً، ليس لكم أن تنكحوها؛ لأن الله حرم من الرضاع ما حرم من النسب، والله نص في القرآن على تحريم الأخوات من الرضاعة، فلا يجوز لك أن تنكح ابنة أرضعتها أمك رضاعاً تاماً؛ لأنها بالرضاع صارت أختك من الرضاعة، والله جل وعلا قال في المحرمات: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23]، والنبي عليه السلام قال: يحرم من الرضاع ما يحرم من النسب فإذا كانت هذه البنت أرضعتها الوالدة خمس رضعات -يعني: أمك- خمس رضعات في مجلس أو في مجالس أو أكثر من خمس رضعات فإنها تكون أختاً لكم، والرضعة كون الطفل أو الطفلة يمسك الثدي ويمتص اللبن.. يبتلع اللبن ثم يفصل عن الثدي، ثم يعود فيرضع، ثم يعود حتى يكمل خمس، فإذا كمل خمساً في المجلس، أو في المجالس في يوم أو في ليلة أو في أيام أو في ليالي صار هذا الرضيع ولداً للمرأة المرضعة، وولداً لزوجها صاحب اللبن، وأخاً لأولادها وأولاد الزوج جميعاً، وبهذا تعلم أن هذه البنت الرضيعة من أمك لا تحل لك، بل هي أختك من الرضاعة إذا ثبت أن أمك أرضعتها خمس مرات أو أكثر، أما إن كان الرضاع قليل مرة أو مرتين فلا بأس، ما تكون أختاً لك؛ لأن النبي عليه السلام قال: لا تحرم الرضعة ولا الرضعتان.\nوكذلك لو كان ثلاث أو أربع حتى يكمل الخمس؛ لأن السنة جاءت بخمس رضعات هي المحرمة، وهكذا لو كان فيه شك، قالت أمك: والله ما أدري هي أرضعتها ثنتين أو ثلاث أو أربع أو خمس، ما عندي ضبط، إذا كانت أمك تشك في العدد فإنها لا تحرم عليكم هذه البنت، لكن إذا تركتموها من باب الاحتياط.. من باب ترك الشبهات فهذا أحسن؛ لأنها امرأة فيها ريبة، فتركها والبعد عنها أولى، ولكن لا تكون أختاً لكم إلا بخمس رضعات أو أكثر، لا تفتش لكم ولا ترون وجهها ونحوه، بل عليها الستر والحجاب حتى تجزم أمك بأنها أرضعتها خمس رضعات أو أكثر. نعم.","link":"https://binbaz.org.sa/fatwas/5951/تحريم-الاخوات-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09003.mp3","categories":["الرضاع"]},{"id":8163,"question":"وردتنا رسالة من خميس مشيط من مرسلها المستمع (س. ب. ش) يقول فيها: السلام عليكم ورحمة الله وبعد: يقول إنني أعتبر الرابع من إخواني، وقد أردت الزواج من واحدة من بنات عمي، ولكن والدتي قالت: إنها قد أرضعت عمي الصغير، أصغر أولاد جدي مع أخي الأكبر، وقد رضعته أكثر من خمس مرات، ويعتبر عمي الذي أرضعته والدتي هو أخو الوالد من أبيه، وأعمامي كثيرون من إخوان الوالد من أبيه ومن أمه، فهل يجوز لي الزواج من بنات عمي، أرجو أن أجد عندكم جواب استفساري هذا؟","title":"مشروعية التزوج من بنات العم إذا لم يظهر رضاع","answer":"الجواب: إذا كان عمك الذي ارتضع من أمك عنده بنات، فليس لك أن تنكح بناته؛ لأنه كان أخاً لكم، لما كانت أمك أرضعت عمك الصغير، فإنه يكون بالرضاع أخاً لأولادها، ويكون أولادها الذكور أعماماً لأولاد هذا العم الصغير، والبنات عمات لأولاده، فليس لك نكاح بنات عمك هذا الذي ارتضع من أمك، أما أعمامك الآخرون فلك أن تنكح من بناتهم، مادامت أمك لم ترضعهم، وأنت لم ترضع منهم من زوجاتهم ولا من جدك فلا بأس أن تنكح من بنات عمك الآخرين، بنات أعمامك الآخرين لا بأس أن تتزوج منهم؛ لأنهم ليس هناك مانع، بنت العم مما أباح الله، إذا لم يكن هناك رضاعة، يعني: إذا لم يكن بينك وبينهن رضاعة، إما بكونك رضعت من زوجات أعمامك، أو ارتضعت من جدك، هذا الرضاع يمنع، أما مادمت لم ترضع من زوجات أعمامك ولا من زوجة جدك، ولم ترضع أمك بنات أعمامك، فإنك لا حرج عليك في النكاح منهن، إلا بنات عمك الصغير الذي ارتضع من أمك، فإنك لا يحل لك أن تتزوج منهن أحداً. نعم.","link":"https://binbaz.org.sa/fatwas/5971/مشروعية-التزوج-من-بنات-العم-اذا-لم-يظهر-رضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_091/09103.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":8168,"question":"الأخ سعيد محمد زيد اليماني يقول في سؤاله: لقد تزوجت من عمي ابنته، وزوجته ابنة أختي بدون لا أعطيه شيئاً وأعطاني شيء، فهل هذا يجوز أفيدونا جزاكم الله خيراً؟","title":"زواج الشغار.. حكمه وكيفية تصحيحه إن وقع","answer":"الجواب: إذا كان هذا عن اتفاق بينكما وتشارط فهذا هو نكاح الشغار الذي نهى عنه النبي عليه الصلاة والسلام، وهو يسمى عند بعض الناس نكاح البدل فهذا لا يجوز، أما إذا خطبت منه وزوجك وخطب منك وزوجته من دون مشارطة ولا اتفاق على أنك تزوجه وهو يزوجك فهذا لا بأس ولكل واحدة مهر المثل، أو ما ترضى به من المال ولو قليلاً.\nأما التشارط والاتفاق على أنك تزوجه وهو يزوجك من دون شيء فهذا هو نكاح الشغار المنكر والنكاح فاسد، وعليكما أن تجددا النكاح إذا كان لكما رغبة في البنتين، كل واحد يجدد النكاح من دون شرط المرأة الأخرى، أنت تجدد وهو يجدد بدون شرط المرأة الثانية بمهر جديد وبرضا المرأة، والذي لا ترضاه زوجته عليه أن يطلقها طلقة واحدة لأن النكاح باطل لا يصلح، فيطلقها طلقة واحدة ثم إذا هداه الله بعد ذلك له أن يتزوجها بنكاح جديد.\nالمقصود أن هذا النكاح فيه تفصيل: إن كان عن مجرد تراضٍ من غير اتفاق ولا تشارط فلا بأس وعليكما أن تعطيا البنتين مهرهما إلا إذا سمحتا -مهر المثل- إلا إذا سمحتا عنكما، أو ترضيا كل واحد يرضي زوجته بما تيسر. أما إذا كان عن اتفاق أنك تزوجه وهو يزوجك أو مشارطة بينكما فهذا هو الشغار المنكر فالنكاح فاسد ولا يصح وعلى كل منكما إذا كان له رغبة في امرأته وهي ترغبه أن يجدد النكاح من طريق الولي وشاهدين عدلين ولا حاجة إلى الطلاق، بس يجدد النكاح بدون شرط المرأة الأخرى ولا بأس، أما الذي لا ترغبه زوجته أو لا يرغبها فيطلقها طلقة واحدة فقط، ولا تجبر عليه إذا كان لا ترغبه يطلقها طلقة واحدة وإذا اعتدت تزوجت بعد ذلك.\nنعم، إذا كانت قد دخل بها، إذا كان قد دخل بها خلا بها أو وطئها لابد من العدة، أما إذا كنتما لم تدخلا بهما فالطلاق ويكفيه حينئذ ولا حاجة إلى عدة.","link":"https://binbaz.org.sa/fatwas/5964/زواج-الشغار-حكمه-وكيفية-تصحيحه-ان-وقع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10405.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":8266,"question":"رسالة وصلت إلينا من جيزان وباعثها أحد الإخوة من هناك يقول: (أ. ن. ح) مستشفى الملك فهد، تزوجت منذ ست سنوات تقريباً بابنة خالي، ورزقت منها ثلاثة أطفال، وقبل فترة وجيزة فوجئت بأمي قائلة: أشك أنني رضعت زوجتك يا ولدي، وللتأكد من ذلك سألت والدي البنت ولكنهما قالا: لم نشاهدها على الإطلاق وهي ترضع ابنتنا، والسؤال هو: ما حكم مدى استمراري مع زوجتي مع وجود هذا الشك؟ وما الحكم إذا قالت أمي: إنها رضعت زوجتي ولكنها لم تعرف عدد الرضعات؟ ثم ما الحكم إذا تأكدت من الرضاعة وعدد الرضعات فيما بعد أفيدونا عن ذلك ولكم تحياتي؟","title":"الواجب على الابن إذا ادعت الأم إرضاع زوجته","answer":"الجواب: أما أولاً: فإن الشك لا يؤثر على نكاحك، ولا بأس أن تستمتع بزوجتك مادامت الوالدة ليس عندها ضبط للرضاع، وليست تعلم عدد الرضعات وإنما هو شك، فالشك لا يحرم الحلال، بل عليك أن تبقى مع زوجتك وأن تستمر في معاشرتها ولا يضرك هذا الشك من الوالدة.\nأما إن جزمت الوالدة بأنها أرضعتها خمس رضعات في الحولين أو أكثر من ذلك فينظر في الأمر، فإن كانت الوالدة تتهم ببغضها وتحب فراقك لها، وهناك علامات تدل على أنها تريد ذلك، فإنها لا تقبل شهادتها ولا يعمل بذلك، وتبقى زوجتك معك.\nأما إن كانت الوالدة ثقة وأنت تطمئن إلى قولها وليس بينها وبين زوجتك ما يسبب التهمة فإنك تعمل بقولها، وتفارق المرأة متى جزمت أمك بأنها أرضعتها خمساً في الحولين أو أكثر من الخمس، وهي ثقة معروفة عندك بأنها صدوق، وبأنها لا تتهم في حق زوجتك بأي وجه من أوجه التهم، إذا اطمأننت إلى شهادتها وأنها صادقة في ذلك ففارق المرأة، نسأل الله أن يعوضك عنها خيراً إذا وقعت المفارقة. نعم.\nالسؤال: بارك الله فيكم. سماحة الشيخ! كيد النساء ولا تؤاخذوني في هذا الباب أليس له مجال؟\nالجواب: ما في شك، إن كيدهن عظيم، ولهذا قلت له: إني أخشى أن يكون بينها وبينها شيء، فلهذا بدا لها أن تقول هذا الكلام؛ لأنها قد سكتت مدة طويلة ولم تدع الرضاع.\nالمقدم: ثلاثة أولاد يا شيخ!\nالشيخ: فأخشى أن يكون بدا لها شيء لأن المرأة خالفتها في شيء، أو عاندتها في شيء فأرادت المكيدة لها بهذه الدعوى وبهذه الشهادة.\nفإذا كان هناك شك في عدالة هذه الشهادة أو في صدق هذه الشهادة فالولد لا يلزمه طاعة أمه في ذلك. نعم.\nالمقدم: بارك الله فيكم.\nإذن توصون هذا الزوج بأن يتأكد تماماً، ولا يقدم على فراق زوجته وأولاده إلا بعد التأكد الصحيح المبني على أسس صحيحة.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6101/الواجب-على-الابن-اذا-ادعت-الام-ارضاع-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10012.mp3","categories":["الرضاع"]},{"id":8269,"question":"رسالة وصلت إلينا من جيزان وباعثها أحد الإخوة من هناك يقول: (أ. ن. ح) مستشفى الملك فهد، تزوجت منذ ست سنوات تقريباً بابنة خالي، ورزقت منها ثلاثة أطفال، وقبل فترة وجيزة فوجئت بأمي قائلة: أشك أنني رضعت زوجتك يا ولدي، وللتأكد من ذلك سألت والدي البنت ولكنهما قالا: لم نشاهدها على الإطلاق وهي ترضع ابنتنا، والسؤال هو: ما حكم مدى استمراري مع زوجتي مع وجود هذا الشك؟ وما الحكم إذا قالت أمي: إنها رضعت زوجتي ولكنها لم تعرف عدد الرضعات؟ ثم ما الحكم إذا تأكدت من الرضاعة وعدد الرضعات فيما بعد أفيدونا عن ذلك ولكم تحياتي؟","title":"الواجب على الابن إذا ادعت الأم إرضاع زوجته","answer":"الجواب: أما أولاً: فإن الشك لا يؤثر على نكاحك، ولا بأس أن تستمتع بزوجتك مادامت الوالدة ليس عندها ضبط للرضاع، وليست تعلم عدد الرضعات وإنما هو شك، فالشك لا يحرم الحلال، بل عليك أن تبقى مع زوجتك وأن تستمر في معاشرتها ولا يضرك هذا الشك من الوالدة.\nأما إن جزمت الوالدة بأنها أرضعتها خمس رضعات في الحولين أو أكثر من ذلك فينظر في الأمر، فإن كانت الوالدة تتهم ببغضها وتحب فراقك لها، وهناك علامات تدل على أنها تريد ذلك، فإنها لا تقبل شهادتها ولا يعمل بذلك، وتبقى زوجتك معك.\nأما إن كانت الوالدة ثقة وأنت تطمئن إلى قولها وليس بينها وبين زوجتك ما يسبب التهمة فإنك تعمل بقولها، وتفارق المرأة متى جزمت أمك بأنها أرضعتها خمساً في الحولين أو أكثر من الخمس، وهي ثقة معروفة عندك بأنها صدوق، وبأنها لا تتهم في حق زوجتك بأي وجه من أوجه التهم، إذا اطمأننت إلى شهادتها وأنها صادقة في ذلك ففارق المرأة، نسأل الله أن يعوضك عنها خيراً إذا وقعت المفارقة. نعم.\nالسؤال: بارك الله فيكم. سماحة الشيخ! كيد النساء ولا تؤاخذوني في هذا الباب أليس له مجال؟\nالجواب: ما في شك، إن كيدهن عظيم، ولهذا قلت له: إني أخشى أن يكون بينها وبينها شيء، فلهذا بدا لها أن تقول هذا الكلام؛ لأنها قد سكتت مدة طويلة ولم تدع الرضاع.\nالمقدم: ثلاثة أولاد يا شيخ!\nالشيخ: فأخشى أن يكون بدا لها شيء لأن المرأة خالفتها في شيء، أو عاندتها في شيء فأرادت المكيدة لها بهذه الدعوى وبهذه الشهادة.\nفإذا كان هناك شك في عدالة هذه الشهادة أو في صدق هذه الشهادة فالولد لا يلزمه طاعة أمه في ذلك. نعم.\nالمقدم: بارك الله فيكم.\nإذن توصون هذا الزوج بأن يتأكد تماماً، ولا يقدم على فراق زوجته وأولاده إلا بعد التأكد الصحيح المبني على أسس صحيحة.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6101/الواجب-على-الابن-اذا-ادعت-الام-ارضاع-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10012.mp3","categories":["الرضاع"]},{"id":8319,"question":"أخونا له سؤال آخر يقول: أخي عنده بنت مستجيبة -كما يقول- ولي ولد، وذهبت إلى أخي أخطب ابنته لولدي ووافق أخي على الزواج، وإني أزوج ابنتي ولده وشرط أخي صداق ابنته على ابني ستة آلاف ريال، وشرطت صداق ابنتي على ولد أخي سبعة آلاف ريال، وتم الزواج بين الطرفين. أفيدونا جزاكم الله خيراً، هل الجواز تام، أو يطلقن البنات؟","title":"زواج الشغار.. حكمه وكيفية تصحيحه لمن وقع فيه","answer":"الجواب: إن كان وقع ذلك بينكما على سبيل الشرط كل واحد منكما يقول زوجني وأزوجك، وأنكما اتفقتما على هذا، هذا هو النكاح الذي نهى عنه النبي ﷺ وسماه: نكاح الشغار فلا يجوز هذا، بل النكاح فاسد وعلى كل واحد منكما أن يجدد النكاح لولده، كل واحد يجدد من دون شرط المرأة الأخرى وليس هناك حاجة إلى الطلاق، ولكن إذا كانت كل واحدة ترغب في زوجها وهو يرغب فيها فإنه يجدد النكاح من أبيها لزوجها بحضرة شاهدين ويكفي ذلك ولا حاجة إلى الطلاق.\nأما إن كان وقع منكما ذلك من غير شرط، بل خطب كل واحد من الآخر من دون شرط فلا حرج في ذلك والزواج صحيح والحمد لله، إنما المنكر أن يكون هناك شرط، بأن يقول كل واحد: زوجني وأزوجك، أو يقول: إذا زوجت ابني أنا أزوج بنتي لابنك، فالمعنى: يكون عن تشارط وعن اتفاق وتواطؤ، هذا هو الذي لا يجوز.\nأما إذا خطب كل واحد من الآخر من دون شرط فلا بأس بهذا، فينبغي التنبه لهذا الأمر، وإذا كان عن تشارط فالواجب تجديد النكاح، كل بنت يجدد لها إذا كانت راغبة في زوجها وهو راغب فيها، يجدد النكاح من وليها لزوجها بحضرة شاهدين من دون شرط المرأة الأخرى. نعم.\nأما إذا كان ما يرغبها أو لا ترغبه فإنه يطلقها طلقة واحدة، ولا يبقى معها. نعم.","link":"https://binbaz.org.sa/fatwas/6132/زواج-الشغار-حكمه-وكيفية-تصحيحه-لمن-وقع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_110/11002.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":8385,"question":"الرسالة التالية وصلت إلى البرنامج من مكة المكرمة، باعثها أخونا (ع. أ. ب) يقول: أرجو عدم ذكر اسمي، يوجد لرجل امرأتين، الزوجة الأولى أرضعتني مع أكبر أولادها، فيكون إخوته الذي بعده، إخوةً لي كذلك، ويوجد من المرأة الثانية بنت، ليس بيني وبينها رضاعة، فيقول أهل البنت: إن هذه البنت أختك كذلك، فهي أخت إخوتك من الرضاعة، وتكشف أمامي في منزل أهلها، والآن تزوجت، ولكن زوجها لا يسمح لها بالدخول أمامي، فما هو الحل الصحيح، كلام أهلها، أم كلام زوجها، أفيدونا جزاكم الله خيراً؟","title":"حكم الأخوات لأب من الرضاعة","answer":"الجواب: إذا ارتضع الإنسان من زوجة إنسان رضاعاً كاملاً، خمس مرات أو أكثر، حال كونه في الحولين، فإنه يكون ولداً له، ويكون أخاً لأولاده جميعاً من زوجته المرضعة، ومن الزوجات الأخريات، أولاده من المرضعة إخوة أشقاء من الرضاع، وأولاده من الزوجات الأخرى إخوة من الأب من الرضاع، فهذه المرأة التي من الزوجة الثانية أخت لك من الرضاع، لكن من جهة أبيك، كأختك من النسب، يقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب فكما أن بنت أبيك من زوجة غير أمك أخت لك من الرضاع، هكذا بنت الشخص الذي أرضعتك زوجته من زوجة أخرى هي أخت لك من الرضاع، من الأب، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/6251/حكم-الاخوات-لاب-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11604.mp3","categories":["الرضاع"]},{"id":8514,"question":"هذه رسالة وردتنا من المرسل عبد الباسط عبد العال آدم مصري مقيم بجدة، يقول: إنني تزوجت من بنت خالي، وعقدت قراني ولم أدخل بها، وهذه الزوجة أخت أخ لي من الرضاع، أي: هو رضع من والدتي وأنا لم أرضع من والدته، والزوجة أخته من والده فقط من امرأة أخرى، فهل هذا الزواج حلال أم حرام؟","title":"حكم الزواج من أخت الأخ من الرضاعة","answer":"الجواب: نعم، هذا الزواج لا بأس به، مادام لم ترضع من أمك وأنت لم ترضع من أمها ولا ممن ارتضعت منه فلا بأس، أما كون أخيك رضع من المرأة التي رضعت منها لا يضر، المقصود أنه لا حرج عليك في هذا أيها السائل. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6589/حكم-الزواج-من-اخت-الاخ-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20306.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":8538,"question":"وله سؤال ثان في هذه الرسالة يقول: إن جدتي قد أرضعت إخوتي الأكبر مني فقط ولم ترضعني، و ما هي حالة الحلال والحرام في هذه الحالة، وما هو حظي من بنات أعمامي؟","title":"التحريم في الرضاع على الراضع فقط","answer":"الجواب: مادامت جدتك لم ترضعك فلا حرج عليك أن تنكح من بنات أعمامك، لا بأس وإنما إخوانك لا ينكحون منهم، فإذا كان الرضاع خمس مرات فأكثر في حال كونهم في الحولين، أما أنت فلم ترضع فلا حرج عليك أن تنكح من بنات عمك. نعم.\nالمقدم: جزاكم الله خير، يعني: التحريم على الراضع فقط؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/6626/التحريم-في-الرضاع-على-الراضع-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20517.mp3","categories":["الرضاع"]},{"id":8541,"question":"وله سؤال ثان في هذه الرسالة يقول: إن جدتي قد أرضعت إخوتي الأكبر مني فقط ولم ترضعني، و ما هي حالة الحلال والحرام في هذه الحالة، وما هو حظي من بنات أعمامي؟","title":"التحريم في الرضاع على الراضع فقط","answer":"الجواب: مادامت جدتك لم ترضعك فلا حرج عليك أن تنكح من بنات أعمامك، لا بأس وإنما إخوانك لا ينكحون منهم، فإذا كان الرضاع خمس مرات فأكثر في حال كونهم في الحولين، أما أنت فلم ترضع فلا حرج عليك أن تنكح من بنات عمك. نعم.\nالمقدم: جزاكم الله خير، يعني: التحريم على الراضع فقط؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/6626/التحريم-في-الرضاع-على-الراضع-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20517.mp3","categories":["الرضاع"]},{"id":8577,"question":"تسأل أختنا عن حكم قبلة أخوان الرضاعة والكشف عنهم، وكذلك أعمامهم وأخوالهم، علماً بأنها متيقنة كما تقول من أنها قد رضعت من أمهم أكثر من خمس رضعات، والمراد بالكشف كشف الوجه أمامهم؟","title":"حكم كشف المرأة وجهها لأخيها من الرضاعة وتقبيل المحارم","answer":"الجواب: يقول الله  لما ذكر المحرمات قال سبحانه: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23]، ويقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب فإذا ارتضعت المرأة من المرأة خمس رضعات أو أكثر حال كونها في الحولين قبل الفطام في الحولين فإن المرضعة تكون أماً لها، وأولادها يكونون إخوة لها ذكورهم وإناثهم، فلا مانع أن تكشف لهم ما تكشف لمحارمها من النسب كأخيها من النسب وأبيها وعمها، الرضاعة كذلك لها أن تكشف لهم فيرون وجهها ويدها وقدمها كما يراها محارمها من النسب.\nأما التقبيل فلا مانع من التقبيل في الرأس أو في الخد، وكان الصديق  يقبل عائشة مع خدها رضي الله عنها وأرضاها، أما الفم نفسه فالأولى تركه يكون للزوج، الأولى للولي، يعني: المحرم أن لا يقبل الفم، هذا هو الأحسن يقبل أنفها وبين عينيها، رأسها إذا كانت كبيرة، يقبل خدها، لا بأس بذلك، أما الفم فالأولى والأفضل والأحوط ترك الفم لأنه للزوج، نعم.\nالمقدم: جزاكم الله خيراً أرجو..\nالشيخ: ولا بأس أن يرى المحرم شعرها، لا بأس أن يرى الشعر لا بأس أن يراه، لكن إذا سترت بدنها عند محارمها وصارت محتشمة حتى لا يرى المحرم إلا وجهها ويديها وقدمها فهذا أكمل وأحسن وأبعد عن الخطر بالنسبة إلى بعض المحارم، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6655/حكم-كشف-المراة-وجهها-لاخيها-من-الرضاعة-وتقبيل-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_208/20803.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":8604,"question":"يسأل أيضاً ويقول: إذا كان عند شخص زوجة وطلقها فهل له أن ينكح أختها في عدتها، وإذا ماتت فهل له أن يتزوجها في الحال، أفيدونا أفادكم الله؟","title":"حكم نكاح أخت الزوجة المطلقة قبل انتهاء العدة","answer":"الجواب: إذا طلق امرأة فليس له نكاح أختها ولا عمتها ولا خالتها إلا بعد العدة، بعد انتهاء العدة، إن كانت رجعية فهذا بالإجماع، بإجماع المسلمين ليس له أن يتزوج أختها ولا عمتها ولا خالتها إلا بعد انتهاء العدة؛ لأن الرجعية زوجة، أما إذا كانت بائن، طلاقاً بائناً الطلقة الأخيرة من الثلاث، أو مطلقة على مال -المخلوعة- فهذا فيه خلاف، ولكن الأرجح أنه لا يتزوجها إلا بعد انتهاء عدة أختها، أو بنت أختها، أو بنت أخيها، أما إذا ماتت فهذا لا بأس يتزوجها ولو بعد يوم أو يومين من موتها، إذا كان الزوجة ماتت فقد انتهت عدتها بالموت، انتهى الزواج بالموت، ففي هذه الحال لا حرج أن يتزوج أختها أو عمتها أو خالتها في الحال يعني، من حين ماتت الزوجة. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6743/حكم-نكاح-اخت-الزوجة-المطلقة-قبل-انتهاء-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21009.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":8677,"question":"وهذه رسالة وردت إلينا من المستمع (ق. ل. ق) من العراق له فيها عدة أسئلة، يقول في أولها: لقد تزوج أخي امرأة من أقاربنا، وقد تزوج أخو هذه المرأة من أختي، أي: أنه زواج شغار، وقد علمت أنا السائل أنه لا شغار في الإسلام، فما العمل في هذا النكاح، فهل هو محرم على اعتبار أنه شغار، علماً أن كلاً من أخي وأخو زوجته قد أصبح لهم خمسة أطفال، كما أود أن أعلمكم أن زوجة أخي المذكورة هي ابنة عمة أمي، فهل هذا محرم أم لا، أفيدونا أفادكم الله؟","title":"زواج الشغار فاسد لا يصح","answer":"الجواب: الشغار محرم في الإسلام، يقول النبي ﷺ: لا شغار في الإسلام ونهى عن الشغار عليه الصلاة والسلام، قال: والشغار: أن يقول الرجل: زوجني أختك وأزوجك أختي، أو زوجني بنتك وأزوجك بنتي هذا هو الشغار، فإذا تزوج زيد من عمرو أخته على أن يزوجه أخته أو يزوجه بنته هذا هو الشغار، وهو فاسد ولا يصح، والواجب عليهما التوبة إلى الله والاستغفار، وإذا كان لكل واحد الرغبة في زوجته يجدد النكاح من دون شرط المرأة الثانية، إذا كان كل واحد يرغب زوجته وهي ترغب في زوجها فيجدد النكاح من وليها بدون شرط المرأة الأخرى، كل واحد يزوج موليته على زوجها بنكاح جديد من دون شرط المرأة الثانية. ولا حاجة إلى طلاق ولا شيء؛ لأن الماء ماءه والزوجة زوجته بموجب العقد الذي ظنه عقداً صحيحاً، فعليهما التوبة إلى الله ، وعليهما أن يجددا النكاح إذا كان كل واحد يرغب في زوجته وهي ترغب فيه، أما إن كانت لا ترغب فيه يطلقها طلقة؛ لأن النكاح فيه شبهة، فيطلقها طلقة حسماً لتعلقها به وتعلقه بها، وخروجاً من خلاف من صححه مع الإثم نعم، فعليهما التوبة إلى الله وعليهما التجديد للنكاح إذا كان كل واحد يرغب في زوجته وهي ترغب في زوجها بمهر جديد وعقد جديد وشاهدي عدل يحضران النكاح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6822/زواج-الشغار-فاسد-لا-يصح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21509.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":8750,"question":"له سؤال ثان في هذه الرسالة يقول فيه: إذا غذي الرضيع باللبن الصناعي في الحولين هل يعتبر مفطوماً؟ وهل يغير ذلك من حكم نجاسته؟","title":"حكم بول الصبي المغذى باللبن الصناعي في الحولين","answer":"الجواب: أما بعد الحولين فإنه يعتبر مفطوماً فلو أرضعه أحد بعد الحولين فإنه لا يعتبر الرضاع، أما في حال الحولين فإذا ارتضع من امرأة خمس رضعات أو أكثر في حال الحولين، فإنه يعتبر ولداً لها وأخاً لأولادها وابناً لزوجها، وأما حكم بوله في الحولين حال ارتضاعه من لبن غير لبن أمه فهذا محل نظر، والأقرب والله أعلم أنه كالذي يرتضع من أمه، لا يقال: إنه يتغذى بالطعام حينئذ وإنما يتغذى بلبن قام مقام لبن أمه، فالأقرب والله أعلم أن بوله يكفي فيه الرش والنضح كبول الصبي الذي لا يأكل الطعام إذا كان يتغذى بلبن أمه، هذا هو الأقرب والأظهر والله أعلم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6904/حكم-بول-الصبي-المغذى-باللبن-الصناعي-في-الحولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21702.mp3","categories":["الرضاع"]},{"id":8753,"question":"هذه رسالة وردتنا من السائل (عبد الله . ت. ق) من السعودية يقول: أنا شاب تزوجت بنت عمي بمهر قدره مائة وخمسين ألف ريال، واشترط أن نزوج ابنه وفعلاً تزوج ابنه على بنت أخي بنفس المهر، ثم يقول: حصل سوء تفاهم وادعى عمه أن بنته قد كمل رشدها وتلك أقل منها بحوالي ثلاث سنوات، فأقسم بالله العظيم! أنه لن يعطيني بنته أي: زوجتي فأفيدوني هل أترك هذا الزواج، أم أن هذا الزواج حرام أفيدونا أفادكم الله؟","title":"حكم نكاح البدل (الشغار)","answer":"الجواب: الزواج بالمشارطة أن هذا يعطي بنته هذا وهذا يعطي بنته هذا، أو بنت أخيه، أو أخته هذا يسمى: نكاح الشغار ويسميه بعض الناس: البدل، نكاح البدل، وهذا منكر ولا يجوز وهو نكاح فاسد وباطل لا يجوز؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام، فليس لك أن تدخل على مدخل، بل يجب عليك أن تفارق هذه البنت، وليس لك أن تزوج هذا الزواج الفاسد المخالف لشرع الله عز وجل.\nأما النزاع بينكما فهذا إلى المحكمة تنظر المحكمة في أمر النزاع بينكما، لكن إذا صلحتما ولم تحتاجا إلى المحكمة فعليك أن تجدد النكاح مع ولي المرأة بدون شرط المرأة الأخرى، وهكذا المرأة الأخرى يجدد نكاحها بدون شرط المرأة الأخرى، فإذا جدد النكاح من دون شرط على مهر قليل أو كثير فلا بأس، وأما بشرط أنه يزوجكم وأن تزوجونه فهذا لا يجوز وهذا هو نكاح الشغار الذي نهى عنه الرسول صلى الله عليه وسلم وأنكره عليه الصلاة والسلام، أما النزاع الذي بينكما والمخاصمة فهذا إلى المحاكم وفيما تراه المحاكم الخير والبركة إن شاء الله.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6916/حكم-نكاح-البدل-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21711.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":8781,"question":"الرسالة الثالثة في هذه الحلقة وردتنا من السودان من بور سودان من السائل أوهاج محمد حمد ، يقول في رسالته: هناك رجل كان على صلة بامرأة بغير زواج فأنجب منها طفلة وافترقا فترة طويلة، ثم تقدم لخطبة بنت تعرف عليها ووافقت على الزواج منه فتزوجها وبعد فترة اكتشف أنها بنته الغير شرعية من تلك المرأة، فما حكم الإسلام في ذلك؟ وماذا يفعل؟","title":"حكم من تزوج بابنته غير الشرعية بدون علم","answer":"الجواب: أولاً: عليه التوبة مما جرى منه من الزنا والرجوع إلى الله والندم والإقلاع والصدق في ذلك وكثرة الاستغفار والعمل الصالح.\nثانياً: هذا النكاح باطل، ما دام عرف أنها ابنته من الزنا فالذي عليه جمهور أهل العلم أنه نكاح باطل؛ لأنها خلقت من مائه فلا يجوز له نكاحها، وإن كانت غير شرعية بنت غير شرعية، لكنها تدخل في عموم قوله جل وعلا: حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُم [النساء:23] هي بنت غير شرعية خلقت من مائه فيكون نكاحها باطلاً ولا تنسب إليه، ولا تكون محرماً له، لكن نكاحها باطل عند أهل العلم؛ لأنها خلقت من مائه غير الشرعي فيحرم عليه نكاحها ولا تنسب إليه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6934/حكم-من-تزوج-بابنته-غير-الشرعية-بدون-علم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21907.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":8835,"question":"الرسالة التالية من اليمن الشمالي وأخونا مقيم في جدة كما يقول، يقول: أنا والدتي أرضعت بنت أخي الأولى وأخي له عدة أولاد بعد هذه البنت لم يرضعوا من جدتهم، وأردت أن أزوج ابني بنت أخي التي لم ترضع من جدتها، فالتي رضعت من جدتها هي بنت الأولى، فهل هذا جائز أو لا؟","title":"هل يجوز أن أزوج ابني لبنت أخي التي لم ترضع معه؟","answer":"الجواب: نعم، أما الذي رضعت من جدتها فلا؛ لأنها حينئذ إذا كانت جدتها من أمها تكون خالة لأولاد خالاتها، وإن كانت أم أبيها تكون عمة لأولاد إخوتها، لكن من سواها من البنات اللاتي لم يرضعن من الجدة لا حرج في زواج أبناء عمها لها أو أبناء خالها لها. نعم.","link":"https://binbaz.org.sa/fatwas/6990/هل-يجوز-ان-ازوج-ابني-لبنت-اخي-التي-لم-ترضع-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16505.mp3","categories":["الرضاع"]},{"id":9063,"question":"لهذا أرجو إفادتي عن هذه المسألة، وللعلم فإن الفتاة لم ترضع من والدتي؛ لأنها هي الأصغر، أرجو أن يكون خطابي هذا محل اهتمامكم، وأرجو أن يكون الرد في برنامجكم، جزاكم الله خيرًا؟","title":"حكم الزواج ممن رضع إخوتها من أمه أو رضع أخوته من أمها","answer":"الجواب: إذا كنت لم ترضع من أمها ولم ترضع هي من أمك فلا بأس، وإن رضع إخوتك من أمها أو رضع إخوتها من أمك، المهم أنت إذا كنت لم ترضع أنت من أمها رضاعًا محرمًا خمس رضعات فأكثر في الحولين ولم ترضع هي من أمك ولا من أختك ولا من زوجة أبيك ليس بينكما رضاعة فلا بأس أن تتزوجها، وإن كانت أختا لإخوانك الذين رضعوا من أمها، المهم أنك أنت لم ترضع من أمها وهي لم ترضع من أمك ليس بينكما رضاعة، ولم ترضع أيضًا من أختك حتى تكون خالًا لها، ولا من زوجة أبيك حتى تكون أخًا لها من الأب، ليس بينكما رضاعة، وأما رضاع إخوتك أو أخواتها فلا يضر، ما يضرك، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7222/حكم-الزواج-ممن-رضع-اخوتها-من-امه-او-رضع-اخوته-من-امها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_178/17808.mp3","categories":["الرضاع"]},{"id":9064,"question":"لهذا أرجو إفادتي عن هذه المسألة، وللعلم فإن الفتاة لم ترضع من والدتي؛ لأنها هي الأصغر، أرجو أن يكون خطابي هذا محل اهتمامكم، وأرجو أن يكون الرد في برنامجكم، جزاكم الله خيرًا؟","title":"حكم الزواج ممن رضع إخوتها من أمه أو رضع أخوته من أمها","answer":"الجواب: إذا كنت لم ترضع من أمها ولم ترضع هي من أمك فلا بأس، وإن رضع إخوتك من أمها أو رضع إخوتها من أمك، المهم أنت إذا كنت لم ترضع أنت من أمها رضاعًا محرمًا خمس رضعات فأكثر في الحولين ولم ترضع هي من أمك ولا من أختك ولا من زوجة أبيك ليس بينكما رضاعة فلا بأس أن تتزوجها، وإن كانت أختا لإخوانك الذين رضعوا من أمها، المهم أنك أنت لم ترضع من أمها وهي لم ترضع من أمك ليس بينكما رضاعة، ولم ترضع أيضًا من أختك حتى تكون خالًا لها، ولا من زوجة أبيك حتى تكون أخًا لها من الأب، ليس بينكما رضاعة، وأما رضاع إخوتك أو أخواتها فلا يضر، ما يضرك، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7222/حكم-الزواج-ممن-رضع-اخوتها-من-امه-او-رضع-اخوته-من-امها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_178/17808.mp3","categories":["الرضاع"]},{"id":9194,"question":"هنا رسالة وصلت إلى البرنامج من الأخ عبد الغني صالح علي الصلاحي من الجمهورية العربية اليمنية، أخونا يقول: لي أخت من الرضاع وأنا أصغر إخواني ولي أخ أكبر ويريد أن يتزوج هذه الفتاة، هل يصح أن يتزوجها أم لا؟ أفتونا جزاكم الله خيرا.","title":"حكم زواج الأخ من أخت أخيه من الرضاع","answer":"الجواب: إذا كانت هذه الفتاة أرضعتها أمكم رضاعًا كافيًا وهو خمس رضعات فأكثر فهي حرام عليكم جميعًا؛ لأنها أختكم جميعًا، إذا كان الرضاع خمس رضعات أو أكثر حال كون الرضيعة في الحولين لم تفطم.\nأما إن كانت الرضاعة أنت رضعت من أمها ولم ترضع هي من أمكم إنما أنت رضعت من أمها فقط ولم يرضع أخوك من أمها فإنها حرام عليك أنت، هي أختك أنت وليست أختًا له هو؛ لأنه لم يرضع من أمها، وإنما أنت رضعت من أمها، فتحرم عليك؛ لأنها أختك من الرضاعة إذا كان الرضاع خمس رضعات أو أكثر، ولكن لا تحرم على أخيك؛ لأنه لم يرضع من أمها، والله أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/7354/حكم-زواج-الاخ-من-اخت-اخيه-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18104.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":9239,"question":"هذه رسالة وردتنا من السائل (م. ع. أ) من العراق، محافظة نينوى، يقول: تزوجت من بنت خالي وهي راضعة من والدة أمي، وفي هذه الحالة تكون أخت والدتي من الرضاعة ولي منها طفلان، وأنا لا أعلم في هذا الشأن أو بهذا الشأن إلا بعد أن صار لي منها طفلان أفيدوني أفادكم الله؟","title":"حكم الزوجة إن ظهر للزوج أن زوجته رضعت من جدته","answer":"الجواب: إذا ثبت أن الجدة أرضعتها خمس رضعات معلومات أو أكثر، فإنها تكون خالتك أخت أمك، إذا ثبت أن جدتك أم أمك أرضعت زوجتك خمس رضعات أو أكثر حال كونها في الحولين، حال كون الزوجة زوجتك في الحولين صغيرة، فإذا ثبت هذا بشهادة الثقات، أو باعتراف المرضعة وهي ثقة تقول: إني أرضعتها خمس مرات وهي ثقة يطمأن إليها عدل، فإن هذه الزوجة تكون خالتك أخت أمك، وأولادك منها شرعيون يلحقون بك؛ لأنك لم تتعمد الباطل، فزوجتك هذه معذورة وأنت معذور؛ لأنكما لم تتعمدا ما حرم الله، ولكنكما جهلتما هذا الرضاع، فالأولاد شرعيون، ولا حرج عليك في وطئها فيما مضى، وجماعها فيما مضى، واعتبارها زوجة فيما مضى بسبب الجهل، والله يقول جل وعلا: وَلَيْسَ عَلَيْكُمْ جُنَاحٌ فِيمَا أَخْطَأْتُمْ بِهِ وَلَكِنْ مَا تَعَمَّدَتْ قُلُوبُكُمْ [الأحزاب:5]، ويقول الله سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، فقال الله: قد فعلت»، فهذا من الخطأ المعفو عنه، لأنك لم تعلم، وأولادك لاحقون بك شرعيون؛ لأنه وطء بشبهة النكاح لم تعلم أنها خالتك، فاطمئن يا أخي! ولا يكون في صدرك حرج، وفارقها وأحسن إليها؛ لأنها أم ولديك فأحسن إليها، واسأل ربك أن يعطيك خيراً منها، وأن يعطيها خيراً منك، والله المستعان.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7401/حكم-الزوجة-ان-ظهر-للزوج-ان-زوجته-رضعت-من-جدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_234/23410.mp3","categories":["الرضاع"]},{"id":9246,"question":"هذه رسالة وردت إلى البرنامج من يسري عبد النبي غازي مصري من كفر الشيخ، وهو مقيم بالمنطقة الشرقية يقول في رسالته الطويلة: لي أخ طلق زوجته ثلاث مرات، لكونها تعمل ممرضة بمستوصف بالقاهرة، وكانت تقوم في غير أوقات العمل في شقتها بضرب الحقن للرجال والنساء، وتقوم بالذهاب إلى بعض الشقق لضرب حقن والله أعلم إن كانت نساء أو رجال، ويحضر إليها في الساعة الثانية من الليل بعض الرجال ويقولون: احضري معنا فلانة تعبانة، وتخرج دون إذن زوجها وهو غير راضٍ عن ذلك، حيث قام بطلاقها مرتين من أجل ذلك، وعند تكرار ذلك وهو ضرب الحقن للرجال كان يقول لها: لا تخرجي، تقول له: أخرج رغماً عنك، وليس لك علي حكم، هذا هو الحال وكانت عندما تطلق تقبل أقدامه وتبدي الندم حيث أرجعها مرتين وفي هذه المرة الثالثة تريد الرجوع، وتريد أن تعمل محللاً كي ترجع لزوجها، ولكن دون جدوى؛ لأنها لها ثلاث مرات أفيدونا أفادكم الله في حالتها؟","title":"حكم مراجعة المبتوتة عن طريق المحلل","answer":"الجواب: بعد الطلقة الثالثة لا رجوع إلا بعد زوج شرعي، والمحلل لا يجوز، المحلل تيس مستعار ملعون، لا يجوز نكاحه باطل ولا يحصل به التحليل، ومثل هذه الزوجة لا يرغب فيها ولو نكحت زوجاً آخر، ينبغي للزوج هذا أن لا يعود إليها، وأن لا يرغب فيها؛ لأنها متهمة ما دامت تعمل هذه الأعمال، فلا يليق به أن يرجع إليها، بل يطلب غيرها وأفضل منها: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] .. وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].\nهذه المرأة متهمة بالشر، فلا يليق به أن يعود إليها لو تزوجت، ولا تحل له حتى تنكح زوجاً غيره، نكاحاً شرعياً لا تحليل، ويطأها الزوج الجديد ثم يفارقها بموت أو طلاق ثم تعتد، لكن ما دامت بهذه الصفة التي ذكرها السائل، فإنه لا ينبغي أن يعود إليها؛ لأن ظاهرها شر، ولأنها متهمة بالشر، نسأل الله السلامة والعافية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7414/حكم-مراجعة-المبتوتة-عن-طريق-المحلل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23513.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":9282,"question":"الرسالة التالية وصلت إلى البرنامج من حوطة بني تميم وباعثها أخونا عبدالرحمن الحداد يمني الجنسية كما يقول، أخونا يقول: لقد حدثنا إمام أحد المساجد وكان الحديث بخصوص الرضاعة قال: إن الإخاء في الرضاعة لا يقع إلا من كان معتمداً على حليب الأم فقط أما إذا كان المرتضع يتناول حليبًا صناعيًا أو حليبًا آخر فإن الرضاعة حينئذ لا تؤثر، نرجو أن تفيدونا عن صحة هذا القول؟","title":"أثر الرضاع على الطفل المعتمد على الحليب الصناعي","answer":"الجواب: متى ثبت الرضاع أثر الرضاع ولو كان يتعاطى حليباً صناعياً، متى ثبت الرضاع خمس مرات أو أكثر في حال كونه في الحولين فإن المرضعة تكون أماً له وإخوانها أخوالاً له وأبوها جداً له وهكذا، ولو كان يعطى حليباً صناعياً فإن حليبها لابد أن يؤثر فيه.\nفالحاصل أنه متى أرضعته وإن كانت أمه ترضعه وإن كان يعطى حليبًا صناعيًا فرضاعها له خمس مرات أو أكثر يؤثر ونجعله ابناً لها كما قال الله جل وعلا في كتابه العظيم: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23]. نعم.","link":"https://binbaz.org.sa/fatwas/7445/اثر-الرضاع-على-الطفل-المعتمد-على-الحليب-الصناعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15412.mp3","categories":["الرضاع"]},{"id":9284,"question":"سمعت أيضاً قبل هذا الحديث من رجل آخر أنه يجوز للرجل أن يتزوج أخت أخته من الرضاعة، ما عدا المرتضعة معه فقط؟","title":"حكم زواج الرجل بأخت أخته من الرضاعة","answer":"الجواب: هذا فيه إجمال إن كان مراد السائل أو القائل أن المرأة إذا أرضعت إنساناً مع بنت لها فإنه يكون أخاً للرضيعة فقط التي ارتضع معها دون بقية أخواتها التي قبلها والتي بعدها فهذا غلط، بل الرضاع يعم جميع بنات المرضعة التي قبل البنت الرضيعة معه وبعدها لا فرق في ذلك، فإذا أرضعت زينب صالحاً أو محمداً خمس رضعات أو أكثر فإنه يكون أخاً لجميع أولادها من الذكور والإناث الذين قبله والذين بعده بنص قوله تعالى: وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23]، فهي أمه وهم أخواته، وقوله ﷺ: يحرم من الرضاع ما يحرم من النسب.\nأما إن أراد القائل هذا أنه لا يحرم عليه إلا أخته التي رضعت معه في مسألة أخرى كأن يقال: إن فلانة رضعت من أمه معه ولم ترضع أخواتها هذا صحيح، مثلاً: عبد الله عنده خمس بنات فرضعت إحداهن مع محمد من أم محمد فإن بقية أخواتها لا يكونوا إخوة لمحمد؛ لأنهن لم يرضعن من أمه إنما رضع من أمه واحدة منهن، فالتي رضعت من أم محمد خمس رضعات أو أكثر في حال الحولين هي التي تكون أختاً لمحمد وأما أخواتها فلا؛ لأنهن لم يرضعن من أم محمد، أما هو لو رضع من أمهن صار أخ لهن جميعاً لا أخ للتي رضعت معه، لا. بل يكون أخاً لهن جميعاً؛ لأن المرضعة صارت أمه وأولادها جميعاً صاروا إخوة له، فيجب الفرق بين هذا وهذا. نعم.","link":"https://binbaz.org.sa/fatwas/7448/حكم-زواج-الرجل-باخت-اخته-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15413.mp3","categories":["الرضاع"]},{"id":9343,"question":"هذه رسالة وردت من يحيى بن علي محمد جاد الله يماني مقيم في الأفلاج في الهدار، يقول في رسالته: أنا متزوج بدل بأختي لكن زوج أختي سلم المهر وأنا أيضاً سلمت مهر زوجتي، وقد تم هذا العقد برضا الزوجتين وكل واحدة راضية بزوجها، فهل هذا العقد صحيح أم لا أفيدونا أفادكم الله؟","title":"نكاح البدل لا يجوز","answer":"الجواب: نكاح البدل لا يجوز، ويسمى نكاح الشغار، وقد نهى عنه النبي ﷺ في أحاديث كثيرة، عن جابر وعن أبي هريرة وعن ابن عمر وغيرهم، فالواجب على المؤمن أن يحذر هذا النكاح، وأن لا يفعله، فإن فعله فليتب إلى الله وليستغفر الله وليجدد النكاح، فإنه نكاح فاسد فيجتنبها حتى يجدد النكاح، إذا كان يرغب فيها وهي ترغب فيه عليه أن يجدد النكاح بدون شرط المرأة الأخرى، يعيد النكاح مع وليها عليها بمهر جديد ولو في الحال ما يحتاج عدة؛ لأن الماء ماؤه إذا كانت تريده ويريدها، فيجدد النكاح بدون شرط المرأة الأخرى، أما إن كانت لا تريده فإنه يطلقها طلقة ويفارقها لأنه نكحها بغير حق.\nوهكذا الآخر صاحبه يعيدها بنكاح جديد إذا كانت تريده، ولو في الحال ما يحتاج عدة يعيدها له وليها بمهر جديد، ولا بأس مع التوبة والاستغفار فإن كانت لا تريده فارقها بطلقة واحدة، هذا الواجب وهذا هو الصحيح من أقوال أهل العلم في هذه المسألة، نعم.","link":"https://binbaz.org.sa/fatwas/7514/نكاح-البدل-لا-يجوز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23810.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":9417,"question":"أخونا المستمع واصل سالم الفارسي بعث برسالة يقول فيها: رجل متزوج من امرأتين وله جار، وتوفت زوجة جاره ومعها ابنة صغيرة ترضع، أعطاها الرجل الجار لحرمة الرجل الأولى، وأرضعتها حتى أكملت الرضاعة من الزوجة الأولى، فهل هذه الابنة تكون أختًا للأولاد من الزوجة الثانية أم لا، نرجو الإفادة؟","title":"حكم أولاد الزوجة الثانية إذا كان الرضاع من الأولى","answer":"الجواب: نعم، إذا كان للرجل زوجتان أو ثلاث أو أربع، فأرضعت إحداهن طفلة أو طفلًا في الحولين خمس رضعات أو أكثر فإن هذا الرضيع يكون ولدًا للزوج، ويكون أخًا لأولاده من النساء كلهن، يكون أخًا لأولادهن جميعًا، لكن أولاد المرضعة يكونون إخوانًا أشقاء، وأولاد الزوجات الأخريات يكن إخوة لأب؛ لأن الفحل واحد.\nفالتي أرضعت أولادها إخوة للرضيع من أمه وأبيه بالرضاع، وبقية الأولاد من الزوجة الثانية أو الثالثة أو الرابعة يكونون إخوة من الأب، كالنسب سواء، كما قال النبي ﷺ: يحرم من الرضاع ما يحرم من النسب.\nفأولاد الزوجات اللاتي لم يرضعن الطفل إخوة من الأب كالنسب، كما أن أولادهن من هذا الرجل إخوة لأولاد المرأة الأخرى من النسب من جهة الأب. نعم.","link":"https://binbaz.org.sa/fatwas/7582/حكم-اولاد-الزوجة-الثانية-اذا-كان-الرضاع-من-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19003.mp3","categories":["الرضاع"]},{"id":9430,"question":"أخونا (س. ص. الخثعمي ) من أبها بعث برسالة مطولة بعض الشيء يقول فيها: إنني ذهبت لأتزوج من أحد أفراد جماعتي، وسبق لي أن تزوجت عدة مرات ولدي بنين وبنات ولكن النساء متن، فذهبت وخطبت عند هذا الرجل الذي من الجماعة وقال: لن أزوجك ابنتي إلا بشرط أن تزوج ابني الأكبر ابنتك، فوافقت وتم الزواج، ولكل واحدة منهن مهر خاص بها وغير متساوٍ، وبرضا كل من ابنته وابنتي وتم الزواج، وبعد مضي خمسة أشهر من زواج ابنتي ماتت، وسؤالي الآن: ما حكم هذا الزواج؟ وهل هو شغار؟ وهل بوفاة ابنتي إن كان شغارًا هل انتهى الشغار بوفاتها أم لا، أرجو التوجيه في هذه الأمور جزاكم الله خيرا.","title":"صورة زواج الشغار وحكمه","answer":"الجواب: نعم. هذا النكاح شغار؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام عن جماعة من أصحابه  عن ابن عمر وأبي هريرة وجابر ومعاوية أنه ﷺ نهى عن الشغار، والشغار مثل ما قال النبي ﷺ: أن يقول الرجل للرجل: زوجني ابنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي هذا هو الشغار.\nفالذي ذكرته في السؤال شغار، وما دامت المرأة ماتت فأولادك لاحقون بك، وهم أولادك من أجل شبهة النكاح، وعليك التوبة إلى الله، والندم على ما حصل منك، وهكذا صاحبك عليه التوبة إلى الله، وعلى صاحبك الذي زوجته موجودة أن يجدد النكاح، عليه أن يجدد العقد؛ لأن العقد الأول فاسد، والأولاد لاحقون بآبائهم لأجل الشبهة، وعليه التوبة كما أن عليك التوبة، وعليه أن يجدد العقد بعد ما علم حكم الشرع يجدده من دون شرط امرأة أخرى، يجدده بشاهدين ولو ما توصلتما إلى المحكمة، ولو بالتزويج في البيت أو عند من ترون بحضرة شاهدين، والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7595/صورة-زواج-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19013.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":9475,"question":"أولى الرسائل في حلقة الليلة وردتنا من المستمعة (ح. غ) من المملكة، تقول في رسالتها: أنا أحاول أن أطبق تعليمات ديننا الحنيف من صلاة وصيام ومحافظة على الحجاب عن غير المحارم، إلا أنني أكشف عن وجهي ويدي وما يظهر عادة للمحارم لجد زوجي، فهل هو منهم أفيدوني أفادكم الله؟","title":"حكم محرمية جد الزوج بالنسبة للزوجة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فجزاك الله خيراً على اهتمامك بالدين وحرصك على المحافظة على ما أوجب الله عليك.\nأما السؤال عن جد الزوج فلاشك أنه محرم، جد الزوج أبو أبيه أو أبو أمه كلهم محارم، فلا بأس عليك بالكشف له كالوجه واليدين ونحو ذلك، كل هذا لا حرج فيه كسائر المحارم، كأخيك وعمك ونحو ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7636/حكم-محرمية-جد-الزوج-بالنسبة-للزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24101.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":9494,"question":"وأولى رسائل هذه الحلقة وردتنا من المرسل (ح. م. ن. ص. السامرائي) من العراق، يقول: عقدت مهري على بنت خالتي ولم أدخل بها، وحدثت مشاجرة بيني وبين جدتي أم والدتي، فقالت: إنك لا تستحق الحليب الذي رضعته مني، وعند ذلك انتبهت إلى كلامها، فسألتها عن عدد الرضعات، فقالت لي: لقد أرضعتك مع خالتك ولم أعلم عدد الرضعات، والآن أنا متحير في هذه المسألة، أرجو أن تفتوني مشكورين، مع العلم أني لم أدخل بها إلى الآن؟","title":"حكم من رضع من جدته وأراد أن يتزوج حفيدتها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الرضاع الذي يحصل به التحريم لابد أن يكون خمس رضعات معلومات، فإذا كانت جدتك لم تعلم هذه الرضعات ولم تحفظها فإنه لا حرج عليك في زواج ابنة خالتك؛ لأن الرضعات التي يحصل بها التحريم كما تقدم لابد أن تكون خمس رضعات معلومات، فإذا كانت الجدة شاكة في ذلك وليس عندها علم عن عدد الرضعات لا خمس ولا أقل ولا أكثر؛ فإن هذا الرضاع ليس عليه عمل ولا يعتمد، ولا حرج عليك في زواج ابنة خالتك، وفق الله الجميع.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7661/حكم-من-رضع-من-جدته-واراد-ان-يتزوج-حفيدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_242/24204.mp3","categories":["الرضاع"]},{"id":9501,"question":"وأولى رسائل هذه الحلقة وردتنا من المرسل (ح. م. ن. ص. السامرائي) من العراق، يقول: عقدت مهري على بنت خالتي ولم أدخل بها، وحدثت مشاجرة بيني وبين جدتي أم والدتي، فقالت: إنك لا تستحق الحليب الذي رضعته مني، وعند ذلك انتبهت إلى كلامها، فسألتها عن عدد الرضعات، فقالت لي: لقد أرضعتك مع خالتك ولم أعلم عدد الرضعات، والآن أنا متحير في هذه المسألة، أرجو أن تفتوني مشكورين، مع العلم أني لم أدخل بها إلى الآن؟","title":"حكم من رضع من جدته وأراد أن يتزوج حفيدتها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الرضاع الذي يحصل به التحريم لابد أن يكون خمس رضعات معلومات، فإذا كانت جدتك لم تعلم هذه الرضعات ولم تحفظها فإنه لا حرج عليك في زواج ابنة خالتك؛ لأن الرضعات التي يحصل بها التحريم كما تقدم لابد أن تكون خمس رضعات معلومات، فإذا كانت الجدة شاكة في ذلك وليس عندها علم عن عدد الرضعات لا خمس ولا أقل ولا أكثر؛ فإن هذا الرضاع ليس عليه عمل ولا يعتمد، ولا حرج عليك في زواج ابنة خالتك، وفق الله الجميع.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7661/حكم-من-رضع-من-جدته-واراد-ان-يتزوج-حفيدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_242/24204.mp3","categories":["الرضاع"]},{"id":9521,"question":"هذا سؤال من سائلة من العراق تقول: من رضع من امرأة ولها ضرائر فهل يحرم عليه بنات الجميع، كما قرأت في كتاب مقدمة الوصول إلى طريق الرسول؟","title":"حكم من رضع من امرأة لها ضرائر","answer":"الجواب: نعم، من رضع من امرأة لها ضرائر فإن أولاد الضرائر إخوة له من أبيه، وأما أولادها فإخوة له من أمه وأبيه أشقاء بالرضاع، إذا كان الرضاع خمس مرات أو أكثر يمسك الثدي ويمتص اللبن خمس مرات كل مرة منفصلة عن الأخرى ولو في مجلس واحد يمتص اللبن ويطلق الثدي ثم يعود ثم يمتص اللبن ثم يعود خمس مرات في المجلس أو في مجالس أو في أيام مادام في سن الرضاع في الحولين، فإن هذا الرضاع يجعله ولداً للزوج -زوج المرأة المرضعة- ويجعل أولاد الزوج من الضرائر إخوة له من أبيه، لقول النبي ﷺ: يحرم من الرضاع مايحرم من النسب ولقول الله سبحانه: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23] فيعم الأخوات من الأب ومن الأم و منهما جميعاً . نعم .\nالمقدم: وبنات الضرائر كذلك ؟\nالشيخ: بنات الضرائر أخواته وأولاد الضرائر إخوة له كلهم من أبيه إخوة من أب كالنسب، وأولاد المرأة من غير هذا الزوج كذلك لوكان لها أولاد من غير هذا الزوج من زوج قبله أو بعده إخوة له من أمه .نعم .\nوالملاحظ في هذا مثلما تقدم لابد خمس رضعات فأكثر. نعم.","link":"https://binbaz.org.sa/fatwas/7684/حكم-من-رضع-من-امراة-لها-ضراىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_244/24403.mp3","categories":["الرضاع"]},{"id":9588,"question":"يسأل أيضاً ويقول: هناك من العوام من يعتقد أن من أنقذ طفلاً أو طفلة غريقة تكون بنتاً له ولا يصح له الزواج منها، وإن كانت ولداً فتكون ولداً له. أفيدونا عن صحة هذه المقولة بارك الله فيكم؟","title":"هل تثبت المحرمية لمن أنقذ طفلة من الغرق؟","answer":"الجواب: هذا من خرافات العامة، هذا وأشباهه من خرافات العامة ومن أكاذيبهم التي يقولونها بغير حجة، فلو أنقذ إنسان طفلة من غرق أو حرق أو غيرهما فإنه لا يكون محرماً لها إذا كانت أجنبية حتى ولو كانت كبيرة، فإذا أنقذها إنسان من غرق أو حرق أو هدم فإنه يكون محسناً وله أجر المحسنين وله ثواب المحسنين، لكن لا يكون محرماً لها بذلك، وهكذا لو أنقذ ذكراً لا يكون أباً له ولا محرماً له ولزوجته ونحو ذلك لا، بل يكون على حاله الأولى إن كان أجنبياً فهو أجنبي وإن كان قريباً فهو قريب، المقصود أن إنقاذ الطفل أو الطفلة أو إنقاذ الكبير أو إنقاذ الكبيرة لا يكون سبباً للمحرمية.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7747/هل-تثبت-المحرمية-لمن-انقذ-طفلة-من-الغرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24804.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":9734,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع (أحمد . م. ع) من مكة المكرمة يقول في رسالته: لي ابن خالة قد رضع مع خالي وخالي ليس بشقيق لوالدتي بل أخيها من أبيها، فهل يصبح خالًا لي هو وإخوانه أيضًا، ولي ابنة خالة قد رضعت من أم خالي ولكن لم ترضع معه بل مع أخته وأخيه من أمه وأبًا آخر، فهل تجوز لي أن أتزوجها أفيدوني أفادكم الله؟","title":"حكم إرضاع ابن الخالة من زوجة جده لأمه","answer":"الجواب: إذا كان ابن خالتك قد رضع من زوجة جدك ولو كانت من غير جدتك من زوجة أخرى فإنه يكون خالًا لك وأخًا لأمك ولو كان من أبيها، متى رضع من زوجة جدك سواء كان جدة لك أو ليست جدة لك فإن هذا الرضيع إذا رضع خمس مرات أو أكثر حال كونه طفلًا في الحولين فإنه يكون خالًا لك؛ لأنه صار أخًا لأمك من أبيها، وإن كان من أمها صار أخًا لها من أبيها وأمها فيكون خالًا لك بكل حال.\nالشيخ: وايش سؤاله الثاني.\nالمقدم: لي ابنة خالة قد رضعت من أم خالي ولكن لم ترضع معه بل مع أخته وأخيه من أمه وأبًا آخر فهل تجوز لي؟\nالشيخ: إذا كانت رضعت من زوجة الجد الذي هو أبو الخال وأبو الأم ،إذا كان رضعت منه رضاعًا تامًا خمس مرات فأكثر بنت خاله هذه فإنها تكون أيضًا خالة تصير أختًا للأم مثل ما سبق، ولو كانت راضعة من شخص قبل خاله أو بعد خاله ما هو بلزوم مع خاله متى رضعت من زوجها التي هي أم خاله وأم أمه أو من زوجة أخرى ليست أمهما بل زوجة لأبيهما أخرى وسواء كانت معهما أو مع أولاد قبلهما أو أولاد بعدهما فإنها تكون خالة إذا كان الرضاع خمس مرات أو أكثر في الحولين.","link":"https://binbaz.org.sa/fatwas/7888/حكم-ارضاع-ابن-الخالة-من-زوجة-جده-لامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_195/19511.mp3","categories":["الرضاع"]},{"id":9748,"question":"وهذه رسالة وردت من السودان من كسلا من عبد العزيز محمد أسحت يقول في رسالته: هل نقل الدم للمريض يدخل إليه أي تحريم كاللبن مثلاً، أفيدونا أفادكم الله؟","title":"نقل الدم لا يأخذ حكم الرضاع","answer":"الجواب: لا، نقل الدم لا يكون مثل الرضاع، نقل الدم لا يضر ولا يكون حكمه حكم الرضاع، فلو أن زوجاً أعطى زوجته من دمه إسعافاً لها فإنها لا تحرم عليه بذلك، بل هذا من باب المساعدة كالمساعدة بالمال.\nالرضاع شيء آخر، ليس له حكم الدم، وليس للدم حكم الرضاع. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7916/نقل-الدم-لا-ياخذ-حكم-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25607.mp3","categories":["الرضاع"]},{"id":9955,"question":"أولى رسائل هذه الحلقة وردتنا من المرسل (و. م. د) من الجوف بالمملكة، يقول الأخ السائل في رسالته: لي ابنة خالة أريد الزواج منها لكن أهلها رفضوا ذلك بحجة أنها أختي من الرضاع، ولكن أهلي أخبروني خلاف ذلك، والرضاع قد حصل بين ابنة خالتي وأختي، فهل يمنع ذلك الزواج من ابنة خالتي أم لا، أفيدوني أفادكم الله؟","title":"حكم زواج الرجل بامرأة رضعت مع أخته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالرضاع الكامل المستوفي لشروطه يمنع من النكاح، فهذه المسألة التي ذكرت تعرض على المحكمة حتى تنظر في الموضوع تحضر المرضعة تسألها عن صفة الرضاع وفيما تراه المحكمة الكفاية إن شاء الله، ولا تقدم على الزواج إلا على بصيرة وعلى علم بأن هناك سلامة لدينك مما حرم الله عليك جل وعلا.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8134/حكم-زواج-الرجل-بامراة-رضعت-مع-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26601.mp3","categories":["الرضاع"]},{"id":9964,"question":"أولى رسائل هذه الحلقة وردتنا من المرسل (و. م. د) من الجوف بالمملكة، يقول الأخ السائل في رسالته: لي ابنة خالة أريد الزواج منها لكن أهلها رفضوا ذلك بحجة أنها أختي من الرضاع، ولكن أهلي أخبروني خلاف ذلك، والرضاع قد حصل بين ابنة خالتي وأختي، فهل يمنع ذلك الزواج من ابنة خالتي أم لا، أفيدوني أفادكم الله؟","title":"حكم زواج الرجل بامرأة رضعت مع أخته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالرضاع الكامل المستوفي لشروطه يمنع من النكاح، فهذه المسألة التي ذكرت تعرض على المحكمة حتى تنظر في الموضوع تحضر المرضعة تسألها عن صفة الرضاع وفيما تراه المحكمة الكفاية إن شاء الله، ولا تقدم على الزواج إلا على بصيرة وعلى علم بأن هناك سلامة لدينك مما حرم الله عليك جل وعلا.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8134/حكم-زواج-الرجل-بامراة-رضعت-مع-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26601.mp3","categories":["الرضاع"]},{"id":10070,"question":"المستمع سعيد علي محمد يماني بعث يسأل ويقول: رجل تزوج امرأة على أن يحللها لزوجها الأول، وبعد الزواج رفض أن يطلقها، فما هو توجيهكم؟","title":"حكم زواج التحليل","answer":"الجواب: إذا كان النية تحليلها لزوجها، إذا كانت النية تحليلها لزوجها فهذا نكاح باطل وصاحبه ملعون نعوذ بالله من ذلك والرسول ﷺ لعن المحلل والمحلل له وهو نكاح ملعون صاحبه وهو فاسد لا يحلها لزوجها الأول، ولا للثاني الذي نكحها بنية التحليل ولو رغب فيها، بل يجب عليه أن يطلقها طلقة واحدة لإبطال هذا العقد الفاسد وإزالة شبهته، وبعد ذلك هي مخيرة شاءت تزوجت عليه وإن شاءت تزوجت على غيره بعد خروجها من العدة إذا كان وطئها، فإذا خرجت من العدة بثلاث حيض إن كانت تحيض أو بثلاثة أشهر إن كانت كبيرة لا تحيض أو صغيرة لا تحيض، وإذا خرجت من العدة فهي تنكح من شاءت غير زوجها الأول حتى يتزوجها زوج شرعي ويطأها يتزوجها زوج شرعي ما أراد التحليل ثم طلقها أو مات عنها تحل لزوجها الأول، أما هذا الذي أراد التحليل ولو وطئها لا تحل لزوجها الأول وهو عاص بعمله، ملعون كما في الحديث يجب عليه أن يفارقها بطلقة واحدة ثم بعد التوبة وخروجها من العدة له أن يتزوجها من جديد إذا رضيت بذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8245/حكم-زواج-التحليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30408.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10294,"question":"إذا حرمت علي امرأة، فهل بناتها يحرمن علي؟","title":"هل تحرم البنت بحرمة الأم؟","answer":"الجواب: هذا فيه تفصيل: إن كانت المرأة أختك فبناتها بنات أختك، حرام عليك هي وبناتها؛ لأنك خالهن، أما إذا كانت عمتك أو خالتك فإنها تحرم عليك هي؛ لأنها خالة وعمة لكن لا تحرم بناتها؛ لأن بنات الخالة حل وبنات العمة حل لك أن تتزوج منهن، وهكذا لو كانت زوجة أبيك أو زوجة جدك فإنها محرم لك، لكن بناتها من غير جدك من زوج آخر لسن محارم لك بل أجنبيات، وإنما حرمت هي عليك؛ لأنها زوجة أبيك أو جدك، لكن بناتها من غير أبيك ومن غير جدك لسن محارم لك إن لم يكن بينك وبينهن رضاعة.\nفالمقصود أن هذا فيه تفصيل: فالمرأة التي هي محرم لك تكون بناتها محرماً لك إذا كانت أختاً لك أو زوجةً لأبيك أو زوجة لجدك أو بنتاً لك أو بنت ابن لك فبناتها كذلك محارم، أما إذا كانت خالةً أو عمةً فإن بناتها لسن محارم لك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8467/هل-تحرم-البنت-بحرمة-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31207.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":10384,"question":"حدثونا عن نكاح الشغار بالتفصيل، فهناك كثير من الأقرباء والأصدقاء كل منهم متزوج أخت الآخر والعكس بالعكس؟","title":"زواج الشغار.. تعريفه وحكمه","answer":"الجواب: الشغار: هو الذي يكون بالشرط زوجني وأزوجك هذا الشغار، أما إذا قال: زوجني وأزوجك، ما أزوجك حتى تزوجني هذا هو الشغار ما يجوز، النكاح باطل لا يجوز، أما إذا خطب منه، وهذا خطب منه من دون مشارطة فلا بأس، زوجه أخته، وزوجه أخته، بنته بنته عمته عمته لا بأس، لكن من دون مشارطة، أما أن يقول: لابد تزوجني وأزوجك، ما تزوجني ما أوزوجك، هذا يقال له: نكاح الشغار، والرسول نهى عنه عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8556/زواج-الشغار-تعريفه-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28009.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10418,"question":"المستمع محمد منير باكستاني من باكستان ويعمل في المملكة -الجلة- بعث برسالة يقول فيها: رجل رضع ثدي جدته مع ابنها وعمره سنة -أي: أنه في سن الرضاع- واستمر هذا الرضاع سنة، ثم بعد ذلك تزوج من ابنة عمه، فهل صار هذا الرجل أخًا لعمه من الرضاع أم لا؟ وإذا كان أخًا لعمه هل يجوز زواجه من ابنة عمه؟ لقد أفتى بعض العلماء بعدم صحة هذا الزواج، ثم أفتاه أحدهم بصحة هذا الزواج، علمًا بأن له من ابنة عمه أربعة أو خمسة أولاد، أرجو الإفادة هل هذا الزواج صحيح أم لا؟ وإذا كان غير صحيح فما هو المترتب على ذلك، وما هو وضع الأولاد، أفيدونا جزاكم الله خيرا؟","title":"حكم الزواج بابنة العم إذا رضع الزوج من أم عمه","answer":"الجواب: إذا كان الرضاع ثابتًا بإقرار الجدة وهي ثقة، أو بشهادة بعض الثقات أنها أرضعته خمس مرات فأكثر، ولو كان أقل من السنة، خمس مرات فأكثر تكفي، فإنه يكون ولدًا لها ويكون أخًا لأبيه إذا كانت أم أبيه يكون أخًا لأبيه، ويكون أخًا لأعمامه، وتكون بنت عمه بنت أخيه ليس له زواجها؛ لأن العم صار أخًا والأب صار أخًا، فيكون النكاح باطلًا من ابنة عمه؛ لأنها ابنة أخيه من الرضاعة.\nوقد ثبت عن الرسول ﷺ أنه قيل له: ألا تنكح ابنة حمزة؟ قال: إنها لا تحل لي إنها ابنة أخي من الرضاعة ويحرم من الرضاعة ما يحرم من النسب.\nفالخلاصة: أن هذا الرجل الذي نكح ابنة عمه وقد ثبت الرضاع من جدته له أن نكاحه باطل وأولاده تبعًا له لأجل شبهة النكاح الذي غلطوا فيه، أولاده ينسبون إليه والحمد لله، ولكن يجب عليه مفارقتها وعدم اتصاله بها، وأن يثبت ذلك عند المحكمة حتى تزوج من شاءت بعد العدة، إذا كان الرضاع ثابتًا بإقرار المرأة وهي ثقة يعني: الجدة، أو بشاهد ثقة أو امرأة ثقة تعرف ذلك وتضبط ذلك أنها أرضعته سنة أو أقل من ذلك، والمطلوب خمس رضعات، متى أرضعته خمس رضعات فأكثر كفى، لقول النبي ﷺ لزوجة أبي حذيفة: أرضعي سالمًا خمس رضعات تحرمي عليه، وهي سهلة بنت سهيل بن عمرو قال لها: أرضعي سالما خمس رضعات تحرمي عليه.\nوفي صحيح مسلم عن عائشة رضي الله عنها قالت: كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات فتوفي النبي ﷺ وهي فيما يقرأ من القرآن، وفي رواية الترمذي رحمه الله: والأمر على ذلك. فالواجب على هذا الرجل ما دام رضاعه ثابتًا أن يفارق ابنة عمه؛ لأنها صارت ابنة أخيه وأولاده منها تابعون له من أجل شبهة النكاح، ونسأل الله أن يعوض كل واحد منهم خيرًا من صاحبه، وأن يوفق الجميع لما يرضيه، وإذا كان لم يتعمدها بل عن جهل فنسأل الله أن يعفو عنهما.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8591/حكم-الزواج-بابنة-العم-اذا-رضع-الزوج-من-ام-عمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34104.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":10423,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول المستمع خليفة السعيد من سوريا يقول: أنا رجل مسلم اتفقت أنا ورجل مسلم آخر وزوجته أختي وزوجني بنته، وأنجبت بنته مني تسعة أولاد، وأنا أحبها لأنها صاحبة دين وخلق، هل زواجي صحيح؟ وإذا لم يكن صحيحاً فكيف أعمل، وجزاكم الله خيراً؟","title":"حقيقة نكاح الشغار وكيفية تصحيحه لمن وقع فيه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه.\nأما بعد: فهذا الزواج فيه تفصيل: فإن كنت اشترطت عليه وشرط عليك هذا الزواج فهذا يسمى نكاح الشغار، وقد نهى عنه النبي عليه الصلاة والسلام في الأحاديث الصحيحة، والشغار أن يقول الرجل: زوجني بنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي أو بنتي، أو يقول نحو ذلك كبنت أخيه ونحو ذلك، هذا يقال له: الشغار، ويقال له عند بعض الناس: نكاح البدل، فإذا كنت حين زوجته أختك وزوجك بنته عن اشتراط بينكما فهذا يسمى نكاح الشغار، وعليكما أن تجددا العقد، إذا كان كل واحد يرغب في زوجته وهي ترغب فيه فيجدد النكاح بمهر جديد وشاهدين، تقول: زوجتك، وهو يقول: زوجتك، أنت تقول: زوجتك أختي، بمهر جديد ولو قليلاً بحضرة شاهدين عدلين إذا كانت راضية، وهو كذلك إذا كانت بنتك تريده، يقول: زوجتك، وتقول: قبلت، ولو بمهر قليل كمائة ريال أو مائتين أو أكثر، بحضرة شاهدين وينتهي الأمر والحمد لله، وما مضى معفو عنه لأجل الجهل، وأولادكم لكم، أولادك وأولاده كل واحد أولاده تابعون له للجهل، والله يعفو عما سلف بسبب الجهل سبحانه وتعالى، كما قال جل وعلا في كتابه الكريم: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] فقال الله: قد فعلت.\nأما إن كنتما لم تشترطا، بل خطب منك وخطبت منه فقط فالنكاح صحيح ولا حرج، خطب أختك وخطبت بنته من دون مشارطة فالنكاح صحيح ولا حرج عليكما والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8593/حقيقة-نكاح-الشغار-وكيفية-تصحيحه-لمن-وقع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31701.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10456,"question":"المستمع (م. ع. س) يقول: ما حكم الزواج من امرأة لا تصلي؟","title":"حكم الزواج من امرأة لا تصلي","answer":"الجواب: لا يجوز لمسلم أن يتزوج امرأة لا تصلي؛ لأن ترك الصلاة كفر، كفر أكبر على الصحيح، وعند آخرين كفر أصغر، فلا يجوز له أن يتزوج امرأة لا تصلي؛ لأنها كافرة على الصحيح حتى تصلي، وفي النساء بحمد الله المسلمات غنية عنها، يلتمس، يلتمس المرأة الطيبة، يقول النبي ﷺ: تنكح المرأة لأربع: لمالها، ولحسبها، ولجمالها، ولدينها، فاظفر بذات الدين تربت يداك فالمؤمن يلتمس ذات الدين المعروفة بالستر والصلاة وحسن السمعة، حتى يختارها شريكة له، أما من عرفت التساهل في دينها، أو بترك الصلاة، فهذه لا يرغب فيها، ولا ينبغي له أن يتزوجها، ولا يصح نكاحه لها إذا كانت لا تصلي، إلا إذا كان مثلها لا يصلي، صح نكاحهما، وهما كافران حينئذ، كما يصح نكاح الوثني مع الوثنية، واليهودي مع اليهودية، والنصراني مع النصرانية، كلهم كافر، نكاحهم صحيح فيما بينهم، إذا تمت شروطه الأخرى، هكذا الذي لا يصلي مع من لا تصلي نكاحهما صحيح، إذا تمت الشروط الأخرى.\nأما المسلم الذي من الله عليه بالاستقامة والصلاة فليس له أن ينكح امرأة لا تصلي، نسأل الله السلامة والعافية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8632/حكم-الزواج-من-امراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31910.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10573,"question":"المستمع عمر محمد عابدين، مقيم بضواحي مكة المكرمة بعث يسأل ويقول: لقد رضع شقيقي الأصغر من ابنة عمتي مع بنتها الكبرى رضعة واحدة، وأريد أن أتزوج من بنتها الرابعة فهل يجوز لي ذلك أم لا؟ مع العلم بأن أمهاتنا متأكدات بأن الرضعة واحدة، ولكن لا يعلمن هل كانت مشبعة أم لا؟ وهل يجوز لشقيقي المذكور الزواج من أصغر بناتها؟ جزاكم الله خيراً.","title":"الرضاع المحرم","answer":"الجواب: الرضعة لا تحرم ولا يحصل بها تحريم الرضاع، لابد من خمس رضعات، فله أن يتزوجها ولك أن تتزوجها أو تتزوج إحدى أخواتها، ليس على هذا عمل، ثم لو قدر أنها أرضعته خمس رضعات يختص التحريم به هو، أما أنت فلا حرج أن تتزوج أختها، إنما التحريم إذا أرضعته يكون أخاً لها، إذا أرضعته أمها خمس رضعات يكون أخاً لها هو، أما أنت فلست أخاً لها أنت لم ترضع.\nفالحاصل: أنك لك أن تتزوج إحدى بناتها لأنك لست رضيعاً لهن، ولست أخاً لهن، أما هو لو ثبت أنها أرضعته خمساً صار ولداً لها هو خاصاً به. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8752/الرضاع-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32312.mp3","categories":["الرضاع"]},{"id":10574,"question":"من القصيم من بريدة المستمع محمد .........بعث برسالة تضمنها ثلاثة أسئلة، في سؤال الأول يقول: ما هو نكاح الشغار؟ أفيدونا جزاكم الله خيراً؟","title":"صفة زواج الشغار وحكمه","answer":"الجواب: نكاح الشغار هو: أن يشترط كل واحد من الوليين نكاح المولية الأخرى، فيقول أحدهما زوجتك بنتي على أن تزوجني بنتك، أو أختي على أن تزوجني أختك، وهكذا ما أشبه ذلك، يعني يشترط كل واحد تزوجه بالأخرى، زيد يخطب هند، وعمرو يخطب أخت زيد، كل واحد يشترط على الآخر، زيد يشترط على عمرو، وعمرو يشترط على زيد أخته، أو بنته، أو بنت أخيه، هذا هو الشغار؛ لقول النبي ﷺ: الشغار أن يقول رجل زوجني بنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي، هذا هو الشغار أي التشارط في تزويج المولية للشخص سواءٌ كانت بنته، أو أخته، أو بنت أخيه، أو بنت عمه، يقول أنا أزوجك إياه لكن بشرط أنك تزوجني بنتك ، أو أختك، أو ما أشبه ذلك، وهذا لا يجوز المهر هذا باطل، أما لو خطب منك وخطب الآخر من دون مشارطة، فلا حرج، وخطب بنت هذا وهذا خطب بنت هذا، والآخر خطب بنته، أو أخته لا حرج، من دون مشارطة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8747/صفة-زواج-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32307.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10702,"question":"يقول: لي أعمام كل واحد عنده ولد وبنت زوجوا أبناءهم من بعضهم، هل يسمى هذا بزواج الشغار؟ علماً بأنهم أنجبوا أطفال، فما رأي سماحتكم في هذا الزواج؟ وهل هذا الزواج باطل علماً بأن لكل زوجة من الزوجات مهر خاص ولا يساوي مهر الأخرى، فهل في هذه الحالة يجب الطلاق، وهل الأطفال شرعيون أم لا، أفيدونا جزاكم الله خيراً؟","title":"نكاح الشغار.. حكمه وكيفية تصحيحه لمن وقع فيه","answer":"الجواب: إذا كان الزواج من دون اشتراط بل خطب هذا وخطب هذا وزوج هذا وزوج هذا بالرضا، فليس هذا شغارا ولا حرج أن ينكح الإنسان ابنة عمه أو ابنة خاله والآخر كذلك لا حرج في ذلك، الشغار أن يكون عن شرط زوجني وأزوجك، هذا هو الشغار، إذا قال كل منهما للآخر: زوجني ابنتك وأنا أزوجك بنتي، أو زوج ولدي وأنا أزوج ولدك أو ما أشبه ذلك، هكذا جاء الحديث عن رسول الله عليه الصلاة والسلام لما سئل عن الشغار قال: هو أن يقول الرجل: زوجني ابنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي، هذا هو الشغار يعني المشارطة هذا يشرط وهذا يشرط، أما إذا خطب هذا من هذا وخطب هذا من هذا من دون مشارطة فلا حرج في ذلك ولا يسمى شغاراً.\nوإذا كان شغاراً بالمشارطة فالأولاد تابعون لآبائهم من أجل شبهة النكاح؛ لأن نكاح الشغار فاسد وفيه خلاف بين أهل العلم، فالشبهة التي في صحة النكاح وفساده توجب إلحاق الأولاد بآبائهم، ولكن ما دام كل واحد يرغب في زوجته فإنه يجدد النكاح كل واحد يجدد النكاح، وإذا كانت زوجته لا ترغب فيه فإنه يطلقها طلقة واحدة وتكفي، أما إذا كان يرغب فيها وهي ترغب فيه فإنه يجدد النكاح، إذا كان هناك مشارطة فيزوجه من جديد يزوج وليها من جديد بعقد شرعي ومهر شرعي وحضور شاهدين ولا حاجة إلى عدة بل في الحال؛ لأن الماء ماؤه إن كانت حاملاً فالماء ماءه.\nفالحاصل: أنه يزوج في الحال بحضرة شاهدين وبعقد جديد ومهر جديد إذا رضيت به وهو أحبها فلا بأس بذلك، أما إذا كان لا يرغب فيها أو هي لا ترغب فيه، فيطلقها طلقة واحدة فإذا اعتدت تزوجت من شاءت.\nفينبغي الفهم لهذا المقام لئلا يشتبه المقام، فالمشارطة تجعل النكاح شغاراً وعدم المشارطة تجعل النكاح صحيحاً، فالذي يقول لعمه أو لخاله: زوجني بنتك وهو يقول: أزوجك بنتي مشارطة زوجني وأزوجك، يعني: ما يرضى هذا إلا بزواج هذا، لا يعطيه ابنته حتى يعطيه ابنته أو أخته حتى يعطيه أخته، فهذا هو الشغار، أما إذا كان بالرضا من دون مشارطة فلا حرج في ذلك والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8878/نكاح-الشغار-حكمه-وكيفية-تصحيحه-لمن-وقع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_342/34202.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10762,"question":"سنعود إلى رسالة أخينا في حلقة قادمة إن شاء الله تعالى لنستكمل ما تبقى من أسئلتها، فننتقل الآن إلى رسالة وصلت إلى البرنامج من العراق وباعثها أحد الإخوة من هناك يقول: أنا عبد الكريم حسن مهدي من العراق، لي من الإخوان أربعة رجال وأربع نساء وأنا التاسع فيهم والصغير منهم، بنت عمي رضعت مع أخي الكبير وتزوجت شخصاً آخر وأنجبت بنت، هل يحق لي الزواج من هذه البنت أم لا، علماً بأن الناس يقولون: إذا كانت الرضاعة تمت عليهما سوياً فهما اللذان لا يحق لهما الزواج من بعضهما، أفيدونا جزاكم الله خيراً؟","title":"حكم التزوج ببنت رضعت أمها مع أخي الكبير","answer":"الجواب: إذا كانت رضعت من أمك مع أخيك خمس رضعات أو أكثر في الحولين ولو في مجلس واحد أو في يوم واحد، فإنها تكون أختكم ولو أنها مع أخيك الكبير، تكون أختكم جميعاً، وليس لك أن تنكح ابنتها؛ لأنك خالها، أنت خال أولادها جميعاً وإن نزلوا خال أولادها وأولاد أولادها، إذا كانت هذه المرأة رضعت من أمك خمس رضعات أو أكثر، فإنها تكون أختاً لكم ولجميع أولاد أمك ولجميع أولاد أبيك صاحب اللبن، تكون أختاً لكم جميعاً إذا كانت رضعت خمس رضعات أو أكثر في الحولين، حال كونها طفلة في الحولين، وأولادها لا يجوز لك نكاح بنت منهم أنت خالهم خال أولادها الذكور والإناث جميعاً؛ لأنها صارت أختك من الرضاعة وصار أولادها أولاد أختك، وأنت خالهم فليس لك أن تنكح من بناتها شيئاً، ولا من بنات بناتها ولا بنات أولادها وإن نزلوا، فأنت خالهم جميعاً وإن نزلوا. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8933/حكم-التزوج-ببنت-رضعت-امها-مع-اخي-الكبير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_347/34703.mp3","categories":["الرضاع"]},{"id":10780,"question":"بالنسبة لهذه الرسالة وردتنا من المستمع (أ. ع. م) من العراق يقول: نحن خمسة إخوة وأن عمتي قد أرضعت أخي الأكبر وأن والدتي لم ترضع من أولادها أحد وأنا أصغر إخوتي فهل يجوز لي أن أتزوج من بنت عمتي أرشدونا؟","title":"حكم زواج إخوة الراضع من بنات مرضعة أخيهم","answer":"الجواب: نعم لا حرج إنما تحرم بناتها على من رضع منها، وأما الإخوة الذين لم يرضعوا فإنهم لا يحرم عليهم أن يتزوجوا من بنات العمة لأن الرضاع يختص بالذي رضع فقط، إذا كن بنات العمة لم يرضعن من أمك أيها السائل! ولا من أخواتك ولا من زوجة أبيك، يعني: لم يرضعن من امرأة تحرم عليك بنتها فلا حرج عليك، وكون أخيك الكبير رضع من عمتك لا يمنع تزويج البقية من بنات العمة. نعم.","link":"https://binbaz.org.sa/fatwas/8962/حكم-زواج-اخوة-الراضع-من-بنات-مرضعة-اخيهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_350/35008.mp3","categories":["الرضاع"]},{"id":10804,"question":"يقول في سؤال آخر: زوجة أخينا أنجبت توأمين ذكورًا، أحدهما أحضرته والدتنا لكي ترضعه، ولكنه رفض الرضاعة مدة ليلة واحدة، ولم تدر عليه اللبن، وفي الصباح أعطته لأمه وأحضرت الآخر، وقد ربته وأرضعته،  هل الأول الذي لم يرضع هل يتزوج بنات أعمامه، أم أنهن إخوته؟","title":"الرضاع المحرم خمس رضعات فأكثر في الحولين","answer":"الجواب:  الذي لم يرضع له أن يتزوج بنات أعمامه؛ لأنه ليس ولدًا لأمكم، ما أرضعته، ولو ربته، ولو أحسنت إليه، ولو حاولت إرضاعه، ما دام ما رضع فإنه يكون ابن عم البنات، ويتزوج من بنات أعمامه، كغيره من الناس؛ لأن الرضاع المحرم لابد أن يكون خمس رضعات فأكثر في الحولين، فإذا كانت أمكم لم ترضعه فإنه يكون سائغًا، الزواج من بنات أعمامه ليس هناك مانع، نعم. المقدم: أمهم أرضعت أخاه التوأم. الشيخ: ما يضر، ما يضر، إنما الرضاع لأخيه التوأم فقط، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8981/الرضاع-المحرم-خمس-رضعات-فاكثر-في-الحولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35303.mp3","categories":["الرضاع"]},{"id":10848,"question":"يقول: إني أخ من الرضاعة لابنة عمي، هناك أقوال تقول: إن إخوانك من أسرة عمك هم البنت والذين أصغر منها والأكبر منها ليسوا إخوانك، فما هو توجيه سماحتكم؟","title":"الضابط في التحريم بالرضاع","answer":"الجواب:  إذا ارتضع الإنسان من المرأة صار أولادها كبارهم وصغارهم إخوة له، الرضيع الذي ارتضع معه والذي قبله والذي بعده كلهم إخوة، إذا ارتضع رضاعًا شرعيًا خمس رضعات، أو أكثر في الحولين، يعني: حال كونه في الحولين فإن أولاد المرضعة، وأولاد زوجها يكونون إخوة لهذا الرضيع كلهم، صغارهم وكبارهم الذي قبله والذي بعده، إذا كان الرضاع تامًا خمس رضعات أو أكثر، وكان الطفل في الحولين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9021/الضابط-في-التحريم-بالرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35602.mp3","categories":["الرضاع"]},{"id":10850,"question":"يقول: إني أخ من الرضاعة لابنة عمي، هناك أقوال تقول: إن إخوانك من أسرة عمك هم البنت والذين أصغر منها والأكبر منها ليسوا إخوانك، فما هو توجيه سماحتكم؟","title":"الضابط في التحريم بالرضاع","answer":"الجواب:  إذا ارتضع الإنسان من المرأة صار أولادها كبارهم وصغارهم إخوة له، الرضيع الذي ارتضع معه والذي قبله والذي بعده كلهم إخوة، إذا ارتضع رضاعًا شرعيًا خمس رضعات، أو أكثر في الحولين، يعني: حال كونه في الحولين فإن أولاد المرضعة، وأولاد زوجها يكونون إخوة لهذا الرضيع كلهم، صغارهم وكبارهم الذي قبله والذي بعده، إذا كان الرضاع تامًا خمس رضعات أو أكثر، وكان الطفل في الحولين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9021/الضابط-في-التحريم-بالرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35602.mp3","categories":["الرضاع"]},{"id":10860,"question":"من العراق بغداد المواطن عادل جاسم بعث يسأل ويقول: يقال: إن رسول الله ﷺ حرم زواج المتعة في خطبته الشهيرة أثناء حجة الوداع، أصحيح ما يقال؟","title":"حكم نكاح المتعة","answer":"الجواب: نعم حرم نكاح المتعة في حجة الوداع -عليه الصلاة والسلام- قال: إني كنت أذنت في الاستمتاع من النساء، وإن الله قد حرم ذلك إلى يوم القيامة، فالمتعة محرمة، إذ قال بعض أهل العلم: إنه حرمها مرتين في حجة الوداع، وفي عام الفتح، ولكن في هذا نظر، وبكل حال فهي أصبحت محرمة منسوخة، سواء كانت محرمة مرتين، أو مرة واحدة، فهي أصبحت محرمة وممنوعة، ولا يحل نكاح المتعة، بل لابد أن يكون النكاح عن رغبة، لا عن متعة عند أهل السنة والجماعة بإجماع أهل السنة والجماعة.","link":"https://binbaz.org.sa/fatwas/9041/حكم-نكاح-المتعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35709.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":10864,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أرجو إفادتي سماحة الشيخ! إذ أني تزوجت منذ ما يقارب العشر سنوات، ولقد أنجبت من زوجتي خمسة أولاد، وعلمت بأن أم زوجتي قد أرضعتني، وأنا لا أعلم عدد هذه الرضعات أرجو إفادتي، صاحب السؤال هو المستمع (ع. م. أ) من جمهورية مصر العربية، ومقيم حاليًا في دولة قطر؟","title":"حكم من تزوج بامرأة ثم علم أن أمها أرضعته","answer":"الجواب:  إذا كنت لا تعلم عدد الرضعات، وليس هناك من يعلمها فلا شيء عليك حتى تعلم أنت، أو يخبرك ثقة من الرجال، أو النساء أنها أرضعتك خمس رضعات، أو أكثر في الحولين، وأنت في الحولين، أما ما دامت الرضعات مجهولة لا تعرفها أنت ولا غيرك، والمرضعة غير موجودة، أو ناسية، فليس عليك شيء، وزوجتك معك والحمد لله، لأن الأصل براءة الذمة، والأصل سلامة النكاح، والأصل عدم وجود الرضاع المحرم، هذا هو الأصل، فلا يثبت الرضاع إلا باليقين أنها أرضعتك خمس رضعات، أو أكثر حال كونك في الحولين بخبرها إذا كانت ثقة، أو بخبر ثقة عنها شاهد رضاعك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9038/حكم-من-تزوج-بامراة-ثم-علم-ان-امها-ارضعته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35706.mp3","categories":["الرضاع"]},{"id":10966,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية، وباعثتها إحدى الأخوات المستمعات من هناك رمزت إلى اسمها بحرفين هما (م. ع) تقول في رسالتها: واحدة رضعت من عمتها مع ابن عمتها الصغير، فهل يجوز لها أن تتزوج من أخيه الكبير؟","title":"حكم تزوج الرجل بمن رضعت من أمه مع أخيه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كانت هذه الجارية رضعت خمس رضعات أو أكثر من عمتها مع ابنها الصغير، فإنها تكون أختًا لجميع أولاد العمة، ولا تحل لا للصغير ولا للكبير، بل تكون أختًا لهم، إذا رضعت خمس رضعات أو أكثر حال كونها في الحولين من عمتها، فإن عمتها تكون أمًا لها، ويكون أولاد العمة ذكورهم وإناثهم إخوة لهذه الرضيعة، لا يجوز لها أن تنكح منهم أحدًا، وفق الله الجميع، نعم. المقدم: جزاكم الله خيرًا، حتى أخوها الكبير حينئذ؟ الشيخ: مطلقًا، جميع أولاد العمة إخوة لها، وإخوان العمة أخوال لها، وأخواتها خالات لها، والزوج أب لها، زوج العمة الذي ارتضعت من لبنه أب لها، وأولاده إخوة لها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9138/حكم-تزوج-الرجل-بمن-رضعت-من-امه-مع-اخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_364/36405.mp3","categories":["الرضاع"]},{"id":10992,"question":"من الطائف رسالة بعث بها المستمع (ح. هـ. م. الحارثي) يقول: أبعث إليكم بسؤالي هذا وهو أنني قد تزوجت، ولم أبلغ سن الرشد، وإن ولي أمري هو الذي تولى تزويجي، وحيث أنني لم أعلم ذلك الوقت مسؤولية الزواج، وتزوجت بعقد ومهر قدره ثمانية آلاف ريال، لكنني لم أدفع المهر المعلوم في العقد، وقد زوج ولي أمري شقيقتي لأخي زوجتي، وقد أنجبت زوجتي ما يزيد عن عشرة أبناء، أسأل الآن هل هذا الزواج صحيح، وماذا يجب علي فعله إذا كان غير صحيح، هل أجدد عقد الزواج؟ أرشدوني جزاكم الله خيرًا.","title":"عقد زواج فيه نظر يرجع فيه للمحكمة","answer":"الجواب:  هذا العقد فيه نظر والذي نرى أن تراجع المحكمة، لأنه قد يكون من عقد الشغار، قد يكون فيه تشارط، والشغار لا يجوز وهو نكاح البدل، فعليك أن تراجع أنت ووالدك وزوج أختك، عليكم أن تراجعوا المحكمة، وهي تفيدكم -إن شاء الله- في بلدكم، حتى تعرف الحقيقة المحكمة، وتعرف هل شروط الشغار موجودة فيه أم لا، وفيما تراه المحكمة إن شاء الله الكفاية، فعليكما أنت ووالدك أو وليك إن كان غير الوالد عليكما أن تراجعا المحكمة مع زوج أختك، حتى تنظر المحكمة في الزواج الذي أشرت إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9179/عقد-زواج-فيه-نظر-يرجع-فيه-للمحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36513.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11003,"question":"من الطائف رسالة بعث بها المستمع (ح. هـ. م. الحارثي) يقول: أبعث إليكم بسؤالي هذا وهو أنني قد تزوجت، ولم أبلغ سن الرشد، وإن ولي أمري هو الذي تولى تزويجي، وحيث أنني لم أعلم ذلك الوقت مسؤولية الزواج، وتزوجت بعقد ومهر قدره ثمانية آلاف ريال، لكنني لم أدفع المهر المعلوم في العقد، وقد زوج ولي أمري شقيقتي لأخي زوجتي، وقد أنجبت زوجتي ما يزيد عن عشرة أبناء، أسأل الآن هل هذا الزواج صحيح، وماذا يجب علي فعله إذا كان غير صحيح، هل أجدد عقد الزواج؟ أرشدوني جزاكم الله خيرًا.","title":"عقد زواج فيه نظر يرجع فيه للمحكمة","answer":"الجواب:  هذا العقد فيه نظر والذي نرى أن تراجع المحكمة، لأنه قد يكون من عقد الشغار، قد يكون فيه تشارط، والشغار لا يجوز وهو نكاح البدل، فعليك أن تراجع أنت ووالدك وزوج أختك، عليكم أن تراجعوا المحكمة، وهي تفيدكم -إن شاء الله- في بلدكم، حتى تعرف الحقيقة المحكمة، وتعرف هل شروط الشغار موجودة فيه أم لا، وفيما تراه المحكمة إن شاء الله الكفاية، فعليكما أنت ووالدك أو وليك إن كان غير الوالد عليكما أن تراجعا المحكمة مع زوج أختك، حتى تنظر المحكمة في الزواج الذي أشرت إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9179/عقد-زواج-فيه-نظر-يرجع-فيه-للمحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36513.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11159,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع عبد الله أبو محمد مصري الجنسية يقول: منذ ما يقرب من خمس عشرة سنة تزوجت من ابنة خالي، وأنجبت منها سبعة أطفال، وبعد هذه المدة الطويلة من الزواج علمت وعرفت أنني وأنا صغير شربت لبنًا من ثدي والدتها عندما وضعت أخاها الأكبر، فهل يجوز دوام العشرة الزوجية بيننا، وما حكم الشرع في ذلك الوضع الذي فوجئت به بعد هذه الفترة من الزواج والمعاشرة بيننا، جزاكم الله خيرًا؟","title":"الرضاع المحرم وغير المحرم","answer":"الجواب:  إذا كان الواقع هو ما ذكره السائل وهو أنه شرب من لبنها مرة واحدة، فإن هذا لا يضر والزواج صحيح؛ لأن الرضاع الذي يحصل به التحريم لا بد أن يكون خمس رضعات، أو أكثر، كل رضعة مستقلة يمص اللبن ويذهب إلى جوفه، ثم يفصل الثدي عن فمه ثم يعود. وهكذا إذا صب له في إناء وشرب مرات خمس فأكثر كل مرة مستقلة لحالها، فإنها تكون في مثابة الرضاع، إذا صب له أو حلب له في إناء وشرب، ثم حلب له وشرب خمس مرات، كل مرة مستقلة فأكثر يكون حينئذٍ الرضاع مؤثرًا، ويحصل به التحريم، أما شرب لمرة واحدة أو مرتين أو ثلاثًا، أو عددًا لا يحفظه لا يدري ...... بلغ خمسًا أم لا، فإن هذا لا يحصل به التحريم، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9336/الرضاع-المحرم-وغير-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37103.mp3","categories":["الرضاع"]},{"id":11178,"question":"من الخرج رسالة بعثت بها إحدى المستمعات تقول: المرسلة أم البراء، أم البراء تسأل وتقول: لي أخت من الرضاعة هل يجوز لأمي أن تكشف وجهها لزوجها؟","title":"حكم كشف المرأة لزوج أخت ابنتها من الرضاعة","answer":"الجواب:  إذا كانت أرضعتها أمك، إذا كانت الأم أرضعتها فزوجها زوج بنتها حينئذٍ، إذا كان أرضعتها خمس رضعات أو أكثر في الحولين، فهي بنتها وزوجها زوج البنت، والرسول ﷺ يقول: يحرم من الرضاع ما يحرم من النسب، هي مثل بنت النسب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9360/حكم-كشف-المراة-لزوج-اخت-ابنتها-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37205.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":11185,"question":"من الخرج رسالة بعثت بها إحدى المستمعات تقول: المرسلة أم البراء، أم البراء تسأل وتقول: لي أخت من الرضاعة هل يجوز لأمي أن تكشف وجهها لزوجها؟","title":"حكم كشف المرأة لزوج أخت ابنتها من الرضاعة","answer":"الجواب:  إذا كانت أرضعتها أمك، إذا كانت الأم أرضعتها فزوجها زوج بنتها حينئذٍ، إذا كان أرضعتها خمس رضعات أو أكثر في الحولين، فهي بنتها وزوجها زوج البنت، والرسول ﷺ يقول: يحرم من الرضاع ما يحرم من النسب، هي مثل بنت النسب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9360/حكم-كشف-المراة-لزوج-اخت-ابنتها-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37205.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":11191,"question":"بعد هذا ننتقل إلى ينبع عبر رسالة بعثت بها إحدى الأخوات المستمعات تقول: المرسلة (ع. س) أختنا تقول: إن هناك رجل رضع مع خالتي أخت أمي، فهل يكون لي محرم أم لا؟","title":"حكم محرمية رضاع أخت الأم مع الخالة","answer":"الجواب:  إذا كان رضع من جدتك رضاعًا شرعيًا كاملًا خمس مرات أو أكثر، حال كونه في الحولين، يكون خالًا لك، أخًا لأمك من الرضاعة، إذا كان رضع مع أمك أو مع إحدى خالاتك من جدتك، فإنه يكون خالًا لك أيضًا من الرضاعة، إذا كان الرضاع خمس رضعات فأكثر، وكان حين الرضاع في الحولين لم يفطم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9357/حكم-محرمية-رضاع-اخت-الام-مع-الخالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37202.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":11271,"question":"بعد هذا رسالة بعث بها المستمع (ع. ف) من جدة يسأل فيها جمعًا من الأسئلة فيقول: ما حكم تزويج من لا يصلي وإن ادعى ذلك؟","title":"لا يجوز تزويج المسلمة بمن لا يصلي","answer":"الجواب:  من لا يصلي لا يجوز تزويجه بالمصليات؛ لأن ترك الصلاة كفر أكبر نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9464/لا-يجوز-تزويج-المسلمة-بمن-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37515.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11354,"question":"إحدى الأخوات المستمعات تقول مقيمة في بريدة (أ. أ. أ) أختنا لها قضيتان: القضية الأولى: تقول فيها: لقد أرضعت ابنة عمي خمس رضعات مشبعات وربما أربع رضعات فلا أتذكر بالضبط، والآن يريد أخي الزواج منها، فهل يجوز زواجه منها، أم أنه خالها من الرضاع وتحرم عليه؟ جزاكم الله خيرًا.","title":"الشك في عدد الرضعات أربعة أم خمسة","answer":"الجواب:  لابد من وجود خمس رضعات مضبوطة معلومات ولو ما فيها شبع، فإذا وجد خمس رضعات حرمت على أخيك وصار خالًا لها، المقصود الأربع ما تحرم لابد من خمس معلومات يتيقن فيها وصول اللبن الحليب إلى جوف الطفل قبل الفطام خمسًا أو أكثر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9539/الشك-في-عدد-الرضعات-اربعة-ام-خمسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37816.mp3","categories":["الرضاع"]},{"id":11384,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من نجران الصعيد، وباعثها المستمع هادي عايض علي القحطاني، أخونا بعث رسالته في البريد الممتاز، إذ أن قضيته عاجلة ومهمة كما يبدو، فيقول في رسالته: سماحة الوالد الشيخ: عبدالعزيز بن عبدالله بن باز حفظكم الله ونفع بكم المسلمين، السلام عليكم ورحمة الله وبركاته وبعد.أفيدكم بأنني تزوجت بفتاة، وبعدما أنجبت لي أربعة من الأطفال حصل هناك شك بأن يكون هناك رضاع مع واحدة من زوجات جدها من أمها مصة أو مصتين، وبعد هذا الكلام ذهبت وسألت عددًا من القضاة وأفادوا أنه لا يحرم إلا خمس رضعات، لكن لا أدري كيف شروط هذه الخمس الرضعات، فهل المصة الواحدة تحسب رضعة، وإلا لا يحسب كون الرضعة إلا الشبع؟ نرجو أن تفيدونا جزاكم الله خيرًا.","title":"ضابط الرضاع المحرم","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد. فقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: لا تحرم الرضعة ولا الرضعتان وثبت أيضًا عن عائشة -رضي الله عنها- أنها قالت: كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن ثم نسخن بخمس معلومات فتوفي النبي ﷺ والأمر على ذلك أخرجه الإمام مسلم والترمذي وهذا لفظ الترمذي، والرضعة: هي أن يمص الصبي أو الصبية الثدي حتى يبتلع اللبن ويصل إلى جوفه ثم يطلق الثدي فإذا أطلقه تمت الرضعة، فإذا عاد بعد ذلك فمصه مصًا يحصل به وصول اللبن إلى جوفه صارت رضعة ثانية إذا أطلقه، وهكذا حتى يكمل خمسًا، وإذا لم يكن الرضاع خمسًا فإنه لا يحرم ولا يعتبر رضاعًا شرعيًا، لابد أن يكون الرضعات خمسًا أو أكثر في الحولين قبل أن يفطم الصبي، أما الرضعة الواحدة والرضعتان والثلاث والأربع فلا يحصل بها التحريم، والرضعة هي أن يمص الثدي حتى يبتلع اللبن، حتى يصل اللبن إلى جوفه وصولًا يقينيًا تعرفه المرضعة ولو لم يشبع، وفق الله الجميع. المقدم: إذًا والحال ما ذكر فلا تأثير على حالتهم الزوجية؟ الشيخ: إذا كان الواقع ما ذكره فلا يحصل تأثير، إذا كان مصة أو مصتين ليس لهما أثر لأن زوجته معه ولا حرج في ذلك. المقدم: الحمد لله، يقول إنها ثلاث مصات كما يذكر؟ الشيخ: ثلاث أو ثنتان أو أربع لا حرج في ذلك، زوجته معه ولا أثر لهذا الرضاع، حتى تكون الرضعات خمسًا معلومة بشهادة الثقة من النساء أو الثقات، وأن يكون ذلك في الحولين، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9563/ضابط-الرضاع-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37912.mp3","categories":["الرضاع"]},{"id":11530,"question":"يقول: ما حكم الزوجة التي لا تصلي؟ علمًا بأني بينت لها عقوبة تارك الصلاة، فأحيانًا تصلي وأحيانًا تترك، فمثلًا تصلي الظهر، وتترك بقية الفروض، جزاكم الله خيرًا.","title":"حكم الزوجة التي لا تصلي وأثر ذلك على العقد","answer":"الجواب:  حكمها أنها كافرة، ولا يجوز بقاؤها في عصمته، يجب إبعادها إلا أن تتوب توبة صادقة، وإلا فالواجب إبعادها؛ لأن ترك الصلاة كفر أكبر، يقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة، ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. هذا هو الصواب من قولي العلماء: أن تركها كفر أكبر، فالواجب عليك إبعادها، وعدم بقائها عندك، بل ترسلها إلى أهلها، نعم، لعدم صلاحها لكفرها، نسأل الله العافية. المقدم: نسأل الله السلامة والعافية، سماحة الشيخ! كثير من إخواننا الذين يستمعون إلى مثل هذه الفتوى يتصلون ويسألون: هل يجب علينا أن نعيد كتابة العقد -وهم كثرة- ويرجون من سماحتكم أن يكون هناك فتوى تعم أرجاء العالم الإسلامي؛ حتى يفطنوا لهذا الأمر؟  الشيخ: نعم، إذا تزوج امرأة لا تصلي وهو يصلي؛ فالعقد غير صحيح، أو تزوج وهو يصلي، وهي لا تصلي فالعقد غير صحيح، لابد أن يكونا جميعًا مسلمين، فإن كانت لا تصلي، وهو يصلي؛ فليس بصحيح، أو العكس، لابد أن يكونا مصليين، أو غير مصليين جميعًا، يصح العقد إذا كانا غير مصليين، كافرين جميعًا، أو كانا مصليين جميعًا. أما إذا كان الزوج لا يصلي، وهي تصلي؛ فلا يصح أو العكس، هي لا تصلي، وهو يصلي، فالواجب تجديد العقد، إذا كان لهما الرغبة في بعضهما، يكون كل واحد يرغب الآخر، يعني: إذا كان يرغب فيها، وهي ترغب فيه يجدد العقد بحضرة شاهدين، والولي الشرعي، يقول: قد زوجتك وهو يقول: قبلت، بمهر جديد، ولو قليلًا، بمهر جديد، لابد من تجديد العقد على الصحيح، ولو كان التارك لها لا يجحد وجوبها، الصحيح: أن تركها كفر مستقل، نعوذ بالله، نعم. المقدم: جزاكم الله خيرًا، هل يعد سماحتكم المسلمين بإصدار فتوى حول هذا الموضوع؟ الشيخ: قد صدر في هذا كتابات كثيرة، نعيد نشرها، إن شاء الله. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9715/حكم-الزوجة-التي-لا-تصلي-واثر-ذلك-على-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38511.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11561,"question":"تقول: إذا المرأة لم ترضع طفلها إلا لمدة سنة، فحملت، وأفطمت الرضيع، هل تكون آثمة والحال ما ذكر؟ لأني سمعت أن المرأة إذا أرضعت وهي حامل أن الرضيع يتضرر، فهل هذا صحيح؟","title":"حكم فطام الرضيع قبل تمام الحولين","answer":"الجواب:  هذا يرجع إليها وزوجها، فإن تراضيا على فطامه؛ فلا بأس، وإن تراضيا على بقائه؛ يبقى ولا يضره. فالحاصل أن المرأة تشاور زوجها في ذلك، فإذا تراضيا؛ فلا حرج؛ لقوله سبحانه: فَإِنْ أَرَادَا فِصَالًا [البقرة:233] يعني: فطاماً عَنْْ تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ فَلا جُنَاحَ عَلَيْهِمَا [البقرة:233]، فالأمر يرجع إليهما في فطمه، وعدم فطمه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9744/حكم-فطام-الرضيع-قبل-تمام-الحولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29710.mp3","categories":["الرضاع"]},{"id":11663,"question":"بنت أخي هل زوجها يكون محرمًا لي؟","title":"حكم محرمية زوج بنت الأخ","answer":"الجواب:  بنت أخيك ليس زوجها محرمًا لك، هذا البنت وبنت بنتك نعم، أما بنت أخيك لا، ولا بنتك أختك، ليس زوجها محرمًا لك، وإنما المحرم زوج البنت، زوج بنت البنت، زوج بنت الابن، هذا محرم، زوج الأم، زوج الجدة محرم -يعني: الذرية والأصول- زوج البنات، وهكذا أزواج بنات البنات وبنات البنين، هؤلاء محارم، وكذلك أزواج الأمهات والجدات محارم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9846/حكم-محرمية-زوج-بنت-الاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29815.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":11668,"question":"من اليمن المستمع صالح محمد هاجر بعث يسأل ويقول: أرضعت أمي بنت عمي الكبيرة، فهل يجوز لي الزواج من أخواتها الأخر؟ أفتونا جزاكم الله خيرًا.","title":"حكم تزوج الشخص بأخت من أرضعتها أمه","answer":"الجواب:  نعم إذا كانت أمك أرضعت البنت الكبيرة خمس رضعات، أو أكثر في الحولين؛ حرمت عليكم الكبيرة، وصارت أختًا لكم من الرضاعة، وأما أخواتها؛ فلا بأس بنكاحهن؛ لأنهن لم يرضعن من الوالدة، أما الرضيعة؛ فتحرم إذا كان الرضاع خمس مرات أو أكثر حال كونها في الحولين. نعم. المقدم: جزاكم الله خيرُا.","link":"https://binbaz.org.sa/fatwas/9852/حكم-تزوج-الشخص-باخت-من-ارضعتها-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39002.mp3","categories":["الرضاع"]},{"id":11748,"question":"يقول: بنت خالتي أخوها الأكبر رضع معي أكثر من خمس رضعات، هل يجوز لي الزواج منها، أو لا؟","title":"حكم الزواج بامرأة رضع أخوها من أمه","answer":"الجواب:  نعم ما دام رضع من أمك، ما رضعت من أمه فهي أجنبية، إنما هو أخوك هو من الرضاعة إذا كان رضع من أمك، أما إذا رضعت من أمها أنت، أو زوجة أبيها خمس رضعات، أو أكثر؛ حرمت عليك، أما إذا رضع أخوها فقط من أمك، أو من أخواتك؛ فإنها لا تحرم.. لأنها لم ترضع. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9930/حكم-الزواج-بامراة-رضع-اخوها-من-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39311.mp3","categories":["الرضاع"]},{"id":11762,"question":"يقول: ماذا أفعل مع زوجتي إذ أني نصحتها بأن تصلي، ولكن لم تسمع كلامي، ولم تستمع إلى نصيحتي، حتى إني ألاحظها في كثير من الأوقات لا تصلي أبدًا، بينما تقول: إنها تصلي، ما هو توجيهكم يحفظكم الله؟","title":"كيفية معاملة الزوج زوجته التي لا تصلي","answer":"الجواب:  إذا تيقنت أنها لا تصلي؛ فطلقها، وأبعدها، لا خير فيها؛ لأن ترك الصلاة كفر أكبر، فإذا علمت أنها لا تصلي، ولم تسمع منك؛ فأبعدها بالطلاق، وأبشر بأن الله سيعوضك خيرًا منها، فلا تتساهل معها أبدًا.  الواجب نصيحتها، وتأديبها على ذلك، فإن لم ينفعها ذلك، وأصرت على ترك الصلاة، فالواجب عليك فراقها، وسوف يعوضك الله خيرًا منها، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9946/كيفية-معاملة-الزوج-زوجته-التي-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39408.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11777,"question":"من القصيم بريدة رسالة بعث بها مستمع يقول (س. ع. م) يقول: لي زوجة لا تصلي، وقد أمرتها عدة مرات بالصلاة، ولكن أيضًا هي لا تصلي، وبعض الأحيان تقول: إنها تصلي، لكن أنا لم أرها فما هو توجيه سماحتكم؟ يحفظكم الله.","title":"حكم بقاء الرجل مع زوجة لا تصلي","answer":"الجواب:  إذا كنت تعلم أنها لا تصلي، فالواجب فراقها؛ لأن ترك الصلاة كفر أكبر على الصحيح، وإن لم يجحد وجوبها، فهذه لا خير فيها، إذا كنت تعلم أنها لا تصلي؛ فأبعدها، وطلقها، وأبشر بالخير، سوف يعوضك الله خيرًا منها وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، لكن قبل هذا تنصحها، وتأمرها بالتوبة؛ لعلها تتوب، ويهديها الله بأسبابك، فيكون لك مثل أجرها، فإن أبت، أو رأيت منها الكذب؛ فأبعدها، وفارقها، وطلقها، وأبشر بالخير، نعم.","link":"https://binbaz.org.sa/fatwas/9962/حكم-بقاء-الرجل-مع-زوجة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39424.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11788,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: المرسل أخوكم (إبراهيم . ع. م) الأخ إبراهيم له بعض الأسئلة في أحدها يقول: ما هو حكم الزواج من إخوة من الرضاع، وإذا كان قد حدث دون أن يعلم أحد بالرضاعة عدا الوالدة الجاهلة، هل يفسخ الزواج بعد أن تم فعلًا، أم لا؟ وهل جميع الأبناء تحرم عليهم الزواج من بعضهم، أم الذين قبل أن تتم عملية الرضاعة؟ جزاكم الله خيرًا.","title":"شروط ثبوت الرضاع والأثر المترتب على ذلك","answer":"الجواب:  السؤال فيه إجمال، فمتى ثبت الرضاع متى ثبت أن زيدًا رضع من فلانة؛ فإنه يحرم عليه بناتها وأخواتها؛ لأن بناتها أخوات، وأخواتها خالات، فالواجب عليه أن يحذر ذلك؛لأن الرضاع يحرم ما يحرمه النسب، كما قال النبي ﷺ: يحرم من الرضاع ما يحرم من النسب لكن لابد أن تكون الرضاع ثابتة بشهادة امرأة عدل، أو أكثر بأنها أرضعته خمس رضعات في الحولين، لابد أن تكون الرضعات خمسًا، ولابد أن تكون في الحولين قبل أن يفطم الطفل، ولابد أن يكون الشاهد عدلًا إن كان رجلًا، أو امرأة، أو أكثر من واحد. فإذا كانت الشاهدة غير معروفة بالعدالة؛ لا تثبت شهادتها، وهكذا الرجل، لابد أن يكون الشاهد بالرضاع عدلًا من الرجال، أو النساء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9972/شروط-ثبوت-الرضاع-والاثر-المترتب-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42205.mp3","categories":["الرضاع"]},{"id":11837,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات تقول: إن لدي ابن خالة رضع من ثدي أمي أكثر من مرة، بمعنى: أن الرضعات تعدت الخمس بالتأكيد من والدتي، فهل يعتبر هذا الشخص محرمًا لي ولأخواتي، علمًا بأنني أكبر منه، وقد رضع مع أخي الأصغر، وإخوتي يمنعونني من رؤيته عندما يأتي لزيارتنا، فهل علي إثم في ذلك؟ لأنني حاولت إقناع إخوتي بأنه أخي، ولكنهم لم يقتنعوا.","title":"الرضاع المحرم وما يترتب عليه","answer":"الجواب:  إذا كان رضع من الوالدة خمس رضعات، أو أكثر؛ فإنه يكون أخًا لكن، ولو كنت أكبر منه يكون أخًا لجميع أولاد الوالدة، وأولاد الزوج يكون أخًا لهم، الذي بعده، والذي قبله كلهم، إذا كان الرضاع خمس مرات مضبوطات يصل اللبن إلى الجوف، في الحولين قبل أن يفطم؛ فلا بأس هو أخ لكن الكبار والصغار، أنت ومن دونك ومن فوقك. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10027/الرضاع-المحرم-وما-يترتب-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39607.mp3","categories":["الرضاع"]},{"id":11846,"question":"إحدى الأخوات تقول المرسلة ع أم نشرا، أم نشرا تقول: إن زواجها كان بدلًا، وإني قد سمعت أنه حرام، وغير جائز، وقد أنجبت تسعة أولاد من ذلكم الزوج، وقد قمت بتربيتهم جميعهم بدون أن ينفق عليهم أحد غيري، هل يجوز أن أطلب طلاقي من ذلكم الزوج؟","title":"صفة زواج الشغار وكيفية تصحيحه لمن وقع فيه","answer":"الجواب:  إذا كان الزواج بدلاً يعني: هو نكاح الشغار، بأن تزوجتيه على أن يزوج أخاك أو أباك ابنته أو أخته، هذا نكاح الشغار، كل واحد يقول: زوجني على أن أزوجك، هذا يقول: زوجني بنتك على أن أزوجك بنتي، أو يقول: أختي أو أختي أو .. أختك يعني: بدل، كل واحد يشترط بنته، أو أخته أو بنت أخيه على الآخر، هذا لا يجوز، نكاح غير صحيح، ومتى علمتم الحكم الشرعي جددوا النكاح، ولو بعد سنوات يجدد النكاح بدون شرط المرأة الأخرى، كل واحد يجدد النكاح والأولاد أولادكم لأجل الشبهة ولاحقون بكم .... ولا حرج. وإنفاقك على أولادك، جزاك الله خيرًا إذا أنفقتي عليها من دون حاجة إلى مطالبته، هذا إليك، هذا معروف منك، وإلا فالنفقة عليه إذا كان قادرًا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10035/صفة-زواج-الشغار-وكيفية-تصحيحه-لمن-وقع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39615.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":11895,"question":"هل يجوز أن أقابل أعمام أمي، أو لا يجوز ذلك؟ جزاكم الله خيرًا.","title":"حكم مقابلة المرأة لأعمام وأخوال أبيها وأمها","answer":"الجواب:  أعمام أمك أعمام لك، وهكذا أخوالها أخوالك، عمك عم أبيك وعم أبيك عمك، المقصود عم أبيك، وعم أمك عم لك، وخال أبيك وخال أمك خال لك، فهم محارم، الأخوال لأمك ولجدتك والأعمام لأمك ولجدتك كلهم أعمام لك، وأخوال لك محارم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10079/حكم-مقابلة-المراة-لاعمام-واخوال-ابيها-وامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42516.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":11911,"question":"من وادي الدواسرة المستمع (ب. غ) بعث يسأل ويقول: رضعت من خالتي دون أن يرضع معي أحد من أولادها، هل يصبح جميع أولادها إخوة لي إناثًا وذكورًا؟ جزاكم الله خيرًا.","title":"حكم من رضع من امرأة دون مشاركة من أبنائها","answer":"الجواب:  إذا كان الرضاع في الحولين وأنت صغير لم تفطم في الحولين، وكان اللبن لبنًا صحيحًا؛ فلا بأس، تكون ولدًا لها، أما إذا كان مجرد ماء، ما فيها لبن، ما يكون رضاعًا، لابد تكون لبنًا، إذا درت عليك لبنًا، وأنت في الحولين، ما بعد فطمت خمس رضعات فأكثر؛ تكن ولدًا لها، وأخًا لأولادها الكبار والصغار بهذا الشرط، أن تكون صغيرًا لم تفطم، وأن تكون الرضعات خمس رضعات، وأن يكون اللبن صحيحًا ليس مجرد ماء؛ لأن بعض العجائز يكون عندها ماء ما ينفع، ما يكون رضاعًا، إذا درت عليك لبنًا صحيحًا؛ صارت أمًا لك. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10095/حكم-من-رضع-من-امراة-دون-مشاركة-من-ابناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42612.mp3","categories":["الرضاع"]},{"id":11925,"question":"من اليمن رسالة بعث بها المستمع: رامز قائد محمد سفيان، أخونا يقول: أنا شاب أريد الزواج من بنت عمي، أخبرني الأهل أنها رضعت من أمي، ولكن لا يدرون كم رضعت قليلًا أم كثيرًا؟ وأيضًا لا يدرون خمس مصات أم أقل؟ المهم أنهم قالوا لي: رضعت من أمك فقط، فما هو توجيه الشيخ عبد العزيز؟ هل أتقدم لخطبة هذه الفتاة، أم أبتعد؟ جزاكم الله خيرًا.","title":"حد الرضاع المحرم","answer":"الجواب:  إذا كانت لم ترضع من أمك خمس رضعات، أو أكثر في الحولين بالبينة الشرعية؛ فإنها تحل لك، ولا تحرم عليك إلا بخمس رضعات أو أكثر حال كونها في الحولين، بإقرار الوالدة، أو بشهادة ثقة من الرجال أو النساء أن هذا وقع، لكن تركها أحوط، وأفضل من باب ترك المشتبه؛ لقول النبي ﷺ: دع ما يريبك إلى ما لا يريبك وقوله ﷺ: من اتقى الشبهات؛ فقد استبرأ لدينه وعرضه فالتماسك ابنة أخرى لا شبهة فيها أولى وأفضل .. وإلا فإنها لا تحرم عليك ما دام الرضاع مشكوكًا فيه، ولم يثبت أنه خمس رضعات، وفي الحولين؛ فإنها لا تحرم بذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10109/حد-الرضاع-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42702.mp3","categories":["الرضاع"]},{"id":12015,"question":"مستمع يقول: الطيب البشير محمد علي يقول: لقد خطبت فتاة، ولكن بعد ثلاثة أيام من الخطوبة ذكرت لي والدتي أنني قد رضعت مع عم الفتاة الذي هو أصغر من أبيها، أي: مع والدته -كما يقول في سؤاله- وقد علم أبو الفتاة بهذا الخبر، والآن والدته هي الأخرى قالت: إنني أرضعته، فهل يمكنني الزواج من هذه الفتاة؟","title":"حكم من خطب امرأة وقد رضع من جدتها","answer":"الجواب:  إذا كنت رضعت من والدة أب الفتاة رضاعًا كاملًا، خمس مرات فأكثر، وأنت في الحولين؛ فأنت عم لها، أخ لأبيها، فليس لك نكاحها، إذا كنت ارتضعت من أم أبيها خمس رضعات أو أكثر، ولو في مجلس واحد، وأنت في الحولين قبل أن تفطم؛ فأنت حينئذ عم لها، ولا تحل لك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10200/حكم-من-خطب-امراة-وقد-رضع-من-جدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43206.mp3","categories":["الرضاع"]},{"id":12044,"question":"هل يجوز تقبيل رأس الجدة والخالة والعمة، أو لا يجوز هذا جزاكم الله خيرًا؟","title":"حكم تقبيل رأس الجدة والعمة والخالة","answer":"الجواب: كلهن محارم، الجدة، والخالة، والعمة، والأخت كلهن محارم، فإذا قبل رأس الكبيرة، أو بين عينيها، أو قبل خدها فلا مانع، قد كان الصديق -رضي الله عنه- يقبل عائشة في خدها، وهي ابنته لما دخل عليها وهي مريضة؛ قبلها في خدها.  فهذا لا حرج فيه، وكان النبي ﷺ إذا دخل على فاطمة؛ قامت إليه، وقبلته -عليه الصلاة والسلام- وأخذت بيده وصافحته، وكانت إذا دخل عليها وهو جالس؛ قام إليها، وأخذ بيدها، صافحها وقبلها -عليه الصلاة والسلام، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10229/حكم-تقبيل-راس-الجدة-والعمة-والخالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43313.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":12057,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، رمزت إلى اسمها بالحروف (ن. ر. ف. ر. أ) أختنا لها قضية مطولة عن الرضاع فتقول: أنا سيدة متزوجة منذ ما يقارب خمساً وعشرين سنة من ابن عمي، وبعد مدة طويلة من الزواج عرفت أن زوجي أخي من الرضاعة، أي: أني قد رضعت من أمه مع أخيه الأصغر لمدة خمسة عشر يومًا، وكان عمره سنة، وأنا عمري أسبوع، فهل يحرم علي، ويجب أن يفرق بيننا، أم لا؟ علمًا بأن عمتي يوم زواجي قد حاولت منع الزواج بسبب رضاعي، ولكن أبي وعمي قد أصرا على إقامة الزواج، فهل الإثم علينا، أم عليهم؟ وماذا نفعل الآن علمًا؟ بأني لم أنجب منه حتى الآن جزاكم الله خيرًا.","title":"حكم من تزوج بامرأة رضعت من أمه","answer":"الجواب:  هذا الموضوع يرفع إلى المحكمة، وتحضر المرضعة حتى يسألها القاضي عن حقيقة الرضاع، وعن عدد الرضعات، وحتى يسأل الناس عن ثقتها وعدالتها، وبعد ذلك يحكم القاضي في الموضوع، هذا الذي أرى في هذه المسألة؛ لأنها مسألة خطيرة مضى عليها دهر طويل، فالذي أرى أن تقدم المرضعة إلى القاضي حتى يسألها عن صفة الرضاع وعدد الرضعات وعن تيقنها لذلك، ويسأل العارفين بها عن عدالتها، وبعد ذلك يحكم بما يرى، وفيه الكفاية، إن شاء الله. المقدم: إن شاء الله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10242/حكم-من-تزوج-بامراة-رضعت-من-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43406.mp3","categories":["الرضاع"]},{"id":12180,"question":"من المملكة الأردنية الهاشمية رسالة بعث بها مستمع من هناك رمز إلى اسمه بالحروف (م. و. د) مصري الجنسية يقول: أنا وبنت أختي رضعنا من أختي، فهل يجوز لأولادنا. الشيخ: أنا. المقدم: وبنت أختي رضعنا من أختي، فهل يجوز لأولادنا أن يتزوجوا أولاد بنت أختي التي رضعنا أنا وهي من أختي؟ الشيخ: أعد.المقدم: يقول: أنا وبنت أختي رضعنا من أختي، فهل يجوز لأولادنا أن يتزوجوا أولاد بنت أختي التي رضعنا أنا وهي من أختي؟","title":"رضع من أخته مع بنت أخته، فما حكم زواج أولادهما؟","answer":"الجواب:  هي صارت أمًا لكم، صارت أمًا لكما، أختك صارت أمًا لكما، وبنتها وبناتها أخوات لكما، وعمات لأولادك، وخالات لبنت الأخت التي رضعت معك، فليس لأولادكم التزوج من بناتها؛ لأنها صارت بهذا الرضاع أمًا لك ولابنة أختك التي رضعت معك، وكأن ........ أخت أخرى. فالحاصل: أن هذه المرضعة التي هي أختك صارت أمًا لكما، وجدة لأولادكما، فأولادها أخوال لأولاد البنت، وأعمام لأولادك أنت، فليس لأولادك أن يتزوجوا من بناتها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10366/رضع-من-اخته-مع-بنت-اخته-فما-حكم-زواج-اولادهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44307.mp3","categories":["الرضاع"]},{"id":12203,"question":"السؤال الآخر في الرضاع يقول فيه: أنا رضعت من امرأة، هل يجوز لإخواني أن يتزوجوا من بناتها، أم لا؟","title":"حكم زواج إخوة الراضع ببنات من رضع منها","answer":"الجواب:  نعم إذا كانوا لم يرضعوا، لهم أن يتزوجوا من بناتها، أما أنت لا، أما أنت إذا رضعت رضاعًا شرعيًا خمس رضعات، أو أكثر في الحولين؛ صارت أمك، وصار بناتها أخوات لك، ليس لك أن تنكح منهن أحدًا؛ لأنهن أخوات من الرضاعة، إذا كان رضاعًا شرعيًا في الحولين، وكان خمس رضعات، أو أكثر، أما إخوانك فلا بأس لهم أن يتزوجوا من بناتها؛ لأنهم لم يرضعوا منها، وليس بناتها أخوات لهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10389/حكم-زواج-اخوة-الراضع-ببنات-من-رضع-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_444/44410.mp3","categories":["الرضاع"]},{"id":12260,"question":"من المستمع (ر. ش. ع. أبو عيسر) فيما يبدو، من المنطقة الشرقية بقيق، بعث برسالة، يقول فيها: في أحد الأيام وجدت امرأة تبلغ من العمر سبعين عامًا، وجدت طفلًا يتيمًا، وأحسنت إليه جزاها الله خيرًا، لكن المشكلة أنها أرضعته، وهي كانت أرملة، أي: أن زوجها متوفىً عنها منذ أكثر من عشرين عامًا، إلا أنها أدرت له اللبن بقدرة الله  وبعد أن كبر وبلغ سن الرشد أراد واحد من أبنائها الكبار أن يزوجه من كريمته، هل يصح الزواج، والحالة هذه، علمًا بأنا سمعنا أناسًا يقولون: إن اللبن لابد أن يكون قد در عن الرجل، وجهونا حول هذا الموضوع، جزاكم الله خيرًا.","title":"حكم من وجدت طفلًا فأرضعته وهي مسنة غير متزوجة","answer":"الجواب:  إذا كانت درت عليه لبنًا وأرضعته وهو صغير، قبل كمال السنتين، فإنه يكون ولدًا لها، ولو كان زوجها قد مات من مدة طويلة، أو مطلقة، إذا درت اللبن؛ فهي مرضعة، وهي والدة، إذا أرضعته خمس رضعات أو أكثر، حال كونه في الحولين، قبل الفطام؛ فإنه يكون ولدًا لها وأخًا لأولادها، وليس له أن يتزوج من بنات أولادها؛ لأنه يكون عمًا للبنت، أخو أبيها، فهي أمه، وجميع أولادها إخوة لهذا الطفل، إذا كان الرضاع خمس رضعات أو أكثر، حال كون الطفل في الحولين. أما إن كان درها ليس لبنًا؛ وإنما هو ماء، فلا عبرة به، ولا يعول عليه، لابد أن يكون لبنًا، من جنس اللبن المعروف للنساء، وهذا يقع كثيرًا، كثير من العجائز إذا أخذت الطفل عطفت عليه، ودرت عليه؛ فيكون ولدًا لها بهذا اللبن الجديد؛ الذي درت عليه به، وإن كان زوجها قد مات من دهرٍ طويل، أو كانت مطلقة، حتى ولو كانت لا زوج لها، لم تتزوج، متى درت، فالصحيح أنه يكون ولدًا لها، إذا كان في الحولين، وأرضعته خمس رضعات، أو أكثر، حال كونه طفلًا صغيرًا في الحولين لم يفطم، نعم. المقدم: جزاكم الله خيرًا، التي لم تتزوج بعد؟ الشيخ: حتى من لم تتزوج، الصحيح أنه تعمها النصوص: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ [النساء:23]. المقدم: هل تذكرون حوادث معينة سماحة الشيخ من هذا القبيل؟ امرأة لم تتزوج مثلًا، وأدرت لبن ... ؟ الشيخ: نعم، ....... المقدم: حصل هذا.  الشيخ: ..... بلغنا .... المقدم: نعم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10460/حكم-من-وجدت-طفلا-فارضعته-وهي-مسنة-غير-متزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44911.mp3","categories":["الرضاع"]},{"id":12270,"question":"المستمع عبدالعزيز عبدالله من العراق بعث برسالة يقول فيها: رضع ابن خالتي من لبن أمي، ولكنه توفي بعد ذلك، فهل يجوز لي أن أتزوج ابنتها، أم لا؟ أرجو الإفادة، جزاكم الله خيرًا.","title":"حكم التزوج ببنت الخالة التي رضع أخوها من أم الخاطب","answer":"الجواب:  نعم الرضاعة للابن ما هو .... للبنت، لك أن تتزوج البنت بنت خالتك؛ لأنها ليست رضيعة لك، وإنما الرضيع ابنها وقد توفي حتى ولو كان حيًا، الرضاع يختص به، لا تأخذ بنته، تكون أنت أخوه، لو كان له بنت لا تأخذها؛ لأنك عمها، أما أخواته فحل لك؛ لأنهن بنات خالتك، لا بأس عليك، إذا كن لم يرضعن من أمك، وأنت لم ترضع من أمهن؛ لا حرج عليك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10470/حكم-التزوج-ببنت-الخالة-التي-رضع-اخوها-من-ام-الخاطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_450/45007.mp3","categories":["الرضاع"]},{"id":12398,"question":"من المنطقة الجنوبية المستمع (ن. س. ح) بعث برسالة في الرضاع مطولة بعض الشيء، يقول فيها: والدتي أرضعت بنت عمتي، وكان الرضاع مع أختي التي هي أصغر مني، وترتيبها بين إخواني الرابعة، وكذلك أرضعت عمتي أختي المذكورة مع بنتها، فصار هناك رضاع بين الطرفين، هل بنت عمتي التي رضعت مع أختي أخت لنا من الرضاعة والتي أرضعتها أمي؟ وهل أختي التي أرضعتها عمتي أخت لأولاد عمتي؟ نرجو أن تفيدونا، جزاكم الله خيرًا.","title":"حكم شمول الأخوة من الرضاع للمتقدم والمتأخر","answer":"الجواب:  نعم، التي أرضعتها أمك ابنة عمتك إذا أرضعتها أمك خمس رضعات، أو أكثر حال كونها في الحولين تكون أختًا لكم جميعًا، والرضعة كونها تمسك الثدي، وتمص اللبن حتى يذهب إلى بطنها، ثم تطلق الثدي، ثم تعيدها وترضعها مرة ثانية، وهكذا حتى تكمل خمس رضعات في يوم، أو في أيام، تكون أختًا لكم جميعًا التي قبلها والتي بعدها. وهكذا أختك التي أرضعتها عمتك إذا أرضعتها عمتك رضاعًا شرعيًا، خمس مرات، أو أكثر، تكون وحدها أختًا لأولادها وحدها فقط، أختًا لأولاد عمتك؛ لأنها صارت بنتًا لعمتك، وأختًا لأولادها، وأولاد الزوج الذي هو صاحب اللبن، تكون بنتًا له، وأختًا لأولاده، إذا كان الرضاع في الحولين، وكان خمس رضعات، أو أكثر، كما تقدم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10603/حكم-شمول-الاخوة-من-الرضاع-للمتقدم-والمتاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45503.mp3","categories":["الرضاع"]},{"id":12399,"question":"أيضًا يذيل الرسالة بسؤال يقول فيه: هل يصح لي الزواج من بنت عمتي التي هي أصغر من التي أرضعتها أمي مع أختي، مع العلم أنه لم يحصل بين إخواني وبين بنت عمتي الثانية رضاع، وإذا كان يجوز لي الزواج فأرجو توضيح ذلك، وإذا كان لا يجوز فأرجو التوضيح، جزاكم الله خيرًا؟","title":"حكم تزوج الشخص بأخت أخته من الرضاعة","answer":"الجواب:  بنت عمتك لا بأس بها التي لم ترضع من أمك لا بأس أن تتزوجها أنت، أو أحد إخوانك إذا كنتم لم ترضعوا من أمها وهي لم ترضع من أمكم، فالرضاع يختص بالتي رضعت من أمك، أما أخواتها اللاتي لم يرضعن من أمك فهن حل لكم؛ لأنهن بنات عمة حلال، إذا كنتم لم ترضعوا أنتم من أمها؛ فلا حرج في الزواج منها، وإنما المحرم عليكم التي رضعت من أمكم خاصة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10604/حكم-تزوج-الشخص-باخت-اخته-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45504.mp3","categories":["الرضاع"]},{"id":12422,"question":"هل للمرأة أن تكشف على أولاد مطلقها من امرأة أخرى؟","title":"حكم كشف الوجه لأولاد الزوج المطلق","answer":"الجواب: نعم، أولاد زوجها نعم؛ لأنها محرم لهم، زوجة أبيهم، فإذا كان له أولاد من زوجة أخرى؛ فهم محارم، نعم.  المقدم: ولو كانت مطلقة. الشيخ: ولو كانت مطلقة، ولو كان ميتًا هو. المقدم: ما شاء الله، جزاكم الله خيرًا.  الشيخ: الله يقول: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22] يعني: زوجة أبيهم محرمًا لهم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10624/حكم-كشف-الوجه-لاولاد-الزوج-المطلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40212.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":12470,"question":"رسالة بتوقيع أحد الإخوة المستمعين يقول: أبو تركي يسأل ويقول: تزوجت ابنة عمي، وابن عمي تزوج أختي بدون أن يدفع أيًا منا مهرًا سوى بعض نفقات الزواج، فهل ما فعلناه جائز؟","title":"صفة نكاح الشغار وحكمه","answer":"الجواب:  هذا فيه تفصيل: إن كان هذا العقد عن مشارطة، هذا يقال له: نكاح الشغار، ولا يجوز، والعقد باطل، يجب تجديده إذا كان مشرطًا بينكم، زوجني وأزوجك، أما إذا خطب منكم، وخطبتم منه، ورضيت كل واحدة بالمهر الذي تعطاه من حلي، ونقود؛ فلا بأس، ولا حرج في ذلك، يعني: يكفي ولو قليلًا من المال إذا تراضوا عليه، أما إذا كان مشارطة زوجني وأزوجك؛ فهذا نكاح الشغار الذي نهى عنه النبي -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10671/صفة-نكاح-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40412.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":12555,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين هو (ع. ع. ش) يقول: إنني تزوجت من بنت خالتي أخت أمي من الأب، وذلك منذ سنتين، وقد جاءتني أمي، وعاشت معي مدة شهرين، ثم عادت إلى البلاد، وكذلك زوجتي أرسلتها إلى أهلها لتلد عندهم، وبعد شهر تقريبًا من ذهابهم من عندي اتصل أخي من البلد ليقول: إن أمي قالت له: إنها أرضعت خالتي، أي أختها أم زوجتي مع بنتها البكر، فذهبت إلى البلاد لأجد أن أمي تقول نفس الكلام، ولكنها تقول: ليست متأكدة كم رضعة أرضعتها؛ حيث المدة طويلة، وقد سألت جدتي، أم خالتي فنفت ذلك، وأنا منذ ذلك الوقت لم أقرب من زوجتي، وقد ولدت زوجتي ولدًا عمره شهران، وأنا محتار، هل أطلقها؟ وهل على والدتي إثم؟ وما هي الكفارة؟ وهل لي الحق لو طلقتها في شيء من الصداق الذي أعطيتهم إياه، أو هل لها نفقة أقوم بدفعها لها؟ أرجو إفادتي هذا الموضوع، وحول هذه القضية، جزاكم الله خيرًا.","title":"حكم من تزوج بابنة خالته ثم أخبرها أنها وأمها رضعتا من أمه","answer":"الجواب:  إذا كانت الوالدة ليس عندها ضبط للرضعات، هل هي خمس، أو ثلاث، أو ثنتان؛ فليس عليك بأس، وزوجك معك، والحمد لله، أما إذا كانت الوالدة عندها يقين أنها أرضعت أختها خمس رضعات، أو أكثر؛ فإن هذا يوجب حينئذ أن تكون هذه الزوجة التي أمها أرضعتها أمك؛ تكون بنت أختك، تكون خالتك أختًا لك؛ لأن أمك أرضعتها، فإذا أرضعتها خمس رضعات؛ صارت الخالة أختًا لك، وصارت زوجتك بنتًا لأختك؛ فيبطل النكاح، لو جزمت الوالدة بأن الرضاع خمسًا، وثبت أنها ثقة الوالدة ليس فيها بأس؛ فإن النكاح حينئذ يبطل بهذا الرضاع، وعليك أن تفارقها، لكن ما دامت الوالدة عندها شك، وليس عندها ضبط لعدد الرضعات؛ فالحمد لله، زوجتك معك، ولا حرج عليك، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ، هل من كلمة حول عدم التشويش على الأزواج بهذا الرضاع، إذا نشب خلاف بين الزوجة، وأم الزوج أثير موضوع الرضاع في حالات كثيرة، هل من توجيه لو تكرمتم؟ الشيخ: نعم، ننصح الأخوات في الله أن يحذرن الكذب في الرضاع، أو التساهل في الرضاع، أو التشويش في الرضاع، ما دامت المرأة ليس عندها ضبط لخمس رضعات؛ فلا ينبغي لها أن تتكلم في ذلك، وتشوش على الناس. أما إذا كان عندها ضبط؛ فالواجب عليها تقوى الله، تخبر بما عندها، الله يقول: وَلا تَكْتُمُوا الشَّهَادَةَ [البقرة:283] فإذا كانت ضابطة يقينًا أنها أرضعت فلانة خمس رضعات، أو فلانًا خمس رضعات، أو أكثر؛ فعليها أن تبين، وأن تتقي الله، ولا يجوز لها أن تحدث بشيء، ليس له أصل، أو بالأوهام، وعدم الضبط، كل هذا لا يجوز؛ لأن هذا يشوش على الناس، ويضرهم بلا فائدة، ونسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10762/حكم-من-تزوج-بابنة-خالته-ثم-اخبرها-انها-وامها-رضعتا-من-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41007.mp3","categories":["الرضاع"]},{"id":12749,"question":"بعد هذا رسالة وصلت إلى البرنامج من شقراء، باعثتها إحدى الأخوات المستمعات تقول أم غادة، أم غادة لها قضية تقول فيها: ما حكم إرضاع المرأة لابنها أكثر من حولين، وما الحكم إذا زاد عن ذلك، جزاكم الله خيرًا؟","title":"حكم الزيادة والنقصان في الرضاع عن الحولين","answer":"الجواب:  لا حرج في ذلك إذا دعت إليه الحاجة، الواجب حولان، قال الله تعالى: وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَنْ يُتِمَّ الرَّضَاعَةَ [البقرة:233] فيجب إرضاعه حولين إلا إذا تراضى أبواه -أمه وأبوه- على فطمه عن الرضاع قبل ذلك؛ لأسباب تقتضي ذلك. أما الزيادة على الحولين، فإذا دعت إليه الحاجة؛ فلا بأس، كأن يكون لا يشتهي الطعام، أو لأسباب أخرى. المقصود: أنه إذا دعت الحاجة؛ فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10963/حكم-الزيادة-والنقصان-في-الرضاع-عن-الحولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41820.mp3","categories":["الرضاع"]},{"id":13152,"question":"رجل تزوج بامرأة، وأنجبت له أولادًا، ثم بعد ذلك تبين أنه رضع من أمها عشر رضعات متواليات، هل يطلقها، أم يستمر معها، وهل الأولاد يرثونه، أم ل؟ا مأجورين.","title":"حكم من تزوج بامرأة ثم تبين أنها أخته من الرضاع","answer":"الجواب:  إذا ثبت أنه رضع من أمها بشهادة الثقة من النساء، أو الثقات خمس رضعات، أو أكثر في الحولين، حال كونه في الحولين؛ بان أنها أخت له، فيبطل النكاح، والأولاد يتبعونه، الأولاد نسبهم صحيح؛ لأنهم ولدوا على فراشه على أنها زوجة، فإذا ظهر بعد ذلك أنها رضيعة له؛ لا يضره ذلك، أولاده ينسبون إليه، وهم أولاده، وأولادها. لكن متى ثبت أنها أخته من الرضاع، أو خالته، أو عمته، أو بنت أخيه، أو بنت أخته؛ بطل النكاح، والأولاد أولاده ينسبون إليه؛ لأنه ولدوا على شبهة النكاح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11406/حكم-من-تزوج-بامراة-ثم-تبين-انها-اخته-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51012.mp3","categories":["الرضاع","المحرمات من النساء","مبطلات النكاح"]},{"id":13220,"question":"هذه السائلة من المدينة النبوية السائلة: (ف. م. أ) تقول: إذا رضع الطفل من امرأة لمدة أسبوع كامل، ولكن هذه المرأة ليس فيها حليب، فهل يعتبر ابنًا لها، أم لا؟","title":"حكم من رضع من امرأة ليس فيها حليب","answer":"الجواب:  إذا ارتضع منها ولو دهرًا طويلًا إذا كان ما فيها لبن؛ ما يصير ولدًا لها، لابد من لبن فيها، ولابد من خمس رضعات، أو أكثر، يشرب اللبن، ويذهب إلى جوفه عن يقين، وإلا فمص الثدي وما فيه شيء؛ ما ينفع، ولو شهرًا، ولو سنة، ما ينفع، لكن لابد أن يكون فيه لبن، ويذهب إلى بطن الصبي خمس رضعات، أو أكثر حال كون الصبي في الحولين قبل أن يفطم، قبل تمام الحولين، يكون ولدًا لها بهذه الشروط: كونها في الحولين، وكونها ترضعه لبنًا حقيقة موجود، وكونها خمس رضعات، أو أكثر، أما المص من دون لبن ما ينفع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11499/حكم-من-رضع-من-امراة-ليس-فيها-حليب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52009.mp3","categories":["الرضاع"]},{"id":13226,"question":"ننتقل بعد ذلك إلى رسالة بعثت بها أختكم في الله فتاة الإسلام من اليمن، تقول: سماحة الشيخ! إذا كان الزوج لا يحافظ على الصلاة، فيصلي أيامًا، ويدعها أخرى، وكذلك الصيام، هو رجل طيب القلب، ولا يمنع زوجته عن مجالس العلم، وحرية الالتزام، فما حكم الزواج في مثل هذه الحالة، هل أستمر معه، أم لا، علمًا بأن لي منه ابن وبنت، وهو ابن عمي، وهل الامتناع في الفراش عنه يعتبر معصية، أفتونا مأجورين؟","title":"حكم بقاء الزوجة مع زوج متهاون بالصلاة","answer":"الجواب:  إذا كان الرجل لا يصلي بعض الأوقات لا يجوز البقاء معه؛ لأن ترك الصلاة كفر، فإذا كان زوجك لا يصلي بعض الأوقات؛ فالواجب عليك البعد عنه، والذهاب إلى أهلك، والامتناع منه حتى يتوب إلى الله ويصلي، هذا هو الصواب من قولي العلماء. والقول الثاني: أنه لا يكفر بذلك، أنه كفر دون كفر، وأنه عاصٍ، معصية عظيمة، ولكن لا يكفر بذلك إلا إذا جحد الوجوب، وهذا قول ضعيف ومرجوح.  والصواب: أنه متى تركها عمدًا؛ كفر بذلك؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وكل امرأة زوجها يترك الصلاة يجب عليها أن تفارقه، وأن تمنعه من نفسها حتى يتوب إلى الله، وإلا فعليها أن تفارقه إلى أهلها، وأن تطلب فسخ الطلاق من جهة المحكمة، ولا يجوز لها البقاء معه؛ لأنه بترك الصلاة؛ صار كافرًا في أصح قولي العلماء؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر نسأل الله العافية، ولو ما جحد وجوبها، لكن متى جحد وجوبها، قال: ما هي بواجبة؛ كفر عند الجميع -نعوذ بالله- ولو صلى، نسأل الله العافية. المقدم: نسأل الله العافية، بارك الله فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11510/حكم-بقاء-الزوجة-مع-زوج-متهاون-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52013.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":13240,"question":"تقول هذه السائلة -أيضًا- في أسئلتها: هل صحيح بأن جدتي أم والدتي يكون زوجي لها محرم تسافر معه، وكذلك جدتي والدة أبي؟","title":"جدات الزوجة محرم للزوج","answer":"الجواب: نعم، أمك وجداتك كلهم محارم لزوجك؛ لأن الله قال في المحرمات: وَأُمَّهَاتُ نِسَائِكُمْ [النساء:23] والجدة أم كأمهات النساء، أم المرأة، وإلا جداتها من جهة أبيها، وأمها كلهم محارم للزوج، وهكذا بناتها من زوج سابق، بناتها من زوج سابق محارم لزوجها الحالي، إذا كان قد دخل بها، قد جامعها، فجميع بناتها من أزواجها السابقين محارم لزوجها الجديد إذا دخل بهن، إذا كان قد وطئها؛ لقوله -جل وعلا-: وَرَبَائِبُكُمُ اللَّاتِي فِي حُجُورِكُمْ مِنْ نِسَائِكُمُ اللَّاتِي دَخَلْتُمْ بِهِنَّ [النساء:23] يعني: وطئتموهن، وقوله: فِي حُجُورِكُمْ [النساء:23] وصف أغلبي ليس بشرط، ولو كانت ليست في حجره. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11524/جدات-الزوجة-محرم-للزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51306.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":13330,"question":"سماحة الشيخ! هذا السائل من اليمن نجيب أحمد يقول: لقد رضعت من جدتي، فهل يجوز لي الزواج من بنات أعمامي، أو عماتي؟","title":"حكم الزواج من بنت العمة لمن رضع من جدته","answer":"الجواب:  إذا رضعت من جدتك أم أبيك رضاعًا شرعيًا كاملًا، خمس رضعات رضعت، أو أكثر في الحولين؛ صرت أخًا لأبيك، وأعمامك، وإن كانت جدتك أم أمك، إذا رضعت منها خمس رضعات، أو أكثر في الحولين؛ صرت أخًا لأمك، ولخالاتك. فالرضاع كالنسب يحرم من الرضاع ما يحرم من النسب فإذا رضعت من أم أبيك؛ صرت أخًا لأبيك، وأخًا لأعمامك، وعمًا لبنات أعمامك، عمًا لهم لا يحلون لك. وهكذا إذا رضعت من جدة أم أمك رضاعًا شرعيًا، خمس مرات، أو أكثر في الحولين؛ فإنك تكون أخًا لأمك، وأخًا لخالاتك، وخالًا لبناتهن، ليس لك نكاحهن، تكون خالًا لهن، والرسول يقول -عليه الصلاة والسلام-: يحرم من الرضاع ما يحرم من النسب اللهم صل عليه وسلم. المقدم: اللهم صل وسلم عليه يقول -يا سماحة الشيخ! امتدادًا للسؤال السابق-: أنا كتبت الكتاب على ابنة عمتي، ولم أدخل عليها بعد، فما حكم هذا العقد في هذه الحالة؟ الشيخ: إذا كنت قد رضعت من جدة أم أبيك رضاعًا شرعيًا، خمس مرات، أو أكثر، وأنت في الحولين؛ فالنكاح باطل، ما يصح؛ لأنك حينئذ عمًا لها، أخًا لأبيها، أخًا لعمك، وأخًا لأبيك، وعماً لبنات عمك؛ فالنكاح باطل. المقدم: بارك الله فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11616/حكم-الزواج-من-بنت-العمة-لمن-رضع-من-جدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54111.mp3","categories":["الرضاع"]},{"id":13386,"question":"سائلة للبرنامج رمزت لاسمها بمريم (أ. أ) من الرياض، تقول: كم عدد الرضعات المحرمة؟","title":"كم عدد الرضعات المحرمة؟","answer":"الجواب: خمس رضعات، العدد خمس رضعات في الحولين، إذا مص الثدي، وابتلع اللبن، ثم أطلق الثدي، ثم عاد إليه في المجلس، أو في مجلس آخر، وارتضع حتى يكمل خمسًا؛ صار بذلك ولدًا للمرضعة، وابنًا لصاحب اللبن زوجها، أما إذا كان الرضاع أقل من خمس، أو شك في ذلك، أو شك في حصول اللبن، أو وصوله إلى الجوف؛ فلا يعتبر. فلابد أن يتيقن أن هناك لبنًا وصل إلى جوفه، ولابد من اليقين خمس رضعات، أو أكثر، ولابد من اليقين أن هذا في الحولين قبل تمام السنتين للطفل، فإذا كان خمس رضعات، أو أكثر متيقنة، يصل فيها اللبن إلى جوف الطفل، وكان الرضاع في الحولين قبل الفطام، قبل تمام السنتين؛ صار الطفل ابنًا للمرضعة، وابنًا لزوجها، وأخًا لأولادها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11676/كم-عدد-الرضعات-المحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52508.mp3","categories":["الرضاع"]},{"id":13465,"question":"بعد ذلك ننتقل إلى رسالة السائل: إبراهيم عبدالعزيز أبو حامد من الرياض، بعث بمجموعة من الأسئلة يبدأ هذه الرسالة بالسؤال الأول ويقول: ما حكم كشف المرأة لوجهها لأبي زوجها من الرضاعة؟","title":"حكم كشف المرأة وجهها لوالد زوجها من الرضاعة","answer":"الجواب: لا حرج، أبو الزوج يصير محرمًا، سواءً نسبًا، أو رضاعة، يقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب أبوه من الرضاع، وابنه من الرضاع محرم، جده من الرضاع، كذلك جد جده، ابن بنته، ابن ابنه، كلهم محارم من النسب والرضاع، نعم.","link":"https://binbaz.org.sa/fatwas/11768/حكم-كشف-المراة-وجهها-لوالد-زوجها-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51713.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":13501,"question":"السائل من أسئلته يقول: ما هي المحرمات من النساء على الرجال؟","title":"المحرمات من النساء","answer":"الجواب: بين الله -جل وعلا- المحرمات في سورة النساء، من قرأ سورة النساء؛ عرف المحرمات في قوله -جل وعلا-: حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالاتُكُمْ وَبَنَاتُ الأَخِ وَبَنَاتُ الأُخْتِ وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23] .. الآية، وبين النبي ﷺ الزيادة على هذا قال: لا يجمع الرجل بين المرأة وعمتها، ولا بين المرأة وخالتها وقال ﷺ: يحرم من الرضاعة ما يحرم من النسب فالأمر واضح، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11815/المحرمات-من-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53104.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":13646,"question":"هذا السائل من السودان رمز لاسمه بـ (أ. ع. ح) يقول: أجبرني والدي على الزواج من قريبة لي، ولكنني لا أحبها، وهي لا تصلي، ولي منها ثلاثة أولاد، وهي تكره أمي، ماذا أفعل معها مأجورين؟","title":"ماذا يفعل من تزوج امرأة لا تصلي؟","answer":"الجواب: إذا كانت لا تصلي، وأنت تصلي فالنكاح غير صحيح، الذي ما يصلي كافر، إذا كنت أنت تصلي والحمد لله، وهي لا تصلي؛ فالنكاح غير صحيح، وأبعدها إلى أهلها، وسوف يرزقك الله خيرًا منها، من ترك شيئًا لله؛ عوضه الله خيرًا منه يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فأبعدها، والتمس غيرها من المصليات، وأبشر بالخير، وأولادك تابعون لك لأجل الشبهة، أولادك منها أولاد لك، وتابعون لك، ونسبهم صحيح، ولكن فارقها، أعطها وثيقة بطلقة واحدة، واسأل ربك أن يبدلك خيرًا منها، وسل الله لها الهداية. نعم. المقدم: وإن رجعت إلى الصلاة سماحة الشيخ؟ الجواب: وإن تابت فلك أن تبقيها تجدد العقد، إذا تابت؛ فلا بأس أن تجدد العقد إن رغبت فيها، يكون بعقد جديد، ومهر جديد إذا تابت. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11979/ماذا-يفعل-من-تزوج-امراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52817.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":13712,"question":"السائلة من مكة المكرمة، والتي رمزت لاسمها بـ: (ف. ص) تقول في هذا  تزوج أبي من امرأة متوفى عنها زوجها، ولها أولاد وبنات، فأنجبت ابنًا، وأرضعتني مع ابنها الذي أنجبته من أبي، علمًا بأن ..الشيخ: أعد.المقدم: تقول: تزوج أبي من امرأة متوفى عنها زوجها، ولها أولاد وبنات، فأنجبت ابنًا، وأرضعتني مع ابنها الذي أنجبته من أبي، علمًا بأنني من امرأة متزوجها أبي، فهل يصير أبناء هذه المرأة المتوفى عنها زوجها إخوتي؟","title":"أولاد المرضعة جميعًا إخوة لمن رضع منها","answer":"الجواب: نعم، إذا أرضعتك خمس رضعات، أو أكثر يكون أولادها جميعًا إخوة لك من جميع أزواجها، إذا كنت صغيرة حين الرضاع دون الحولين، إذا أرضعتك وأنت طفلة دون الحولين خمس رضعات، أو أكثر تكون أمًا لك، ويكون جميع أولادها من أبيك، ومن غيره إخوة لك، من جميع الأزواج. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12081/اولاد-المرضعة-جميعا-اخوة-لمن-رضع-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54507.mp3","categories":["الرضاع"]},{"id":13722,"question":"هذه السائلة أم بندر من المدينة المنورة تقول في هذا  امرأة أرضعت لها طفلًا يومًا كاملًا، ولكنها لا تدري كم عدد الرضعات، فهو الآن أصبح رجلًا، هل يجوز أن يسلم عليها، وعلى بناتها، وعلى بنات زوجها من غيرها؟ أفيدونا سماحة الشيخ.","title":"حكم سلام ومخالطة من لا يُعلم عدد رضعاته","answer":"الجواب: ليس له السلام عليها، ولا على بناتها؛ حتى تعلم أنها أرضعته في هذا اليوم خمس رضعات، أو أكثر، والرضعة: كونه يمسك الثدي، ويرضع اللبن حتى يدر إلى جوفه، ثم يطلقه إما لانتقاله إلى ثدي آخر، أو لأسباب أخرى، أما إذا كان ....... أرضعت له اليوم الثاني يوم الإثنين، أو يوم الأربعاء، ولكن ما أدري هل أرضعته خمسًا، أو ثلاثًا، أو ثنتين، ما أدري؟ هذا ما يكفي، ولا يكون ولدًا لها حتى تجزم، وتعلم يقينًا أنها أرضعته خمسًا، أو أكثر؛ لما ثبت عن النبي ﷺ أنه قال لـسهلة بنت سهيل: أرضعي سالمًا خمس رضعات؛ تحرمي عليه ولما ثبت عن عائشة -رضي الله عنها- قالت: «كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك» توفي النبي ﷺ والأمر على ذلك؛ أخرجه مسلم في صحيحه، والترمذي في جامعه، وهذا لفظه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12094/حكم-سلام-ومخالطة-من-لا-يعلم-عدد-رضعاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54512.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":13800,"question":"المستمع عبد الله الحربي جدة، العزيزية، بعث يسأل ويقول: قامت والدتنا بتربية طفل وكان عمره حين التربية سبعة أيام، وأرضعته رضاعة صناعية، أي على الحليب الصناعي، ولم يكن باستطاعتها إرضاعه إرضاعًا طبيعيًا لعدم وجود الحليب يومئذٍ، هل يجوز للبنات -بنات المرأة المذكورة- أن يقابلنه وقد بلغ من العمر ثمانية عشر سنة، أو هل تجوز مصافحته ولو كان بحضور الأهل جميعًا؟ نرجو التوجيه، جزاكم الله خيرًا.","title":"هل من ربت طفلا يكون محرمًا لها؟","answer":"الجواب:\n\nالتربية لا تجعل المربى محرمًا للمرأة ولا لبناتها، ولكن لهم أجر ذلك، لهم أجر الإحسان، وفعل المعروف، ولكن لا يكون هذا المربى محرمًا لمربية أو لبناتها ولا لأخواتها، هو أجنبي، عليهن التحجب عنه، ولا يصافحنه، ولكن يسلمن عليه السلام الشرعي، ويبدأنه بالسلام، وإذا بدأ ردين عليه السلام وسألنه عن حاله لا بأس بهذا كل هذا أمرٌ مطلوب معه ومع غيره.\n\nأما كونه يعتبر محرمًا بهذه التربية فلا ليس بمحرمًا بهذه التربية، فهو كسائر الأجانب له أن يتزوج المربية، وله أن يتزوج من بناتها إذا لم يكن بينهما رضاع ولا قرابة، وأما كونها ربته على الحليب الذي لم يكن من ثديها هذا لا يجعله ولدًا لها، لكنها محسنة ولها أجر إحسانها، ولكن لا يكون بهذا ولدًا لها، ولا محرماً لبناتها ولا لأخواتها ولا لأمها، بل هو أجنبي.\n\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12177/هل-من-ربت-طفلا-يكون-محرما-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60204.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":13808,"question":"المستمع عبد الله الحربي جدة، العزيزية، بعث يسأل ويقول: قامت والدتنا بتربية طفل وكان عمره حين التربية سبعة أيام، وأرضعته رضاعة صناعية، أي على الحليب الصناعي، ولم يكن باستطاعتها إرضاعه إرضاعًا طبيعيًا لعدم وجود الحليب يومئذٍ، هل يجوز للبنات -بنات المرأة المذكورة- أن يقابلنه وقد بلغ من العمر ثمانية عشر سنة، أو هل تجوز مصافحته ولو كان بحضور الأهل جميعًا؟ نرجو التوجيه، جزاكم الله خيرًا.","title":"هل من ربت طفلا يكون محرمًا لها؟","answer":"الجواب:\n\nالتربية لا تجعل المربى محرمًا للمرأة ولا لبناتها، ولكن لهم أجر ذلك، لهم أجر الإحسان، وفعل المعروف، ولكن لا يكون هذا المربى محرمًا لمربية أو لبناتها ولا لأخواتها، هو أجنبي، عليهن التحجب عنه، ولا يصافحنه، ولكن يسلمن عليه السلام الشرعي، ويبدأنه بالسلام، وإذا بدأ ردين عليه السلام وسألنه عن حاله لا بأس بهذا كل هذا أمرٌ مطلوب معه ومع غيره.\n\nأما كونه يعتبر محرمًا بهذه التربية فلا ليس بمحرمًا بهذه التربية، فهو كسائر الأجانب له أن يتزوج المربية، وله أن يتزوج من بناتها إذا لم يكن بينهما رضاع ولا قرابة، وأما كونها ربته على الحليب الذي لم يكن من ثديها هذا لا يجعله ولدًا لها، لكنها محسنة ولها أجر إحسانها، ولكن لا يكون بهذا ولدًا لها، ولا محرماً لبناتها ولا لأخواتها ولا لأمها، بل هو أجنبي.\n\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12177/هل-من-ربت-طفلا-يكون-محرما-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60204.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":13877,"question":"السائلة (ر . م . هـ) من القصيم استعرضنا سؤالاً لها في حلقة سابقة، تقول: لي أخ من الرضاع أسلم عليه وأقبله كأخي فهل ما أفعله صحيح؟ وهل هو محرم لي؟ أرجو منكم الإجابة.","title":"حكم مصافحة الأخ من الرضاعة وتقبيله","answer":"الجواب:  نعم. هو محرم لك، إذا كان الرضاع ثابت فهو محرم لك كأخيك من النسب، ولكي تقبيله بين عينيه أو على أنفه أو على رأسه ومصافحته كأخيك من النسب وكعمك من النسب فهو محرم إذا كان الرضاع ثابت خمس رضعات أو أكثر في الحولين، إذا كان الرضاع ثابت خمس رضعات أو أكثر حال كونه في الحولين فلا بأس، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12278/حكم-مصافحة-الاخ-من-الرضاعة-وتقبيله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50611.mp3","categories":["الرضاع","المحرمات من النساء","قضايا المرأة"]},{"id":13891,"question":"السائلة (ر . م . هـ) من القصيم استعرضنا سؤالاً لها في حلقة سابقة، تقول: لي أخ من الرضاع أسلم عليه وأقبله كأخي فهل ما أفعله صحيح؟ وهل هو محرم لي؟ أرجو منكم الإجابة.","title":"حكم مصافحة الأخ من الرضاعة وتقبيله","answer":"الجواب:  نعم. هو محرم لك، إذا كان الرضاع ثابت فهو محرم لك كأخيك من النسب، ولكي تقبيله بين عينيه أو على أنفه أو على رأسه ومصافحته كأخيك من النسب وكعمك من النسب فهو محرم إذا كان الرضاع ثابت خمس رضعات أو أكثر في الحولين، إذا كان الرضاع ثابت خمس رضعات أو أكثر حال كونه في الحولين فلا بأس، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12278/حكم-مصافحة-الاخ-من-الرضاعة-وتقبيله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50611.mp3","categories":["الرضاع","المحرمات من النساء","قضايا المرأة"]},{"id":13895,"question":"السائل (م. س. ف) يقول: ما هي الرضعات المحرمة، نرجو بهذا إفادة؟","title":"ما هي الرضعات المحرمة؟","answer":"الجواب: الرضعات المحرمة لابد أن تكون خمسًا أو أكثر، كل رضعة مستقلة، يمص الثدي حتى يذهب اللبن إلى جوفه ثم يقطع - يفصل الثدي - ثم يعود في المجلس ذلك أو في مجلس آخر حتى يكمل خمسًا على ثدي واحد أو على الثديين، هذا هو الرضاع الشرعي المحرم؛ خمسًا فأكثر؛ لقوله ﷺ لسهلة بنت سهيل: أرضعي سالمًا خمس رضعات تحرمي عليه ولما ثبت في الصحيح عن عائشة رضي الله عنها قالت: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك\" أخرجه الإمام مسلم في صحيحه، والإمام الترمذي في جامعه، وهذا لفظه، فعلم بهذا أنه لابد من خمس رضعات أو أكثر في الحولين؛ لقوله ﷺ: لا رضاع إلا في الحولين وكل رضعة مستقلة وحدها، يمص الثدي ويبلع اللبن ويفصل الثدي عن فمه، إذا علمت هذا المرأة وشهدت بهذا المرأة الثقة أو أكثر من مرأة يعمل بذلك، خمس رضعات فأكثر، أما إذا كانت المرأة لا تعلم هل هي خمس أو أقل أو أكثر، أو لا تعلم هل وصله اللبن إلى جوفه أم لا فهذا ليس عليه عمل، ولا يثبت به أحكام الرضاع، حتى يثبت أنه رضع خمسًا كل واحدة مستقلة، وأن اللبن يصل إلى جوفه، وأن ذلك في الحولين، ويشهد بهذا ثقة من النساء أو أكثر. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12271/ما-هي-الرضعات-المحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53809.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":14007,"question":"في الحقيقية أن أسئلة المستمع مساعد سالم جار النبي المالكي جيدة، لكن هذا السؤال ما أدري كيف خطر على باله يقول فيه: رجل كان له زوجة أنجبت بنت وتزاعل معها وطلقها والبنت معها وتزوج ثانية وهي باقية معه أنجبت ولد - ذكر - كبر الولد وأراد أن يزوجه والده، هل يجوز الولد هذا يأخذ البنت التي من والده أنجبتها الزوجة التي كانت قبل والدته؟","title":"حكم زواج الولد من بنت زوجة والده","answer":"الجواب: يزوج بأخته؟! هذا منكر! لا، هو أخوها سواء كان من أمها أو من أبيها فقط، أخوها لا يتزوجها سواء كان أخًا لها من أبيها أو أخًا لها من أمها أو أخًا لها من أمها وأبيها جميعًا، هذا غريب هذا السؤال.\nالمقصود: أنه لا يجوز له، أما لو كانت البنت من غيره بنتًا له من زوج سابق، فهذا لا بأس، زوج ولده من زوجة أخرى لا بأس أن ينكح بنت زوجته من زوج آخر، أما بنت زوجته منه فهي أخت لولده من الزوجة الأخرى ولا تحل له؛ لأنها أخته.\nالمقدم: شكرًا أثابكم الله.","link":"https://binbaz.org.sa/fatwas/12426/حكم-زواج-الولد-من-بنت-زوجة-والده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_540/54007.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":14021,"question":"المستمع (م. م.ع) من ليبيا بعث برسالة يقول فيها: كما علمت أن مصافحة المرأة الأجنبية حرام، هل يجوز لي مصافحة امرأة خالي؟ وأرجو توضيح المحارم؛ لأن والدتي قالت: إذا لم تصافح امرأة خالك لا أصافحك، هل يجوز طاعتها في ذلك؟","title":"حكم مصافحة زوجة الخال","answer":"الجواب: المصافحة للنساء لا تجوز، قال النبي ﷺ: إني لا أصافح النساء، وقالت عائشة رضي الله عنها: \"ما مست يد رسول الله ﷺ يد امرأة قط، ما كان يبايعهن إلا بالكلام\"، ولأن المصافحة للنساء فيها فتنة وخطر كالنظر إليهن، فالواجب عدم مصافحة النساء سوى المحارم، أما المحارم فلا بأس، والمحارم: من يحرم عليك نكاحها؛ كأمك وبنتك وأختك وخالتك وعمتك وبنت أخيك وبنت أختك كما بيَّن الله في كتابه العظيم في سورة النساء حيث قال : حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالاتُكُمْ وَبَنَاتُ الأَخِ وَبَنَاتُ الأُخْتِ وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ ...[النساء:23] الآية. فهؤلاء هن المحارم؛ أمك وجداتك للأب والأم وهكذا بناتك وبنات أولادك وبنات بناتك محارم، وهكذا أخواتك وبناتهن وبنات بناتهن أنت خالهن، وهكذا عماتك محارم وخالاتك محارم، أما بناتهن فلسن محارم لكن خالاتك محارم وعماتك محارم، بنات أخيك وبنات أبناء أخيك وبنات بناتهن كل ذلك محارم، بنات أختك كذلك وبنات بناتهن كل ذلك محارم، وبنات أبناء أختك كلهن محارم، وأمك من الرضاعة وجداتك من الرضاعة وأخواتك من الرضاعة وبناتك من الرضاعة وعماتك من الرضاعة وخالاتك من الرضاعة وبنات أخيك من الرضاعة وبنات أختك من الرضاعة كلهن محارم؛ لقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب. وليس لك أن تصافح زوجة خالك ولا زوجة عمك ولا زوجة أخيك؛ لأنهن لسن محارم، زوجة أخيك وزوجة عمك وخالك لسن محارم، وليس لك أن تطيع أمك في ذلك حتى ولو قالت أمك تصافحها؛ لا تصافحها، فإن الطاعة للوالدين في المعروف لا في المعاصي، قال النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق، فليس لك أن تطيع أباك ولا أمك ولا أميراً ولا عالماً ولا غيرهم في معصية إنما الطاعة في المعروف في المباح، وفق الله الجميع للعلم النافع والعمل الصالح.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12439/حكم-مصافحة-زوجة-الخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61109.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":14064,"question":"هل يجوز لشخص أن يتزوج من أخت إنسان رضع معه رضعتين: أي: الراضع هو الذي يريد الزواج؟","title":"حكم الزواج ممن رضعت من أمه رضعتين","answer":"الجواب: الرضعتان لا تحرمان، يقول النبي ﷺ: لا تحرم الرضعة ولا الرضعتان، لا بد من خمس رضعات، إذا كان الرضاع المضبوط ثنتين أو ثلاث أو أربع هذه لا تحرم، لا بد من خمس رضعات أو أكثر في الحولين مضبوطة معلومة، لكن إذا ترك ذلك من باب ترك المشتبه فلا بأس؛ لقوله ﷺ: دع ما يريبك إلى ما لا يريبك، من اتقى الشبهات استبرأ لدينه وعرضه، لكن لا يحصل التحريم إلا بخمس رضعات أو أكثر، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12481/حكم-الزواج-ممن-رضعت-من-امه-رضعتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48405.mp3","categories":["الرضاع"]},{"id":14286,"question":"رسالة وصلت إلى البرنامج من حائل، باعثها المستمع: (م. م. ع. ع) أخونا يسأل عن الشغار سماحة الشيخ، ولعله لا يستطيع التفريق بين الشغار وما هو غير شغار في الزواج، ويرجو من سماحتكم التوجيه، إذ يسأل ويقول: هل يجوز أن يزوج أبي ولد عمي، وعمي يزوجني ابنته؟ علمًا؛ بأن الجميع موافقون على هذا الزواج، ولقصد القرابة والمودة بين الأخوين، وهل يدخل هذا الزواج في حكم الشغار؟ ما هو رأيكم هل أتمم هذا الزواج أو لا؟ جزاكم الله خيرًا.","title":"صورة نكاح الشغار وحكمه","answer":"الجواب: الشغار لقد ثبت عن النبي ﷺ في الأحاديث الصحيحة النهي عنه قال: والشغار أن يقول الرجل للرجل: زوجني ابنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي هذا هو الشغار أن يقول كل واحد للآخر: زوجني، وأزوجك، هذا يقول: زوجني ابنتك أو أختك، وأنا أزوجك بنتي أو أختي على سبيل المشارطة، هذا هو الشغار. أما إذا خطب أبوك بنت عمك لك، وخطب عمك بنت أبيك وهي أختك لولده أو لابن أخيه فكل هذا لا بأس به إذا لم يكن على سبيل المشارطة والإلزام.\nأما إذا كان على سبيل المشارطة: لا أزوج حتى تزوج، يعني كل واحد يقول: لا أزوجك حتى تزوجني أو تزوج ولدي، هذا هو الشغار المنهي عنه؛ لأنه جعل كل واحدة مهرًا للأخرى، فهو عقد بعقد فلا يجوز ذلك، ولأنه وسيلة إلى ظلم النساء وإكراههن على الزواج بمن لا يرضين، ولأنه وسيلة أيضًا للخصومات والنزاع الكثير، كلما حصل شيء بين الزوج وزوجته تأست بها الأخرى أو ألزمها وليها بذلك حتى يكون النزاع مستمرًا.\nفالحاصل أن الشغار هو أن يقول كل واحد للآخر: زوجني بنتك أو نحوها من مولياته؛ وأنا أزوجك بنتي أو نحوها من مولياته، مشارطة، على سبيل الشرط والإلزام، أما إذا كان من غير هذا الشرط بل خطب منه وهذا خطب من الآخر وكل وافق من دون مشارطة فلا بأس بذلك ولا حرج.\nالمقدم: بارك الله فيكم، وإن تساوى المهر، وإن تساوت التكاليف؟\nالشيخ: نعم، لا حرج، سواء تساوت أو اختلفت. نعم.\nالمقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12757/صورة-نكاح-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_618/61802.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":14428,"question":"المستمعة (ش. م. عوضة ) من مدينة أبها، بعثت برسالة تقول فيها: لي أبناء أعمام رضعوا معي في الحولين الأولين أكثر من خمس رضعات، واحد رضع معي من أمي، ولم أرضع أنا من أمه، فكيف يكون وضع إخوتي الذين هم أكبر مني وأصغر مني؟","title":"حكم أولاد المرضعة بالنسبة لمن رضع منها","answer":"الجواب: الذي رضع من أمك، من أولاد عمك، خمس رضعات أو أكثر، يكون أخًا لكم جميعًا، الذي رضع من أمك، سواءً قبلك أو معك، أو بعدك خمس رضعات أو أكثر في الحولين، حال كونه في الحولين هذا يكون أخًا لجميع أولاد أمك، وجميع أولاد أبيك إذا كانت حين أرضعته مع أبيك، سواءً كان هذا المرتضع قبلك، أو بعدك أو معك أو مع أخيك الكبير أو مع أختك الكبيرة أو الصغيرة كله واحد. أما إذا كنت أنت رضعت من أمه فأنت أخته فقط، إذا كنت رضعت من أمه خمس رضعات فأكثر فأنت أخت أولاد الأم التي أرضعتك، أولاد المرأة التي أرضعتك دون إخوتك، أما إخوتك فليسوا أخًا لأولاد المرضعة؛ لأنهم لم يرتضعوا منها، وإنما ارتضع منها أنت وحدك، فأنت أخت لأولاد المرضعة فقط، وأما إذا كان الشخص رضع من أمك أنت أو من زوجة أبيك فهو أخ لكم جميعًا، نعم.\nالمقدم: جزاكم الله خيرًا. ابن عمي الآخر رضعت أنا معه من أمه، وهو رضع معي من أمي، وله أخ أكبر منه وأخ أصغر منه، ولم يرضعوا من أمي، وأخته الكبرى رضعت مع أختي الكبرى، وطريقتهم مثلنا كل منهم رضع من أم الآخر، فماذا أكون أنا وأخواتي بالنسبة لإخوان أخي من الرضاعة؟ وماذا تكون القرابة بين أخوات أخي من الرضاعة لإخواني الذكور؟\nالشيخ: تقدم الجواب عن هذا، أما أنت إذا رضعت من أم بعض أولاد عمك فأنت أخت لجميع أولاد المرأة المرضعة، أنت وحدك دون إخوانك؛ لأنك رضعت من أمه فيكون أخًا لك، وهكذا إخوته وأخواته كلهم أخوات لك؛ لأنك رضعت من أمهم، وهكذا أولاد الزوج الذي هي معه حين الرضاع -صاحب اللبن- أولاده إخوة لك.\nوأما إذا كان أحدهم رضع من أمك أنت فهو أخ لك ولإخوانك جميعًا كما تقدم في جواب السؤال السابق، نعم. المقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/12922/حكم-اولاد-المرضعة-بالنسبة-لمن-رضع-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62403.mp3","categories":["الرضاع"]},{"id":14442,"question":"المستمعة (ش. م. عوضة ) من مدينة أبها، بعثت برسالة تقول فيها: لي أبناء أعمام رضعوا معي في الحولين الأولين أكثر من خمس رضعات، واحد رضع معي من أمي، ولم أرضع أنا من أمه، فكيف يكون وضع إخوتي الذين هم أكبر مني وأصغر مني؟","title":"حكم أولاد المرضعة بالنسبة لمن رضع منها","answer":"الجواب: الذي رضع من أمك، من أولاد عمك، خمس رضعات أو أكثر، يكون أخًا لكم جميعًا، الذي رضع من أمك، سواءً قبلك أو معك، أو بعدك خمس رضعات أو أكثر في الحولين، حال كونه في الحولين هذا يكون أخًا لجميع أولاد أمك، وجميع أولاد أبيك إذا كانت حين أرضعته مع أبيك، سواءً كان هذا المرتضع قبلك، أو بعدك أو معك أو مع أخيك الكبير أو مع أختك الكبيرة أو الصغيرة كله واحد. أما إذا كنت أنت رضعت من أمه فأنت أخته فقط، إذا كنت رضعت من أمه خمس رضعات فأكثر فأنت أخت أولاد الأم التي أرضعتك، أولاد المرأة التي أرضعتك دون إخوتك، أما إخوتك فليسوا أخًا لأولاد المرضعة؛ لأنهم لم يرتضعوا منها، وإنما ارتضع منها أنت وحدك، فأنت أخت لأولاد المرضعة فقط، وأما إذا كان الشخص رضع من أمك أنت أو من زوجة أبيك فهو أخ لكم جميعًا، نعم.\nالمقدم: جزاكم الله خيرًا. ابن عمي الآخر رضعت أنا معه من أمه، وهو رضع معي من أمي، وله أخ أكبر منه وأخ أصغر منه، ولم يرضعوا من أمي، وأخته الكبرى رضعت مع أختي الكبرى، وطريقتهم مثلنا كل منهم رضع من أم الآخر، فماذا أكون أنا وأخواتي بالنسبة لإخوان أخي من الرضاعة؟ وماذا تكون القرابة بين أخوات أخي من الرضاعة لإخواني الذكور؟\nالشيخ: تقدم الجواب عن هذا، أما أنت إذا رضعت من أم بعض أولاد عمك فأنت أخت لجميع أولاد المرأة المرضعة، أنت وحدك دون إخوانك؛ لأنك رضعت من أمه فيكون أخًا لك، وهكذا إخوته وأخواته كلهم أخوات لك؛ لأنك رضعت من أمهم، وهكذا أولاد الزوج الذي هي معه حين الرضاع -صاحب اللبن- أولاده إخوة لك.\nوأما إذا كان أحدهم رضع من أمك أنت فهو أخ لك ولإخوانك جميعًا كما تقدم في جواب السؤال السابق، نعم. المقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/12922/حكم-اولاد-المرضعة-بالنسبة-لمن-رضع-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62403.mp3","categories":["الرضاع"]},{"id":14627,"question":"من المملكة الأردنية الهاشمية، عمان إربد، الأغوار الشمالية؛ هذه الرسالة بعث بها المستمع أبو زيد لطفي فرج، أخونا أبو لطفي يسأل ويقول: رضعت أختي الصغيرة من زوجة عمي مع ابنتها، فهل يصح لي الزواج من بنت عمي التي رضعت معها أختي الصغيرة؟","title":"حكم الزواج بامرأة رضعت أخته من أمها","answer":"الجواب: نعم لا حرج؛ لأن الرضاع يختص بالرضيعة أختك، أخت السائل، أما بنت عمه فلا تعلق لها بذلك، إذا كانت بنت العم لم ترضع من أمك -أيها السائل- ولا من أخواتك، ولا من زوجة أبيك، فإنها أجنبية، ولا يضرك كون أختك رضعت من أمها لا يضرك، ولا يحرمها عليك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13123/حكم-الزواج-بامراة-رضعت-اخته-من-امها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62612.mp3","categories":["الرضاع"]},{"id":14629,"question":"من المملكة الأردنية الهاشمية، عمان إربد، الأغوار الشمالية؛ هذه الرسالة بعث بها المستمع أبو زيد لطفي فرج، أخونا أبو لطفي يسأل ويقول: رضعت أختي الصغيرة من زوجة عمي مع ابنتها، فهل يصح لي الزواج من بنت عمي التي رضعت معها أختي الصغيرة؟","title":"حكم الزواج بامرأة رضعت أخته من أمها","answer":"الجواب: نعم لا حرج؛ لأن الرضاع يختص بالرضيعة أختك، أخت السائل، أما بنت عمه فلا تعلق لها بذلك، إذا كانت بنت العم لم ترضع من أمك -أيها السائل- ولا من أخواتك، ولا من زوجة أبيك، فإنها أجنبية، ولا يضرك كون أختك رضعت من أمها لا يضرك، ولا يحرمها عليك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13123/حكم-الزواج-بامراة-رضعت-اخته-من-امها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_626/nour_62612.mp3","categories":["الرضاع"]},{"id":14631,"question":"تقول السائلة: ابن خالي رضع مع أخي الأكبر، هل يكون أخًا لي ولإخواني من الرضاعة؟","title":"هل من رضع من امرأة يكون أخًا لأولادها جميعًا؟","answer":"الجواب: إذا رضع الإنسان ابن الخال أو ابن العم أو غيرهم إذا رضع من المرأة رضاعًا تامًا خمس مرات فأكثر، في الحولين، صار أخًا لأولادها كلهم، الذين قبله والذين بعده، إذا رضع من فاطمة من زينب مثلًا خمس رضعات أو أكثر حال كونه في الحولين، قبل أن يفطم، يكون أخًا لأولادها جميعًا السابقين واللاحقين، الذين قبله والذين بعده، من زوجها صاحب اللبن، أو من أزواج آخرين، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13124/هل-من-رضع-من-امراة-يكون-اخا-لاولادها-جميعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55914.mp3","categories":["الرضاع"]},{"id":14699,"question":"إذا أرضعت امرأة طفلًا في الحولين خمس رضعات، هل يكون جميع إخوان الطفل أبناءً لها؟ وهل جميع أبنائها إخوان للطفل؟","title":"هل إخوان من رضع من امرأة أبناء لها؟","answer":"الجواب: أما إذا أرضعت امرأة إنسانًا خمس رضعات فأكثر في الحولين -حال كونه في الحولين- فإنه يكون ولدًا لها فقط هو، أما إخوته لا، الذين لم يرضعوا ليسوا أولادًا لها، إنما هو فقط يكون ولدًا لها، ويكون أخًا لأولاها ذكورهم وإناثهم، ويكون زوجها الذي أرضعته وهي في عصمته يكون زوجها أبًا له من الرضاع، وأمها جدة له من الرضاع، وإخوانها أخوالًا له من الرضاع، وأخواتها خالات له من الرضاع.  وأما إخوته هو فليسوا أولادًا لها، الرضاع يختص به هو، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13209/هل-اخوان-من-رضع-من-امراة-ابناء-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62905.mp3","categories":["الرضاع"]},{"id":14708,"question":"إذا أرضعت امرأة طفلًا في الحولين خمس رضعات، هل يكون جميع إخوان الطفل أبناءً لها؟ وهل جميع أبنائها إخوان للطفل؟","title":"هل إخوان من رضع من امرأة أبناء لها؟","answer":"الجواب: أما إذا أرضعت امرأة إنسانًا خمس رضعات فأكثر في الحولين -حال كونه في الحولين- فإنه يكون ولدًا لها فقط هو، أما إخوته لا، الذين لم يرضعوا ليسوا أولادًا لها، إنما هو فقط يكون ولدًا لها، ويكون أخًا لأولاها ذكورهم وإناثهم، ويكون زوجها الذي أرضعته وهي في عصمته يكون زوجها أبًا له من الرضاع، وأمها جدة له من الرضاع، وإخوانها أخوالًا له من الرضاع، وأخواتها خالات له من الرضاع.  وأما إخوته هو فليسوا أولادًا لها، الرضاع يختص به هو، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13209/هل-اخوان-من-رضع-من-امراة-ابناء-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62905.mp3","categories":["الرضاع"]},{"id":14802,"question":"نختم هذا اللقاء بهذا السؤال من سوريا يا سماحة الشيخ، يقول السائل: عبدالسلام من سوريا، حلب:شاب يريد الزواج من فتاة ترغب فيه، ويرغب فيها، ولكن هذا الشاب رضع من أم تلك الفتاة رضعة واحدة مشبعة، فهل تحرم هذه الرضعة هذا الزواج؟","title":"هل تحرم الرضعة الواحدة المشبعة؟","answer":"الجواب: الرضعة الواحدة لا تحرم، والرضعتان لا تحرمان، يقول النبي ﷺ: لا تحرم الرضعة ولا الرضعتان، ولا المصة ولا المصتان ويقول ﷺ لـسهلة بنت سهيل: أرضعي سالمًا خمس رضعات تحرمي عليه وتقول عائشة -رضي الله عنها-: «كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك».  فالرضعات المحرمة لا بد أن تكون خمسًا، أو أكثر، كل واحدة مستقلة، يمص الثدي ويشرب اللبن حتى يذهب إلى جوفه، ثم ينزع يطلق الثدي، فإذا عاد ومص الثدي وشرب اللبن هذه ثانية، فإذا أطلق الثدي، ثم عاد ثالثة، هذه ثالثة، وهكذا حتى يكمل خمس، كل واحدة مستقلة، تجزم المرأة أنه شرب لبنًا، أنه حصل له لبن، أما إذا مصه من دون لبن ما ينفع، أو كانت ما فيها لبن إنما اشتغل بثديها حتى يسكت، وإلا ما فيها لبن ما ينفع، فلا بد من خمس رضعات، أو أكثر كل رضعة مستقلة، فيها لبن يصل إلى جوفه.  أما الرضعة الواحدة والرضعتان فلا تحرمان ولا الثلاث ولا الأربع، نعم.","link":"https://binbaz.org.sa/fatwas/13293/هل-تحرم-الرضعة-الواحدة-المشبعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56120.mp3","categories":["الرضاع"]},{"id":14833,"question":"المستمع صلاح بن إبراهيم محمود، مقيم في القصيم، بعث يسأل ويقول: ولدتني أمي، وهي في عصمة أبي، ثم طلقها أبي بعد ولادتي، وتزوج من أمي رجل آخر، ولم أبلغ آنذاك الفطام، فرضعت من أمي بعد زواجها الأخير أكثر من خمس مرات مروية ومشبعة، فهل أكون بذلك ابنًا لزوج أمي من الرضاعة وأخًا لأبنائه؟","title":"هل من رضعت من أمها تكون بنتًا لزوجها؟","answer":"الجواب: لا تكون ابنًا له، أنت ابن زوجته، ربيبه، لكن لو حملت أمك، انقطع لبنها وحملت وأتت بولد أو بنت، وجاء لها لبن وأنت في الرضاع ما بعد فطمت، تكون ولدًا له، إذا أرضعك بلبنه الجديد، لو حملت وأنت صغير، ثم ولدت، ودر لها لبن على الولد الأخير، وأرضعتك، وأنت لم تبلغ الفطام ما فطمت فإنك تكون ولدًا له من الرضاعة.  أما كونك رضعت منها من لبن الأول من لبن أبيك بعدما تزوجت لا يجعلك ولدًا له؛ لأن اللبن لبن أبيك باقي، لكن لو حملت من الزوج الجديد، ودرت لبن بعدما وضعت الحمل، وأنت لا تزال في الحولين، ثم أرضعتك من لبن الزوج الجديد مع أخيك الجديد تكون ولدًا له من الرضاعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13318/هل-من-رضعت-من-امها-تكون-بنتا-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_491/49104.mp3","categories":["الرضاع"]},{"id":14849,"question":"أحد المستمعين، بعث بسؤال يقول فيه: رضعت مع ابن عمي من أمه، ورضع معي من أمي أكثر من خمس مرات لكل منا، فما حكم زواجي بأخته أو زواجه بإحدى أخواتي.الشيخ: أعد.المقدم: يقول: رضعت مع ابن عمي من أمه، ورضع معي من أمي أكثر من خمس مرات لكل منا، فما حكم زواجي بأخته أو زواجه بإحدى أخواتي التي لم يكن بينه وبينها رضاع؟","title":"حرمة الزواج ببنات الأم من الرضاع","answer":"الجواب: ما دام رضع من أمك فأخواتك حرام عليه، إذا كان الرضاع كما قلت: خمس رضعات أو أكثر؛ لأن أخواتك أخوات له بالرضاعة، وهكذا أنت ما دمت رضعت من أمه، فجميع أخواته حرام عليك؛ لأنهن أخوات لك، إذا كان أولئك من الأم من تلك المرأة التي أرضعتكما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13348/حرمة-الزواج-ببنات-الام-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64405.mp3","categories":["الرضاع"]},{"id":14882,"question":"المستمع سليمان بن إبراهيم الوكيل، من منطقة سدير، بعث يسأل ويقول: قال الله تعالى: وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَنْ يُتِمَّ الرَّضَاعَةَ [البقرة:233] الآية، هل هذا خاص بالمطلقة أم هو عام؟ وما حكم من أرضعت طفلها أكثر من عامين؟","title":"مدة الرضاع وحكم الزيادة على عامين","answer":"الجواب: هذا عام، الآية عامة، في الطفل الذي قد طلقت أمه، وفي الطفل الذي لم تطلق أمه، الآية عامة، المدة حولان، قال تعالى: وَحَمْلُهُ وَفِصَالُهُ ثَلاثُونَ شَهْرًا [الأحقاف:15] الفصال: مدة الرضاع أربعة وعشرون شهرًا، ومدة الحمل ستة أشهر، هذا أقل مدة الحمل، قال تعالى: وَفِصَالُهُ فِي عَامَيْنِ [لقمان:14] فدل ذلك على أن الرضاع سنتان للمطلقة وغير المطلقة، وهذا إذا أحب الوالدان، أما إذا تراضيا أن يفطماه قبل الحولين فلا بأس بذلك ليسقى من لبن الحيوانات؛ لقوله تعالى: فَإِنْ أَرَادَا فِصَالًا عَنْ تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ فَلا جُنَاحَ عَلَيْهِمَا [البقرة:233] الفصال: الفطام، فَإِنْ أَرَادَا فِصَالًا [البقرة:233] يعني: فطامًا عَنْ تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ فَلا جُنَاحَ عَلَيْهِمَا [البقرة:233]. فإذا اتفق الأبوان، يعني: الزوجان، أن يفطماه لسنة أو لسنة وأشهر أو لأقل أو لأكثر لأسباب اقتضت ذلك فلا بأس، فإن لم يتفقا فإنه يرضع سنتين، ولا يزاد على السنتين إلا في حاجة، إذا ادعت حاجة إلى الزيادة فلا بأس، مثل كونه ما يشتهي الطعام، فلا بأس أن تزيده على الحولين حتى يشتهي الطعام، وحتى يتغذى بالطعام، ولا حرج في ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/13378/مدة-الرضاع-وحكم-الزيادة-على-عامين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64521.mp3","categories":["الرضاع"]},{"id":14884,"question":"رجل تزوج بامرأة، وعلم أنها لا تجوز له من جهة الرضاعة؛ لكونه رضيع أختها الأصغر، ولم يعلم إلا بعد أن طلقها، وقد أنجبت له ولدًا، هل يجب عليه كفارة، أو ما شابه ذلك؟الشيخ: أعد أعد.المقدم: يقول: رجل تزوج بامرأة، وعلم أنها لا تجوز له من جهة الرضاعة؛ لكونه رضيع أختها الأصغر، ولم يعلم إلا بعد أن طلقها، وقد أنجبت له ولدًا، هل يجب عليه كفارة، أو ما شابه ذلك؟","title":"ما يجب على من تزوج بأخته من الرضاع دون علمه؟","answer":"الجواب: ليس عليه شيء، ما دام ما علم ليس عليه شيء، وولده صحيح، ولده منسوب له، والحمد لله؛ لأنه ما تعمد الباطل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13381/ما-يجب-على-من-تزوج-باخته-من-الرضاع-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_491/49107.mp3","categories":["الرضاع"]},{"id":14885,"question":"المستمع إبراهيم ( ع. ك ) سوري الجنسية، بعث برسالة يقول فيها: تزوجت ابنة عمي، وأنجبت لي ولدين ولله الحمد، ومن فترة سافرت إلى سوريا، واجتمعت العائلة عندي في البيت، وقالت لي عمتي والدة زوجتي: إن زوجتي رضعت من خالتي زوجة أبي أكثر من خمس رضعات، ومنذ ذلك اليوم...الشيخ: خالتي.المقدم: يقول: رضعت من خالتي زوجة أبي أكثر من خمس رضعات، ومنذ ذلك اليوم ابتعدت عن فراش الزوجية، ولم أخبر زوجتي بذلك، وأنا في حيرة من أمري، ما هو المطلوب مني؟ أفيدوني، وفقكم الله.الشيخ: أعد بعد، الله المستعان.المقدم: الله المستعان، تزوجت بنت عمي، وأنجبت لي ولدين، ولله الحمد، ومن فترة سافرت إلى سوريا، واجتمعت العائلة عندي في البيت، وقالت لي عمتي والدة زوجتي: إن زوجتي رضعت من خالتي زوجة أبي أكثر من خمس رضعات، ومنذ ذلك اليوم ابتعدت عن فراش الزوجية، ولم أخبر زوجتي بذلك، وأنا في حيرة من أمري، ما هو المطلوب مني؟أفيدوني، وفقكم الله.","title":"حكم من تزوج من امرأة رضعت من زوجة أبيه","answer":"الجواب: بهذا الرضاع تكون أختًا لك من أبيك، ويبطل النكاح، إذا كانت المخبرة التي هي أمها ثقة، معروفة بالصدق والعدالة والاستقامة، ولا تتهم بأنها تريد فراقك لابنتها. المقدم: أو تريد فراق تلك. الشيخ: المقصود: أنها لا بد أن تكون ثقة يعرفها الناس بالصلاة والاستقامة والصدق، وعدم وجود ما يقدح في شهادتها، لا بد أن تكون معروفة بالاستقامة والصدق والمحافظة على الصلوات، وليس فيها جرح يمنع شهادتها. أما أولادك فأولادك تابعون لك؛ لأنهم ولدوا على شبهة النكاح. فالحاصل: أن الواجب التثبت في هذا الأمر، تجتنب المرأة، تثبت، تسأل، ولا مانع من إحضارها عند قاضٍ شرعي يسألها، أو عند بعض العلماء هناك يخوفونها الله ويحذرونها من التساهل، ويعرفون ما لديها، وسؤال العارفين بها من جهة استقامتها، وأنها ثقة دينة، ليست ممن يعبد القبور أو يسأل الأولياء والصالحين أو يتساهل بالصلاة، أو ليست من المعروفين بالمعاصي الأخرى، فإذا كانت ثقة ليس فيها جرح فاجتنب الزوجة حينئذٍ، وأعطها طلقة صكًا بطلقة حتى تعتمد على ذلك عند رغبتها في الزواج، تعطيها صكًا شرعيًا.  هذا بعد التثبت في الأمور، تعتزلها وتبقى تسأل وتنظر في الأمر وحتى تعرف ثقة والدتها، وأنها لا تتهم في شيء من ذلك، ويطمئن قلبك إلى فراق زوجتك بعد وجود المبررات التي لا يبقى معها شك في الشهادة، وإذا كان من طريق بعض القضاة الطيبين أو العلماء المعروفين تحضرها عندهم والشهود العارفين بها؛ حتى يكون الأمر عن بصيرة وعن فتوى أهل العلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13383/حكم-من-تزوج-من-امراة-رضعت-من-زوجة-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_491/49108.mp3","categories":["الرضاع"]},{"id":14888,"question":"سماحة الشيخ كثير من الناس عندما يتزوج وربما أنجب ولدًا أو ولدين أو أكثر أو أقل، يفاجأ فتأتي امرأة فتقول: إن بينك وبين فلانة رضاع، وهي تعتقد أن الرضاع هذا إن كان صحيحًا يوقع الفصال في الأسرة، بم تنصحون النساء في مواضيع الرضاع والتثبت والورع في هذا الموضوع؟جزاكم الله خيرًا.","title":"وجوب التثبت في مسائل الرضاع","answer":"الجواب: هذا واقع يقع، قد وقع عليه عقبة بن الحارث في عهد النبي ﷺ، تزوج امرأة ثم جاءته امرأة أمة فقالت: قد أرضعتكما، فذهب إلى النبي ﷺ واستفتاه في ذلك، فقال له النبي ﷺ: كيف وقد قيل، دعها عنك فأمره -عليه الصلاة والسلام- بفراقها، وهذا عند أهل العلم محمول على أنها ثقة المرأة، وأنها أرضعتها خمس رضعات أرضعتهما جميعًا. فالمقصود: أن هذا يقع، كما وقع لـعقبة بن الحارث، يقع، لكن الواجب التثبت في الأمور؛ لأن المرأة قد تكون عندها يعني: أسبابًا تحملها على الشهادة الباطلة: إما لأنها بينها وبين الزوج شيء تريد أن تفرق بينها وبين ابنتها، أو لأسباب أخرى تدعوها إلى الشهادة التي تفرق بينه وبين أهله، أو قد تكون في نفسها لا تعتبر لفسقها أو كفرها من جهة ترك الصلاة، أو التعلق بالأموات والاستغاثة بالأموات، أو سب الدين، أو لغير هذا من الأسباب التي تدل على عدم دينها أو ضعف دينها فلا تعتبر شهادتها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13386/وجوب-التثبت-في-مساىل-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_491/49109.mp3","categories":["الرضاع"]},{"id":14927,"question":"رسالة وصلت إلى البرنامج من المستمع: (ب. م. أ) يقول: هل يجوز الزواج بالتبادل أو في البدلة، بمعنى: رجلان يتبادلان بأخواتهم، أو في بناتهم؟ مع دفع مبلغٍ من المال كمهر، لكل واحدةٍ منهن، ولكن أقل من المهر السائد في المنطقة؟ علمًا أن الزواج بموافقتهن. أفيدونا، أفادكم الله.","title":"هل يجوز الزواج بالتبادل إذا وافقت الزوجتان؟","answer":"الجواب: الزواج بالتبادل لا يجوز، كونه يسمى: نكاح الشغار، وقد نهى عنه النبي ﷺ في أحاديث كثيرة صحيحة، وهو أن يقول: زوجني أختك، وأزوجك أختي، أو بنتك، وأزوجك بنتي، أو ما أشبه ذلك، هذا لا يجوز، ولو بالمهر، ولو تراضى الجميع؛ لأن الرسول نهى عن ذلك -عليه الصلاة والسلام-؛ ولأنه وسيلة إلى إجبار النساء، وظلم النساء؛ ولأنه وسيلة إلى الفتن، والخصومات، إذا تنازع هذا مع زوجته، كذلك الرجل الآخر تنازعه زوجته أو أهلها. فالحاصل: أنه لا يجوز لما يترتب عليه من الشرور، أما إذا خطب هذا، وخطب هذا من دون شرط، هذا خطب من الأسرة، وخطبوا منه، من دون مشارطة؛ فلا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13423/هل-يجوز-الزواج-بالتبادل-اذا-وافقت-الزوجتان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64008.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":14943,"question":"السؤال الأخير لأخينا يقول: لدي أخت من أم، رضعت مع ابن خالي، فتقدم ابن خالي للزواج من أختي شقيقتي، فهل له أن يتزوجها أم لا؟","title":"حكم الزواج بأخت الأخت من الرضاع","answer":"الجواب: إذا كانت الأخت من أم رضعت من أمه هو، فلا بأس أن ينكح أختك -شقيقتك- لأنه ليس بينه وبينها رضاع.  أما إن كان رضع من أمك مع أختك من أمك رضاعًا كاملًا خمس رضعات أو أكثر؛ فإنه يكون أخًا لكم جميعًا، ولا يجوز له أن ينكح لا أختك من أمك، ولا أختك شقيقتك، لأنها رضيعة له.  أما إن كانت أختك من أمك رضعت من أمه هو فإنها تكون محرمًا له، ويكون محرمًا لها، إذا كان الرضاع خمس رضعات فأكثر، وكان في الحولين، أما أختك الشقيقة التي لم ترضع من أمه، ولم يرضع من أمها؛ فإنه لا يحرم عليه نكاحها، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ","link":"https://binbaz.org.sa/fatwas/13437/حكم-الزواج-باخت-الاخت-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64013.mp3","categories":["الرضاع"]},{"id":14953,"question":"هذه رسالة وردتنا من الرياض من المرسل (م. ع. ج) يقول فيها: يوجد عندي ابنة عم، وأريد الزواج منها ولكن بنفسي من ذلك أن أخوها -أكبر منها- رضع مع أختي التي هي أصغر مني، فهل تحل لي؟ وهل أخواتي يحلون لأولاد عمي؟وشكرًا.","title":"حكم الزواج بامرأة رضع أخوها من أم الخاطب","answer":"الجواب: أما هي تحل لك؛ لأن رضاع أخيها من والدتك لا يضر، رضاع أخيها من أمك لا يضر، ولا يحرمها عليك، فهي تحل لك، أما هو فإن كان رضاعًا شرعيًا بأن كان خمس رضعات.  أما هو ينظر في رضاعه، إن كان خمس رضعات فأكثر في الحولين؛ صار أخًا لكم، صار أخًا لك ولإخوانك، وصار عمًا لبناتكم لا يحل له شيئًا منهن.  أما إن كان رضاعه أقل من خمس فإنه لا يكون أخًا لكم، أو كان الرضاع في غير الحولين وهو كبير، ما يكون أخًا لكم، فإذا كان الرضاع خمس رضعات، أو أكثر في الحولين؛ فإنه يكون أخًا لكم ويكون عمًا لبناتك وبنات إخوتك، ولا يجوز له أن ينكح منهن أحدًا، نعم.","link":"https://binbaz.org.sa/fatwas/13456/حكم-الزواج-بامراة-رضع-اخوها-من-ام-الخاطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_648/nour_64807.mp3","categories":["الرضاع"]},{"id":14991,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد بن علي حمدان تهامي أخونا له جمع من الأسئلة من بينها سؤال يقول:عندي بنت وطلبها مني رجل للزواج بها، فاشترطت عليه أن يزوجني بأخته، فزوجني بها، وزوجته بابنتي، فما حكم ذلك؟","title":"ما حكم من زوج ابنته برجل وشرط أن يزوجه بأخته؟","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فهذه الصورة التي ذكرها السائل تسمى نكاح الشغار، وقد ثبت عن رسول الله -عليه الصلاة والسلام- في عدة أحاديث النهي عن ذلك، فهو نكاح فاسد مطلقًا، سواء سمي مهرًا أو لم يسم مهرًا، والواجب فسخه، وإذا كان كل واحد يرغب في المرأة فإنه يجدد النكاح، ولا حاجة إلى طلاق، كل واحد يجدد النكاح بمهر وشاهدين وولي، ولا حرج في ذلك مع التوبة والاستغفار عما مضى، والأولاد يلحقون بآبائهم؛ لأن النكاح نكاح شبهة، فأولاده لاحقون به، ولكن عليه أن يجدد النكاح إذا كانت ترغب فيه وهو يرغب فيها، يجدد النكاح بمهر جديد، وشاهدي عدل إذا رضيت المرأة بذلك، وبذلك ينتهي الأشكال، لكن بشرط ألا تشترط المرأة الأخرى، يعني: لا يشترط المرأة الأخرى، يتزوجها من غير اشتراط لتزوج الأخرى، كل واحد يتزوج برضى المرأة من دون اشتراط المرأة الأخرى، ويكون هذا نكاحًا جديدًا بشروطه التامة، برضاها وبالولي، لكن لا يشترط خروجها من العدة، بل يتزوجها في الحال؛ لأن الماء ماؤه، يتزوجها في الحال، ولا حاجة إلى عدة، فإن لم ترده طلقها طلقة واحدة، تكفي طلقة واحدة لإنهاء هذا النكاح الفاسد.  وعلى الجميع التوبة إلى الله سبحانه، على الرجال والنساء والأولياء، عليهم التوبة إلى الله جميعًا؛ لأنهم وقعوا أمر نهى عنه النبي ﷺ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13481/ما-حكم-من-زوج-ابنته-برجل-وشرط-ان-يزوجه-باخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49301.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":14997,"question":"الرسالة التي بين يدينا -وهي الرسالة الأخيرة في لقائنا هذا- وردتنا من المرسلة من المنطقة الشرقية (ل. ع. ع) تقول في رسالتها: أطلب من فضيلة الشيخ الإجابة على السؤال التالي:تقول: عندي أب له زوجة قبل أمي أرضعت ولدًا، وهو الآن يبلغ الخمسين من العمر، وأنا الآن أكشف عنه، وقد سمعت من الناس أنه يجب أن ألبس حجاب لأغطي وجهي عن هذا الرجل، وأنا الآن محتارة لا أدري هل أكشف عنه أم لا؟مع العلم أني لا أعرف كم عدد الرضعات التي رضعها؟أفيدوني، جزاكم الله عني خير الجزاء.","title":"حكم كشف المرأة وجهها لمن رضع من زوجة أبيها","answer":"الجواب: إذا كانت زوجة أبيك السابقة أرضعته خمس رضعات؛ فإنه يكون أخًا لك، ولجميع أولاد أبيك، أخًا من الأب بالرضاعة، فلك أن تكشفي له وجهك كسائر المحارم.  أما إذا كان الرضاع فيه شك، وليس عندكم من يعلم الرضاع هل هو خمس أو أقل أو أكثر؟ فلا تكشفي له، ولا تعتبريه محرمًا؛ لأن الرضاع المحرم لا بد يكون خمس رضعات فأكثر في الحولين، فإذا ثبت بشهادة امرأة ثقة، أو رجل ثقة أن هذا الرجل رضع من زوجة أبيك خمس رضعات حال كونه طفلًا في الحولين، أو أكثر من خمس؛ فهذا أخوكم تكشفين له كسائر المحارم، محرم لك، أما إذا كان في هذا شك وليس عندكم من يحفظ هذا، ولا يدرى هل رضع خمسًا أو أقل أو أكثر؛ فهذا لا يكون محرمًا، ولا يكون أخًا لك، وعليك أن تحتجبي عنه كسائر الناس، نعم.","link":"https://binbaz.org.sa/fatwas/13497/حكم-كشف-المراة-وجهها-لمن-رضع-من-زوجة-ابيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_651/nour_65109.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":15026,"question":"أيضًا يقول: هل يجوز أن يجمع شخص بين امرأة وبنت ولد أخيها؟","title":"حكم الجمع بين المرأة وبنت ولد أخيها","answer":"الجواب: ثبت في الصحيحين عن النبي -عليه الصلاة والسلام- أنه: \"نهى أن يجمع الرجل بين المرأة وعمتها، وبين المرأة وخالتها\" وبين أهل العلم أن العمة تكون قريبة، وتكون بعيدة، والخالة كذلك، فليس للرجل أن يجمع بين المرأة وبنت أخيها التي هي عمتها، ولا بنت ابن أخيها، التي هي عمة أبيها، مثل هذا السؤال، فإن عمة الرجل عمة لأولاده وإن نزلوا، وهكذا خالته خالة لأولاده وإن نزلوا.  فليس له أن يجمع بين امرأةٍ وبنت أخيها، ولا بنت بنت أخيها، ولا بنت ابن أخيها، ولا بنت ابن ابن أخيها، وهكذا؛ لأنها عمة الجميع، وهكذا ليس له أن يجمع بين المرأة وبين بنت أختها، ولا بنت بنت أختها، ولا بنت ابن أختها؛ لأنها خالة الجميع وإن نزلوا، نعم.","link":"https://binbaz.org.sa/fatwas/13535/حكم-الجمع-بين-المراة-وبنت-ولد-اخيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65308.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":15165,"question":"هذا رسالة وردتنا من عبدالله حسين بن علي من الطائف من الشرقية، شارع عكاظ، يقول فيه: لدي سؤال وهو كما يلي:أفيدكم أنني رضعت على ابنة عمي أكثر من الرضاعة الشرعية بكثير جدًا، فأصبحت أخًا لها بالرضاع، والسؤال هو: هل يجوز لي أن أتزوج من إحدى أخواتها؟ وهل يجوز لأخي أيضًا أن يتزوج من إحدى أخواتها؟ علمًا بأن لأختي هذه -من الرضاعة يعني- أختان في سن الزواج؟أفيدوني، أفادكم الله.","title":"حكم نكاح أخت الأخت من الرضاعة ونكاح الأخ لأحدى أخواتها","answer":"الجواب: إذا كنت رضعت -أيها السائل- من أمها، أو معها من امرأة أخرى رضاعًا كثيرًا خمس مرات فأكثر، فإنها تحرم عليك وحدك، تكون أخًا لها، ولا تحرم على إخوانك؛ لأن إخوتك ما رضعوا من أمها، ولا ارتضعوا من امرأة ارتضعت منها؛ فيكونوا أجانب، ولا حرج عليهم في نكاحها، ونكاح أخواتها. أما أنت فلا، إذا كنت رضعت من أمها، أو من امرأة غير أمها أرضعتكما جميعًا أنت وإياها؛ فإنك تكون أخًا لها إذا كان الرضاع خمس رضعات، وكان في الحولين، كان رضاعك من أمها وأنت في الحولين، وأما إخوتك فلا لا بأس عليهم أن ينكحوها، أو ينكحوا أخواتها. وهكذا أنت إذا كنت رضعت معها من امرأة أخرى؛ فلك أن تنكح أخواتها من شئت من أخواتها، أما إذا كنت رضعت من أمها؛ فإنك تكون أخًا لها ولأخواتها جميعًا من أمها وأبيها، إذا كنت رضعت من أمها من لبن أبيها؛ صارت أخواتها أخوات لك من أبيها وأمها جميعًا دون إخوتك، نعم.","link":"https://binbaz.org.sa/fatwas/13667/حكم-نكاح-اخت-الاخت-من-الرضاعة-ونكاح-الاخ-لاحدى-اخواتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65902.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":15172,"question":"هذا رسالة وردتنا من عبدالله حسين بن علي من الطائف من الشرقية، شارع عكاظ، يقول فيه: لدي سؤال وهو كما يلي:أفيدكم أنني رضعت على ابنة عمي أكثر من الرضاعة الشرعية بكثير جدًا، فأصبحت أخًا لها بالرضاع، والسؤال هو: هل يجوز لي أن أتزوج من إحدى أخواتها؟ وهل يجوز لأخي أيضًا أن يتزوج من إحدى أخواتها؟ علمًا بأن لأختي هذه -من الرضاعة يعني- أختان في سن الزواج؟أفيدوني، أفادكم الله.","title":"حكم نكاح أخت الأخت من الرضاعة ونكاح الأخ لأحدى أخواتها","answer":"الجواب: إذا كنت رضعت -أيها السائل- من أمها، أو معها من امرأة أخرى رضاعًا كثيرًا خمس مرات فأكثر، فإنها تحرم عليك وحدك، تكون أخًا لها، ولا تحرم على إخوانك؛ لأن إخوتك ما رضعوا من أمها، ولا ارتضعوا من امرأة ارتضعت منها؛ فيكونوا أجانب، ولا حرج عليهم في نكاحها، ونكاح أخواتها. أما أنت فلا، إذا كنت رضعت من أمها، أو من امرأة غير أمها أرضعتكما جميعًا أنت وإياها؛ فإنك تكون أخًا لها إذا كان الرضاع خمس رضعات، وكان في الحولين، كان رضاعك من أمها وأنت في الحولين، وأما إخوتك فلا لا بأس عليهم أن ينكحوها، أو ينكحوا أخواتها. وهكذا أنت إذا كنت رضعت معها من امرأة أخرى؛ فلك أن تنكح أخواتها من شئت من أخواتها، أما إذا كنت رضعت من أمها؛ فإنك تكون أخًا لها ولأخواتها جميعًا من أمها وأبيها، إذا كنت رضعت من أمها من لبن أبيها؛ صارت أخواتها أخوات لك من أبيها وأمها جميعًا دون إخوتك، نعم.","link":"https://binbaz.org.sa/fatwas/13667/حكم-نكاح-اخت-الاخت-من-الرضاعة-ونكاح-الاخ-لاحدى-اخواتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65902.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":15233,"question":"أيضًا وردتنا رسالة بعث بها أحد السادة المستمعين، يقول مرسلها إبراهيم عبدالواحد محمد، إخوتي في الله، أرجو أن أتقدم لكم بسؤالي هذا، وأرجو شاكرًا ومقدرًا أن يصلني الرد، إما عبر الإذاعة أو إرسالًا، يقول سؤالي: فهو أن والدتي -رحمها الله- توفت، وتركت طفلًا صغيرًا حملته خالتي، وقد كانت متزوجة، ولكنها لم تلد قط، يقول: وقد درت عليه لبنًا ورضع من ثديها، وبعد.الشيخ: أعد.المقدم: يقول أما سؤالي: فهو أن والدتي -رحمها الله- توفت وتركت طفلًا صغيرًا حملته خالتي، وقد كانت متزوجة، ولكنها لم تلد قط، قد درت عليه لبنًا ورضع من ثديها، وبعد مرور أكثر من ثلاث سنوات شاء الله أن تحمل وتنجب طفلة، أولًا: ما هو حكم هذا الرضيع من هذه المولودة، هل يصح الزواج منها؟ ثانيًا: هل تحل لإخوانه من أمه؟أفيدونا، جزاكم الله عنا خير الجزاء.الشيخ: أولًا ماذا؟المقدم: يقول: أولًا: ما هو حكم هذا الرضيع أو الترضيع من هذه المولودة؟ يعني حكم رضاع هذه البنت هل يصح الزواج منها؟ثانيًا: هل تحل لإخوانه من أمه؟","title":"حكم الرضاع ممن درت لبنًا مع أنها لم تلد","answer":"الجواب: السؤال فيه إشكال، لكن هذا الرضاع الذي حصل من هذه المرأة من خالة الطفل رضاع شرعي، ما دام درت عليه تكون أمه، وليس من شرط ذلك أن تكون قد حملت.  الصواب: أن درها يؤثر، ولو لم يسبق حمل، هذا هو الصواب؛ لأن الله أطلق قال: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ [النساء:23] فإذا أرضعته مما در لها فهي أمه، وجميع أولادها إخوة لهذا الرضيع، إخوة له، سواء قبله أو بعده، وهذه المرأة التي أرضعت ثم حملت وولدت هذا ولد جديد أخ للرضيع، وهكذا أولادها بعد ذلك، وأخواتها خالاته، وإخوانها أخواله، وأبوها جده، وزوجها أبو هذا الرضيع، ولو كانت لم تحمل إلا بعد ذلك؛ لأن وطأه لها من أسباب درها باللبن. فيكون هذا الطفل الرضيع ولدًا لها، وولدًا لزوجها، وأخًا لأولادها الذين جاؤوا بعد ذلك، نعم، إذا كان الرضاع خمس مرات فأكثر، إذا كان الرضاع الذي درت به خمس مرات فأكثر، وكان الطفل في الحولين، يعني: أرضعته قبل أن يتجاوز الحولين، نعم.\nالمقدم: يعني: لا يختلف الرضاع من حيث كانت ولدته.\nالشيخ: أبد، ما يختلف، سواء كان عن حمل، أو عن وطء، أو درت من دون حمل، ولا وطء، تكون أمه، لو كانت امرأة بكر ما تزوجت أصلًا، ثم درت على إنسان تكون أمًا له، ويكون أبوها جده، ويكون إخوانها أخواله وأعمامها أعمامه، وهكذا، ما هو بشرط أن يكون هناك زوج وحمل ما هو بشرط، الصحيح أنه ليس بشرط، نعم.\nالمقدم: إذًا اشتراط الحولين هل هو للمولود أو للوالدة؟\nالشيخ: للمولود. لا بد يكون المولود دون الحولين؛ لحديث: لا رضاع إلا في الحولين لا رضاع إلا ما فتق الأمعاء، وكان قبل الفطام إنما الرضاعة من المجاعة فالحولان للطفل الرضيع، نعم.","link":"https://binbaz.org.sa/fatwas/13746/حكم-الرضاع-ممن-درت-لبنا-مع-انها-لم-تلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_673/nour_67307.mp3","categories":["الرضاع"]},{"id":15237,"question":"نبدأ أولًا برسالة (ح. م. ع) من جرش، مخيم غزة، يقول: امرأة أرضعت صبية، وهذه البنت ابنتها حقيقية، ثم إن هذه المرأة قد جف حليبها، وانقطع إلى الآخر، ودر لها حليب آخر أرضعت به طفلة ثانية، وهذه الطفلة مجاورة لهم في المنزل، فهل زوج المرأة هنا يعتبر أبًا للطفلة الثانية؟ ونرجو التدليل على ذلك، وفقكم الله.","title":"من أرضعت طفلة فإن صاحب اللبن يكون أباً لها","answer":"الجواب:  بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله نبينا محمد وعلى آله وأصحابه والتابعين، أما بعد: فإن الله سبحانه بين أن الرضاعة يحصل بها الأمومة، وتحصل بها الأخوة؛ لما ذكر المحرمات قال سبحانه في سورة النساء: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23] وقال النبي ﷺ: يحرم من الرضاع ما يحرم من النسب. فالتي أرضعت طفلة، ثم جف ضرعها، ثم أرضعتها بما در لها من اللبن تكون أمها، ويكون صاحب اللبن هو أباها، ولا يؤثر الانقطاع كونه انقطع اللبن، ثم عاد لا يؤثر، فإن صاحب اللبن هو أبو البنت التي حدث اللبن بأسبابها، فهي أم الأولى وأم الثانية، أم الأولى نسبًا ورضاعًا، وأم الثانية من الرضاعة إذا أرضعتها خمس رضعات أو أكثر، وهي في الحولين الرضيعة، إذا كانت الرضيعة في الحولين وأرضعتها هذه المرأة خمس رضعات أو أكثر، فإنها تكون أمها، ويكون صاحب اللبن الذي هو زوجها يكون أبًا للرضيعة، ويكون إخوانها أخوالًا لها، وأخواتها خالات لها، وهكذا كالنسب؛ لقول المصطفى -عليه الصلاة والسلام-: يحرم من الرضاع ما يحرم من النسب نعم.","link":"https://binbaz.org.sa/fatwas/13732/من-ارضعت-طفلة-فان-صاحب-اللبن-يكون-ابا-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_673/nour_67301.mp3","categories":["الرضاع"]},{"id":15249,"question":"وأول سؤال نطرحه على فضيلته ورد إلينا من الأخ المستمع حسن عبدالجواد، مصري الجنسية، يقول في سؤاله: لي طفل رضيع، ولنا جيران مسيحيو الديانة، وأحيانًا تحضر زوجة جارنا وهي مسيحية، وتقوم بإرضاع الطفل في حال غياب أمه عنه، فما الحكم في هذه الحالة، وهل يصبح أولادها إخوة لابني أم لا؟","title":"حكم الرضاع من امرأة نصرانية","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الرضاع لا يشترط فيه الإسلام، فإذا أرضعت النصرانية أو اليهودية أو غيرهما من الكافرات طفلًا مسلمًا، فإنها تكون أمه من الرضاعة إذا ثبت أنها أرضعته خمس رضعات أو أكثر في مجلس أو مجالس.  والرضعة: أن يمسك الثدي الطفل، ويمتص اللبن حتى يصل إلى جوفه، ثم يطلق الثدي، ثم يعود إلى الثدي بعد ذلك فتكون رضعة ثانية، وهكذا، فإذا أمسك الطفل أو الطفلة الثدي وامتص اللبن، وذهب إلى جوفه، ثم أطلقه منتقلًا إلى الثدي الآخر، أو مستريحًا، ثم عاد إلى الرضاعة، فارتضع من المرأة مرة ثانية، وامتص اللبن حتى، وصل إلى جوفه، ثم أطلقه، هذه ثنتان، ثم هكذا حتى يكمل خمس رضعات، أو في مجالس، أو في أيام، المهم أنه لا بد من خمس رضعات فأكثر، حال كون الطفل في الحولين؛ لما ثبت في الحديث الصحيح عن رسول الله -عليه الصلاة والسلام-: «أنه أمر سهلة بنت سهيل أن ترضع سالمًا خمس رضعات» وفي الصحيح من حديث عائشة -رضي الله عنها- قالت: «كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات فتوفي النبي ﷺ والأمر على ذلك» رواه مسلم في صحيحه و الترمذي في جامعه، وهذا لفظه. فهذان الحديثان وما جاء في معناهما يدلان على أنه لا بد من خمس رضعات أو أكثر. وفي الحديث الآخر: لا رضاع إلا في الحولين يدل على أنه لا بد من كون الطفل في الحولين، فإذا تم الشرطان فإن المرضعة تكون أمًا للرضيع، وإن كانت كافرة، ويكون أولادها إخوة له، وإخوانها أخوالًا له، وهكذا مثل إرضاع المسلمة، نعم.\nالمقدم: أي رضاع وعمر الطفل فوق السنتين لا يؤثر؟\nالشيخ: لا يؤثر إذا كان الطفل قد جاوز السنتين، فإن إرضاعه لا يؤثر، في الحديث الآخر: لا رضاع إلا ما فتق الأمعاء، وكان قبل الفطام، لا رضاع إلا في الحولين وكلاهما صحيح. وفي الصحيحين من حديث عائشة: إنما الرضاعة من المجاعة فالصواب: أن التأثير للرضاع لا بد أن يكون في الحولين، هذا هو الصواب الذي عليه جمهور أهل العلم، نعم","link":"https://binbaz.org.sa/fatwas/13747/حكم-الرضاع-من-امراة-نصرانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_670/nour_67001.mp3","categories":["الرضاع"]},{"id":15274,"question":"هذه رسالة مقدمة من السائل خليل زيدان جاسم، من العراق، محافظة الموصل، يقول: إذا أخذ الطفل دواء ممزوجًا بحليب امرأة أخرى غير أمه، وكرر هذه العملية أكثر من خمس أو ست مرات، فهل يأخذ هذا حكم الرضاع الشرعي؟","title":"ما حكم حليب الرضاع إذا مزج بالدواء؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، وصلى الله وسلم وبارك على عبده ورسوله نبينا محمد وعلى آله وأصحابه ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد: فلا ريب أن الرضاع يحرم بشرطه الشرعي، وهو أن يكون ذلك خمس رضعات معلومات فأكثر، في الحولين، فإذا مزج الحليب بشيء آخر من الأدوية فإنه يؤثر أثره المعروف، فإذا كان خمس مرات أو أكثر حال كون الطفل في الحولين، فيكون له حكم من ارتضع خمس رضعات فأكثر، إذا كان الحليب له أثره، يعني: وتحقق أنه حليب، وصل إلى جوفه، مع هذا الدواء، أو مفردًا كل ذلك لا يغير من الحكم شيئًا، فإن العلماء قد نصوا على أن ما يحلب للطفل ويسقى إياه بمثابة ما يرتضعه من ثدي المرأة، فله حكم الرضاع إذا علم ذلك، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13775/ما-حكم-حليب-الرضاع-اذا-مزج-بالدواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67501.mp3","categories":["الرضاع"]},{"id":15382,"question":"تقول: ما الحكم -حفظكم الله- فيمن تتجاوز العامين في إرضاع طفلها؟ وهل لذلك أثر عليه أو عليها؟","title":"ما حكم إرضاع الولد أكثر من حولين؟","answer":"الجواب: يجوز الزيادة على الحولين، إذا دعت الحاجة، الواجب إرضاعه حولين، كما قال الله سبحانه: وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَنْ يُتِمَّ الرَّضَاعَةَ [البقرة:233] فإذا كان لا يأكل، ويحتاج إلى رضاعة بعد الحولين فلا بأس، ترضعه حتى يستغني بالأكل، نعم.","link":"https://binbaz.org.sa/fatwas/13886/ما-حكم-ارضاع-الولد-اكثر-من-حولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56713.mp3","categories":["الرضاع"]},{"id":15455,"question":"يقول في سؤاله الأول: تزوجت من ابنة خالتي، ولي منها طفلان، وقد علمت الآن أنني قد رضعت مع خالي الذي هو أصغر من أمها، حتى بلغت الفطام، فما العمل الآن في زوجتي هذه؟أفيدونا، بارك الله فيكم.","title":"حكم من تزوج بامرأة ثم تبين أنه رضع من جدتها","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: إذا كان الرضاع المذكور ثابتًا بشهادة الثقات أو الثقة من النساء، أو الثقة من الرجال، على أنك ارتضعت مع خالك من أم خالك، أو أم المرأة التي تزوجتها، فإنك بهذا تكون خالها أيضًا؛ لأنك ارتضعت من جدتها التي هي أم خالك وأم زوجتك، فإذا كان رضاعًا كاملًا خمس مرات فأكثر، فإنها تكون بنت أختك، ويبطل النكاح، ونسأل الله أن يعوض كلًا منكما خيرًا من صاحبه. أما الذرية فذريتك لاحقون بك؛ لأن الوطء باعتقاد النكاح الشرعي، وأنتم معذورون للجهل، فالأولاد أولادك وأولادها ولا حرج عليكما فيما مضى، والمستقبل تفارقها؛ لأنها صارت حينئذٍ بنت أختك، وأنت أخو أمها، نعم. المقدم: لو قدر وفرضنا مثل هذه الحالة وتوفي الزوج قبل أن يعلم هذا الوضع فهل ترث الزوجة؟\nالشيخ: لو توفي ثم بان أنه بهذه المثابة ما يكون زوج يكون النكاح باطل، وليس بينهما توارث.\nالمقدم: ليس بينهما توارث.\nالشيخ: لا ما فيه توارث. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13977/حكم-من-تزوج-بامراة-ثم-تبين-انه-رضع-من-جدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68701.mp3","categories":["الرضاع","المحرمات من النساء","مبطلات النكاح"]},{"id":15463,"question":"وأول سؤال نطرحه على فضيلته ورد إلينا من المستمع أبو بكر شعيب عثمان، سوداني الجنسية، مقيم في جدة، يقول: هل يجوز للرجل أن يتزوج بمهر ابنته؟ أو يتفق مع رجل آخر كل واحد منهما يأخذ بنت الثاني زوجة له بدون مهر أم لا؟ وماذا يسمى هذا في الشرع؟","title":"حكم أخذ الوالد من مهر ابنته وحكم نكاح الشغار","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، وخيرته من خلقه، نبينا وإمامنا وسيدنا محمد بن عبدالله، وعلى آله، وأصحابه، ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد: فلا حرج في أن يتزوج الرجل من مهر ابنته؛ لقول النبي ﷺ: أنت ومالك لأبيك وقوله ﷺ: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم فإذا أخذ من مهرها ما لا يضرها، ودفعه في زوجة له، فلا حرج، لكن لا يضرها، بل يدع لها شيئًا ينفعها عند زوجها، ويغنيها عن الحاجة إلى الغير، ويكون سببًا لوئامها مع زوجها، وبقائها مع زوجها، هذا هو الذي ينبغي؛ لقول النبي ﷺ: لا ضرر ولا ضرار فلا يضرها، ويشق عليها، ولا يكون سببًا لفراقها من زوجها بأخذه مهرها، ولكن لا حرج أن يأخذ منه شيئًا لا يضرها، فيستعين به في حاجاته، يجعله مهرًا لزوجة، أو بغير ذلك. أما المسألة الثانية وهي كونه يزوج ابنته على شخص آخر ليزوجه ابنته هذا لا يجوز، وهذا يسمى شغارًا في الإسلام، والنبي ﷺ قال: لا شغار في الإسلام ونهى عن الشغار في أحاديث كثيرة، قال -عليه الصلاة والسلام-: والشغار أن يقول الرجل: زوجني ابنتك وأزوجك بنتي أو زوجني أختك وأزوجك أختي هذا هو الشغار، وهو حرام وفاسد، وهو أن يشرط كل واحد منهما نكاح الأخرى كبنته أو أخته أو بنت أخيه، سواء كان هذا له أو لولده أو لابن أخيه، ونحو ذلك، هذا كله لا يجوز، والصحيح أيضًا أنه لا يجوز، ولو سمي مهرًا، حتى ولو سمي مهرًا.  وقد خالف في هذا من خالف من أهل العلم، وقالوا: إذا سمي لكل منهما مهر العادة، وتراضتا بذلك، فلا بأس، ولكن هذا قول مرجوح، وليس بصواب. والصواب: أنه متى وقع الشرط بينهما فإن المهر لا يحل ذلك سموا مهرًا أو لا؛ لأن الرسول ﷺ نهى عن الشغار، ولم يستثن، ولم يقل: إلا أن يكون لهما مهر، وما جاء في حديث ابن عمر في تفسير الشغار أنه ليس بينهما صداق فهو من كلام نافع، ليس من كلام النبي ﷺ، بل هو من كلام الراوي نافع، وكلامه ليس بحجة، الحجة في كلام النبي ﷺ، والنبي ﷺ لم يفصل بين الشغار الذي فيه مهر، والشغار الذي لا مهر فيه، ويدل على هذا ما رواه أحمد و أبو داود بإسناد جيد عن معاوية : \"أنه كتب إليه أمير المدينة، وذكر له أن بعض رجال قريش تزوج امرأة وجعل لها مهرًا، وتزوجها شغارًا، فكتب إليه معاوية  يقول له: فرق بينهما، فإن هذا هو الشغار الذي نهى عنه النبي \" ولم يلتفت معاوية إلى المهر، وهذا هو الصواب؛ لأن العلة موجودة، ولو فيه مهر، وهذه العلة هي أن هذا الشرط يفضي إلى ظلم النساء، وإلى استحلال فروجهن من غير حق، وإلى النزاع الكثير والخصومات بين الطرفين، وإلى تزويجهن بدون إذنهن، وهذه كلها نتائج وثمرات لهذا العقد الفاسد، وهي ثمرات خبيثة، ونتائج رديئة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13989/حكم-اخذ-الوالد-من-مهر-ابنته-وحكم-نكاح-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_701/nour_70104.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":15501,"question":"هذا السائل محسن صابر عبداللطيف، مصري يعمل بالطائف، يقول: لقد تزوجت من فتاة هي ابنة خالي، ولكنها رضعت مع أحد إخوتي الأصغر مني، ورضع معها أربع مرات رضعات، مشبعات على فترات طويلة، ولي منها أطفال خمسة، فما الحكم في هذا الرضاع؟ هل تعتبر أختًا لي أم لا؟ وما الحكم لو كان أخي هو الذي رضع من أمها وهي لم ترضع من أمي؟","title":"حكم من تزوج امرأة رضعت من أمه أربع رضعات","answer":"الجواب: أما إن كانت رضعت من أمك خمس رضعات أو أكثر؛ فإنها تكون أختًا لك والنكاح باطل، أما إن كان الرضاع أقل من خمس بأن كان أربعًا ولو مشبعات أو ثلاثًا أو أقل؛ فإنه لا يعول على ذلك؛ لما ثبت عن النبي ﷺ أنه قال لـسهلة بنت سهيل: أرضعي سالمًا خمس رضعات تحرمي عليه وثبت في صحيح مسلم عن عائشة -رضي الله عنها- قالت: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك\" خرجه الإمام مسلم في صحيحه والترمذي -رحمه الله- في جامعه، وهذا لفظه.  ولا بد أن يكون الرضاع في الحولين أيضًا، فإن كان الرضاع بعد الحولين؛ فلا تعويل عليه؛ لقوله ﷺ: لا رضاع إلا في الحولين، لا رضاع إلا ما أنشأ العظم وأنبت اللحم، وكان قبل الفطام فإذا رضعت من أمك خمس رضعات أو أكثر، وشهد بهذا ثقة من الرجال أو النساء أو أمك إذا كانت ثقة؛ فإن النكاح يكون غير صحيح، وعليك اعتزالها، والولد منها لاحق بك؛ لأنك لم تتعمد الباطل، فالولد لاحق بك، يعني: ولدها من ذكر وأنثى لاحق بك؛ لأنه نكاح شبهة، لم تعلما جميعًا أنها رضيعة؛ فالعذر قائم. أما رضاع أخيك من أمها فلا يضرك، ليس له نكاح إحدى بناتها؛ لأنه صار أخًا لبناتها، وأما أنت لا، إذا كانت أرضعته خمس رضعات أو أكثر في الحولين؛ فيكون أخًا لأولادها، ويحرم عليه أن يتزوج من بناتها، أما أنت فأجنبي إلا أن ترضع من أمك أو ترضع أنت من أمها رضاعًا شرعيًا يبلغ خمس رضعات فأكثر، نعم، في الحولين.","link":"https://binbaz.org.sa/fatwas/14033/حكم-من-تزوج-امراة-رضعت-من-امه-اربع-رضعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_702/nour_70203.mp3","categories":["الرضاع"]},{"id":15552,"question":"هذه فتاة تسأل في إحدى أسئلتها وتقول: لي عمة أخت أبي من الأم والأب، وقد أقمت عندها يوم وليلة، وأنا صغيرة، ورضعت منها أكثر من خمس رضعات، فهل يجوز لي أن أسلم على زوجها وعلى أولادها وعلى إخوان زوجها؟","title":"حكم كشف الوجه لزوج المرضعة وأولاده وإخوانه","answer":"الجواب: إذا ثبت أنها أرضعتك خمس رضعات، هي أعلم منك، إذا ثبت أنها أرضعتك خمس رضعات، أو أكثر، وأنت صغيرة في الحولين قبل الفطام، فهي أمك، وزوجها زوج أمك تكشفين له، وتكشفين لعيالها؛ لأنهم إخوانك، وأخو زوجها عمك فلا بأس، وأولادها إخوان لك، لكن لا بد من كون الرضاع خمس رضعات، لا بد أن يعرف أنها أرضعتك خمس رضعات قبل الفطام في الحولين، نعم. المقدم: حفظكم الله يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14093/حكم-كشف-الوجه-لزوج-المرضعة-واولاده-واخوانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69128.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":15580,"question":"أول رسالة في هذه الحلقة من المستمعة أم بلال، من خميس مشيط، لها عدة أسئلة في الواقع، تقول في السؤال الأول: ما هو الترجيح الفقهي للأحاديث الواردة في رضاع الكبير؟","title":"القول الراجح في حكم رضاع الكبير","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد اختلف أهل العلم في رضاع الكبير هل يؤثر أم لا؟\nوالسبب في ذلك: أنه ورد في الحديث الصحيح عن عائشة -رضي الله عنها-: \"أن النبي ﷺ أمر سهلة بنت سهيل أن ترضع سالم، مولى أبي حذيفة، وكان كبيرًا، وكان مولى لدى زوجها، فلما كبر طلبت من النبي ﷺ الحل لهذا الأمر، فأمرها أن ترضعه خمس رضعات\" فاختلف العلماء في ذلك، والصحيح من قولي العلماء: أن هذا خاص بسالم، وبسهلة بنت سهيل، وليس عامًا للناس، بل هذا خاص بهما، كما قاله غالب أزواج النبي ﷺ، وقاله جم غفير من أهل العلم، وهذا هو الصواب؛ لقوله ﷺ: لا رضاع إلا ما فتق الأمعاء، وكان قبل الفطام ولقوله -عليه الصلاة والسلام-: إنما الرضاعة من المجاعة رواه الشيخان في الصحيحين؛ ولقوله أيضًا -عليه الصلاة والسلام-: لا رضاع إلا في الحولين. فهذه الأحاديث تدل على أن الرضاع يختص بالحولين، ولا يؤثر الرضاع بعد ذلك، وهذا هو الصواب، والله -جل وعلا- ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14115/القول-الراجح-في-حكم-رضاع-الكبير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69201.mp3","categories":["الرضاع"]},{"id":15683,"question":"تسأل أختنا سؤالها الأخير في هذه الحلقة، وتقول: ما رأيكم إذا كان الزوج لا يصلي، أو الزوجة لا تصلي، والزوج يصلي، ما الذي على من يصلي والحال ما ذكر؟جزاكم الله خيرًا.","title":"حكم نكاح من لا يصلي","answer":"الجواب: إذا تزوج إنسان امرأة، ثم بان بعد الزواج أن أحدهما لا يصلي يفسخ النكاح؛ لأن من لا يصلي كافر على الصحيح من أقوال العلماء، ولو لم يجحد الوجوب، ولو كان كسلًا، ترك الصلاة كفر أكبر، نسأل الله العافية في أصح قولي العلماء.\nفإذا كان لا يصلي فسخ النكاح، أو كانت هي لا تصلي وهو يصلي فسخ النكاح.\nأما إن كانا لا يصليان جميعًا، فالنكاح صحيح، كنكاح سائر الكفرة.\nأما إذا كان أحدهما يصلي، والآخر لا يصلي، فإنه يفسخ النكاح حتى يتوب من لا يصلي، وإذا تاب ورجع جدد النكاح له عليها إذا رضيت بذلك.\nوإن كانت هي التي لا تصلي فإذا تابت ورجعت جدد لها النكاح عليه إذا رغب في ذلك، والدليل على هذا قول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة مع أدلة أخرى في ذلك، نعم. المقدم: سنعود إلى أسئلتك الباقية يا أخت (ج. ع) من الجمهورية اليمنية في حلقة قادمة -إن شاء الله تعالى-.","link":"https://binbaz.org.sa/fatwas/14234/حكم-نكاح-من-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57204.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":15811,"question":"يسأل سماحتكم فيقول: متى يكون الرضاع محرمًا بالخمس؟ ومتى يكون محرمًا في رضعة واحدة؟جزاكم الله خيرًا.","title":"شروط الرضاع المحرم","answer":"الجواب: الرضاع لا يكون محرماً إلا إذا كان خمس رضعات حال كون الطفل في الحولين، أما إذا كان الرضاع أقل من خمس، أو كان بعد أن تجاوز الطفل الحولين، فهذا لا أثر له، ولا يعتبر محرمًا، فلا بد من شرطين:\nأحدهما: أن يكون الطفل في الرضاع ما أكمل الحولين.\nوالشرط الثاني: أن تكون الرضعات خمسًا، لا أقل لمجيء الأحاديث بذلك؛ لقوله ﷺ: لا رضاع إلا في الحولين والله سبحانه يقول: وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ[البقرة:233] ولقوله ﷺ لـسهلة بنت سهيل: أرضعي سالمًا خمس رضعات تحرمي عليه ولما ثبت في الصحيح أن عائشة -رضي الله عنها- قالت: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك\" يعني: توفي النبي ﷺ والأمر على هذا الحال لم ينسخ ولم يغير، خمس معلومات ثابتة بشهادة المرأة العدل أو الرجل العدل أو أكثر، فإذا كانت المرضعة عدلًا، واعترفت بالخمس في الحولين قبل منها، فلا بد من خمس، ولا بد من كونها في الحولين، ولا بد أن تكون المدعية لذلك امرأة عدل، يعني: ثقة، والرجل يشهد على المرأة أنها أرضعته خمسًا، وهو عدل ثقة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14399/شروط-الرضاع-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74313.mp3","categories":["الرضاع"]},{"id":15825,"question":"من جدة وصلتنا هذه الرسالة من السائلة (ف. س. س) تقول سماحة الشيخ: ما مقدار الرضاعة التي يثبت بها التحريم؟ وما هو مقدار الرضعة الواحدة؟ وهل يجب أن تكون الرضعات معلومات؟","title":"الرضاع الذي يثبت به التحريم","answer":"الجواب: الرضعات التي يحصل بها التحريم لا بد تكون خمسًا، أو أكثر معلومات، كل واحدة مستقلة، لما ثبت في الصحيح عن عائشة -رضي الله عنها- قالت: «كان فيما أنزل من القرآن: عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك» رواه مسلم في الصحيح، ورواه الترمذي، وهذا لفظه.\nوثبت عنه ﷺ أنه قال لـسهلة بنت سهيل: أرضعي سالمًا خمس رضعات تحرمي عليه.\nوقال ﷺ: لا تحرم الرضعة ولا الرضعتان فالرضاع المحرم لا بد أن يكون خمسًا أو أكثر، حال كون الرضيع في الحولين، حال كون الطفل في الحولين، كل رضعة معلومة يمص الثدي ويبلع اللبن، ثم ينفصل، هذه واحدة، ثم يعود فيرتضع ويمص اللبن ثم ينفصل، هذه ثانية، وهكذا، لا بد أن يكون يمص اللبن، ويبلع اللبن، ويعلم هذا، ثم يعود بعد هذا إلى الرضعة، إذا مص اللبن وترك الثدي لتنقل من ثدي إلى ثدي أو للتنفس والراحة هذه رضعة.\nالمقدم: يا شيخ -حفظكم الله- تكون في موقع واحد.\nالشيخ: ولو في مجلس واحد، ولو في يوم واحد، ولو في مجلس واحد، خمس رضعات بينهما فواصل، يشرب اللبن، ويتنفس، يترك الثدي، أو ينقلب من ثدي إلى ثدي، أو يستريح، أو تقوم أمه لحاجة وتعود، أو ما أشبه ذلك. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14414/الرضاع-الذي-يثبت-به-التحريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57517.mp3","categories":["الرضاع"]},{"id":16035,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين هو: مالك آدم وهب، أخونا مالك له قضية في الرضاع يقول: لي ابنة خال رضعت مع ابنها، فهل يجوز لي أن أتزوج ابنتها، علمًا بأنها في بادئ الأمر قالت: لا تدري عن عدد الرضعات، وعندما أردت أن أتزوج ابنتها قالت: هي رضعة واحدة، أرجو إفادتي بهذا مأجورين، جزاكم الله خيرًا؟","title":"شروط الرضاع المحرم","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.  الرضاع الذي يحصل به التحريم لابد أن يكون خمس رضعات أو أكثر، فإذا كانت لم تضبط الرضاع، ولم تحفظه؛ فإنه لا يحرم عليك نكاح ابنتها، ولا تكون أمًا لك، لكن ترك هذا أحسن من باب ترك المشتبه؛ لقول النبي ﷺ: دع ما يريبك إلى ما لا يريبك ولقوله ﷺ: من اتقى الشبهات؛ فقد استبرأ لدينه وعرضه والنساء كثير الحمد لله، لكن لا تحرم عليك إلا إذا كان الرضاع ثابتًا خمس رضعات، أو أكثر في الحولين، وأنت في الحولين، فإن بنتها تكون أختًا لك، وهي تكون أمًا لك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14661/شروط-الرضاع-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74801.mp3","categories":["الرضاع"]},{"id":16202,"question":"مع بداية هذه الحلقة نعود إلى رسالة الأخت (نالة. ح. ع) من المملكة، أختنا عرضنا بعض أسئلة لها في حلقة مضت، وبقي لها في هذه الحلقة بعض الأسئلة: في أحد أسئلتها تقول: رضع ابن عم والدتي مع خالي، فأصبح أخًا له من الرضاعة، فهل يصبح ابن عم والدتي خالًا لي من الرضاعة؟","title":"صفة الرضاع المحرم وما يترتب عليه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإذا رضع ابن عمك، أو ابن عمتك مع خالك من جدتك، أم أمك؛ فإنه يكون أخًا لأمك، وأخًا لخالك، إذا كان الرضاع خمس رضعات، فأكثر، حال كونه في الحولين، والرضعة كونه يمسك الثدي، ويمتص اللبن، ويصل إلى جوفه، ثم يطلق الثدي، ثم يعود في المجلس، أو في وقت آخر حتى يكمل خمس رضعات، فهذا يكون حينئذ أخًا لأمك، وأخًا لجميع أولاد الجدة المرضعة، بشرط أن يكون في الحولين قبل أن يفطم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14860/صفة-الرضاع-المحرم-وما-يترتب-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80601.mp3","categories":["الرضاع"]},{"id":16283,"question":"إحدى الأخوات المستمعات بعثت برسالة، وضمنتها عددًا من الأسئلة، ورمزت إلى اسمها بالحروف (ع. ف) تقول: إن لي ابن عمة، توفيت والدته وهو ما زال طفلًا صغيرًا، ثم قامت جدتي أم أبي -وهي جدته لأمه- بإرضاعه مع إحدى عماتي، وسؤالي: هل هو محرم لنا، ولا يجوز لنا الزواج منه؛ لأنه رضع مع عمتي، ويكون أخًا لها، وابن أختها، مع العلم أنني أتغطى عنه حتى أعلم الحكم؟","title":"محرمية من رضع من الجدة لبنات ابنها","answer":"الجواب: إذا كان الرضاع شرعيًّا خمس مرات، أو أكثر في حال كونه طفلًا، لم يفطم قبل الحولين؛ فإنه يكون عمًّا لك، يكون أخًا لأبيك ومحرمًا لك؛ لأنها أرضعته الجدة أم أبيك، فيكون عمًّا لك، وعمًّا لأولاد أبيك كلهم، إذا كان الرضاع خمس رضعات، أو أكثر، في الحولين قبل أن يفطم، أما إن كان الرضاع أقل، أو بعد فطامه؛ فلا عبرة به، ولا يؤثر، ولا يكون عمًا لك، نعم. المقدم: جزاكم الله خيرًا، إذًا: عليها أن تتأكد من تفاصيل الرضاع وحينئذٍ .....؟ الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14967/محرمية-من-رضع-من-الجدة-لبنات-ابنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75207.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16304,"question":"من الرياض المستمع (ر. ك. ف) رسالة وضمنها هذا السؤال يقول: لي ولد، ولأخي ولد، وكل منهما يريد أن يتزوج أخت الآخر، لكنا نسمع أن البدلة لا تجوز إلا بقطع مهر، ويكون زيادة في مهر الواحدة عن الأخرى، هل هذا صحيح، أم لا؟ نرجو الإفادة والتوضيح جزاكم الله خيرًا.","title":"ماهية نكاح الشغار وحكمه","answer":"الجواب: نكاح البدل لا يجوز، ويسمى نكاح الشغار، وقد نهى عنه النبي ﷺ في عدة أحاديث، فلا يجوز نكاح البدل بالمشارطة، يقول هذا: زوجني أختك، وأزوجك أختي، أو زوجني بنتك، وأزوجك بنتي، هذا هو نكاح البدل، ويقال له: نكاح الشغار، ولو سموا مهرًا، ولو تساوى المهر، ولو اختلف المهر، ما دام فيه مشارطة لا يجوز. أما إذا خطب هذا بنت هذا، وهذا بنت هذا لنفسه، أو لأخيه، أو لولده من دون مشارطة؛ فلا بأس، الممنوع المشارطة، فأما إذا تراضوا من دون مشارطة، البنت رضيت، أو الأخت رضيت، والأخرى رضيت من دون مشارطة، بل خطب هذا، وخطب هذا؛ فلا بأس بذلك، الممنوع المشارطة، كونه يشترط ما أزوجك حتى تزوج، يعني: ما أزوجك بنتي حتى تزوجني بنتك، أو ما أزوج ولدك حتى تزوج ولدي، هذا ما يجوز، هذا هو الذي نهى عن النبي، عليه الصلاة والسلام.  فالواجب ترك ذلك، ولو سموا مهرًا متساويًا، أو أحدهما أكثر من الآخر، المهر لا يبيح الشغار، لكن لا بد من التراضي، وألا يكون هناك مشارطة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15005/ماهية-نكاح-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81006.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16311,"question":"من الرياض المستمع (ر. ك. ف) رسالة وضمنها هذا السؤال يقول: لي ولد، ولأخي ولد، وكل منهما يريد أن يتزوج أخت الآخر، لكنا نسمع أن البدلة لا تجوز إلا بقطع مهر، ويكون زيادة في مهر الواحدة عن الأخرى، هل هذا صحيح، أم لا؟ نرجو الإفادة والتوضيح جزاكم الله خيرًا.","title":"ماهية نكاح الشغار وحكمه","answer":"الجواب: نكاح البدل لا يجوز، ويسمى نكاح الشغار، وقد نهى عنه النبي ﷺ في عدة أحاديث، فلا يجوز نكاح البدل بالمشارطة، يقول هذا: زوجني أختك، وأزوجك أختي، أو زوجني بنتك، وأزوجك بنتي، هذا هو نكاح البدل، ويقال له: نكاح الشغار، ولو سموا مهرًا، ولو تساوى المهر، ولو اختلف المهر، ما دام فيه مشارطة لا يجوز. أما إذا خطب هذا بنت هذا، وهذا بنت هذا لنفسه، أو لأخيه، أو لولده من دون مشارطة؛ فلا بأس، الممنوع المشارطة، فأما إذا تراضوا من دون مشارطة، البنت رضيت، أو الأخت رضيت، والأخرى رضيت من دون مشارطة، بل خطب هذا، وخطب هذا؛ فلا بأس بذلك، الممنوع المشارطة، كونه يشترط ما أزوجك حتى تزوج، يعني: ما أزوجك بنتي حتى تزوجني بنتك، أو ما أزوج ولدك حتى تزوج ولدي، هذا ما يجوز، هذا هو الذي نهى عن النبي، عليه الصلاة والسلام.  فالواجب ترك ذلك، ولو سموا مهرًا متساويًا، أو أحدهما أكثر من الآخر، المهر لا يبيح الشغار، لكن لا بد من التراضي، وألا يكون هناك مشارطة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15005/ماهية-نكاح-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81006.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16335,"question":"رسالة وصلت إلى البرنامج من المستمع إسماعيل محمد، الأخ إسماعيل له سؤال مطول بعض الشيء يقول فيه: أنا رجل قد تزوجت من امرأة منذ سنوات عديدة، وكانت زوجتي هذه لها أخت قد تزوجت من رجل، وأنجبت منه ولدًا، فطلقها زوجها، وبعدما طلقها تزوجها أخي، فأنجبت منه بنتًا، بعد أسبوع تمامًا أنجبت زوجتي أيضًا بنتا، فتبادلت الرضاع مع بنت أختي، فابنتي رضعت من خالتها، وهكذا بالعكس، واستمرت الرضاعة لمدة خمسة أشهر، وكان حينها الولد الذي حدثتك عنه سابقًا له من العمر ست سنوات، والآن وبعد مضي العديد من السنوات تقدم هذا الولد للزواج من ابنتي التي تصغر أختها التي رضعت بست سنوات، وكل هدفي من طرح هذه القضية هو: هل يجوز زواج ابنتي من هذا الشاب، مع ملاحظة أن ابنتي هذه لم ترضع من خالتها، وهو أيضًا لم يرضع؟","title":"حكم زواج الرجل بامرأة رضعت أختها من أمه","answer":"الجواب: لا حرج في ذلك، إذا كان الواقع هو ما ذكر؛ لا حرج في ذلك؛ لأن الرضاعة تختص بمن رضعت، فالتي رضعت من أمه هي أخته لا تحل له، أما أخواتها اللاتي لم يرضعن من أمه، وهو لم يرضع من زوجتك؛ فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15028/حكم-زواج-الرجل-بامراة-رضعت-اختها-من-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75402.mp3","categories":["الرضاع"]},{"id":16406,"question":"من أحد الإخوة المستمعين اسمه بكري أحمد رسالة، وضمنها جمعًا من الأسئلة، يسأل عن مصافحة عدد من النساء، ويصفهم كالتالي: وجهوني حول مصافحة زوجة الجد هل هي جائزة، أو لا؟","title":"حكم مصافحة زوجة الجد","answer":"الجواب: مصافحة النساء إذا كن من المحارم لا بأس بها، ولا حرج فيها، وزوجة الجد من المحارم، زوجة أبيك، وجدك، وجد جدك كلهن من المحارم، وهكذا زوجة أبنائك.. زوجات أبنائك، وأبناء بناتك، وأبناء بنيك؛ كلهن من المحارم. أما زوجة أخيك فليست من المحارم لا تصافحها، وهكذا زوجة عمك وخالك، وابن عمك؛ كلهن لسن من المحارم، وهكذا جارتك وزوجة جارك كلهن من الأجناب لا تصافح، ولكن لا مانع من السلام، السلام مشروع بالكلام، السلام عليكم... وعليكم السلام! كيف حالكم؟ كيف أولادكم؟ كل هذا طيب، هذا مشروع. أما المصافحة فلا، لا تصافح إلا من كانت محرمًا لك؛ لكونها أختك، أو بنتك، أو أمك، أو عمتك، أو خالتك، أو زوجة أبيك، أو زوجة جدك، أو زوجة ابنك، أو ابن ابنك، أو ابن بنتك، هؤلاء كلهن محارم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15124/حكم-مصافحة-زوجة-الجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75505.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16416,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ع. ز. ي) يقول: أنا شاب أبلغ من العمر الثامنة عشرة، تقدمت لخطبة ابنة عمي، ولكنهم رفضوا بحجة أننا إخوان من الرضاعة، ولكني لم أرضع من أمها، وهي لم ترضع من أمي، ولكن أمها أرضعت أختي التي هي أختي من أب فقط، هل صحيح نحن أخوان من الرضاعة، أم لا؟الشيخ: أعد.المقدم: يقول: أنا شاب أبلغ من العمر الثامنة عشرة، تقدمت لخطبة بنت عمي، ولكنهم رفضوا؛ بحجة أننا أخوان من الرضاعة، ولكني لم أرضع من أمها، وهي لم ترضع من أمي، لكن أمها أرضعت أختي التي هي أخت من أب فقط، هل صحيح نحن أخوان من الرضاعة، أم لا؟ وهل يصح زواجي منها، أم لا؟ جزاكم الله خيرًا.","title":"حكم زواج الرجل من بنت امرأة أرضعت أخته","answer":"الجواب: إذا كان الواقع كما ذكرت في السؤال فلا حرج في زواجها، وإرضاع أمها لأختها لا يسري عليها، بل الزواج بها لا حرج فيه؛ لأنها ليست أختًا من الرضاعة لك، إذا كان الواقع مثلما ذكرت في السؤال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15165/حكم-زواج-الرجل-من-بنت-امراة-ارضعت-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81210.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":16430,"question":"أيضًا مصافحة الجد لزوجة ابن ابنه؟","title":"ما حكم مصافحة الجد لزوجة ابن ابنه؟","answer":"الجواب: نعم... محارمه، سواء كان من الرضاع، أو من النسب، وهكذا زوجة أبيه من الرضاع والنسب؛ كلهن محارم، نعم.","link":"https://binbaz.org.sa/fatwas/15127/ما-حكم-مصافحة-الجد-لزوجة-ابن-ابنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75506.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16521,"question":"اتفق والدي وعمي والد زوجتي عندما خطب والدي منهم أن والدي يدفع أي مبلغ يطلبه والد أي بنت يريدها ولده، ولكن لم يعجب ولده أي بنت، فطلب مني والدي أن يزوجه بشقيقتي، فوافق والدي، وذهبنا، وعقدنا القران، ودفع والدي مبلغ عشرة آلاف ريال لوالد العروسة، وكذلك جاء عمي وولده، وعقد ولده القران على أختي، ودفع أيضًا نفس المبلغ، وبعد سنة من عقد القران سأل والدي أحد العلماء، فأفاده أنه لا يجوز، ويسمى شغارًا، ولكن كل واحد يدفع لزوجته مهرًا متفقًا عليه، ودفعته لزوجتي قبل العرس بمبلغ وقدره خمسة آلاف ريال، وكذلك دفع رحيمي لزوجته نفس المبلغ، فهل هذا الزواج شغار، أم لا؟ أفيدوني جزاكم الله خيرًا.","title":"حقيقة الشغار المنهي عنه","answer":"الجواب: الشغار: هو أن يكون العقد مشروطًا بين المتعاقدين، يقول هذا: زوجني، والآخر يقول: زوجني، زوجني وأزوجك، كل واحد منهما يشترط على الآخر، فإذا كان والدك وعمك اشترطا هذا العقد؛ فهذا هو الشغار. أما إن كان والدك خطب ابنة عمك لك، ولم يشترط والدها شيئًا، أو خطب والدها منكم، ولم تشترطوا شيئًا؛ فلا حرج، أما إذا كان عن تشارط بين الوالد، وبين العم، تشارطا على أنه يزوجك ابنته، وأبوك يزوج ولده ابنته، هذا هو الشغار المنهي عنه، الرسول نهى عن الشغار -عليه الصلاة والسلام- في عدة أحاديث قال: والشغار أن يقول الرجل: زوجني ابنتك، وأزوجك ابنتي، أو زوجني أختك، وأزوجك أختي هذا هو الشغار. أما إذا خطب هذا من هذا من دون شرط، ثم خطب الآخر بعد ذلك في أي وقت من دون شرط؛ فلا يضر، ولا يكون شغارًا إلا بالمشارطة، والاتفاق، وأنتم أعلم بالواقع، فإذا كان والدك، وعمك تشارطا، واتفقا على الأمر الواقع، وأنه يزوجك، وأبوك يزوج ولده، وأنه لابد من هذا؛ فهذا هو الشغار، والعقد باطل. وعلى كل واحد منكما أن يجدد العقد إذا كان له رغبة فيها، وهي ترغب فيه؛ يجدد العقد، عقدًا شرعيًا برضاها، من دون شرط المرأة الأخرى، كل واحدة لها رضاها... رغبتها من دون شرط، فيجدد العقد بمهر جديد، وعقد جديد وشاهدين، إذا كان كل واحد يرغب في الآخر من دون شرط المرأة الأخرى، والله ولي التوفيق، نعم. المقدم: الله ولي التوفيق، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15241/حقيقة-الشغار-المنهي-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75702.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16605,"question":"المستمع طه سيد أحمد مقيم في الطائف، مصري الجنسية، بعث يسأل، ويقول: أرضعت والدتي رضيعًا، وكانت الرضاعة تنقيطًا في فم الرضيع، ولا تتعدى ثلاث رضعات، هل يجوز لأخي الأصغر أن يتزوج من بنت هذا الرضيع؟","title":"صفة الرضاع الذي يحصل به التحريم","answer":"الجواب: الرضاع الذي يحصل به التحريم لابد أن يكون خمس رضعات أو أكثر، كل رضعة مستقلة، لابد يسقى اللبن، أو يقطر في حلقه اللبن حتى يصل إلى جوفه من المرأة مرة بعد مرة، خمس مرات، أو أكثر، أو بالثدي -من الثدي يمص الثدي- أو من الثدي الصناعي يصب له في الثدي، ثم يمصه من الآلة خمس مرات فأكثر، هذا هو الذي يحصل به التحريم، ويكون الرضيع ولدًا للمرضعة، وولدًا لزوجها، وأخًا لأولادها. وإذا كان الرضاع ثلاثًا، أو أقل، أو أربعًا لم يحصل به التحريم، ولا حرج في النكاح، نكاح بنته من أولاد المرأة، أو أولاد زوجها نكاح بنت هذا الرجل، أو بنت بنته، أو بنت ولده؛ لأن هذا الرضاع ليس برضاع شرعي يحصل به التحريم، وإن ترك ذلك من باب ترك الريبة؛ فحسن؛ لأن بعض أهل العلم يحرم بالرضعات الثلاث، فإذا ترك الإنسان ذلك لقول النبي ﷺ: من اتقى الشبهات؛ فقد استبرأ لدينه وعرضه ولقوله -عليه الصلاة والسلام-: دع ما يريبك إلى ما لا يريبك وقوله ﷺ: الإثم ما حاك في نفسك، وكرهت أن يطلع عليه الناس هذا من باب الحيطة، تركه أولى، ترك الزواج أولى بعد وجود الرضاع المذكور ثلاثًا، أو ثنتين، أو واحدة، ترك النكاح أولى؛ لأنها شبهة، فبعض أهل العلم يحرم بالرضعة، ويحرم بالرضعات الثلاث؛ لإطلاق بعض الأحاديث، وإطلاق الآية الكريمة وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ [النساء:23]. لكن الصواب الذي عليه جمهور أهل العلم: أنه لابد من خمس رضعات، أو أكثر، هذا هو الصواب، في الحولين قبل أن يفطم، قبل تمام الحولين، فإن كان الرضاع بعد الحولين، وهو كبير؛ ما ينفع الرضاع، ولا يؤثر على الصحيح، وهكذا لو كان الرضاع أقل من خمس؛ لا يؤثر، ولا يحصل به التحريم، هذا هو الصواب، والله ولي التوفيق. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15332/صفة-الرضاع-الذي-يحصل-به-التحريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71606.mp3","categories":["الرضاع"]},{"id":16711,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع قابل قبل الحربي، أخونا عرضنا بعض أسئلة له في حلقة مضت، وله في هذه الحلقة سؤال فهمت منه أنه يسأل عن صفة الرضاع المحرم، فصلوا له هذا الموضوع لو تكرمتم، جزاكم الله خيرًا.","title":"صفة الرضاع المحرم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فأصل الرضاع قوله -جل وعلا- في كتابه العظيم في سورة النساء لما ذكر المحرمات، قال : وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ [النساء:23] وقال النبي ﷺ: يحرم من الرضاع ما يحرم من النسب، فالرضاعة هي أن يمتص الصبي الصغير -دون الحولين- اللبن من امرأة، هذا يقال له: رضاعة، وفي حكم ذلك إذا سقي اللبن من المرأة من دون مص يسمى رضاعة، ولا يتم التحريم إلا بخمس رضعات، لابد أن تكون خمس رضعات، يمسك الثدي، ويمتص اللبن، ثم يطلق الثدي، ثم يعود إلى الرضاعة في ذلك المجلس، أو في مجلس آخر، حتى يكمل خمس رضعات، بشرط أن يكون اللبن يصل إلى جوفه من المرأة، وأن يكون ذلك في الحولين. أما إن كان اللبن لا يصل، أو ماء ما هو لبن، أو يمصه بدون شيء، هذا ما عليه عمل، لا بد أن يمتص لبنًا من المرأة في الحولين قبل أن يفطم، قبل كمال السنتين، فإذا كان الرضاع خمس مرات في الحولين، قبل أن يفطم؛ فهذا هو الرضاع الذي يحصل به التحريم. وهكذا لو كان أكثر من خمس؛ لقول النبي ﷺ لسهلة بنت سهيل : أرضعي سالمًا خمس رضعات؛ تحرمي عليه ولقوله ﷺ: لا تحرم الرضعة، ولا الرضعتان ولقوله ﷺ: لا رضاع إلا في الحولين وقوله -عليه الصلاة والسلام-: لا رضاع إلا ما فتق الأمعاء، وكان قبل الفطام ولما ثبت في صحيح مسلم عن عائشة -رضي الله عنها- قالت: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك\" وأخرجه الترمذي بهذا اللفظ، هذا هو الرضاع، وهذا حكمه. فإن كان الرضاع أقل من خمس؛ لم يحصل به التحريم، أو كان فوق الحولين؛ لم يحصل به التحريم، أو كان الرضاع مصًا، بدون شيء، ما في المرأة لبن، لم يحصل التحريم بمجرد المص، أو كان فيها ماء؛ لأن كبيرة السن ما فيها إلا ماء، ما فيها حليب، ما يحصل به التحريم، لابد من حليب، لا بد من خمس مرات، أو أكثر، ولابد أن يكون في الحولين قبل أن يفطم الصبي، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ! مما مر علينا من رسائل هذا البرنامج حالات يعتقد أصحابها أنها من الرضاع، فمثلاً إذا أرضعت البنت أخاها، وهي لم تتزوج بعد، وتعتقد أنه قد در منها حليبًا، هل يعتبر هذا من الرضاع المحرم؟ الشيخ: نعم، نعم إذا درت البنت حليبًا صحيحًا، أو العجوز يعتبر؛ تكون أمه، خمس مرات، فأكثر، ما يشترط أن يكون ذلك عن زوج، أو عن حمل هذا الصواب، أما اشتراط أنه عن زوج، أو عن حمل، ليس عليه دليل، نعم. المقدم: جزاكم الله خيرًا، الرضاع أيضًا من الحامل سماحة الشيخ؟ الشيخ: نعم كذلك. المقدم: له نفس الحكم؟ الشيخ: نعم، نعم، ويكون أبوه صاحب الحمل. المقدم: ويكون أبوه من الرضاع صاحب الحمل، جزاكم الله خيرًا. الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/15442/صفة-الرضاع-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76101.mp3","categories":["الرضاع"]},{"id":16715,"question":"سماحة الشيخ! أنا لا أملك شيئًا من المال، والمهر عندنا غالٍ؛ فلجأت للمقايضة، أي: أعطيت أختي إلى ابن عمي، وأخذت بنت عمي بدل أختي، فما حكم هذا؟ جزاكم الله خيرًا.","title":"ما حكم أن أزوج أختي لابن عمي، وأتزوج بنت عمي دون مهر؟","answer":"الجواب: هذا لا يجوز، هذا يسمى نكاح الشغار، إذا كان بينكم مشارطة أنت تعطيه أختك، وهو يعطيك أخته؛ هذا ما يجوز، الرسول ﷺ نهى عن هذا في عدة من الأحاديث الصحيحة، أما لو خطبت بنتًا، وخطب بنتًا من دون مشارطة، بالتراضي؛ فلا بأس، أما أن تقول: زوجني وأزوجك هذا لا يجوز، لا مع البنت، ولا مع الأخت، ولا مع بنت الأخ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15478/ما-حكم-ان-ازوج-اختي-لابن-عمي-واتزوج-بنت-عمي-دون-مهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76110.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16773,"question":"القضية التالية: قضية رضاع يقول: ما رأيكم في زواج رجل من امرأة رضع مع أختها الكبرى؟","title":"حكم زواج رجل من امرأة رضع مع أختها","answer":"الجواب: إذا كان رضع من أمها خمس رضعات فأكثر، فهو أخوها، والنكاح باطل، إذا ثبت ذلك بالبينة الشرعية، أما إذا كان الرضاع أقل من خمس رضعات، أو كان فيه شك، ليس هناك من يضبطه، فالزواج صحيح، ولا يضره ذلك، والحمد لله.","link":"https://binbaz.org.sa/fatwas/15540/حكم-زواج-رجل-من-امراة-رضع-مع-اختها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82211.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":16836,"question":"يقول في سؤال آخر: إن لي زوجة أرضعتها امرأة في صغرها، وزوجتي تقول لها: هي أمي، والمرضعة تقول لها: هي ابنتي، هل تكون مرضعة زوجتي محرمًا لي؟","title":"الزوج محرم لأم الزوجة من الرضاعة","answer":"الجواب: نعم، إذا كانت أرضعتها خمس رضعات في الحولين؛ فإنها أم زوجتك، يقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب فإذا كانت ثقة المرضعة، وذكرت أنها أرضعتها خمس مرات فأكثر، خمس رضعات في الحولين، فهي محرم لك، أو شهد لها بذلك من هو معروف بالثقة من الرجال، أو النساء، أما قول البنت فقط لا يكفي، لا بد أن تكون المرضعة ثقة، وتشهد برضعات، خمس رضعات فأكثر؛ لأن الرسول ﷺ لما قالت امرأة لعقبة بن الحارث: إني قد أرضعتكم، أرضعتك وزوجتك، قال له النبي ﷺ: دعها؛ كيف وقد قيل ذلك؟. فالمقصود: أنه إذا كانت المدعية للرضاعة ثقة، وذكر أنها أرضعتها خمس رضعات فأكثر، في الحولين؛ فإنها تكون محرمًا لك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15601/الزوج-محرم-لام-الزوجة-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82402.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16852,"question":"يقول في سؤال آخر: إن لي زوجة أرضعتها امرأة في صغرها، وزوجتي تقول لها: هي أمي، والمرضعة تقول لها: هي ابنتي، هل تكون مرضعة زوجتي محرمًا لي؟","title":"الزوج محرم لأم الزوجة من الرضاعة","answer":"الجواب: نعم، إذا كانت أرضعتها خمس رضعات في الحولين؛ فإنها أم زوجتك، يقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب فإذا كانت ثقة المرضعة، وذكرت أنها أرضعتها خمس مرات فأكثر، خمس رضعات في الحولين، فهي محرم لك، أو شهد لها بذلك من هو معروف بالثقة من الرجال، أو النساء، أما قول البنت فقط لا يكفي، لا بد أن تكون المرضعة ثقة، وتشهد برضعات، خمس رضعات فأكثر؛ لأن الرسول ﷺ لما قالت امرأة لعقبة بن الحارث: إني قد أرضعتكم، أرضعتك وزوجتك، قال له النبي ﷺ: دعها؛ كيف وقد قيل ذلك؟. فالمقصود: أنه إذا كانت المدعية للرضاعة ثقة، وذكر أنها أرضعتها خمس رضعات فأكثر، في الحولين؛ فإنها تكون محرمًا لك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15601/الزوج-محرم-لام-الزوجة-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82402.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16873,"question":"هل يحل أن يتزوج شخص من فتاة رضع مع أختها التي هي من سنه، وفي عمره، هل تكون حلالًا، أم لا؟","title":"حكم زواج الرجل من فتاة رضع مع أختها","answer":"الجواب: إذا رضع من أمها رضاعًا تامًا خمس مرات فأكثر، فأولادها إخوة له، هذه وغيرها، إذا كان رضع من أمها رضاعًا كاملًا، خمس مرات، أو أكثر في حال كونه في الحولين، فجميع بنات المرضعة كلهن أخوات له، ليس له التزوج من إحداهن، سواء كانت أكبر، أو أصغر، أما لو كان رضعت من أمه هو، رضعت من أمه معه، فله أن يتزوج بعض أخواتها اللاتي لم يرضعن من أمه، وأما هو إذا كان رضع من أمها، فجميع بنات الأم المرضعة أخوات له، التي قبل الرضيعة، والتي بعد الرضيعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15631/حكم-زواج-الرجل-من-فتاة-رضع-مع-اختها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82423.mp3","categories":["الرضاع"]},{"id":16887,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات اسمها أنداء كراسًا فيما يبدو، تقول في أحد أسئلتها: إن أمي قد أرضعت عمتي شقيقة والدي، وعمتي في عمر يناهز السنة والنصف، وبلغت عدد الرضعات المشبعات خمسًا فما فوق، فهل يحق لابن عمتي أن يتزوج بي أو لا؟ جزاكم الله خيرًا، وإن حصل الزواج فهل الانفصال واجب مؤكد في هذه الحالة؟ أجيبوني أثابكم الله، وجعلنا جميعًا من عباده الصالحين.","title":"حكم الزواج من ابن الأخت من الرضاعة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإذا كان الواقع هو ما ذكرته السائلة، وأن أمها أرضعت عمتها خمس رضعات، أو أكثر، فإن ابن العمة يكون ابن أخت، وتكون العمة أختًا لك، ويكون ولدها ابن أختك، وأنت خالته؛ فالنكاح باطل حينئذ إن كنت قد أصبت في السؤال، ولا بد من عرض الموضوع على المحكمة لديكم -إذا كانت الوالدة موجودة- حتى يسألها الوالد عن حقيقة الرضاع، أو تحضر عندي إن كانت في الرياض حتى أسألها. المقصود: أنه إذا كان الواقع هو ما ذكرت: أن أمك أرضعت عمتك خمس رضعات، فأكثر؛ فإنها تكون أختًا لك، ويكون ولدها ابن أختك، وأنت خالته، والنكاح باطل حينئذ لو نكحكِ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15640/حكم-الزواج-من-ابن-الاخت-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76501.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":16919,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين وقع في نهايتها بقوله: أخوكم في الله (م. ن. ع) يسأل ويقول: لي بنت عم رضعت معي رضعة واحدة، أريد الزواج بها، فهل يجوز ذلك؟","title":"حكم زواج الرجل ممن رضعت معه رضعة واحدة","answer":"الجواب: نعم، إذا كانت لم ترضع إلا رضعة واحدة من أمك، أو أنت رضعت واحدة من أمها، فالرضعة لا تحرم، ولك أن تزوجها، لقول النبي ﷺ: لا تحرم الرضعة، ولا الرضعتان خرجه مسلم في صحيحه، ولقوله ﷺ لزوجة... أبي حذيفة: أرضعي سالمًا زوجة أبي حذيفة يقول ﷺ لزوجة أبي حذيفة بن عتبة: أرضعي سالمًا خمس رضعات؛ تحرمي عليه خمس، ولما ثبت عن عائشة -رضي الله عنها- قالت: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك\" خرجه مسلم في صحيحه، والترمذي، وهذا لفظ الترمذي، ولفظ مسلم -رحمه الله-: \"فتوفي النبي ﷺ وهي فيما يقرأ من القرآن\". فالمقصود: أن التحريم مضبوط بخمس، معلق بخمس رضعات، فإذا كانت الرضعات أقل من خمس؛ فإنها لا تحرم، الرضعة: كونه يمص الثدي، ويبتلع اللبن، ويطلق الثدي، ثم يعود إليه في المجلس، أو في مجالس أخرى خمس مرات، هذه الرضعة، أما إن كان أمسك الثدي، لكن لا يجزم أنه حصل لبن، أو ما حصل لبن، ما يعتبر، أو يشك هل كمل خمسًا، أو ما كمل خمسًا؛ لا يعتبر، لابد من خمس معلومات يقين، كل رضعة فيها لبن يصل إلى جوفه في الحولين قبل أن يفطم. فإذا كانت أقل من خمس، أو بعد الحولين؛ فإنها لا تعتبر، ولا يكون رضاعه معتبرًا، أو شك فيه، هل بلغ خمسًا، أو ما بلغ، أو ... هل وصل اللبن إلى جوفه، أم لا؟ أو كانت المرضعة ما فيها لبن، إنما تشغله فقط لئلا يصيح، تشغله بالثدي، وإلا ما فيها لبن، أو لبن ما يعتبر ماء، ما له قيمة، ما يسمى لبنًا، ما دام يتسرب منها ماء، فهذا لا يسمى لبنًا، فلا بد أن يكون لبنًا ينفع الطفل، ولا بد أن يكون خمس مرات، أو أكثر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15677/حكم-زواج-الرجل-ممن-رضعت-معه-رضعة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82601.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":16938,"question":"أحسن الله إليكم، هذه الرسالة من اليمن من السائل محمد أحمد يقول: سماحة الشيخ ما حكم من تزوج من امرأة تصلي وهو لا يصلي؟ وما حكم عكس ذلك مأجورين؟ وهل يجوز الزواج من رجل لا يصلي؟","title":"حكم الزواج بمن لا يصلي","answer":"الجواب: الصواب أنه يجدد النكاح إذا كان يصلي، وهي لا تصلي، أو العكس هي تصلي، وهو لا يصلي فإنه يجدد النكاح، هذا هو الأحوط والأفضل، لقول النبي ﷺ: بين الرجل، وبين الكفر، والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. أما إذا كانا لا يصليان جميعًا فالعقد صحيح، إذا كانا لا يصليان كلاهما فالعقد صحيح، أما إذا كانت لا تصلي، وهو يصلي، أو هو لا يصلي، وهي تصلي فلا يصح تزوجه منها إلا بعد التوبة، إذا كان لا يصلي حتى يتوب، أو هي لا تصلي حتى تتوب، وإذا عقد العقد، وهو لا يصلي، أو هي لا تصلي، واحد منهما يصلي وواحد لا يصلي يجدد العقد على الصحيح.","link":"https://binbaz.org.sa/fatwas/15711/حكم-الزواج-بمن-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58611.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":17017,"question":"المستمع يحيى غروي بعث بسؤال يقول فيه: أنا شخص لدي ابنة رضعت من امرأة وهي حامل رضعة واحدة، فهل تكفي هذه الرضعة لحصول الأحكام المترتبة على الرضاع؟ أفيدونا جزاكم الله خيرًا.","title":"حكم من رضعت من غيرها رضعة واحدة","answer":"الجواب: الرضعة الواحدة لا يحصل بها تحريم، ولا تثبت بها أحكام الرضاعة، بل وجودها كعدمها لقول النبي ﷺ: لا تحرم الرضعة، ولا الرضعتان ولقوله ﷺ لسهلة بنت سهيل لما أرادت إرضاع سالم مولى أبي حذيفة، قال لها: أرضعيه خمس رضعات تحرمي عليه ولما ثبت عن عائشة -رضي الله عنها- قالت: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك\" خرجه الإمام مسلم في صحيحه، والترمذي في جامعه، وهذا لفظ الترمذي، وهذه الأحاديث تدل على أن الرضعة الواحدة لا يحصل بها التحريم، بل لا بد من خمس رضعات معلومات في الحولين؛ لقوله ﷺ: لا رضاع إلا في الحولين وقوله -عليه الصلاة والسلام-: لا رضاع إلا ما فتق الأمعاء، وكان قبل الفطام فلا بد من شرطين للرضاع الذي يحصل به التحريم: أحدهما: أن يكون في الحولين قبل الفطام. الشرط الثاني: أن تكون الرضعات خمسًا، أو أكثر، يمص الثدي، يرضعه يرضعه، ثم يطلق الثدي بعد وصول اللبن إلى جوفه، ثم يعود فيرضع حتى يصل اللبن إلى جوفه .. هذه ثانية وهكذا، في مجلس، أو في مجالس، في يوم، أو في أيام، هذا هو الصواب من أقوال أهل العلم، وهو الذي دلت عليه الأحاديث المذكورة عن النبي ﷺ نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15804/حكم-من-رضعت-من-غيرها-رضعة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76706.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":17058,"question":"تقول: أنا رضعت من أختي مع ابنة لها، ثم إنه لما كبرت أصبحت لا أتحجب عن زوجها، فما هو توجيهكم لي الآن، جزاكم الله خيرًا؟","title":"حكم التحجب من زوج الأخت لمن رضعت من أختها","answer":"الجواب: إذا كنت رضعت من أختك خمس رضعات، أو أكثر، وأنت في الحولين صغيرة ما بعد فطمت فأنت بنتها، هي أمك وهي أختك، وزوجها محرم لك؛ لأنك ابنته من الرضاعة، إن كنت رضعت من لبنها وهي معه، وإن كان من زوج قبله فأنت ربيبة، ربيبة له، بنت زوجته إذا كان قد دخل بأمك، وجامعها واتصل بها، فالحاصل أنك بنت له إذا كان اللبن لبنه، أو ربيبة له إذا كنت رضعت من لبن زوج قبله. إذا كان الرضاع خمس رضعات، أو أكثر حال كونك في الحولين قبل أن تفطمي، أما إن كان الرضاع أقل من ذلك، فلا، لست محرمًا له، بل أنت أخت زوجته، ولا تكوني محرمًا له إلا إذا كان الرضاع كاملًا خمس رضعات أو أكثر حال كونك في الحولين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15850/حكم-التحجب-من-زوج-الاخت-لمن-رضعت-من-اختها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_721/nour_72104.mp3","categories":["الرضاع"]},{"id":17163,"question":"من تبوك رسالة بعث بها المستمع: سالم مسلم البياضي، الأخ سالم يسأل ويقول: حدثونا لو تكرمتم عن نكاح الشغار، وعن حكمه، وما حكم إكراه البنات عليه؟ جزاكم الله خيرًا.","title":"تعريف الشغار وحكم إكراه البنات في الزواج","answer":"الجواب: نكاح الشغار هو أن يشترط الولي على الآخر نكاح بنته، أو أخته إذا أراد تزويجه على بنته، أو أخته، فيقول: نعم أزوجك ابنتي، أو أختي بشرط أنك تزوجني ابنتك، أو أختك، أو تزوج ابني، أو ابن أخي، أو أخي، هذا هو الشغار، شرط نكاح في نكاح، الرسول نهى عن هذا -عليه الصلاة والسلام- نهى عن الشغار، ولو كان فيه مهر. فالواجب الحذر من ذلك، فالتزويج لا يكون بالشرط، يكون بغير شرط، تزوجه إذا رغبت فيه ورضيت المرأة تزوجه من دون شرط نكاح آخر، فشرط النكاح .... يسمى الشغار، فإذا قال: أزوجك ابنتي، أو أختي، أو بنت أخي على شرط أنك تزوجني، أو تزوج ولدي، أو أخي بنتك، أو أختك، أو بنت أخيك، أو نحو ذلك، هذا هو الشغار، لا يجوز، والنكاح باطل على الصحيح. المقدم: وما حكم إكراه البنات؟ الشيخ: أما إكراه البنات فلا يجوز، يقول النبي ﷺ: لا تنكح الأيم حتى تستأمر والأيم: الثيب التي قد تزوجت ولا تنكح البكر حتى تستأذن قالوا: يا رسول الله، وكيف إذنها؟ قال: أن تسكت. فلا يجوز تزويج النساء إلا برضاهن حتى من الأب، حتى الأب لا يكرههن، لابد... الحق لهن، والحاجة لهن، فلابد من مشاورة البنت، ثيبًا كانت أو بكرًا، فإن رضيت وإلا فلا تزوج، لا يزوجها أبوها، ولا أخوها، ولا غيرهما بالإكراه، والغصب لا، بالمشاورة وطيب النفس، فإذا رضيت فالحمد لله، وإن أبت فلا، لكن إذا كانت بكرًا يكفي سكوتها، إذا تشاور، وسكتت كفى. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15982/تعريف-الشغار-وحكم-اكراه-البنات-في-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72215.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":17299,"question":"المستمعة أم يوسف لها هذا السؤال نختم به هذه الحلقة تقول: هل يجوز للأم من الرضاعة أن تكشف وجهها عن زوج ابنتها من الرضاعة؟ وكذلك إذا كان عندها أولاد، فهل تكشف لهم؟","title":"زوج البنت من الرضاعة محرم لأمها","answer":"الجواب: نعم، زوج بنتها من الرضاعة محرم، زوج ابنتها من الرضاعة، وزوج أمها من الرضاعة محرم لها، تكشف له.","link":"https://binbaz.org.sa/fatwas/16142/زوج-البنت-من-الرضاعة-محرم-لامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59312.mp3","categories":["الرضاع","المحرمات من النساء","قضايا المرأة"]},{"id":17521,"question":"الفتاة التي لا تصلي هل يجوز الزواج بها؟","title":"حكم الزواج بالفتاة التي لا تصلي","answer":"الجواب: يجوز الزواج بها لأمثالها من الذين لا يصلون؛ لأنهم يكفرون بترك الصلاة كلهم، فتساووا في الكفر، فإن تزوجها من لا يصلي فلا حرج، أما أن يتزوجها من يصلي فالصحيح أنه لا يصح النكاح، بل عليهم التجديد تجديد النكاح إذا تابوا إلى الله ورجعوا إليه ، أما إذا كانا لا يصليان جميعًا فالنكاح صحيح وعليهما التوبة إلى الله والبدار بأداء الصلاة ونكاحهم صحيح؛ لأن الرسول ﷺ لما أسلم الناس لم يسألهم عن أنكحتهم أقرهم على أنكحتهم، لكن من تزوج امرأة يعرف أنها لا تصلي وهو يصلي لا يصح أو بالعكس هو لا يصلي وهي تصلي كذلك لا يجوز، فإذا علمت أنه لا يصلي لا يحل لها أخذه وهو كذلك لا يحل له أخذها إذا كانت لا تصلي، فإن وقع العقد وجب أن يجدد ويعاد، إذا كان كل واحد يرغب في صاحبه يجب أن يجدد إذا تاب من يترك الصلاة ورجع إلى الله فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16461/حكم-الزواج-بالفتاة-التي-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83715.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":17531,"question":"تقول السائلة أيضًا: هل يجوز للمرأة أن تقابل عم والدها؟","title":"ما حكم مقابلة المرأة عم والدها؟","answer":"الجواب: عم والدها عم لها، عم الوالد عم لها.. محرم لها، عم أبيها وعم جدها عم لها، وعم أمها وعم جدتها عم لها محرم تقابلهم وتصافحهم ولا تحتجب عنهم؛ لأن عم الإنسان عم أبيك عمك، وعم جدك عمك، وهكذا الخال، خال أمها خالها وخال جدتها خالها وخال أبيها خالها.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16451/ما-حكم-مقابلة-المراة-عم-والدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77507.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":17594,"question":"يسأل سماحة الشيخ مع الناس الذين يسألون عن زواج الشغار، توجيهكم، وكيف يكون الشغار؟","title":"صورة زواج الشغار وحكمه","answer":"الجواب: نكاح الشغار محرم ولا يجوز وباطل على الصحيح، ولو سمي فيه مهر؛ لأن الرسول نهى عنه في أحاديث كثيرة عليه الصلاة والسلام، والشغار أن يقول: زوجني وأزوجك، زوجني بنتك وأزوجك بنتي، أو زوجني بنتك وأزوجك أختي، أو زوجني أختك وأزوجك أختي، هذا يقال له: الشغار، يشترط نكاح مرأة بمرأة، هذا الشغار، يعني: اشتراط هذا أخت هذا أو بنت هذا، أو هذا بنته وهذا أخته، هذا هو الشغار، يقول النبي ﷺ لما نهى عن الشغار قال: والشغار أن يقول الرجل: زوجني بنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي هذا هو الشغار، شرط عقد في عقد، ولو سموا مهرًا. فالواجب الحذر من ذلك وعدم فعل ذلك، أما إذا خطب منه ولم يشترط شيئًا وخطب الآخر وتزوجوا لا بأس، خطب بنته والآخر خطب بنته أو أخته وتزوجوا من دون مشارطة هذا لا بأس، لا حرج ، أما بالمشارطة فهذا لا يجوز. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16529/صورة-زواج-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84114.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":17672,"question":"هذا سائل محمد طويلع يقول في هذا السؤال يا سماحة الشيخ: الإخوة في برنامج نور على الدرب لي مجموعة من الأسئلة يقول: هل يجوز للمرأة أن تصافح خال أمها؟ وهل يعتبر محرمًا لها؟","title":"محرمية خال الأم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالخال محرم، خال الأم خال الجدة محرم، خال أمك خال لك وخال أبيك خال لك، فخال أبيك وخال أمك وخال جدتك وخال جدك كلهم أخوال لك محارم. نعم.","link":"https://binbaz.org.sa/fatwas/16603/محرمية-خال-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59501.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":17759,"question":"هذه سائلة للبرنامج (العوفي ) قرية قصيبة تقول: سماحة الشيخ! هل زوجة الخال من المحارم أم لا؛ لأنني سمعت أن زوجة العم ليست من المحارم، ولكن زوجة الخال من المحارم الذي لا يجوز الزواج بها بعد وفاة زوجها أو طلاقها منه؟","title":"زوجة الخال ليست من المحارم","answer":"الجواب: زوجة الخال وزوجة العم وزوجة الأخ لسن من المحارم، إذا مات زوجها أو طلقها وخرجت من العدة؛ جاز أن ينكحها ولد أخته لا بأس، زوجة الأخ، الأخ أقرب زوجته ما هي بمحرم، المحرم زوجة الأب والجد والابن، أما زوجة الأخ وزوجة الخال وزوجة العم، فلسن محارم، بل هو أجنبي ..، زوجة خاله أجنبية، زوجة عمه أجنبية، زوجة أخيه أجنبية، ليس له أن يخلو بها، وليس لها أن تكشف له. نعم.\nالمقدم: حفظكم الله يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16729/زوجة-الخال-ليست-من-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59617.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":17760,"question":"تقول السائلة: هل يجوز لأزواج بنات أختي أن أكشف لهم وأسلم عليهم بوجهي، أم لا يجوز؟","title":"زوج بنت الأخت ليس محرمًا","answer":"الجواب: لست محرمًا لهم، أنت خالتها خالة بنات أختك، فأزواج ... ليس محرمًا لك، زوج أختك ليس محرمًا لك ولست محرمًا له، إنما هو زوج أمك زوج جدتك ما يخالف زوج بنتك ما يخالف لا بأس، أما زوج الأخت وزوج بنت الأخت لا ليس محرم.\nالمقدم: حفظكم الله يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16732/زوج-بنت-الاخت-ليس-محرما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59618.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":17950,"question":"من أسئلة هذه السائلة تقول يا سماحة الشيخ: إذا كانت المرأة عليها جنابة، هل ترضع طفلها، أم لا يجوز إلا بعد الغسل؟","title":"حكم إرضاع المرأة طفلها وهي جنب","answer":"الجواب: لا حرج أن ترضعه وهي على جنابة، لا بأس بذلك أن ترضع طفلها وهي على جنابة، لا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16957/حكم-ارضاع-المراة-طفلها-وهي-جنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59829.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":18023,"question":"المستمعة (ف. س) من الباحة بعثت برسالة وضمنتها سؤالًا مطولًا بعض الشيء عن الرضاع، تقول: أرضعت والدتي ابنة خالتي مع أخي الأكبر، ولكنه توفي وهو مولود وبعدما كبرت ابنة خالتي وتزوجت أنجبت ولداً فأرضعته والدتي معي ثم أرضعت شقيقته الصغرى مع شقيقي الأصغر مني.والسؤال هو: هل يجوز لي أن أكشف على والد أخي من الرضاع؟ وهل يجوز الكشف على أبناء خالتي الذين هم أشقاء أختنا من الرضاع وأخوال أخي من الرضاع؟","title":"حكم كشف المرأة لوالد الأخ من الرضاعة","answer":"الجواب: تكشفين للرضيع الذي هو أخوك أما أبوه ليس محرمًا لك إذا كان أجنبي ما تكشفين له، تكشفين للرضيع الذي أرضعته والدتك يكون أخًا لك من الرضاعة، وأما أبوه إذا أرضعت الأم ابنة شخص فالرضيع هو الذي أخ لك إذا كان خمس رضعات فأكثر، أما أبوه الأجنبي ليس محرمًا لك. أما لو كان ابن خالك خالك محرمًا ولو ما أرضعت أمك ابنه، خالك محرم وخال أمك وخال جدتك محرم لك، لكن إذا أرضعت أمك شخصًا من الناس فهو الذي يكون أخًا لك إذا كان الرضاع خمس رضعات في الحولين أو أكثر، أما أبوه الأجنبي سواء كان ابن عم أو ابن خال أو من الجيران ما يكون محرمًا لك؛ لأنه ليس رضيعًا هو الرضيع ولده. فالرضيع هو الذي يكون محرمًا لك، أما إخوته الذين ما أرضعتهم أمك وأبوه هؤلاء ليسوا محارم لك، المحرم الشخص الذي أرضعته أمك خمس رضعات أو أكثر في الحولين، أما إخوته الذين لم يرضعوا وهم أجناب أو أبوه أو جده فليسوا محارم لك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17067/حكم-كشف-المراة-لوالد-الاخ-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85012.mp3","categories":["المحرمات من النساء","الرضاع","قضايا المرأة"]},{"id":18149,"question":"والدتي أرضعت ابن خالتي ستة أيام، في كل يومٍ جلسة، وتقول: أخشى أنه لا يشبع في الجلسة الواحدة، هل يكون بتلك الرضعات أخًا لي؟","title":"الرضعات المحرمات خمس فأكثر","answer":"الجواب: نعم، إذا كانت الوالدة أرضعته ست مرات، فإنه يكون ابنًا لها، ويكون أخًا لك، حتى ولو خمس، لا ينقص عن خمس، الرضاع المحرم خمس فأكثر، لابد من تحقق أن اللبن ذهب إلى جوفه، ولو لم يشبع، إلى جوف الطفل، أو الطفلة، ولو لم يشبع، خمس مرات، كل واحدة منفصلة عن الأخرى، يرضع حتى يصير اللبن إلى جوفه، ثم يقطع، ثم يعود، أو ينتقل إلى الثدي الثاني، إذا تم الخمس مرات؛ صار ابنًا للمرضعة، وإذا زاد عن الخمس، فأولى وأولى، ولو لم يشبع في كل رضعة، المهم أن يرضع لبنًا يصل إلى جوفه، خمس مراتٍ أو أكثر، في الحولين، حال كونه في الحولين، فيكون ابنًا للمرضعة، وأخًا لأولادها، ذكورهم وإناثهم، ويكون أبوها جدًا له، وإخوتها أخوالًا، وأخواتها خالات. أما إن كان الرضاع ناقص عن خمس، فإنه لا يعتبر، ولا يكون الرضيع ابنًا للمرضعة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17201/الرضعات-المحرمات-خمس-فاكثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73104.mp3","categories":["الرضاع"]},{"id":18278,"question":"من جيزان الأخت: (ل. م. ح) تسأل وتقول: أخو خال أمي من الرضاعة، هل يكون محرمًا لي، وأكشف وجهي أمامه؟ أم لا يكون من المحارم؟","title":"أخو خال الأم من الرضاعة ليس محرمًا","answer":"الجواب: لا ليس من المحارم، أخو الخال ليس من المحارم، إلا إذا كان خالًا، إذا كان لك خال، مثلاً: زيد أخو أمك من الرضاعة أو من النسب، فهو خال لك أيضًا محرم لك، لكن أخوه الذي ليس برضيع لأمك، وليس خالًا لك لا يكون محرمًا؛ لأنه قد يكون له أخ أجنبي من أبيه، أو خال من الرضاع فلا يكون خالًا لك، إنما خالك الذي بينه وبين أمك رضاعة، إذا رضع من أمها أو من جدتها صار خالًا لها، فيكون خالًا لك بسبب الرضاع أو بسبب النسب، وأما أخوه الذي ليس بخال فليس خالًا لك، وليس محرمًا لك. نعم.","link":"https://binbaz.org.sa/fatwas/17327/اخو-خال-الام-من-الرضاعة-ليس-محرما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91014.mp3","categories":["الرضاع"]},{"id":18341,"question":"إحدى الأخوات المستمعات أم فيصل، تقول: لي أخ يبلغ من العمر عشرين سنة وقد رضع من زوجة خالي، وهو يأكل ويشرب ويجلس مع ابنة خالي التي رضع معها، ويذهب بها إلى المدرسة، وينفرد بها مثل أخته، ونحن لا نعلم كم عدد الرضعات التي رضعها من زوجة خالي، وما حكم جلوسها معه وانفراده بها ونحن لا ندري كم عدد الرضعات كما أسلفت؟ جزاكم الله خيرًا.","title":"حكم خلوة المرأة مع من يُشك في محرميته","answer":"الجواب: لا يتم كونه محرمًا لها ولا كونه أخًا لها إلا بإثبات الرضاعة، فلابد من إثبات أن الرضاعة خمس رضعات في الحولين، بشهادة امرأة ثقة أو رجل ثقة أو أكثر من ذلك. أما إذا كان لا يعلم عدد الرضعات وليس هناك من يشهد بعدد الرضعات التي هي معتبرة وهي خمس فأكثر؛ فإنها لا تكون أختًا له وليس له الخلوة بها، وليس له الذهاب بها وحده إلى المدرسة ولا غيرها؛ لأنه يعتبر أجنبيًا، إلا إذا ثبت أنه رضع من أمها خمس رضعات أو أكثر من ذلك، باعتراف أمها أو بشهادة الثقة العارف بذلك أو المرأة الثقة العارفة بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/17428/حكم-خلوة-المراة-مع-من-يشك-في-محرميته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_861/nour_86111.mp3","categories":["الرضاع"]},{"id":18355,"question":"إحدى الأخوات المستمعات أم فيصل، تقول: لي أخ يبلغ من العمر عشرين سنة وقد رضع من زوجة خالي، وهو يأكل ويشرب ويجلس مع ابنة خالي التي رضع معها، ويذهب بها إلى المدرسة، وينفرد بها مثل أخته، ونحن لا نعلم كم عدد الرضعات التي رضعها من زوجة خالي، وما حكم جلوسها معه وانفراده بها ونحن لا ندري كم عدد الرضعات كما أسلفت؟ جزاكم الله خيرًا.","title":"حكم خلوة المرأة مع من يُشك في محرميته","answer":"الجواب: لا يتم كونه محرمًا لها ولا كونه أخًا لها إلا بإثبات الرضاعة، فلابد من إثبات أن الرضاعة خمس رضعات في الحولين، بشهادة امرأة ثقة أو رجل ثقة أو أكثر من ذلك. أما إذا كان لا يعلم عدد الرضعات وليس هناك من يشهد بعدد الرضعات التي هي معتبرة وهي خمس فأكثر؛ فإنها لا تكون أختًا له وليس له الخلوة بها، وليس له الذهاب بها وحده إلى المدرسة ولا غيرها؛ لأنه يعتبر أجنبيًا، إلا إذا ثبت أنه رضع من أمها خمس رضعات أو أكثر من ذلك، باعتراف أمها أو بشهادة الثقة العارف بذلك أو المرأة الثقة العارفة بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/17428/حكم-خلوة-المراة-مع-من-يشك-في-محرميته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_861/nour_86111.mp3","categories":["الرضاع"]},{"id":18356,"question":"هذا السائل علي الطيب، مقيم بالمملكة العربية السعودية، يقول: رجل تم عقده على امرأة، ولم يدخل بها وتوفي هذا الرجل، فهل يجوز لابنه من بعد وفاة أبيه أن يتزوج هذه المرأة؟","title":"حكم الزواج بمن عقد عليها الأب ولم يدخل بها","answer":"الجواب: بعقد الزواج عليها حرمت على أبنائه، وعلى آبائه، ما يجوز .","link":"https://binbaz.org.sa/fatwas/17407/حكم-الزواج-بمن-عقد-عليها-الاب-ولم-يدخل-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91323.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":18369,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول أم محمد بنت معري -فيما يبدو- أختنا تسأل وتقول: أرضعت ابن أخ زوجي بعد أن استأذنت من زوجي بدافع من إلحاح أمه وأبيه؛ لأنها كانت لا تستطيع والطفل يصرخ من الجوع فأرضعته، ولكن الآن نسيت كم أرضعته، نعم يا سماحة الشيخ أنا متأكدة من أنني أرضعته ولكن هل ارتوى، هل أرضعته يوم أو أكثر؟ جميع هذه الأسئلة تراودني، وأبحث لها عن جواب،  وهذا الطفل الذي أصبح شابًا الآن يجلس معي ويعتبرني أمه، ويجلس مع أولادي وبناتي ولا أحد يشك في أنه لم يعد أخًا لهم إلا أنا، فالخوف يؤرقني كما أني لا أستطيع أن أواجهه وهو قد أمضى هذا العمر معنا على أنه ابن لنا، فماذا أصنع؟","title":"حكم الرضاع إذا لم يعلم عدده","answer":"الجواب: الواجب على المؤمن أن يتقي الله  وهكذا المؤمنة، في الرضاع وغيره، وإذا كنت لا تعلمين عدد الرضعات فهو ليس ابنًا لك، ولا يكون محرمًا لك ولا لبناتك حتى تعلمي أنه ارتضع خمس رضعات فأكثر، أما كونه ارتضع؛ لأنه يصرخ أو لأنه يحتاج، هذا لا يكفي قد يرضع مرة، ويكتفي بهذا أو مرتين أو ثلاث، فلابد من الرضاع المضبوط خمس مرات فأكثر في يوم أو في أيام؛ لقول النبي ﷺ لسهلة بنت سهيل: أرضعي سالمًا خمس رضعات تحرمي عليه، ولما ثبت عن عائشة رضي الله عنها قالت: كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات فتوفي النبي ﷺ والأمر على ذلك، وفي لفظ: وهي فيما يقرأ من القرآن رواه مسلم في الصحيح. ولقوله ﷺ: لا تحرم الرضاعة ولا الرضعتان، فعلم بذلك أن الرضعة والرضعتين وهكذا الثلاث والأربع لا يحصل بها التحريم، بل لابد من خمس متيقنة في الحولين، فإذا كنت لا تعلمين ذلك، وعندك الشك في ذلك فاعتبريه غير محرم، لا لك ولا لبناتك، وكونه يتزوج من إحداهن فيه شبهة، فينبغي أن لا يتزوج منهن بعدًا عن الريبة؛ لقوله ﷺ: دع ما يريبك إلى ما لا يريبك، من اتقى الشبهات فقد استبرأ لدينه وعرضه، نسأل الله للجميع التوفيق والهداية. نعم.","link":"https://binbaz.org.sa/fatwas/17454/حكم-الرضاع-اذا-لم-يعلم-عدده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_862/nour_86207.mp3","categories":["الرضاع"]},{"id":18381,"question":"تقول في قضية أخرى: فتاة رضعت من امرأةٍ وهي صغيرة رضعتين، وجاء ابن هذه المرأة وأراد أن يخطب هذه الفتاة، مع العلم أنها رضعت مع أخيه الأصغر منه، فهل يجوز أن تتزوج هذه الفتاة من هذا الشاب؟ أم لا؟ جزاكم الله خيرًا.","title":"حكم الزواج بامرأة رضعت من أم الزوج رضعتين","answer":"الجواب: الرضعتان لا تحرمان، يقول النبي ﷺ: لا تحرم الرضعة، ولا الرضعتان ويقول ﷺ لسهلة بنت سهيل: \"أرضعي سالمًا خمس رضعات تحرمي عليه\"، وتقول عائشة رضي الله عنها في الحديث الصحيح: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك\". فالرضعتان لا تحرمان، ولا حرج عليه في الزواج، لكن إذا ترك هذا من باب الاحتياط؛ لأن بعض أهل العلم يرى الرضعة الواحدة تحرم، من باب ترك المشتبه حسن، يقول النبي ﷺ: دع ما يريبك، إلى ما لا يريبكإذا ترك هذا احتياطًا، وبعدًا عن الشبهة؛ فلا حرج، هذا حسن طيب. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17438/حكم-الزواج-بامراة-رضعت-من-ام-الزوج-رضعتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73213.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":18390,"question":"أولى أسئلة هذه الحلقة من المستمع (ع. ع. ب) أخونا له جمع من الأسئلة في أحدها يقول: هل أبو الزوج من الرضاع وأجداده كأبيه من النسب؟ جزاكم الله خيرًا.","title":"هل أبو الزوج من الرضاع وأجداده كأبيه من النسب؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن أبا الزوج من الرضاع، وهكذا أجداده من الرضاع، وهكذا بنو الزوج من الرضاع كلهم كالنسب، عند عامة العلماء، ولم ينقل في ذلك خلاف يعتبر إلا خلافًا شاذًا لا يعتبر، بل الذي عليه جمهور الأئمة ومنهم الأئمة الأربعة رحمهم الله أن أبا الزوج من الرضاع كأبيه من النسب، وهكذا جده من الرضاع كجده من النسب؛ لعموم قوله جل وعلا: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ [النساء:22]، وقوله سبحانه في زوجات الأبناء وَحَلائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلابِكُمْ [النساء:23]، ولقوله ﷺ: يحرم من الرضاع ما يحرم من النسب، فكما أن الآباء آباء الزوج وأجداده من النسب محارم فهكذا من الرضاع، وهكذا زوجات البنين من الرضاع محارم كالنسب. وأما قوله سبحانه: مِنْ أَصْلابِكُمْ [النساء:23] فهذا احتراز من الأدعياء، كما قال أهل العلم، الدعي ..... الدعي كان أهل الجاهلية يدعون يتبنون أولادًا وينسبونهم إليهم، ومن ذلك زيد بن حارثة كان ﷺ تبناه، وكان ينسب إليه يقال: زيد بن محمد، فلما أنزل الله قوله جل وعلا: ادْعُوهُمْ لِآبَائِهِمْ [الأحزاب:5]، وقوله سبحانه: وَمَا جَعَلَ أَدْعِيَاءَكُمْ أَبْنَاءَكُمْ [الأحزاب:4]، دعي إلى أبيه زيد بن حارثة، أما أبناء الرضاع فهم كالنسب، وهكذا آباء الرضاع كالنسب سواءً بسواء عند الأئمة الأربعة وجمهور أهل العلم، ولم يحك أبو محمد المقدسي الموفق رحمه الله في المغني خلافًا في ذلك. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17450/هل-ابو-الزوج-من-الرضاع-واجداده-كابيه-من-النسب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73301.mp3","categories":["الرضاع"]},{"id":18420,"question":"من الأمارات العربية المتحدة مدينة العين هذه رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من هناك تقول آمنة علي: أنا امرأة -هذه رسالتها- رضعت ولدًا وبنتًا علمًا بأنه لا تصلني بهم أي قرابة، وليس هناك صلة بيننا، رضعت الولد عند ابني والبنت مع ابنتي، وتزوج الولد من البنت، وقد أخبرتهم بأن الزواج هذا لا يجوز؛ لأنهم إخوة من الرضاع، ولم يستجيبوا فما الحكم، وهل أديت ما علي في ذلكم الزواج؟ جزاكم الله خيرًا.","title":"حكم الزواج ممن رضعت معه من غير أمه","answer":"الجواب: إذا كنت أرضعت الذكر والأنثى المذكورين خمس رضعات حال كونهما في الحولين فهما أخوان كما قلت، إذا كنت أرضعت كل واحد منهما خمس رضعات أو أكثر حال كونهما في الحولين فهما أخوان ولا يجوز للذكر أن ينكح الأنثى المذكورة؛ لأنه أخوها. والرضعة: أن يمسك الثدي ويمتص اللبن ثم يترك ثم يعود حتى يكمل خمسًا في مجلس أو مجالس، في يوم أو أيام، فإذا كان الطفل رضع منك خمس رضعات في كل رضعة يمص الثدي ويرتضع اللبن ثم يطلق الثدي ثم يعود في ذلك المجلس أو في مجلس آخر ويرتضع منك حتى كمل خمسًا أو أكثر فإنه ولد لك وأنت أمه من الرضاعة. وهكذا البنت إذا كانت ارتضعت منك خمس رضعات أو أكثر في كل رضعة تمسك الثدي وتمتص اللبن ويذهب إلى جوفها ثم تطلق الثدي ثم تعود بعد ذلك في مجلس أو في مجالس أخرى حتى كملت خمسًا أو أكثر فإنها بنتك وأنت أمها وكلاهما أخوان، وهما أخوان لأولادك جميعًا. وعلى من علم ذلك أن يفرق بينهما إذا كان نكحها فعلى من علم هذا أن يفرق بينهما؛ لأن نكاح الذكر لأخته من الرضاع باطل، لأن الله سبحانه حرم الأخوات من الرضاعة بنص الكتاب العزيز، وحرم ذلك نبيه ﷺ فقال: يحرم من الرضاع ما يحرم من النسب، فعلى ولاة الأمر في بلدك أن ينظروا الأمر، وعلى المحكمة أن تنظر في هذا، فإذا رأت المحكمة أنك ثقة وأن كلامك يقبل فهذا إليها فعليها أن تفرق، وإذا رأت المحكمة غير ذلك بأن رأت المحكمة أن كلامك غير مقبول لأسباب رأتها المحكمة فهذا إلى المحكمة وفي ذمة المحكمة، وفيما تراه المحكمة في بلادكم الشرعية كفاية إن شاء الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17527/حكم-الزواج-ممن-رضعت-معه-من-غير-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_864/nour_86403.mp3","categories":["الرضاع"]},{"id":18495,"question":"سماحة الشيخ! يقول السائل من الدمام: هل يجوز للوالدات أن يرضعن أولادهن أكثر من حولين كاملين؟ وإذا حصل هذا هل يؤثر على صحة الاثنين؟","title":"حكم الزيادة في الرضاع على حولين","answer":"الجواب: لا حرج في ذلك، إذا دعت الحاجة إليه، الله يقول سبحانه: وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ[البقرة:233]، هذا الواجب عليهن أن يرضعن أولادهن حولين كاملين، واجب عند الحاجة إلى هذا، إلا أن يتراضيا في فصلهما قبل الحولين، يعني: يتراضى الزوج والزوجة، يتراضيان في فطامه قبل تمام الحولين فلا بأس؛ لقوله جل وعلا: فَإِنْ أَرَادَا فِصَالًا عَنْ تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ فَلا جُنَاحَ عَلَيْهِمَا[البقرة:233] إذا أرادا الفصال، يعني: (الفطام عن تراض منهما وتشاور) فلا حرج، وإلا فالواجب أن ترضعه حولين. أما الزيادة فتكره الزيادة، إلا عند الحاجة، إذا كان الطفل ما يأكل ولا يحصل له يعني ما يغنيه عن الرضاع، لا بأس أن تزيده للحاجة، في بعض الأطفال ما يكون عنده رغبة في الطعام، ولا يشتهيه، ويحتاج إلى الرضاع فلا بأس، المقصود أنه إذا دعت الحاجة إلى الزيادة لا حرج. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم، وفي علمكم ونفع بكم الإسلام والمسلمين.","link":"https://binbaz.org.sa/fatwas/17587/حكم-الزيادة-في-الرضاع-على-حولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78526.mp3","categories":["الرضاع"]},{"id":18546,"question":"إذا كان لدي خالات، ولهن أبناء وبنات، وأرضعت من إحداهن الرضعات المعتبرة شرعًا، وفي الحولين، ولكن ابنها لم يرضع من والدتي، فهل أنا أخ له ولجميع إخوانه وهو كذلك؟ أم أننا أخوين لبعض دون إخوتي وإخوته، بحكم أن الرضاع حصل بيننا نحن الاثنين فقط؟جزاكم الله خيرًا.","title":"الأحكام التي تثبت بالرضاع","answer":"الجواب: إذا ارتضع الإنسان من خالته رضاعًا كاملًا خمس مرات فأكثر في الحولين؛ فجميع أولادها اخوة له، الذي معه والذي قبله والذي بعده، إذا ارتضع الإنسان من خالته، أو من عمته، أو من غيرهما رضاعًا كاملًا خمس مرات أو أكثر حال كونه في الحولين قبل أن يفطم؛ فإن هذا الرضاع رضاع شرعي يكون ولدًا لها، ويكون أخًا لأولادها كلهم كبيرهم وصغيرهم، الذي رضع معه والذي قبله والذي بعده، لكن لا يكونوا إخوة لإخوانك الذين ما رضعوا، أخوة لك فقط وأنت أخوهم؛ لأنك رضعت من أمهم وهي أمك وأبوها جدك وأخواتها خالاتك وإخوتها أخوالك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17648/الاحكام-التي-تثبت-بالرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73319.mp3","categories":["الرضاع"]},{"id":18682,"question":"تسأل أختنا أيضًا وتقول: أمي أرضعت ابن خالتي، وخالتي أرضعتني، ولكنهن لا يتذكرن عدد الرضعات، فهل يجوز أن أكشف عليهم بحكم أنهم إخواني من الرضاعة ولديه أخ أكبر منه فهل يعتبر أخي أيضًا؟","title":"الشروط التي يثبت بها أحكام الرضاع","answer":"الجواب: لا يصلح أن يكون أخًا إلا بخمس رضعات معلومة، فإذا كانت الوالدة أو الخالة ليس عندها ضبط، فالرضاع لا عمل عليه، والواجب الحجاب، ولا يكون أخًا إلا إذا ثبت أن أمك أرضعته خمس رضعات فأكثر، أو أن خالتك أرضعتك أنت خمس رضعات فأكثر. فإذا ثبت أن أمك أرضعته، أو أرضعت جميع أبناء خالتك رضاعًا كاملًا خمس رضعات، أو أكثر في حال الحولين قبل أن يفطم؛ فإنه أو إخوته جميعًا يكونوا إخوة لك، فإن ثبت رضاعه منهم صار أخًا لك، إذا ثبت رضاعه خمسًا أو أكثر في حال الحولين قبل الفطام؛ فإن من رضع هذا الرضاع يكون أخًا لك سواء واحد أو أكثر. وأنت كذلك إذا أرضعتك خالتك خمس رضعات أو أكثر حال كونك في الحولين، رضاعًا معلومًا لا شك لديها فيه؛ فإنك تكونين بنتًا لها وأختًا لأولادها جميعًا، والله المستعان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17818/الشروط-التي-يثبت-بها-احكام-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87306.mp3","categories":["الرضاع","قضايا المرأة"]},{"id":18692,"question":"السائل يقول في آخر أسئلته: ما هو القول الفصل في المقدار الذي يثبت به التحريم في الرضاع؟ مع ذكر الأدلة في ذلك سماحة الشيخ.","title":"المقدار الذي يثبت به التحريم في الرضاع","answer":"الجواب: الثابت في هذا أن المقدار هو اللبن الذي يصل إلى الجوف، إذا وصل اللبن إلى الجوف في كل رضعة كفى، ولا يحدد بمقدار، متى علمت المرأة أنها أرضعته رضاعًا وصل فيه اللبن إلى جوفه خمس رضعات أو أكثر في الأوقات الخمسة فلا بأس يكون ولدًا لها، وتثبت له أحكام الرضاع، ولو كان قليلًا، إذا أرضعته وذهب اللبن إلى جوفه وأطلق الثدي، ثم أعادت رضاعه في ذلك الوقت، أو في يوم آخر، حتى كمل خمسًا، تيقن أن اللبن يروح إلى جوفه أنه يرضع رضاعة حقيقية، يذهب اللبن إلى جوفه خمس مرات في يوم، أو في أيام، أو أكثر من خمس، يكون ولدًا لها، ويكون إخوانها أخوالًا له، وأبوها جدًا له وهكذا، يثبت له حكم الرضاع لقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب. وقد دل القرآن على أصل ذلك قال تعالى: وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ[النساء:23]، فالمطلوب أن يكون وصول اللبن إلى الجوف متحققًا، تعرفه المرضعة في خمس مرات في اليوم، أو في الليلة، أو في أيام متعددة حال كونه في الحولين قبل أن يفطم، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17801/المقدار-الذي-يثبت-به-التحريم-في-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78808.mp3","categories":["الرضاع"]},{"id":18723,"question":"أسألكم لو تكرمتم عن الرضاع، هل هو بالشبعة، أم بالكرة بعد المرة ؟","title":"الضابط المعتبر في الرضعة","answer":"الجواب: ليس بالشبعة، ولكنه بالكرة بعد الكرة، إذا وصل الحليب إلى الجوف، إذا وصل الجوف ولو قليلً؛ فإنه يعتبر رضعة، فإذا مص الثدي الطفل الذي لم يبلغ الحولين إذا امتص اللبن، وذهب إلى جوفه ولو قليلًا؛ يعتبر رضعة، فإذا قطع ثم عاد وامتص اللبن حتى بلغ جوفه؛ تعتبر رضعة ثانية، وهكذا إذا قطع، ثم عاد ثالثة، وهكذا، في مجلس أو في مجالس، ولو لم يشبع. المهم أن يصل اللبن إلى جوفه، وأن تجزم المرأة بذلك، ثم يفصل انتقاله إلى ثدي آخر، أو بقطعه لأسباب أخرى، ثم يعود إلى الرضاع فيمتص اللبن ويصل إلى جوفه؛ فإن هذه رضعة ثانية وهكذا، ولا يتم الرضاع ولا يكمل إلا بخمس رضعات فأكثر؛ لما ثبت عن عائشة -رضي الله عنها- أنها قالت: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك\" خرجه الإمام مسلم والترمذي -رحمة الله عليهما- وهذا لفظه. ولما ثبت عن عائشة -رضي الله عنها- أيضًا أن النبي ﷺ أمر أسماء أن ترضع سالمًا مولى أبي حذيفة خمس رضعات، وقال: أرضعيه خمسًا تحرمي عليه ولأنه قال: لا تحرم الرضعة ولا الرضعتان خرجه مسلم في صحيحه. هذا كله يدل على أن الرضاع القليل لا يحرم، بل لا بد من خمس رضعات أو أكثر في الحولين؛ لقول النبي ﷺ: لا رضاع إلا في الحولين وقوله ﷺ: إنما الرضاعة من المجاعة والمجاعة محلها الحولان، وقوله ﷺ: لا رضاع إلا ما فتق الأمعاء، وكان قبل الفطام فرضاع الكبير فوق الحولين لا يؤثر عند جمهور أهل العلم، وأما إرضاع سهلة بنت سهيل لسالم مولى أبي حذيفة وهو كبير، فهذا خاص بها في أصح قولي العلماء.","link":"https://binbaz.org.sa/fatwas/17855/الضابط-المعتبر-في-الرضعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_874/nour_87406.mp3","categories":["الرضاع"]},{"id":18800,"question":"سماحة الشيخ، هذه السائلة أم خالد تقول: امرأة أرضعت طفلًا، وكانت تحلب اللبن من ثديها بإناء، وتسقيه هذا الطفل، هل يعتد بهذا الرضاع؟","title":"حكم الرضاع إذا كان من إناء","answer":"الجواب: نعم إذا فعلت ذلك خمس مرات أو أكثر في الحولين، يعتد بذلك، سواءً أرضعته من ثديها، أو حلبت له في الإناء، وأسقته خمس مرات لبن يذهب إلى جوفه خمس مرات، فأكثر في الحولين. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17940/حكم-الرضاع-اذا-كان-من-اناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79119.mp3","categories":["الرضاع"]},{"id":18839,"question":"سماحة الشيخ، هناك بعض القضايا إذا أذنتم لي بمناقشتها:أولًا: تصديق النساء فيما يخصهن في أمر الرضاع، وما أشبهه، ما رأيكم فيه؟","title":"حكم تصديق النساء أمر الرضاع وغيره","answer":"الجواب: الصواب أنها تصدق المرأة إذا كانت ثقة، إذا شهد لها بالصدق والأمانة والديانة، فقد شهد عند النبي ﷺ امرأة في إرضاع عقبة بن الحارث؛ فأمره بفراقها، وقال: دعها، كيف وقد قيل فطلقها عقبة ونكحت غيره، فارقها عقبة ونكحت غيره، وهو من باب الخبر، من باب الخبر الديني، كما يقبل الأذان من الواحد، فهذا خبر ديني يتعلق بحرمة الأبضاع، وهو أمر يحتاط له، فلهذا ذهب جمع من أهل العلم إلى قبول الواحدة، وذهب آخرون إلى أنه لا بد من ثنتين، وآخرون قالوا: لا بد من أربع. المقدم: بالنسبة لأمر الرضاع؟ الشيخ: الرضاع، ولكن الصواب: أن الواحدة تكفي؛ إذا كانت ثقة مأمونة لا شك فيها، نعم. المقدم: إذا كان الأمر مشكوك فيه بالنسبة لعدد الرضعات؟ الشيخ: لا ينفع، لا ينفع، ما يحكم بالرضاع، لا بد من خمس معلومات متيقنات في الحولين، نعم. المقدم: كون الأبناء -كما تفضلتم- صم بكم ليس لهذا علاقة؟ الشيخ: الله أعلم، لا يلزم بهذا؛ لأنها لم تعلم، والولد لم يعلم، فالإثم على الأب، والله لا يعاقب أحدًا بذنب غيره، والله سبحانه يقول: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] لكن لحكمة بالغة وقع ما وقع، له أسباب اقتضتها حكمة الله ، نعم، ، وليست أول من أصيب بهذا، قد أصيب غيرها أكثر من هذا.","link":"https://binbaz.org.sa/fatwas/17987/حكم-تصديق-النساء-امر-الرضاع-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_878/nour_87806.mp3","categories":["الرضاع"]},{"id":18840,"question":"بسم الله الرحمن الرحيم.الوالد العزيز الشيخ عبد العزيز بن عبد الله بن باز المحترم، حياكم الله.أرجو الإجابة على سؤالي؛ لأني حائرة في أمري، بارك الله فيكم، وعظم لكم المثوبة.  أجبرني والدي على الزواج من ابن عمي، وكنت مشمئزة ونافرة من ابن عمي، ولا أدري ما هو السبب، وتم الزواج وأنا قلبي نافر، وأحس بضيق شديد وهموم وغموم، ولم يكن لي أي نية موجهة إلى رجل آخر، ولم أجد مخرجًا من هذا الأمر، وقد أنجبت ثلاثة أولاد، وكلهم بكم الألسنة، صم الآذان، وقد قيل لي: إن السبب هو قد حصلت رضاعة ما بيني وبين ابن عمي المذكور، وقد سألت أمي فأفادت: إنه قد حصل بيني وبينه عدة رضعات، وأفادت إنها أخبرت والدي أثناء زفافي على هذا الرجل، بل أثناء خطبتي عليه، فلم يصدقها، بل ظن أنها تريدني لرجل آخر، وأنا في حيرة كيف أعمل الآن، أرجو التوضيح والتفصيل والإرشاد إلى ما فيه الخير؟ السائلة: (ن. ع. أ) من اليمن الشمالي، لواء الحديدة.","title":"حكم من أجبرت على الزواج ثم وجدت بينهما شبهة رضاع","answer":"الجواب: لا ريب أن الواجب على كل رجل أن يتقي الله في بناته، وأن لا يزوج بنته إلا عن رضاها، وأن لا يجبرها بأحد لا ترضاه، هذا هو الواجب على الأولياء، الأب والإخوة والأعمام وغيرهم، الواجب عليهم جميعًا ألا يزوجوا مولياتهم إلا بإذنهن، والأب بالأخص قد يتساهل في هذا؛ لأن بعض أهل العلم يجيز له أن يزوجها بغير اختيارها إذا كانت بكرًا، ولكن هذا القول وإن قال به بعض العلماء، فهو قول ضعيف قول مرجوح، والصواب: أنه ليس له أن يزوج بناته -أبكارًا كن أو ثيبات- إلا بإذنهن، إذا بلغن التسع فأكثر؛ لقول النبي ﷺ: لا تنكح البكر حتى تستأذن، ولا تنكح الأيم حتى تستأمر قالوا: يا رسول الله، البكر تستحي فكيف إذنها؟ قال: إذنها سكوتها وقال -عليه الصلاة والسلام-: البكر يستأذنها أبوها، وإذنها صماتها. فقد صرح النبي ﷺ بأنه ليس للأب ولا غيره أن يزوج المولية إلا بإذن، والأب هو المقدم، ومع ذلك نهي عن التزويج إلا بإذن، فالأولياء الآخرون من باب أولى، لكن إذا كان حين أمرك بالزواج أطعت ووافقت؛ إرضاءً له ومحبة له وتعظيمًا لأمره -وإن كنت كارهة- فلا حرج الزواج صحيح. وما وقع من وجود البنين الثلاثة الصم البكم؛ فهذا أمره إلى الله، قد يكون له أسباب غير ما ذكرت من الرضاع، قد يكون له أسباب أخرى، وأنت ليس عليك من هذا بأس؛ لأنك لم تعلمي الرضاع، وإنما البأس على أبيك الذي علم الرضاع وتساهل، فالإثم عليه، وعليه التوبة إلى الله من ذلك. وإذا كانت الأم قد حفظت خمس رضعات؛ فإنه يكون أخًا لك، وليس لك الزواج عليه والنكاح باطل، ولكن أنت ليس عليك إثم؛ لأنك لم تعلمي، والأولاد أولاكما لاحقون بأبيهم؛ للجهل وعدم العلم ببطلان النكاح. والواجب على أبيك التوبة إلى الله  من ذلك، فإذا كانت أمك ثقة، وشهدت بخمس رضعات أو أكثر، حال كون ابن عمك في الحولين؛ فإن النكاح يكون باطلًا، والإثم ثابت على أبيك، وعلى أمك نصيب من ذلك؛ لأنها لم تعلمك ولم تعتن بالأمر ولم تشدد فيه، فعليها نصيبها من الإثم، ولكن إثم الأب أكبر. أما إن كان الرضاع أقل من ذلك: رضعة أو رضعتين أو ثلاثًا أو أربعًا؛ فالنكاح صحيح؛ لأن التحريم إنما يحصل بخمس رضعات فأكثر، معلومات في الحولين، على أن تكون الشاهدة ثقة بذلك. والرضعة: هي أن يمسك الصبي أو الصبية الثدي ويمتص اللبن ثم يطلق ذلك، هذه يقال لها: رضعة. فإذا كان ابن عمك رضع من أمك خمس رضعات فأكثر، في كل رضعة يمسك الثدي ويمتص اللبن ويذهب إلى جوفه، ثم يعود بعد ذلك ويرضع، حتى يكمل خمسًا في مجلس أو في مجالس، في يوم أو في أيام؛ فإنك أخته، والنكاح باطل. وأسأل الله أن يشفي أبناءك الثلاثة، وأن يعظم أجرك، وأن يعفو عن أبيك عما حصل منه من الخطأ والتقصير، وعن أمك عما حصل منها من التقصير، نسأل الله أن يعفو عن الجميع؛ وأن يعوضك خيرًا من ابن عمك إذا ثبت الرضاع، أو طلقك؛ لأنك تكرهينه. على كل حال: هذه مصيبة، والدنيا هي دار المصائب، ونسأل الله أن يحسن العاقبة للجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17986/حكم-من-اجبرت-على-الزواج-ثم-وجدت-بينهما-شبهة-رضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_878/nour_87805.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":18860,"question":"رسالة وصلت إلى البرنامج من جدة، وباعثها أخ لنا من هناك يقول: المرسل أخوكم في الإسلام عوض السلمي من جدة، أخونا رسالته مطولة في الواقع فهمت منها سماحة الشيخ: أنه استمع إلى النقاش الذي تفضلتم به عن عقد الزواج على المرأة التي لا تصلي، وكثير من الناس بدأ يتساءل حول هذا الموضوع، ويريدون أن يصححوا أوضاعهم، فكيف توجهونهم؟ جزاكم الله خيرًا، وذلكم إذا تزوج رجل امرأة لا تصلي أو امرأة تزوجت رجلًا واكتشفت أنه لا يصلي، كيف توجهونهم؟جزاكم الله خيرًا.","title":"حكم عقد النكاح إذا كان أحد الزوجين لا يصلي","answer":"الجواب: هذه المسألة مسألة عظيمة، وهي ما إذا تزوج الرجل الملتزم المصلي امرأة لا تصلي أو بالعكس؛ تزوج الرجل المقصر الذي يترك الصلاة تزوج امرأة ملتزمة طيبة تحافظ على صلاتها، فذهب بعض أهل العلم إلى أنه يصح النكاح إذا كان كل منهما لا يجحد الصلاة، بل يقر بها، ويعلم أنها واجبة، ولكنه يتكاسل، وهذا هو المعروف في مذهب مالك وأبي حنيفة والشافعي -رحمة الله عليهم-. وذهب جمع من السلف إلى أن ترك الصلاة كفر أكبر، وإن لم يجحد وجوبها، وهذا ذهب إليه جمع كبير من أهل الحديث -رحمة الله عليهم-، ورواه عبد الله بن شقيق العقيلي التابعي الجليل عن أصحاب النبي -عليه الصلاة والسلام- جميعًا، وقال: «إن أصحاب النبي ﷺ كانوا لا يرون شيئًا تركه كفر إلا الصلاة» والعمدة في هذا ما ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر خرجه الإمام أحمد في مسنده وأصحاب السنن الأربع بإسناد صحيح عن بريدة . وفي صحيح مسلم عن جابر بن عبد الله الأنصاري -رضي الله عنهما- عن النبي -عليه الصلاة والسلام- أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة وهناك أحاديث أخرى في الموضوع، وهذا القول أصح القولين، وهو أن ترك الصلاة عمدًا كفر أكبر، وإن لم يجحد وجوبها في ظاهر الكتاب والسنة. فإذا تزوج الرجل الملتزم المصلي امرأة لا تصلي فإن النكاح ليس بصحيح على الصحيح، فإذا تابت جدد النكاح، وله رغبة فيها، ولها رغبة فيه يجدد النكاح، وهكذا العكس؛ لو تزوج رجل لا يصلي امرأة ملتزمة تصلي، فالنكاح ليس بصحيح أيضًا، وعليهما تجديده إذا تاب من لا يصلي، إذا تاب توبة صادقة، فإنه لا مانع من التجديد إذا كان كل واحد منهما يرغب في الآخر، هذا هو المختار، وهذا هو الأرجح من حيث الدليل، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17997/حكم-عقد-النكاح-اذا-كان-احد-الزوجين-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92207.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":18972,"question":"أختنا أيضًا لها قضية أخيرة نعرضها في هذه الحلقة تقول فيها: إن جدتي أرضعت أحد أقاربي من أمي، ولكنها لا تعرف عدد الرضعات، وأنا الآن مخطوبة لأخي الرجل الذي أرضعته جدتي مع أبي، وأخبروني أن هذا الرجل وأبي إخوان، وأنه أصبح عمي، وأنا مخطوبة لأخيه، وأشك أن حتى هذا الذي أنا مخطوبة له أن يكون عمي، وضحوا لي الطريق؟جزاكم الله خيرًا.","title":"حكم الرضاع إذا كان غير معلوم أو مشكوكًا فيه","answer":"الجواب: الأصل السلامة، الأصل الإباحة، وما دام لا يعلم أنه ارتضع من جدتك، ولا يعلم أنه عمك، فالأصل الإباحة والسلامة، والحمد لله، وإذا كانت الجدة لا تحفظ عدد الرضعات، فلا يثبت فيها حكم، لا بد من خمس رضعات معلومات أو أكثر، فإذا كانت المرضعة لا تحفظ عدد الرضعات لا تدري هل هي خمس أو أربع أو ثلاث فرضاعها لا يعول عليه، ولا يعتمد عليه، وما دام الرضاع لغير هذا الخاطب، وهذا الخاطب إنما يشك أن يكون قد رضع، هذا لا يعول عليه، والأصل الإباحة والسلامة، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18100/حكم-الرضاع-اذا-كان-غير-معلوم-او-مشكوكا-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92410.mp3","categories":["الرضاع"]},{"id":19004,"question":"رسالة من أحد الإخوة المستمعين يقول المرسل: إبراهيم أحمد ذيب من اليمن، أخونا إبراهيم له جمع من الأسئلة من بينها سؤال يقول: رجل عقد على امرأة، ولم يدخل بها سواء توفي أو طلقها،  هل يجوز لابنه أن يتزوجها أم تكون من المحرمات عليه؟ جزاكم الله خيرًا.","title":"حكم زواج الابن من مطلقة أبيه التي لم يدخل بها","answer":"الجواب: إذا تم العقد للرجل على امرأة عقدًا شرعيًا؛ فإنها تكون محرمة على جميع ذريته، وعلى أبيه، وأجداده، ولو لم يدخل بها سواء مات أو طلق؛ لقول الله جل وعلا: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ[النساء:22] هذا عام، نكاح العقد، ونكاح الدخول، ولقوله جل وعلا: وَحَلائِلُ أَبْنَائِكُمُ[النساء:23] زوجات الأبناء الَّذِينَ مِنْ أَصْلابِكُمْ[النساء:23] فحلائل الأبناء محرمات على الآباء، كما أن حلائل الآباء محرمة على الأبناء، على أبنائهم، وأبناء أبنائهم، وأبناء بناتهم، وزوجات البنين محرمة على الآباء، والأجداد سواء كان الابن ابنك أو ابن بنتك. وقوله: مِنْ أَصْلابِكُمْ[النساء:23] احترازًا من الأدعياء كانوا في الجاهلية يتبنون، بعض الناس يربونهم ويتبنونهم، هؤلاء ليسوا بأبناء وإن تبنوهم، وزوجاتهم غير محرمات. والنبي ﷺ تزوج زينب بنت حجش وقد طلقها زيد بن حارثة، وكان النبي ﷺ قد تبناه في الجاهلية، ثم أمره الله أن يدعى لأبيه فقال: ادْعُوهُمْ لِآبَائِهِمْ[الأحزاب:5]، وتزوج النبي ﷺ مطلقته زينب حتى يعلم الناس أنه لا حرج في تزوج مطلقات الأدعياء، الأبناء الأدعياء. أما ابنك من الرضاعة، وابنك من النسب؛ فزوجته حرام عليك، وزوجة أبيه من الرضاعة ومن النسب حرام عليه. وهكذا زوجات أجدادك من النسب؛ والرضاعة، وهكذا زوجات أبنائك من النسب؛ والرضاعة، وأبناء بناتك كلهن محرمات، ولو لم يدخل الزوج بالزوجة، ولو لم يخل بها، ما دام تم العقد الشرعي كفى. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18168/حكم-زواج-الابن-من-مطلقة-ابيه-التي-لم-يدخل-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_795/nour_79509.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":19045,"question":"يسأل أخونا سؤاله الأخير، ما هي حدود التعامل مع الإخوة من الرضاعة الذكور والإناث، فهل مثلًا للأخ من الرضاعة أن يسافر مع أخته من الرضاعة، أو يبقى معها في بيت واحد؟ أو يقبلها كما يقبل أخته من النسب؟ أرجو توضيح ذلك، وما هي الاستثناءات التي لا يجوز فعلها مع الإخوة من الرضاعة؟","title":"الأحكام المترتبة على التحريم بالرضاع","answer":"الجواب: الرضاع كالنسب كما قاله النبي ﷺ: يحرم من الرضاع ما يحرم من النسب يعني: في الخلوة والمحرمية، هي أخته كما أن أخته النسب كذلك، فلا بأس أن يخلو بها ولا بأس أن يسافر بها، ولا بأس أن يصافحها، ولا بأس أن يقبلها، لكن يكون التقبيل في غير الفم، هذا هو الأولى أن يكون مع الرأس أو مع الخد كما كان الصديق يقبل ابنته عائشة مع خدها. فالحاصل أنه مثل النسب سواء، يحرم من الرضاع ما يحرم من النسب لكن ليس مثل النسب في صلة الرحم، الرحم يختص بالأقارب، وإنما هذا في المحرمية والخلوة لا في النفقة ولا في صلة الرحم؛ لقوله ﷺ: يحرم من الرضاع ما يحرم من النسب اللهم صل على محمد. المقدم: اللهم صل على سيدنا محمد.","link":"https://binbaz.org.sa/fatwas/18214/الاحكام-المترتبة-على-التحريم-بالرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_928/nour_92806.mp3","categories":["الرضاع"]},{"id":19141,"question":"أخونا يسأل عن زواج الشغار ويقول: إنه معروف لدينا باسم الزقار.الشيخ: الزقار!المقدم: نعم. يقول: من وقع فيه ومضى على زواجه سبع سنوات وأنجب بنين وبنات، كيف يتصرف؟","title":"حكم زواج الشغار وكيفية معالجته لمن وقع فيه","answer":"الجواب: نكاح الشغار -ويسميه بعض الناس نكاح البدل- هذا النكاح على حسب أسمائه يعرف بأنه اشتراط امرأة في امرأة، اشتراط أحد الوليين الزوجة الأخرى، والآخر كذلك، كل واحد يقول: زوجني بنتك وأزوجك بنتي، أو أختك وأزوجك أختي وما أشبه ذلك، هذا قد نهى عنه النبي ﷺ في الأحاديث الصحيحة \"نهى عن الشغار\"، في الصحيحين من حديث ابن عمر، وفي صحيح مسلم من حديث أبي هريرة، ومن حديث جابر، يقول النبي ﷺ: الشغار أن يقول الرجل: زوجني ابنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي، هذا هو الشغار، فإذا وقع فالصحيح أنه يكون فاسدًا. والواجب أن يجدد إذا كان لهما رغبة فيما بينهما يجدد من غير شرط المرأة الثانية، كل واحد يجدد من غير شرط المرأة الثانية، ولو مضى عليه سنوات، يجدد إذا كانت ترغب فيه و يرغب فيها، يجدد النكاح بحضرة شاهدين، وبمهر جديد، من دون أن يشترط عليه المرأة الأخرى، وهكذا الآخر، كل واحد يجدد، إذا كانت ترغب في زوجته، وهو يرغبها، أما إن كان لا يرغب أحدهما في الآخر فإنه يطلقها طلقة واحدة؛ لأن هذا النكاح فاسد، فلا بد فيه من طلقة واحدة، تمنع تعلق أحدهما بالآخر، وتحتج بها في تزوجها لغيره إذا اعتدت. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18342/حكم-زواج-الشغار-وكيفية-معالجته-لمن-وقع-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88608.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19142,"question":"رسالة وصلت إلى البرنامج من المستمع محمد صالح ناجي من الخبر، أخونا له مجموعة من الأسئلة، يسأل في سؤاله الأول عن حكم من تزوج فتاة لا تصلي، أو يكون العكس أيضًا، وما حكم تارك الصلاة؟ وهل إذا مات يصلى عليه ويدفن في مقابر المسلمين؟","title":"حكم الزواج بامرأة لا تصلي","answer":"الجواب: إذا تزوج الرجل فتاة لا تصلي وهو يصلي، أو العكس: فتاة تصلي وهو لا يصلي، فالنكاح باطل على الصحيح، النكاح فاسد؛ لأنه لا يجوز للمسلم أن يتزوج الكافرة، وليس للمسلمة أن تتزوج الكافر، وترك الصلاة كفر على الصحيح، كفر أكبر، فإذا كان أحدهما يصلي، والآخر لا يصلي فإن النكاح لا يصح، بل يجب أن يجدد بعد توبة من لا يصلي، إذا تاب يجدد النكاح، إذا كان صاحبه يرغب فيه. أما إن كانا لا يصليان جميعًا فأصل النكاح صحيح، كنكاح الكفار، نكاح صحيح، وعليهما أن يتوبا إلى الله ويرجعا إلى طاعة الله ورسوله، ونكاحهما صحيح. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18339/حكم-الزواج-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88607.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19183,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع علي محمد عامر علي من شبرا في جمهورية مصر العربية، أخونا بدأ رسالته بقوله: السلام عليكم ورحمة الله وبركاته، وبعد:حدد لنا الإسلام ما يترتب عن الرضاعة، ومنع زواج الإخوة بالرضاعة بنص الكتاب والسنة وذلك معروف لدينا، ولكن حدث في السنوات الأخيرة عمليات نقل أعضاء مثل زرع القلب وخلافه، وكذلك عمليات نقل الدم، فما حكم ذلك في الإسلام، أولًا: إن كان الذي ينقل إليه الدم أو العضو في سن الرضاعة؟ثانيًا: إن كان الذي سينقل إليه الدم أو العضو أكبر من سن الرضاعة، والسلام عليكم ورحمة الله وبركاته؟","title":"مدى تأثير نقل الأعضاء والدم على أحكام الرضاع","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الله جل وعلا أوضح في كتابه الكريم، وعلى لسان رسوله الأمين محمد عليه الصلاة والسلام أحكام المحرمات في النكاح من النسب والرضاع، أما ما يتعلق بنقل الدم، ونقل الأعضاء فإنه لا يلحق بالرضاع، ولا يكون من جنس الرضاع، فإن هذه أمور توقيفية، لا يقاس فيها شيء على شيء، بل أمر الرضاع بالنص وأمر النسب بالنص والمصاهرة، فلا يقاس على الرضاع نقل الدم ولا نقل الأعضاء، فلو نقل من زيد إلى عمرو دم أو عضو أو من فلانة إلى فلان، أو من فلان إلى فلانة، فإنه لا يثبت به حكم الرضاع، فإذا نقل من امرأة إلى شخص دم ما تكون أمًا له، ولا يكون أولادها إخوة له وهكذا، فليس له حكم الرضاع، لا نقل الدم ولا نقل الأعضاء، ولا أعلم بين أهل العلم خلافًا في هذا الأمر؛ لأن نقل الدم لا يقاس على الرضاع لا في الحولين ولا بعد الحولين. وهكذا نقل الأعضاء كالكلية أو غيرها لا يقاس على الرضاع؛ لأن الرضاع أمر تشريعي جاء عن رسول الله عليه الصلاة والسلام، وجعله كالنسب، فلا يقاس عليه غيره، بل هذه أمور توقيفية لا يقاس عليها لا نقل الدم ولا غيره، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18305/مدى-تاثير-نقل-الاعضاء-والدم-على-احكام-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88501.mp3","categories":["الرضاع"]},{"id":19186,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول إبراهيم أحمد ذيب من اليمن، الأخ إبراهيم له جمع من الأسئلة في أحدها يقول: إن لي ابن أخ ورضع معي، هل يجوز له أن يتزوج من بنات عمتي الأخريات، علمًا بأنه لم يرضع معهن بل رضع معي فقط، نرجو الإفادة جزاكم الله خيرًا.الشيخ: أعد.المقدم: يقول: إن لي ابن أخ ورضع معي، هل يجوز له أن يتزوج من بنات عمه الأخريات، علمًا بأنه لم يرضع معهن بل رضع معي فقط؟ نرجو الإفادة جزاكم الله خيرًا.","title":"ما يترتب على من رضع من أم عمه؟","answer":"الجواب: إذا رضع من أمك خمس رضعات فإنه يكون أخًا لك، ولجميع إخوتك إذا كان قبل الفطام، إذا كان رضع في الحولين قبل الفطام خمس مرات فأكثر من أمك فإنه يكون أخًا لك، ولجميع إخوانك الصغار والكبار، ويكون أخًا لجميع أولاد أبيك أيضًا من الزوجات الأخرى، وعمًا لأولاد الإخوة، عمًا لأولاد الإخوة، وخالًا لأولاد الأخوات؛ ليس له أن ينكح منهن أحدًا، فهو خال لأولاد أخواته من الرضاع، وهو عم لأولاد إخوته من الرضاع، إذا كان أولئك من أمك فهو شقيق، وإن كانوا من زوجة أخرى فهو أخ لهم من الأب؛ لأن أمك هي زوجة هذا الرجل الذي أرضعته من لبنه، ويكون هو ابنًا له، ويكون أخًا لأولاده من الزوجات الأخريات من الأب، وأخًا لأولاد الزوجات الأخريات من الأب. المقصود أن هذا الولد الذي رضع من أمك أخ لك ولإخوانك جميعًا من أمك، شقيق ومن الزوجات الأخرى يكون أخًا لهم من الأب، وللإناث أخًا لهن من الأب، وخالًا لأولاد الإناث، وعمًا لأولاد الذكور. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18375/ما-يترتب-على-من-رضع-من-ام-عمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79812.mp3","categories":["الرضاع"]},{"id":19241,"question":"أخ مستمع من جمهورية مصر العربية يقول: تزوجت فتاة، ولاحظت أنها لا تصلي، كيف توجهونني جزاكم الله خيرًا؟","title":"حكم الزواج بفتاة لا تصلي","answer":"الجواب: إذا كنت تصلي أنت وهي لا تصلي فالعقد غير صحيح في أصح قولي العلماء؛ لأنها بترك الصلاة تعتبر كافرة، والمسلم ليس له نكاح الكافرة إلا إذا كانت من أهل الكتاب.. من اليهود والنصارى المحصنات خاصة، أما الكافرة غير النساء المحصنات من أهل الكتاب فلا تجوز، فلا يجوز نكاحها، فإذا كنت أنت تصلي ومستقيم، وهي لا تصلي فالنكاح باطل، وعليك أن تعيد النكاح في الأصح من قولي العلماء. أما إن كنت لا تصلي مثلها فالنكاح صحيح؛ لأنه يجوز نكاح الكافر بالكافرة كما يجوز نكاح المسلم بالمسلمة، أما إذا كان أحد الزوجين لا يصلي فالنكاح غير صحيح إلا أن تكون كتابية فلا بأس، والكتابية هي اليهودية والنصرانية، فإنه يجوز للمسلم والكافر نكاحها، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا","link":"https://binbaz.org.sa/fatwas/18436/حكم-الزواج-بفتاة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_891/nour_89106.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19336,"question":"مستمعة بعثت برسالة طويلة تقول فيها: المرسلة أم خالد تتحدث عن نفسها وتقول: سماحة الشيخ أنا امرأة أسكن بمدينة الدمام، وكانت لي جارة قبل خمسة عشر عامًا، وهذه الجارة كان لها من الأبناء الصغار؛ فإذا أرادت أن تذهب إلى مكان ما أتت بطفلها عندي؛ فأقوم أنا برضاعته، وقد أصبح هذا الطفل ابنًا لي، وأنا متأكدة من رضاعته الشرعية له، ولكن الذي أشكل علي أنا أن لها طفلًا آخر كانت تضعه عندي بعد عام من رضاعتي للأول، وأنا نسيت إن كان قد رضع ذلك الطفل أم لا، علمًا بأن جدة هذا الطفل أخبرت خالة الطفل أنني أنا أكون أمًا لهذين الطفلين، فهل يعتبر الطفل الثاني ابنًا لي، وهل تكفي شهادة امرأة واحدة في مسألة الرضاعة؟ أفيدونا جزاكم الله خيرًا.","title":"صفة الرضاع المحرم وبم يثبت","answer":"الجواب: أما الطفل الأول الذي أنت تعلمين أنك أرضعتيه هذا يكون ولدًا لك، إذا كنت حافظة أنك أرضعتيه خمس مرات فأكثر، يعني: خمس رضعات، فهو يكون ولدًا لك، ويكون أخًا لأولادك، ويكون إخوانك أخوالاً له، وهكذا أخواتك خالات له؛ لقول النبي ﷺ لبعض النساء: أرضعيه خمس رضعات تحرمي عليه ولأنه ثبت عن عائشة رضي الله تعالى عنها أنها قالت: كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات توفي رسول الله ﷺ وهي فيما يقرأ من القرآن، وفي الرواية الأخرى: فتوفي النبي ﷺ والأمر على ذلك. فالواجب في مثل هذا التثبت والعناية، وعدم التساهل، فإذا كنت حافظة كما قلت أنك أرضعت الأول خمس رضعات أو أكثر فهو يكون ولدًا لك. وأما الثاني الذي تضعه أمه عندك، ولكن لا تعلمين أنك أرضعتيه؛ لا يكون ولدًا لك إلا إذا شهد امرأة ثقة سواءً كانت خالته أو غيرها، إذا كانت الشاهدة امرأة ثقة معروفة بالعدالة، والدين، والضبط؛ أنها شاهدتك أرضعتيه خمس رضعات أو أكثر بالمشاهدة، أنها شاهدتك فهذه تعتبر، وتكون شهادتها معتبرة، ويكون ولدًا لك أيضًا. والمرأة العدل تقبل في الرضاع، وقد ثبت عنه ﷺ: أن عقبة بن الحارث تزوج امرأة يقال لها بنت أبي إهاب، فشهدت امرأة أنها أرضعتهما، فأمره النبي ﷺ أن يدعها وأن يفارقها واكتفى بشهادة امرأة واحدة، فهذه أمور تعلق بالنساء، فإذا شهد امرأة واحدة عدل، أو رجل عدل أو أكثر من ذلك بالرضاع خمس مرات أو أكثر في الحولين يعني: حال كون الطفل في الحولين ثبت الرضاع في أصح قولي العلماء. المقدم: جزاكم الله خيرًا، إذًا خالة هذا الطفل إذا كانت امرأة عدل فشهادتها مقبولة بأنه ولدها؟ الشيخ: إذا كانت شاهدت الرضاع ما هو مجرد الظن، لا. لابد أن تكون شاهدت الرضاع، شاهدت المرأة حين أرضعته خمس مرات، لكن أمه نسيت، المرضعة نسيت، أما هذه فهي حافظة إذا كانت حافظة يقينًا يعمل بشهادتها إذا كانت ثقة عدل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18549/صفة-الرضاع-المحرم-وبم-يثبت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_941/nour_94109.mp3","categories":["الرضاع"]},{"id":19371,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من جدة، وباعثها أخ لنا من هناك يقول: أنا محسن حميد علي السلاط ، من اليمن قرية الرزمة -فيما يبدو- أخونا يقول في أحد أسئلته:لقد ظهرت في بلادنا ظاهرة غريبة حيث أن بعضًا من الناس إذا أراد الزواج وعنده أخت أو بنت يتبادل مع شخص آخر بأن يزوج كل منهم الآخر بموليته، وكل منهم يقوم بتزويج تلك المولية بما تستحق وبما هي أهله في الزواج، ويسأل عن الحكم لو تكرمتم شيخ عبد العزيز ؟","title":"صورة نكاح الشغار وحكمه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وصفوته من خلقه وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين، أما بعد: فهذا النكاح الذي سأل عنه الأخ يسمى نكاح الشغار، ويسميه بعض الناس نكاح البدل، وهو نكاح لا يجوز؛ لأن الرسول عليه الصلاة والسلام نهى عن ذلك، ثبت عنه في الأحاديث الصحيحة من حديث ابن عمر ومن حديث أبي هريرة ومن حديث جابر ومن حديث معاوية النهي عن الشغار، وقال: الشغار أن يقول الرجل: زوجني ابنتك وأزوجك ابنتي، أو زوجني أختك وأزوجك أختي هذا هو الشغار وهو اشتراط نكاح امرأة في نكاح امرأة، سواء كانت المرأة بنته أو أخته أو بنت أخيه، المقصود أنها موليته، فهذا لا يجوز والواجب النهي عن ذلك والتحذير منه، ولو سموا مهرًا، ولو تراضوا على ذلك لا يجوز؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام، والله يقول جل وعلا: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، ويقول جل وعلا: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63]. وثبت عن معاوية  أنه بلغه أن بعض المقيمين في المدينة تزوج امرأة على أن يزوج صاحبه امرأة عنده وسموا مهرًا، فكتب معاوية إلى أمير المدينة أن يفرق بينهما، وقال: «هذا هو الشغار الذي نهى عنه الرسول عليه الصلاة والسلام». ولم يلتفت إلى ما سموا من المهر. فالحاصل: أن هذا النكاح لا يجوز، سواء كان فيه مهر أم لم يكن فيه مهر، وسواء تراضى الجميع أو لم يتراضوا، كله ممنوع؛ لنهي النبي عن ذلك عليه الصلاة والسلام، ولأنه وسيلة إلى جبر النساء وإلزامهن بما لا يرضين به، وهذا واقع كثيرًا، ولأنه -أيضًا- وسيلة إلى تحجر النساء ولا يبادر إلى تزويجهن بالأكفاء ينتظر أن يأتي واحد يبادله، فيمسك ويحبس المرأة عنده بنته أو أخته حتى يجد من يبادله، وفيه ظلم للنساء وتعطيل لهن، والله جل وعلا حكيم عليم، ومن حكمته العظيمة أن نهى هذا النكاح لما يترتب عليه من أنواع الفساد. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18592/صورة-نكاح-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93401.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19385,"question":"رسالة بعث بها لنا مستمع من خليص، سمى نفسه فتى الطلعة، يسأل ويقول: ابنة أخي إذا كان لها بنت هل لي الزواج بها؟","title":"حكم الزواج ببنت بنت الأخ","answer":"الجواب: بنت أخيك وبنت بنت أخيك محرم، ليس لك الزواج ببنت أخيك ولا بناتها ولو نزلن، بنت أخيك وبنت بنت أخيك، وبنت ابن أخيك، وبنت بنت بنت ابن أخيك كلهم محارم، أنت عمهن جميعًا ولو نزلن. فليس لك الزواج بواحدة منهن بإجماع المسلمين؛ لأن الله جل وعلا حرم في المحرمات بنات الأخ.\nوبنات الأخ تشمل القريبات والبعيدات، بنات الأخ وبنات ابن الأخ، وبنات بنات ابن الأخ، يعني: وإن نزلن. فالحاصل أن بنات الأخ وبنات ابن الأخ وإن نزلن محرمات على عمهن، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18606/حكم-الزواج-ببنت-بنت-الاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93413.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":19387,"question":"رسالة وصلت إلى البرنامج من اليمن، وباعثها المستمع (ع. س. ع) يقول: سماحة الشيخ، لقد رضعت مع فتاة في قريتنا في أثناء غياب أمي عني يومًا كاملًا وأنا طفل صغير لا أدري كم أبلغ من العمر، وعندما كبرت كنت أسمع أم الفتاة التي رضعت معها تقول لي ولأسرتي: أنت قد أرضعتك مع بنتي فلانة، وعندما كبرت تزوجت أخت الفتاة التي رضعت معها، وهي الصغرى، وحيث أنا في البادية لا نعلم أنه يحرم من الرضاعة ما يحرم من النسب ونحن الآن مستمرون في حياتنا لنا ثلاث سنوات، وقد خلفنا بنتًا وصارت الآن عدد الرضعات مجهولة لا نعلم: هل هي أقل من خمس أم أكثر والتي يثبت بها التحريم، وجهونا كيف نتصرف الآن؟ جزاكم الله خيرًا.","title":"حكم التحريم بالرضاع إذا لم يعلم عدد الرضعات","answer":"الجواب: إذا كانت الرضعات لا تعلم، فلا حرج عليكم، والزوجة معك والحمد لله، إلا إذا كانت المرضعة موجودة وهي ثقة فاسألوها، فإن ذكرت أنها أرضعتك خمس رضعات أو أكثر؛ فأنت أخ للبنت التي تزوجتها؛ لأنها بنت المرضعة ولا تحل لك، أما إذا كانت المرضعة ميتة، أو لا تعرف كم أرضعتك أو غير ثقة لا يوثق بها لفسقها أو كذبها؛ فلا حرج عليك والزواج صحيح والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18608/حكم-التحريم-بالرضاع-اذا-لم-يعلم-عدد-الرضعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74002.mp3","categories":["الرضاع"]},{"id":19502,"question":"رسالة وصلت من الجزائر، السائل رمز لاسمه بـ (ح. ب) يقول: سماحة الشيخ هل يتم عقد الزواج إذا كان أحد الأشخاص من الزوجين لا يصلي، أو إذا كان أيضًا الزوجان لا يصليان، ما حكم الزواج في مثل هذه الحالة مأجورين؟","title":"حكم النكاح إذا كان أحد الزوجين لا يصلي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. هذا الموضوع يراجع فيه الجهات المختصة المحكمة أو الجهات المختصة بالإذن في النكاح؛ لأن فيه تفصيلًا، فالذي يصلي لا يجوز له أن ينكح من لا تصلي الكافرة، والتي تصلي والخاطب لا يصلي ليس لها أن تتزوج عليه؛ لأن الله جل وعلا يقول: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا[البقرة:221]، ويقول: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ[الممتحنة:10]، فلا يجوز أن تنكح المسلمة الكافر، ولا يجوز للكافر أن ينكح المسلمة. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18748/حكم-النكاح-اذا-كان-احد-الزوجين-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94601.mp3","categories":["الرضاع","الأنكحة المحرمة"]},{"id":19540,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الرياض حي الوزارات وباعثها أحد الإخوة المستمعين يقول المرسل: (ع . س . ش . ج. الشهري)، أخونا يقول: رضعت مع ابنة أخي الأكبر مني، ولم تكن الرضعات معلومة لدى أمهاتنا، ولكن كنّ على هذه الحالة لفترة ثلاثة أشهر تقريبًا، وكن إذا غابت إحداهن ترضعنا الأخرى حسبما أفادتني به الوالدة، فهل يعتبر هذا الرضاع شرعيًا، وإذا كان كذلك فهل أخي أصبح والدي من الرضاعة ومن ثم ما حكم ...الشيخ: أعد أعد.المقدم: يقول: رضعت مع ابنة أخي الأكبر مني، ولم تكن الرضعات معلومة لدى أمهاتنا، ولكن كن على هذه الحالة لفترة ثلاثة أشهر تقريبًا، وكن إذا غابت إحداهن ترضعنا الأخرى حسبما أفادتني به الوالدة، فهل يعتبر هذا الرضاع شرعيًا، وإذا كان كذلك فهل أخي أصبح والدي من الرضاعة؟ ومن ثم ما حكم قرابتي لزوجته الثانية التي لم أرضع منها، وكما أني قد حجبت زوجتي عن أخي واحتجبت عني زوجته الأخرى أرشدونا أثابكم الله وعظم أجركم ونفعنا وإياكم بما نسمع إنه سميع مجيب، والله ولي التوفيق، والسلام عليكم؟","title":"حكم من رضع من امرأة أخيه رضاعًا غير معلوم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كان الواقع كما ذكره السائل ولم تحفظ المرضعة ولا غيرها عدد الرضعات هل هي خمس أو أقل أو أكثر فإن الرضاعة لا تعتبر ولا تكون ولدًا لأخيك ولا يكون أخوك أبًا لك ولا محرمًا لزوجتك، ولا تكون زوجته محرمًا لك لا التي أرضعتك ولا الأخرى، لابد من ضبط الرضاع، وأن تكون الرضعات خمسًا أو أكثر، فإذا كانت المرضعة أو غيرها من النساء الثقات قد حفظت أنك رضعت من زوجة أخيك خمس رضعات أو أكثر من ذلك فأنت ولده، ولو لم تعرف المرضعة عدد الرضعات كلها، إذا عرفت أنك رضعت منها خمس رضعات أو أكثر فإنك تكون ولدًا لها ولا يلزم أن تكون تعرف الرضعات كلها هل هي ثلاثين أو عشرين أو أربعين ما هو لازم. المهم أن تحفظ خمس رضعات صدرت منها لك أو أكثر من ذلك في الحولين حال كونك في الحولين، فإنها بهذا تكون أمًا لك ويكون أخوك أبًا لك من الرضاعة، ويكون أولاده إخوة لك من الرضاعة ويكون محرمًا لزوجتك؛ لأنها زوجة ابنه، وتكون زوجته التي أرضعتك أمًا لك وتكون زوجته الأخرى التي لم ترضعك زوجة لأبيك محرمًا لك أيضًا، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18785/حكم-من-رضع-من-امراة-اخيه-رضاعا-غير-معلوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_940/nour_94001.mp3","categories":["الرضاع"]},{"id":19559,"question":"تقول: هل زوجة الأب المطلقة يجوز لها أن تكشف على أولاد زوجها الذي طلقها؟","title":"محرمية أولاد الزوج لزوجة أبيهم المطلقة","answer":"الجواب: نعم، لها أن تكشف عنهم؛ لأنها زوجة أبيهم، والله يقول: وَلا تَنكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ[النساء:22] فزوجة أبيهم محرم لهم، ولو بعد الطلاق والموت، ولو بعد طلاقه لها أو موته، هي محرم لهم. نعم.","link":"https://binbaz.org.sa/fatwas/18807/محرمية-اولاد-الزوج-لزوجة-ابيهم-المطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94706.mp3","categories":["الرضاع","المحرمات من النساء"]},{"id":19620,"question":"يقول هذا السائل يا سماحة الشيخ: البعض من الناس يتزوجون بطريقة البدل، أي: أعطيك امرأة من قريباتي، وتعطيني امرأة بدلها، فما حكم هذا الزواج؟","title":"حكم زواج البدل بين الأقارب","answer":"الجواب: هذا لا يجوز، نكاح البدل هذا نكاح الشغار، الرسول ﷺ نهى عنه ولا يجوز، ولعن من فعله، وسماه التيس المستعار، فلا يجوز هذا لا بد أن ينكح عن رغبة، من دون شغار، أما أن يقول: زوجني وأزوجك هذا ما يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/18884/حكم-زواج-البدل-بين-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94816.mp3","categories":["الرضاع","الأنكحة المحرمة"]}]
